// ── Canvas 交互：三张图都加 hover tooltip ───────────────────────────
/** 记录每张图的绘制元数据（把坐标系留给 hover 反查） */
const optChartMeta = {
  conv: null,  // { pad, xMin, xMax, yMin, yRange, genList }
  div:  null,  // { pad, genList, divList, mx }
  radar: null, // { cx, cy, radius, enabledParams, axisAngles }
};

function bindCanvasHover(canvasId, type) {
  const c = document.getElementById(canvasId);
  if (!c) return;
  c.addEventListener('mousemove', (e) => optCanvasHover(c, type, e));
  c.addEventListener('mouseleave', () => {
    hideTooltip();
    // 清掉 hover 十字线：重画对应图
    if (type === 'conv') optDrawChart();
    if (type === 'div') optDrawDivChart();
    if (type === 'radar') optDrawRadar();
  });
}

bindCanvasHover('opt_chart', 'conv');
bindCanvasHover('opt_div_chart', 'div');
bindCanvasHover('opt_radar_chart', 'radar');

function optCanvasHover(canvas, type, e) {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  if (type === 'conv') {
    const meta = optChartMeta.conv;
    if (!meta) return;
    const { pad, xMin, xMax, plotW, plotH } = meta;
    if (mx < pad.l || mx > pad.l + plotW) return;
    // 反查最接近的代
    const fracX = (mx - pad.l) / plotW;
    const targetGen = xMin + fracX * (xMax - xMin);
    let nearest = 0, nearestDiff = Infinity;
    for (let i = 0; i < optHistory.length; i++) {
      const d = Math.abs(optHistory[i].gen - targetGen);
      if (d < nearestDiff) { nearestDiff = d; nearest = i; }
    }
    const pt = optHistory[nearest];
    if (!pt) return;
    // 重画 + 十字线
    optDrawChart();
    drawCrosshairConv(canvas, meta, pt);
    showTooltip(canvas, `
      <b>第 ${pt.gen} 代</b><br>
      <span style="color:#58a6ff">Best</span> ${Math.round(pt.best)}<br>
      <span style="color:#8b949e">Avg</span>  ${Math.round(pt.avg)}<br>
      <span style="color:#666">Worst</span> ${Math.round(pt.worst)}<br>
      <span style="color:#c9a847">多样性</span> ${(pt.diversity || 0).toFixed(3)}
    `);
  } else if (type === 'div') {
    const meta = optChartMeta.div;
    if (!meta || !meta.genList.length) return;
    const { pad, plotW } = meta;
    if (mx < pad.l || mx > pad.l + plotW) return;
    const fracX = (mx - pad.l) / plotW;
    const idx = Math.min(meta.genList.length - 1, Math.round(fracX * (meta.genList.length - 1)));
    const pt = optHistory[idx];
    if (!pt) return;
    optDrawDivChart();
    drawCrosshairDiv(canvas, meta, idx);
    showTooltip(canvas, `<b>第 ${pt.gen} 代</b><br>多样性 ${(pt.diversity || 0).toFixed(4)}`);
  } else if (type === 'radar') {
    const meta = optChartMeta.radar;
    if (!meta) return;
    const { cx, cy, radius, enabledParams } = meta;
    const dx = mx - cx, dy = my - cy;
    const dist = Math.sqrt(dx * dx + dy * dy);
    // 命中判定：距离中心在 radius ± 30 范围，最接近的轴
    if (dist < 10 || dist > radius + 30) return;
    const ang = Math.atan2(dy, dx);
    const n = enabledParams.length;
    const step = (2 * Math.PI) / n;
    let axis = Math.round((ang + Math.PI / 2) / step);
    axis = ((axis % n) + n) % n;
    const p = enabledParams[axis];
    if (!p) return;
    const last = optValuesHistory[optValuesHistory.length - 1] || [];
    const curV = last[axis];
    const ov = optOverrides.get(p.id);
    const lo = ov ? ov.min : p.suggested_min;
    const hi = ov ? ov.max : p.suggested_max;
    optDrawRadar();
    drawRadarHighlightAxis(canvas, meta, axis);
    showTooltip(canvas, `
      <b>#${axis + 1} ${extractSkill(p.rule_preview)} · ${p.key}${p.op}</b><br>
      <span style="color:#8b949e">默认</span> ${formatNum(p.original, p.kind)}<br>
      <span style="color:#c9a847">当前最优</span> ${curV == null ? '—' : formatNum(curV, p.kind)}<br>
      <span style="color:#8b949e">搜索区间</span> [${formatNum(lo, p.kind)}, ${formatNum(hi, p.kind)}]
    `);
  }
}

function drawCrosshairConv(canvas, meta, pt) {
  const ctx = canvas.getContext('2d');
  const { pad, plotH, xMin, xMax, yMin, yRange, plotW } = meta;
  const x = pad.l + (pt.gen - xMin) / Math.max(1, xMax - xMin) * plotW;
  const yBest = pad.t + (1 - (pt.best - yMin) / yRange) * plotH;
  ctx.strokeStyle = 'rgba(240,198,116,0.55)';
  ctx.setLineDash([3, 3]);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + 0.5, pad.t); ctx.lineTo(x + 0.5, pad.t + plotH);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = '#c9a847';
  ctx.beginPath(); ctx.arc(x, yBest, 3, 0, Math.PI * 2); ctx.fill();
}

function drawCrosshairDiv(canvas, meta, idx) {
  const ctx = canvas.getContext('2d');
  const { pad, plotW, plotH, genList } = meta;
  if (!genList.length) return;
  const x = pad.l + idx / Math.max(1, genList.length - 1) * plotW;
  ctx.strokeStyle = 'rgba(240,198,116,0.55)';
  ctx.setLineDash([3, 3]);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + 0.5, pad.t); ctx.lineTo(x + 0.5, pad.t + plotH);
  ctx.stroke();
  ctx.setLineDash([]);
}

function drawRadarHighlightAxis(canvas, meta, axis) {
  const ctx = canvas.getContext('2d');
  const { cx, cy, radius, enabledParams } = meta;
  const n = enabledParams.length;
  const ang = -Math.PI / 2 + axis * 2 * Math.PI / n;
  ctx.strokeStyle = 'rgba(240,198,116,0.7)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.cos(ang) * radius, cy + Math.sin(ang) * radius);
  ctx.stroke();
}

