// ═════════════════════════════════════════════════════════════════════════
// RL 训练 tab
// ═════════════════════════════════════════════════════════════════════════

let rlEventSource = null;
const rlChartData = { steps: [], dps: [], ret: [] };

// ── Eval rollout 历史 ──
const rlEvalHistory = [];
let rlEvalIndex = -1;

function rlEvalHistoryPush(ev) {
  rlEvalHistory.push(ev);
  // 内存保护：最多 200 条
  if (rlEvalHistory.length > 200) rlEvalHistory.shift();
  document.getElementById('rl_eval_count').textContent = rlEvalHistory.length;
  const slider = document.getElementById('rl_eval_slider');
  slider.max = rlEvalHistory.length - 1;
  const follow = document.getElementById('rl_eval_follow').checked;
  if (follow || rlEvalIndex < 0) {
    rlEvalIndex = rlEvalHistory.length - 1;
    slider.value = rlEvalIndex;
    rlEvalShow(rlEvalIndex);
  }
}

function rlEvalShow(i) {
  if (i < 0 || i >= rlEvalHistory.length) return;
  rlEvalIndex = i;
  const ev = rlEvalHistory[i];
  document.getElementById('rl_eval_slider').value = i;
  document.getElementById('rl_eval_at').textContent =
    'update ' + ev.update + ' / step ' + ev.global_step.toLocaleString() +
    '  (' + (i + 1) + '/' + rlEvalHistory.length + ')';
  document.getElementById('rl_eval_dps').textContent = Math.round(ev.dps).toLocaleString();
  document.getElementById('rl_eval_total').textContent = Math.round(ev.total_damage).toLocaleString();
  document.getElementById('rl_eval_fight').textContent = ev.fight_time.toFixed(2) + 's';
  document.getElementById('rl_eval_skills').textContent = ev.skill_count;
  renderTimeline(ev.timeline || [], {
    trackEl: document.getElementById('rl_eval_track'),
    scrollEl: document.getElementById('rl_eval_scroll'),
  });
}

function rlEvalPrev() {
  document.getElementById('rl_eval_follow').checked = false;
  rlEvalShow(Math.max(0, rlEvalIndex - 1));
}
function rlEvalNext() {
  document.getElementById('rl_eval_follow').checked = false;
  rlEvalShow(Math.min(rlEvalHistory.length - 1, rlEvalIndex + 1));
}
function rlEvalClearHistory() {
  rlEvalHistory.length = 0;
  rlEvalIndex = -1;
  document.getElementById('rl_eval_count').textContent = '0';
  document.getElementById('rl_eval_slider').max = 0;
  document.getElementById('rl_eval_slider').value = 0;
  ['at', 'dps', 'total', 'fight', 'skills'].forEach(k => {
    document.getElementById('rl_eval_' + k).textContent = '—';
  });
  const track = document.getElementById('rl_eval_track');
  if (track) track.innerHTML = '';
}

// 实时提交 eval_every / eval_duration（训练中也能改）
let rlRuntimeParamsTimer = null;
function rlRuntimeParamsPush() {
  clearTimeout(rlRuntimeParamsTimer);
  rlRuntimeParamsTimer = setTimeout(async () => {
    const body = {
      eval_every: parseInt(document.getElementById('rl_eval_every').value) || 0,
      eval_duration: parseFloat(document.getElementById('rl_eval_duration').value) || 60,
    };
    try {
      const res = await fetch('/api/rl/train/params', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (res.ok) rlAppendLog('[runtime] 已提交 eval_every=' + body.eval_every + ' eval_duration=' + body.eval_duration + 's（下个 update 生效）');
    } catch (_) {}
  }, 300);
}
document.getElementById('rl_eval_every').addEventListener('input', rlRuntimeParamsPush);
document.getElementById('rl_eval_duration').addEventListener('input', rlRuntimeParamsPush);

// 切换 RL tab 时拉当前 runtime params 回填
(function() {
  const origTabHandler = document.querySelectorAll('.tab');
  origTabHandler.forEach(tab => {
    if (tab.dataset.page !== 'page-rl') return;
    tab.addEventListener('click', async () => {
      try {
        const r = await fetch('/api/rl/train/params');
        if (!r.ok) return;
        const p = await r.json();
        document.getElementById('rl_eval_every').value = p.eval_every;
        document.getElementById('rl_eval_duration').value = p.eval_duration;
      } catch (_) {}
    });
  });
})();

// 绑定（DOM 必须已在）
document.getElementById('rl_eval_prev').addEventListener('click', rlEvalPrev);
document.getElementById('rl_eval_next').addEventListener('click', rlEvalNext);
document.getElementById('rl_eval_clear').addEventListener('click', rlEvalClearHistory);
document.getElementById('rl_eval_slider').addEventListener('input', (e) => {
  document.getElementById('rl_eval_follow').checked = false;
  rlEvalShow(parseInt(e.target.value));
});
// 键盘快捷键：左右箭头（聚焦在 RL tab 时生效）
document.addEventListener('keydown', (e) => {
  const rlActive = document.getElementById('page-rl').classList.contains('active');
  if (!rlActive) return;
  if (document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName)) return;
  if (e.key === 'ArrowLeft') { rlEvalPrev(); e.preventDefault(); }
  else if (e.key === 'ArrowRight') { rlEvalNext(); e.preventDefault(); }
});

// 可选动作（与 backend rl/action.rs 的 ACTION_SKILLS 对齐；None 槽不展示）
const RL_ACTION_CHOICES = [
  [1,'盾击'],[2,'盾猛'],[3,'盾压'],[4,'盾飞'],[5,'盾回'],
  [6,'盾刀'],[7,'斩刀'],[8,'绝刀'],[9,'劫刀'],[10,'闪刀'],
  [11,'血怒'],[12,'阵云结晦'],[13,'业火麟光'],[14,'撼地'],[17,'天下宏愿'],
];
function rlBuildAllowedActions() {
  const wrap = document.getElementById('rl_allowed_actions');
  if (!wrap || wrap.childElementCount) return;
  RL_ACTION_CHOICES.forEach(([id, name]) => {
    const lab = document.createElement('label');
    lab.className = 'rl-cb';
    lab.innerHTML = `<input type="checkbox" data-action="${id}" checked> ${name}`;
    wrap.appendChild(lab);
  });
  document.getElementById('rl_actions_all').addEventListener('click',
    () => wrap.querySelectorAll('input').forEach(i => i.checked = true));
  document.getElementById('rl_actions_none').addEventListener('click',
    () => wrap.querySelectorAll('input').forEach(i => i.checked = false));
}
function rlReadAllowedActions() {
  const wrap = document.getElementById('rl_allowed_actions');
  // 始终包含 0=等待
  const out = [0];
  wrap.querySelectorAll('input:checked').forEach(i => out.push(parseInt(i.dataset.action)));
  return out;
}
function rlApplyAllowedActions(arr) {
  if (!Array.isArray(arr)) return;
  const set = new Set(arr.map(x => +x));
  document.querySelectorAll('#rl_allowed_actions input').forEach(i => {
    i.checked = set.has(parseInt(i.dataset.action));
  });
}
rlBuildAllowedActions();

function rlReadForm() {
  const num = (id, fallback = 0) => {
    const v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? fallback : v;
  };
  const numI = (id, fallback = 0) => {
    const v = parseInt(document.getElementById(id).value);
    return isNaN(v) ? fallback : v;
  };
  const baselineRaw = document.getElementById('rl_baseline_dps').value.trim();
  return {
    attributes: getAttrs(),
    target: getTarget(),
    talents: getSelectedTalents(),
    recipes: getSelectedRecipes(),
    duration: num('rl_duration', 60),
    haste_level: getAttrs().haste_level,
    initial_rage: numI('rl_initial_rage', 0),
    network_delay: numI('rl_network_delay', 0),
    baseline_dps: baselineRaw === '' ? null : parseFloat(baselineRaw),
    total_steps: numI('rl_total_steps', 500000),
    n_envs: numI('rl_n_envs', 8),
    n_steps: numI('rl_n_steps', 2048),
    n_epochs: numI('rl_n_epochs', 10),
    minibatch_size: numI('rl_minibatch', 512),
    lr: num('rl_lr', 3e-4),
    gamma: num('rl_gamma', 0.999),
    ent_coef: num('rl_ent_coef', 0.01),
    save_every: numI('rl_save_every', 20),
    device: document.getElementById('rl_device').value,
    allowed_actions: rlReadAllowedActions(),
  };
}

function rlSetState(text, cls) {
  const el = document.getElementById('rl_state');
  el.textContent = text;
  el.className = 'rl-state ' + (cls || '');
}

function rlAppendLog(line, kind) {
  const log = document.getElementById('rl_log');
  const div = document.createElement('div');
  div.className = 'log-line log-' + (kind || 'event');
  const ts = new Date().toLocaleTimeString();
  div.textContent = '[' + ts + '] ' + line;
  log.appendChild(div);
  log.scrollTop = log.scrollHeight;
  while (log.children.length > 500) log.removeChild(log.firstChild);
}

function rlClearMetrics() {
  ['step', 'update', 'sps', 'elapsed', 'ret', 'dps', 'pg', 'v', 'ent', 'kl'].forEach(k => {
    const el = document.getElementById('rl_m_' + k);
    if (el) el.textContent = '—';
  });
  rlChartData.steps.length = 0;
  rlChartData.dps.length = 0;
  rlChartData.ret.length = 0;
  rlDrawChart();
}

// 异常检测阈值：返回 "ok" / "warn" / "bad" / ""
const rlHealth = {
  sps: (v) => v < 200 ? 'bad' : (v < 400 ? 'warn' : 'ok'),
  pg: (v) => Math.abs(v) > 0.1 ? 'bad' : (Math.abs(v) > 0.03 ? 'warn' : ''),
  v: (v) => v > 10 ? 'bad' : (v > 1 ? 'warn' : ''),
  ent: (v) => v < 0.05 ? 'bad' : (v < 0.3 ? 'warn' : ''),  // 18 动作时熵上限 ln(18)≈2.89
  kl: (v) => v > 0.05 ? 'bad' : (v > 0.025 ? 'warn' : ''),
  dps: (v, ctx) => {
    // 长时间卡 0 预警（>= 50 个 episode 仍 0）
    if (v === 0 && ctx.n_episodes >= 50) return 'bad';
    if (v === 0 && ctx.n_episodes >= 20) return 'warn';
    return v > 0 ? 'ok' : '';
  },
};

function rlApplyHealth(metricId, cls) {
  const el = document.getElementById('rl_mc_' + metricId);
  if (!el) return;
  el.classList.remove('ok', 'warn', 'bad');
  if (cls) el.classList.add(cls);
}

function rlUpdateMetrics(ev) {
  const step = ev.global_step != null ? ev.global_step.toLocaleString() : '—';
  document.getElementById('rl_m_step').textContent = step;
  document.getElementById('rl_m_update').textContent = (ev.update || '?') + '/' + (ev.total_updates || '?');
  const sps = ev.sps;
  document.getElementById('rl_m_sps').textContent = sps ? sps.toFixed(0) : '—';
  if (sps != null) rlApplyHealth('sps', rlHealth.sps(sps));
  document.getElementById('rl_m_elapsed').textContent = ev.elapsed ? ev.elapsed.toFixed(1) + 's' : '—';
  document.getElementById('rl_m_ret').textContent = ev.ep_return_mean != null ? ev.ep_return_mean.toFixed(2) : '—';
  const dpsMean = ev.ep_dps_mean;
  // 区分 null（还没完整 episode）和 0（有 episode 但 dps=0，策略 collapse）
  document.getElementById('rl_m_dps').textContent = dpsMean != null ? Math.round(dpsMean).toLocaleString() : '—';
  if (dpsMean != null) rlApplyHealth('dps', rlHealth.dps(dpsMean, { n_episodes: ev.n_completed_episodes || 0 }));

  const m = ev.metrics || {};
  const pg = m['loss/policy'];
  const v  = m['loss/value'];
  const ent = m['loss/entropy'];
  const kl = m['stats/approx_kl'];
  document.getElementById('rl_m_pg').textContent = pg != null ? pg.toFixed(4) : '—';
  document.getElementById('rl_m_v').textContent = v != null ? v.toFixed(4) : '—';
  document.getElementById('rl_m_ent').textContent = ent != null ? ent.toFixed(4) : '—';
  document.getElementById('rl_m_kl').textContent = kl != null ? kl.toFixed(4) : '—';
  if (pg != null) rlApplyHealth('pg', rlHealth.pg(pg));
  if (v != null) rlApplyHealth('v', rlHealth.v(v));
  if (ent != null) rlApplyHealth('ent', rlHealth.ent(ent));
  if (kl != null) rlApplyHealth('kl', rlHealth.kl(kl));

  rlChartData.steps.push(ev.global_step || 0);
  rlChartData.dps.push(ev.ep_dps_mean || 0);
  rlChartData.ret.push(ev.ep_return_mean || 0);
  if (rlChartData.steps.length > 500) {
    rlChartData.steps.shift();
    rlChartData.dps.shift();
    rlChartData.ret.shift();
  }
  rlDrawChart();
}

function rlDrawChart() {
  const c = document.getElementById('rl_chart');
  if (!c) return;
  const ctx = c.getContext('2d');
  // 按 devicePixelRatio 缩放，避免高 DPI 下模糊
  const dpr = window.devicePixelRatio || 1;
  const cssW = c.clientWidth;
  const cssH = 240;
  c.style.height = cssH + 'px';
  c.width = Math.round(cssW * dpr);
  c.height = Math.round(cssH * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const w = cssW;
  const h = cssH;
  ctx.clearRect(0, 0, w, h);
  if (rlChartData.steps.length < 2) return;

  const padL = 60, padR = 60, padT = 16, padB = 24;
  const innerW = w - padL - padR;
  const innerH = h - padT - padB;

  const xMin = rlChartData.steps[0];
  const xMax = rlChartData.steps[rlChartData.steps.length - 1];
  const xs = i => padL + (rlChartData.steps[i] - xMin) / Math.max(xMax - xMin, 1) * innerW;

  const dpsMin = Math.min(...rlChartData.dps);
  const dpsMax = Math.max(...rlChartData.dps);
  const dpsRange = Math.max(dpsMax - dpsMin, 1);
  const retMin = Math.min(...rlChartData.ret);
  const retMax = Math.max(...rlChartData.ret);
  const retRange = Math.max(retMax - retMin, 1);
  const ydps = i => padT + (1 - (rlChartData.dps[i] - dpsMin) / dpsRange) * innerH;
  const yret = i => padT + (1 - (rlChartData.ret[i] - retMin) / retRange) * innerH;

  ctx.strokeStyle = '#2a2f37';
  ctx.lineWidth = 1;
  for (let g = 0; g <= 4; g++) {
    const y = padT + g * innerH / 4;
    ctx.beginPath();
    ctx.moveTo(padL, y);
    ctx.lineTo(padL + innerW, y);
    ctx.stroke();
  }

  ctx.strokeStyle = '#3fb950';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = 0; i < rlChartData.steps.length; i++) {
    const x = xs(i), y = ydps(i);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();

  ctx.strokeStyle = '#c9a847';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = 0; i < rlChartData.steps.length; i++) {
    const x = xs(i), y = yret(i);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();

  ctx.fillStyle = '#888';
  ctx.font = '11px sans-serif';
  ctx.textAlign = 'right';
  ctx.fillText(Math.round(dpsMax).toLocaleString(), padL - 4, padT + 10);
  ctx.fillText(Math.round(dpsMin).toLocaleString(), padL - 4, padT + innerH);
  ctx.fillStyle = '#3fb950';
  ctx.textAlign = 'left';
  ctx.fillText('DPS', padL + 6, padT + 12);
  ctx.fillStyle = '#c9a847';
  ctx.fillText('return', padL + 50, padT + 12);
  ctx.fillStyle = '#888';
  ctx.fillText(retMin.toFixed(1), padL + innerW + 6, padT + innerH);
  ctx.fillText(retMax.toFixed(1), padL + innerW + 6, padT + 10);
  ctx.textAlign = 'center';
  ctx.fillText('step ' + xMin.toLocaleString(), padL + 30, h - 6);
  ctx.fillText(xMax.toLocaleString(), padL + innerW - 30, h - 6);
}

async function rlStart() {
  const body = rlFullConfig();
  const stagesNote = body.stages.length ? ' stages=' + body.stages.length : '';
  const resumeNote = body.resume ? ' resume=' + body.resume.split(/[\\/]/).slice(-2).join('/') : '';
  rlAppendLog('POST /api/rl/train/start total=' + body.total_steps + ' envs=' + body.n_envs + ' dur=' + body.duration + 's device=' + body.device + stagesNote + resumeNote);
  try {
    const res = await fetch('/api/rl/train/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      rlAppendLog('启动失败: ' + (err.error || res.statusText), 'error');
      rlSetState('启动失败', 'error');
      return;
    }
    const j = await res.json();
    rlAppendLog('run_id=' + j.run_id + '  spec=' + j.spec_path);
    rlClearMetrics();
    rlSetState('运行中 ' + j.run_id, 'running');
    document.getElementById('rl_start_btn').disabled = true;
    document.getElementById('rl_stop_btn').disabled = false;
    rlConnectStream();
  } catch (e) {
    rlAppendLog('异常: ' + e.message, 'error');
    rlSetState('异常', 'error');
  }
}

async function rlStop() {
  rlAppendLog('POST /api/rl/train/stop');
  rlSetState('停止中…', 'error');
  document.getElementById('rl_stop_btn').disabled = true;
  try {
    const res = await fetch('/api/rl/train/stop', { method: 'POST' });
    const j = await res.json();
    rlAppendLog('stopped=' + j.stopped + ' killed=' + j.killed);
    if (j.stopped) {
      // 兜底：10 秒内若未收到 exit 事件也强制复原 UI
      setTimeout(() => {
        if (document.getElementById('rl_state').textContent === '停止中…') {
          rlSetState('已停止（超时兜底）', '');
          document.getElementById('rl_start_btn').disabled = false;
          if (rlEventSource) { rlEventSource.close(); rlEventSource = null; }
        }
      }, 10000);
    }
  } catch (e) {
    rlAppendLog('stop 异常: ' + e.message, 'error');
    document.getElementById('rl_stop_btn').disabled = false;
  }
}

function rlConnectStream() {
  if (rlEventSource) { rlEventSource.close(); rlEventSource = null; }
  const es = new EventSource('/api/rl/train/stream');
  rlEventSource = es;
  es.onmessage = (msg) => {
    let ev;
    try { ev = JSON.parse(msg.data); } catch (_) { return; }
    switch (ev.event) {
      case 'start':
        rlAppendLog('[start] obs_dim=' + ev.obs_dim + ' actions=' + ev.action_count + ' params=' + ev.n_params + ' run=' + ev.run_id);
        break;
      case 'stage_start':
        rlAppendLog('[stage ' + ev.index + '/' + ev.total + '] ' + ev.name + ' duration=' + ev.duration + 's steps=' + ev.total_steps + ' lr=' + ev.lr + (ev.resume ? ' resume=' + ev.resume.split(/[\\/]/).slice(-3).join('/') : ''), 'update');
        rlSetState('运行中 阶段 ' + ev.index + '/' + ev.total + ' ' + ev.name, 'running');
        break;
      case 'curriculum_done':
        rlAppendLog('[curriculum_done] final=' + ev.final_ckpt, 'update');
        rlSetState('课程完成', '');
        document.getElementById('rl_start_btn').disabled = false;
        document.getElementById('rl_stop_btn').disabled = true;
        break;
      case 'stage_abort':
        rlAppendLog('[stage_abort] ' + ev.name + ' 中止', 'error');
        break;
      case 'rollout_begin':
        rlAppendLog('[rollout] update ' + ev.update + '/' + ev.total_updates + ' 开始采样 ' + ev.n_steps + ' 步');
        break;
      case 'rollout_progress':
        rlAppendLog('[rollout] step ' + ev.step + '/' + ev.n_steps + ' elapsed=' + ev.elapsed.toFixed(1) + 's sel=' + ev.sel_ms.toFixed(1) + 'ms http=' + ev.http_ms.toFixed(1) + 'ms');
        break;
      case 'eval_rollout':
        rlAppendLog('[eval] update ' + ev.update + ' DPS=' + Math.round(ev.dps).toLocaleString() + ' skills=' + ev.skill_count + ' (' + ev.eval_elapsed.toFixed(1) + 's)', 'update');
        rlEvalHistoryPush(ev);
        break;
      case 'runtime_params':
        rlAppendLog('[runtime] eval_every ' + ev.prev_eval_every + '→' + ev.eval_every + ' eval_duration ' + ev.prev_eval_duration + 's→' + ev.eval_duration + 's', 'update');
        break;
      case 'phase':
        rlAppendLog('[phase] ' + ev.name + (ev.index != null ? ' #' + ev.index : '') + (ev.elapsed != null ? ' ' + ev.elapsed.toFixed(2) + 's' : '') + (ev.n != null ? ' n=' + ev.n : ''));
        break;
      case 'update':
        rlUpdateMetrics(ev);
        break;
      case 'episode':
        break;
      case 'checkpoint':
        rlAppendLog('[ckpt] step=' + ev.step + ' → ' + ev.path, 'update');
        break;
      case 'done':
        rlAppendLog('[done] final=' + ev.final_ckpt + ' elapsed=' + (ev.elapsed != null ? ev.elapsed.toFixed(1) : '?') + 's best_dps=' + Math.round(ev.best_dps || 0), 'update');
        rlSetState('已完成', '');
        document.getElementById('rl_start_btn').disabled = false;
        document.getElementById('rl_stop_btn').disabled = true;
        break;
      case 'exit':
        rlAppendLog('[exit] code=' + ev.exit_code, ev.exit_code === 0 ? 'event' : 'error');
        rlSetState('已停止', '');
        document.getElementById('rl_start_btn').disabled = false;
        document.getElementById('rl_stop_btn').disabled = true;
        if (rlEventSource) { rlEventSource.close(); rlEventSource = null; }
        break;
      case 'error':
        rlAppendLog('[error] ' + ev.message, 'error');
        rlSetState('错误', 'error');
        break;
      case 'log':
        rlAppendLog(ev.line, 'event');
        break;
      case 'raw':
        rlAppendLog('[raw] ' + ev.line);
        break;
    }
  };
  es.onerror = () => {
    rlAppendLog('SSE 连接断开（自动重连中）', 'error');
  };
}

async function rlPollStatus() {
  try {
    const res = await fetch('/api/rl/train/status');
    if (!res.ok) return;
    const s = await res.json();
    if (s.running) {
      rlSetState('运行中 ' + s.run_id, 'running');
      document.getElementById('rl_start_btn').disabled = true;
      document.getElementById('rl_stop_btn').disabled = false;
      if (s.last_event) rlUpdateMetrics(s.last_event);
      if (!rlEventSource) rlConnectStream();
    }
  } catch (_) {}
}

document.getElementById('rl_start_btn').addEventListener('click', rlStart);
document.getElementById('rl_stop_btn').addEventListener('click', rlStop);

document.querySelectorAll('.tab').forEach(tab => {
  tab.addEventListener('click', () => {
    if (tab.dataset.page === 'page-rl') {
      rlPollStatus();
      rlRefreshRuns();
      bcPollStatus();
    }
  });
});

// ═════════════════════════════════════════════════════════════════════════
// BC 行为克隆预训练
// ═════════════════════════════════════════════════════════════════════════
let bcEventSource = null;

function bcLog(line, kind) {
  const log = document.getElementById('bc_log');
  const div = document.createElement('div');
  div.className = 'log-line log-' + (kind || 'event');
  const ts = new Date().toLocaleTimeString();
  div.textContent = '[' + ts + '] ' + line;
  log.appendChild(div);
  log.scrollTop = log.scrollHeight;
  while (log.children.length > 200) log.removeChild(log.firstChild);
}
function bcSetState(text, cls) {
  const el = document.getElementById('bc_state');
  el.textContent = text;
  el.className = 'rl-state ' + (cls || '');
}

async function bcStart() {
  const macro = document.getElementById('bc_macro').value.trim();
  if (!macro) { alert('请填宏文本'); return; }
  const numI = (id, fb) => { const v = parseInt(document.getElementById(id).value); return isNaN(v) ? fb : v; };
  const num = (id, fb) => { const v = parseFloat(document.getElementById(id).value); return isNaN(v) ? fb : v; };
  const body = {
    macro_text: macro,
    attributes: getAttrs(),
    target: getTarget(),
    talents: getSelectedTalents(),
    recipes: getSelectedRecipes(),
    duration: num('bc_duration', 120),
    haste_level: getAttrs().haste_level,
    initial_rage: 0,
    network_delay: 0,
    n_envs: numI('bc_n_envs', 4),
    n_samples: numI('bc_n_samples', 50000),
    n_epochs: numI('bc_n_epochs', 10),
    batch_size: numI('bc_batch', 512),
    lr: num('bc_lr', 0.001),
    hidden: 256,
    device: document.getElementById('bc_device').value,
  };
  bcLog('POST /api/rl/pretrain/start n_samples=' + body.n_samples + ' epochs=' + body.n_epochs);
  try {
    const res = await fetch('/api/rl/pretrain/start', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      bcLog('启动失败: ' + (err.error || res.statusText), 'error');
      bcSetState('失败', 'error');
      return;
    }
    const j = await res.json();
    bcLog('run_id=' + j.run_id);
    bcSetState('运行中 ' + j.run_id, 'running');
    document.getElementById('bc_start_btn').disabled = true;
    document.getElementById('bc_stop_btn').disabled = false;
    bcConnectStream();
  } catch (e) { bcLog('异常: ' + e.message, 'error'); }
}

async function bcStop() {
  bcSetState('停止中…', 'error');
  document.getElementById('bc_stop_btn').disabled = true;
  try {
    const res = await fetch('/api/rl/pretrain/stop', { method: 'POST' });
    const j = await res.json();
    bcLog('stopped=' + j.stopped + ' killed=' + j.killed);
  } catch (e) { bcLog('stop 异常: ' + e.message, 'error'); }
}

function bcConnectStream() {
  if (bcEventSource) { bcEventSource.close(); bcEventSource = null; }
  const es = new EventSource('/api/rl/pretrain/stream');
  bcEventSource = es;
  es.onmessage = (msg) => {
    let ev;
    try { ev = JSON.parse(msg.data); } catch (_) { return; }
    switch (ev.event) {
      case 'start':
        bcLog('[start] obs_dim=' + ev.obs_dim + ' actions=' + ev.action_count + ' n_samples=' + ev.n_samples + ' epochs=' + ev.n_epochs);
        document.getElementById('bc_phase').textContent = '初始化';
        break;
      case 'phase':
        document.getElementById('bc_phase').textContent = ev.name;
        if (ev.name === 'collect_done') {
          document.getElementById('bc_samples').textContent = ev.n_samples.toLocaleString();
          bcLog('[collect] 完成 ' + ev.n_samples + ' 样本 / ' + ev.n_episodes + ' episode', 'update');
        } else if (ev.name === 'collect_begin') {
          bcLog('[collect] 开始采集 (每 env ' + ev.per_env + ' 条)');
        } else if (ev.name === 'train_begin') {
          bcLog('[train] 开始监督学习 ' + ev.n_samples + ' 样本');
        } else if (ev.name === 'train_done') {
          bcLog('[train] 完成', 'update');
        }
        break;
      case 'action_distribution':
        const top5 = Object.entries(ev.dist).slice(0, 5).map(([n, c]) => n + '=' + c).join(' ');
        bcLog('[宏动作分布 top5] ' + top5);
        break;
      case 'train_progress':
        document.getElementById('bc_epoch').textContent = ev.epoch + '/' + ev.total_epochs;
        document.getElementById('bc_loss').textContent = ev.loss.toFixed(4);
        document.getElementById('bc_acc').textContent = (ev.top1_acc * 100).toFixed(1) + '%';
        bcLog('[epoch ' + ev.epoch + '/' + ev.total_epochs + '] loss=' + ev.loss.toFixed(4) + ' top1=' + (ev.top1_acc * 100).toFixed(1) + '%');
        break;
      case 'checkpoint':
        bcLog('[ckpt] → ' + ev.path, 'update');
        break;
      case 'done':
        bcLog('[done] ckpt=' + ev.ckpt + ' 准确率达成', 'update');
        bcSetState('完成', '');
        document.getElementById('bc_start_btn').disabled = false;
        document.getElementById('bc_stop_btn').disabled = true;
        // 刷新续训下拉，让新 ckpt 出现
        rlRefreshRuns();
        break;
      case 'exit':
        bcLog('[exit] code=' + ev.exit_code, ev.exit_code === 0 ? 'event' : 'error');
        if (document.getElementById('bc_state').textContent !== '完成') {
          bcSetState('已退出', '');
        }
        document.getElementById('bc_start_btn').disabled = false;
        document.getElementById('bc_stop_btn').disabled = true;
        if (bcEventSource) { bcEventSource.close(); bcEventSource = null; }
        break;
      case 'error':
        bcLog('[error] ' + ev.message, 'error');
        bcSetState('错误', 'error');
        break;
      case 'log':
        bcLog(ev.line);
        break;
    }
  };
  es.onerror = () => bcLog('SSE 断开', 'error');
}

async function bcPollStatus() {
  try {
    const res = await fetch('/api/rl/pretrain/status');
    if (!res.ok) return;
    const s = await res.json();
    if (s.running) {
      bcSetState('运行中 ' + s.run_id, 'running');
      document.getElementById('bc_start_btn').disabled = true;
      document.getElementById('bc_stop_btn').disabled = false;
      if (!bcEventSource) bcConnectStream();
    }
  } catch (_) {}
}

document.getElementById('bc_start_btn').addEventListener('click', bcStart);
document.getElementById('bc_stop_btn').addEventListener('click', bcStop);
document.getElementById('bc_macro_from_sim').addEventListener('click', () => {
  try {
    const t = (typeof buildMacroText === 'function') ? buildMacroText() : '';
    if (t) document.getElementById('bc_macro').value = t;
    else alert('循环模拟页未填宏');
  } catch (e) { alert(e.message); }
});

// 让 RL ckpt 列表也包含 BC 产物
async function bcRefreshRunsAddon() {
  try {
    const res = await fetch('/api/rl/pretrain/list');
    if (!res.ok) return;
    const j = await res.json();
    const sel = document.getElementById('rl_resume_select');
    if (!sel) return;
    for (const run of (j.runs || [])) {
      const opt = document.createElement('option');
      opt.value = run.ckpt_path;
      const sizeMB = (run.size / 1024 / 1024).toFixed(1);
      opt.textContent = '[BC] ' + run.run_id + '/pretrained.pt  (' + sizeMB + 'MB)';
      sel.appendChild(opt);
    }
  } catch (_) {}
}

// ── 续训 ckpt 列表 ──
async function rlRefreshRuns() {
  try {
    const res = await fetch('/api/rl/train/runs');
    if (!res.ok) return;
    const j = await res.json();
    const sel = document.getElementById('rl_resume_select');
    const cur = sel.value;
    sel.innerHTML = '<option value="">不续训（从头开始）</option>';
    for (const run of j.runs || []) {
      for (const ck of run.ckpts || []) {
        const opt = document.createElement('option');
        opt.value = ck.path;
        const sizeMB = (ck.size / 1024 / 1024).toFixed(1);
        opt.textContent = `${run.run_id} / ${ck.name}  (${sizeMB}MB)`;
        sel.appendChild(opt);
      }
    }
    // 追加 BC 预训练产物
    await bcRefreshRunsAddon();
    if (cur) sel.value = cur;
  } catch (e) {
    rlAppendLog('刷新 ckpt 列表失败: ' + e.message, 'error');
  }
}
document.getElementById('rl_runs_refresh').addEventListener('click', rlRefreshRuns);

// ── 课程学习 stage 编辑器 ──
function rlAddStage(initial) {
  const wrap = document.getElementById('rl_stages');
  const row = document.createElement('div');
  row.className = 'rl-stage';
  row.innerHTML = `
    <label class="name-input">名称<input data-k="name" value="${initial?.name ?? 'stage'}"></label>
    <label>时长(s)<input data-k="duration" type="number" value="${initial?.duration ?? 30}"></label>
    <label>总步数<input data-k="total_steps" type="number" value="${initial?.total_steps ?? 200000}"></label>
    <label>lr<input data-k="lr" type="number" step="0.0001" value="${initial?.lr ?? 0.0003}"></label>
    <label>ent_coef<input data-k="ent_coef" type="number" step="0.005" value="${initial?.ent_coef ?? 0.01}"></label>
    <label>baseline_dps<input data-k="baseline_dps" type="number" placeholder="可空" value="${initial?.baseline_dps ?? ''}"></label>
    <button class="x-btn" title="删除">×</button>
  `;
  row.querySelector('.x-btn').addEventListener('click', () => row.remove());
  wrap.appendChild(row);
}
function rlReadStages() {
  const rows = document.querySelectorAll('#rl_stages .rl-stage');
  return Array.from(rows).map(r => {
    const obj = {};
    r.querySelectorAll('input').forEach(inp => {
      const k = inp.dataset.k;
      const v = inp.value.trim();
      if (v === '') return;
      if (inp.type === 'number') obj[k] = parseFloat(v);
      else obj[k] = v;
    });
    return obj;
  });
}
document.getElementById('rl_stage_add').addEventListener('click', () => rlAddStage());
document.getElementById('rl_stage_preset').addEventListener('click', () => {
  document.getElementById('rl_stages').innerHTML = '';
  rlAddStage({ name: 'warmup_30s', duration: 30, total_steps: 1000000, lr: 0.0003, ent_coef: 0.02 });
  rlAddStage({ name: 'mid_120s', duration: 120, total_steps: 3000000, lr: 0.0002, ent_coef: 0.01 });
  rlAddStage({ name: 'final_300s', duration: 300, total_steps: 5000000, lr: 0.0001, ent_coef: 0.005 });
});

// ── 配置导出导入（JSON 文件 + localStorage）──
function rlFullConfig() {
  const numI = (id, fb) => { const v = parseInt(document.getElementById(id).value); return isNaN(v) ? fb : v; };
  const num = (id, fb) => { const v = parseFloat(document.getElementById(id).value); return isNaN(v) ? fb : v; };
  return {
    ...rlReadForm(),
    stages: rlReadStages(),
    resume: document.getElementById('rl_resume_select').value || null,
    reset_optimizer: document.getElementById('rl_reset_optim').checked,
    eval_every: numI('rl_eval_every', 10),
    eval_duration: num('rl_eval_duration', 60),
  };
}
function rlApplyConfig(cfg) {
  const setIf = (id, v) => { if (v != null) document.getElementById(id).value = v; };
  setIf('rl_total_steps', cfg.total_steps);
  setIf('rl_n_envs', cfg.n_envs);
  setIf('rl_n_steps', cfg.n_steps);
  setIf('rl_n_epochs', cfg.n_epochs);
  setIf('rl_minibatch', cfg.minibatch_size);
  setIf('rl_lr', cfg.lr);
  setIf('rl_gamma', cfg.gamma);
  setIf('rl_ent_coef', cfg.ent_coef);
  setIf('rl_save_every', cfg.save_every);
  setIf('rl_duration', cfg.duration);
  setIf('rl_initial_rage', cfg.initial_rage);
  setIf('rl_network_delay', cfg.network_delay);
  setIf('rl_baseline_dps', cfg.baseline_dps == null ? '' : cfg.baseline_dps);
  if (cfg.device) document.getElementById('rl_device').value = cfg.device;
  document.getElementById('rl_reset_optim').checked = !!cfg.reset_optimizer;
  // 注意：attributes/target/talents/recipes 不写回，由"基础设置"页主导
  document.getElementById('rl_stages').innerHTML = '';
  (cfg.stages || []).forEach(s => rlAddStage(s));
  if (cfg.allowed_actions) rlApplyAllowedActions(cfg.allowed_actions);
}
document.getElementById('rl_cfg_export').addEventListener('click', () => {
  const blob = new Blob([JSON.stringify(rlFullConfig(), null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `rl_config_${Date.now()}.json`;
  a.click();
  URL.revokeObjectURL(url);
  rlAppendLog('配置已导出');
});
document.getElementById('rl_cfg_import').addEventListener('click', () => {
  document.getElementById('rl_cfg_file').click();
});
document.getElementById('rl_cfg_file').addEventListener('change', async (e) => {
  const f = e.target.files[0];
  if (!f) return;
  try {
    const text = await f.text();
    const cfg = JSON.parse(text);
    rlApplyConfig(cfg);
    rlAppendLog('已导入配置: ' + f.name);
  } catch (err) {
    rlAppendLog('导入失败: ' + err.message, 'error');
  }
  e.target.value = '';
});
document.getElementById('rl_cfg_save_local').addEventListener('click', () => {
  localStorage.setItem('jx3_rl_config', JSON.stringify(rlFullConfig()));
  rlAppendLog('已保存到浏览器 localStorage');
});
document.getElementById('rl_cfg_load_local').addEventListener('click', () => {
  const raw = localStorage.getItem('jx3_rl_config');
  if (!raw) { rlAppendLog('localStorage 无保存的配置', 'error'); return; }
  try {
    rlApplyConfig(JSON.parse(raw));
    rlAppendLog('已从 localStorage 加载');
  } catch (e) {
    rlAppendLog('加载失败: ' + e.message, 'error');
  }
});

