let rlrunActionsPayload = null;

document.getElementById('rlrun_mode').addEventListener('change', (e) => {
  const isMacro = e.target.value === 'macro';
  document.getElementById('rlrun_macro_box').style.display = isMacro ? '' : 'none';
  document.getElementById('rlrun_actions_box').style.display = isMacro ? 'none' : '';
});
document.getElementById('rlrun_macro_from_sim').addEventListener('click', () => {
  try {
    const text = (typeof buildMacroText === 'function') ? buildMacroText() : '';
    if (text) {
      document.getElementById('rlrun_macro_text').value = text;
    } else {
      alert('循环模拟页未填宏');
    }
  } catch (e) { alert('导入失败: ' + e.message); }
});
document.getElementById('rlrun_actions_pick').addEventListener('click', () => {
  document.getElementById('rlrun_actions_file').click();
});
document.getElementById('rlrun_actions_file').addEventListener('change', async (e) => {
  const f = e.target.files[0];
  if (!f) return;
  try {
    const text = await f.text();
    rlrunActionsPayload = JSON.parse(text);
    const meta = document.getElementById('rlrun_actions_meta');
    const m = rlrunActionsPayload.meta || {};
    const n = (rlrunActionsPayload.actions || []).length;
    meta.textContent = `${f.name}  动作数=${n}` + (m.rl_dps ? `  RL DPS=${Math.round(m.rl_dps).toLocaleString()}` : '');
    if (rlrunActionsPayload.duration) document.getElementById('rlrun_duration').value = rlrunActionsPayload.duration;
    if (rlrunActionsPayload.initial_rage != null) document.getElementById('rlrun_initial_rage').value = rlrunActionsPayload.initial_rage;
    if (rlrunActionsPayload.network_delay != null) document.getElementById('rlrun_network_delay').value = rlrunActionsPayload.network_delay;
  } catch (err) {
    alert('解析失败: ' + err.message);
  }
  e.target.value = '';
});

async function rlrunExecute() {
  const mode = document.getElementById('rlrun_mode').value;
  const numI = (id, fb) => {
    const v = parseInt(document.getElementById(id).value);
    return isNaN(v) ? fb : v;
  };
  const baseBody = {
    attributes: getAttrs(),
    target: getTarget(),
    talents: getSelectedTalents(),
    recipes: getSelectedRecipes(),
    duration: parseFloat(document.getElementById('rlrun_duration').value) || 60,
    haste_level: getAttrs().haste_level,
    initial_rage: numI('rlrun_initial_rage', 0),
    network_delay: numI('rlrun_network_delay', 0),
  };
  let body;
  if (mode === 'macro') {
    const macro_text = document.getElementById('rlrun_macro_text').value.trim();
    if (!macro_text) { alert('请填宏文本'); return; }
    body = { ...baseBody, policy: { kind: 'macro', macro_text } };
  } else {
    if (!rlrunActionsPayload || !rlrunActionsPayload.actions) {
      alert('请先导入 rl_actions.json');
      return;
    }
    // 用导入的 attributes/target/talents/recipes 优先（保证一致性）
    if (rlrunActionsPayload.attributes) body = {
      ...baseBody,
      attributes: rlrunActionsPayload.attributes,
      target: rlrunActionsPayload.target || baseBody.target,
      talents: rlrunActionsPayload.talents || baseBody.talents,
      recipes: rlrunActionsPayload.recipes || baseBody.recipes,
    }; else body = baseBody;
    body = { ...body, policy: { kind: 'actions', actions: rlrunActionsPayload.actions } };
  }
  document.getElementById('rlrun_state').textContent = '执行中…';
  try {
    const res = await fetch('/api/rl/rollout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      document.getElementById('rlrun_state').textContent = '失败: ' + (err.error || res.statusText);
      return;
    }
    const j = await res.json();
    rlrunRender(j);
    document.getElementById('rlrun_state').textContent = '完成';
  } catch (e) {
    document.getElementById('rlrun_state').textContent = '异常: ' + e.message;
  }
}
document.getElementById('rlrun_run_btn').addEventListener('click', rlrunExecute);

// ═════════════════════════════════════════════════════════════════════════
// RL 分析 tab
// ═════════════════════════════════════════════════════════════════════════

let rlanaEventSource = null;

async function rlanaRefreshCkpts() {
  try {
    const res = await fetch('/api/rl/train/runs');
    if (!res.ok) return;
    const j = await res.json();
    const sel = document.getElementById('rlana_ckpt');
    const cur = sel.value;
    sel.innerHTML = '<option value="">（选择 ckpt）</option>';
    for (const run of j.runs || []) {
      for (const ck of run.ckpts || []) {
        const opt = document.createElement('option');
        opt.value = ck.path;
        const sizeMB = (ck.size / 1024 / 1024).toFixed(1);
        opt.textContent = `${run.run_id} / ${ck.name}  (${sizeMB}MB)`;
        sel.appendChild(opt);
      }
    }
    if (cur) sel.value = cur;
  } catch (e) {
    rlanaLog('刷新 ckpt 列表失败: ' + e.message, 'error');
  }
}

function rlanaLog(line, kind) {
  const log = document.getElementById('rlana_log');
  const div = document.createElement('div');
  div.className = 'log-line log-' + (kind || 'event');
  const ts = new Date().toLocaleTimeString();
  div.textContent = '[' + ts + '] ' + line;
  log.appendChild(div);
  log.scrollTop = log.scrollHeight;
  while (log.children.length > 400) log.removeChild(log.firstChild);
}

function rlanaSetState(text, cls) {
  const el = document.getElementById('rlana_state');
  el.textContent = text;
  el.className = 'rl-state ' + (cls || '');
}

async function rlanaStart() {
  const ckpt = document.getElementById('rlana_ckpt').value;
  if (!ckpt) { alert('请选 ckpt'); return; }
  const macro = document.getElementById('rlana_macro').value.trim();
  if (!macro) { alert('请贴宏文本'); return; }
  const body = {
    ckpt,
    macro_text: macro,
    attributes: getAttrs(),
    target: getTarget(),
    talents: getSelectedTalents(),
    recipes: getSelectedRecipes(),
    duration: parseFloat(document.getElementById('rlana_duration').value) || 300,
    haste_level: getAttrs().haste_level,
    initial_rage: parseInt(document.getElementById('rlana_initial_rage').value) || 0,
    network_delay: parseInt(document.getElementById('rlana_network_delay').value) || 0,
    device: document.getElementById('rlana_device').value,
  };
  rlanaLog('POST /api/rl/analyze/start ckpt=' + ckpt.split(/[\\/]/).slice(-3).join('/') + ' duration=' + body.duration);
  try {
    const res = await fetch('/api/rl/analyze/start', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      rlanaLog('启动失败: ' + (err.error || res.statusText), 'error');
      rlanaSetState('失败', 'error');
      return;
    }
    const j = await res.json();
    rlanaLog('run_id=' + j.run_id + ' out=' + j.out_dir);
    rlanaResetResults();
    rlanaSetState('运行中 ' + j.run_id, 'running');
    document.getElementById('rlana_start_btn').disabled = true;
    document.getElementById('rlana_stop_btn').disabled = false;
    rlanaConnectStream();
  } catch (e) {
    rlanaLog('异常: ' + e.message, 'error');
  }
}

async function rlanaStop() {
  rlanaSetState('停止中…', 'error');
  document.getElementById('rlana_stop_btn').disabled = true;
  try {
    const res = await fetch('/api/rl/analyze/stop', { method: 'POST' });
    const j = await res.json();
    rlanaLog('stopped=' + j.stopped + ' killed=' + j.killed);
    setTimeout(() => {
      if (document.getElementById('rlana_state').textContent === '停止中…') {
        rlanaSetState('已停止（超时兜底）', '');
        document.getElementById('rlana_start_btn').disabled = false;
        if (rlanaEventSource) { rlanaEventSource.close(); rlanaEventSource = null; }
      }
    }, 10000);
  } catch (e) { rlanaLog('stop 异常: ' + e.message, 'error'); }
}

function rlanaResetResults() {
  ['step', 'sim', 'cur_dps', 'disagree', 'rl_dps', 'macro_dps', 'delta', 'total_n'].forEach(k => {
    document.getElementById('rlana_' + k).textContent = '—';
  });
  document.querySelector('#rlana_patterns tbody').innerHTML = '';
}

function rlanaRenderResult(ev) {
  document.getElementById('rlana_rl_dps').textContent = Math.round(ev.rl_dps || 0).toLocaleString();
  document.getElementById('rlana_macro_dps').textContent = Math.round(ev.macro_dps || 0).toLocaleString();
  const d = (ev.delta_pct || 0);
  document.getElementById('rlana_delta').textContent = (d >= 0 ? '+' : '') + d.toFixed(2) + '%';
  document.getElementById('rlana_total_n').textContent = (ev.n_total_decisions || 0).toLocaleString();
  document.getElementById('rlana_disagree').textContent = ((ev.disagree_rate || 0) * 100).toFixed(1) + '%';
  const tbody = document.querySelector('#rlana_patterns tbody');
  tbody.innerHTML = '';
  for (const p of (ev.patterns || []).slice(0, 20)) {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${p.macro_name}</td><td>→</td><td>${p.rl_name}</td><td>${p.count}</td>`;
    tbody.appendChild(tr);
  }
}

function rlanaConnectStream() {
  if (rlanaEventSource) { rlanaEventSource.close(); rlanaEventSource = null; }
  const es = new EventSource('/api/rl/analyze/stream');
  rlanaEventSource = es;
  es.onmessage = (msg) => {
    let ev;
    try { ev = JSON.parse(msg.data); } catch (_) { return; }
    switch (ev.event) {
      case 'start':
        rlanaLog('[start] ckpt=' + (ev.ckpt || '').split(/[\\/]/).slice(-3).join('/') + ' action_count=' + ev.action_count);
        break;
      case 'progress':
        document.getElementById('rlana_step').textContent = (ev.step || 0).toLocaleString();
        document.getElementById('rlana_sim').textContent = (ev.sim_elapsed || 0).toFixed(1) + 's / ' + (ev.duration || 0).toFixed(0) + 's';
        document.getElementById('rlana_cur_dps').textContent = Math.round(ev.current_dps || 0).toLocaleString();
        document.getElementById('rlana_disagree').textContent = ((ev.disagree_rate || 0) * 100).toFixed(1) + '%';
        break;
      case 'macro_dps':
        rlanaLog('[macro baseline] DPS=' + Math.round(ev.macro_dps || 0).toLocaleString());
        document.getElementById('rlana_macro_dps').textContent = Math.round(ev.macro_dps || 0).toLocaleString();
        break;
      case 'done':
        rlanaRenderResult(ev);
        rlanaLog('[done] RL=' + Math.round(ev.rl_dps).toLocaleString() + ' 宏=' + Math.round(ev.macro_dps).toLocaleString() + ' Δ=' + ev.delta_pct.toFixed(2) + '%', 'update');
        rlanaSetState('完成', '');
        document.getElementById('rlana_start_btn').disabled = false;
        document.getElementById('rlana_stop_btn').disabled = true;
        break;
      case 'exit':
        rlanaLog('[exit] code=' + ev.exit_code, ev.exit_code === 0 ? 'event' : 'error');
        if (document.getElementById('rlana_state').textContent !== '完成') {
          rlanaSetState('已退出', '');
        }
        document.getElementById('rlana_start_btn').disabled = false;
        document.getElementById('rlana_stop_btn').disabled = true;
        if (rlanaEventSource) { rlanaEventSource.close(); rlanaEventSource = null; }
        break;
      case 'error':
        rlanaLog('[error] ' + ev.message, 'error');
        rlanaSetState('错误', 'error');
        break;
      case 'log':
        rlanaLog(ev.line);
        break;
    }
  };
  es.onerror = () => rlanaLog('SSE 断开（自动重连）', 'error');
}

async function rlanaPollStatus() {
  try {
    const res = await fetch('/api/rl/analyze/status');
    if (!res.ok) return;
    const s = await res.json();
    if (s.running) {
      rlanaSetState('运行中 ' + s.run_id, 'running');
      document.getElementById('rlana_start_btn').disabled = true;
      document.getElementById('rlana_stop_btn').disabled = false;
      if (!rlanaEventSource) rlanaConnectStream();
    }
    if (s.last_result) rlanaRenderResult(s.last_result);
  } catch (_) {}
}

document.getElementById('rlana_start_btn').addEventListener('click', rlanaStart);
document.getElementById('rlana_stop_btn').addEventListener('click', rlanaStop);
document.getElementById('rlana_ckpt_refresh').addEventListener('click', rlanaRefreshCkpts);
document.getElementById('rlana_macro_from_sim').addEventListener('click', () => {
  try {
    const t = (typeof buildMacroText === 'function') ? buildMacroText() : '';
    if (t) document.getElementById('rlana_macro').value = t;
    else alert('循环模拟页未填宏');
  } catch (e) { alert(e.message); }
});
document.getElementById('rlana_open_in_rollout').addEventListener('click', async () => {
  try {
    const res = await fetch('/api/rl/analyze/latest_actions');
    if (!res.ok) { alert('暂无分析结果'); return; }
    const payload = await res.json();
    rlrunActionsPayload = payload;
    const n = (payload.actions || []).length;
    const m = payload.meta || {};
    document.getElementById('rlrun_mode').value = 'actions';
    document.getElementById('rlrun_mode').dispatchEvent(new Event('change'));
    const meta = document.getElementById('rlrun_actions_meta');
    meta.textContent = '来自 RL 分析  动作数=' + n + (m.rl_dps ? '  RL DPS=' + Math.round(m.rl_dps).toLocaleString() : '');
    if (payload.duration) document.getElementById('rlrun_duration').value = payload.duration;
    if (payload.initial_rage != null) document.getElementById('rlrun_initial_rage').value = payload.initial_rage;
    if (payload.network_delay != null) document.getElementById('rlrun_network_delay').value = payload.network_delay;
    // 切到回放 tab
    document.querySelector('.tab[data-page="page-rlrun"]').click();
  } catch (e) { alert('失败: ' + e.message); }
});
document.querySelectorAll('.tab').forEach(tab => {
  tab.addEventListener('click', () => {
    if (tab.dataset.page === 'page-rlana') {
      rlanaPollStatus();
      rlanaRefreshCkpts();
    }
  });
});

function rlrunRender(j) {
  document.getElementById('rlrun_dps').textContent = Math.round(j.dps).toLocaleString();
  document.getElementById('rlrun_total').textContent = Math.round(j.total_damage).toLocaleString();
  document.getElementById('rlrun_fight').textContent = j.fight_time.toFixed(2) + 's';
  document.getElementById('rlrun_skills').textContent = j.skill_count;

  // 复用主时间轴渲染（注入 RL tab 自己的容器）
  renderTimeline(j.timeline, {
    trackEl: document.getElementById('rlrun_timeline_track'),
    scrollEl: document.getElementById('rlrun_timeline_scroll'),
  });

  // 备用纯文本事件列表
  const tbl = document.getElementById('rlrun_table');
  tbl.innerHTML = '';
  for (const ev of j.timeline) {
    if (ev.triggered) continue;
    const row = document.createElement('div');
    row.className = 'log-line';
    const t = ev.cast_time.toFixed(3).padStart(8);
    const name = (ev.name || '').padEnd(12);
    const dmg = ev.damage_total != null ? Math.round(ev.damage_total).toLocaleString() : '';
    row.textContent = `${t}s  ${name}  ${dmg}`;
    tbl.appendChild(row);
  }
}

// ─── 序列→宏 转换器 ────────────────────────────────────────────────
async function seqToMacro() {
  if (!lastSimResult || !Array.isArray(lastSimResult.timeline) || lastSimResult.timeline.length === 0) {
    alert('请先点"模拟"跑出一个 timeline，然后再点序列→宏');
    return;
  }
  const body = {
    timeline: lastSimResult.timeline.map(e => ({
      name: e.name,
      triggered: !!e.triggered,
      is_main: e.is_main !== false,
      state_before: e.state_before || null,
    })),
    options: {},
  };
  let resp;
  try {
    const r = await fetch('/api/macro/from_sequence', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!r.ok) throw new Error(await r.text());
    resp = await r.json();
  } catch (e) {
    alert('生成失败：' + e.message);
    return;
  }
  showSeqMacroModal(resp);
}

function showSeqMacroModal(resp) {
  let overlay = document.getElementById('seq_macro_modal');
  if (overlay) overlay.remove();
  overlay = document.createElement('div');
  overlay.id = 'seq_macro_modal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:24px;';
  const pageInfo = (resp.pages || []).map(p =>
    `<span style="margin-right:14px;color:${p.chars > p.limit ? '#f85149' : '#3fb950'}">${p.stance}: ${p.chars}/${p.limit} 字, ${p.rule_count} 条</span>`
  ).join('');
  const dropped = (resp.dropped_rules || []).map(d =>
    `<div style="font-size:12px;color:#aaa;">丢: ${d.rule} （${d.reason}, ${d.coverage_pct.toFixed(1)}%）</div>`
  ).join('');
  const stats = resp.stats || {};
  overlay.innerHTML = `
    <div style="background:#161b22;border:1px solid #30363d;border-radius:8px;width:min(900px,95vw);max-height:90vh;display:flex;flex-direction:column;color:#e6edf3;">
      <div style="padding:14px 18px;border-bottom:1px solid #30363d;display:flex;align-items:center;">
        <div style="font-size:16px;font-weight:600;flex:1;">序列 → 宏（P0 MVP）</div>
        <button class="sim-btn" id="seq_macro_close">×</button>
      </div>
      <div style="padding:12px 18px;border-bottom:1px solid #30363d;font-size:13px;">
        <div>共 ${stats.total_main_casts ?? '?'} 个主动 cast，使用 ${stats.used_casts ?? '?'} 个，技能 ${stats.skill_count ?? '?'} 种</div>
        <div style="margin-top:6px;">${pageInfo}</div>
      </div>
      <div style="padding:14px 18px;flex:1;overflow:auto;">
        <textarea id="seq_macro_text" spellcheck="false"
          style="width:100%;height:380px;background:#0d1117;color:#e6edf3;border:1px solid #30363d;border-radius:6px;padding:10px;font-family:ui-monospace,Consolas,monospace;font-size:13px;">${escapeHtml(resp.macro_text || '')}</textarea>
        ${dropped ? `<div style="margin-top:10px;">${dropped}</div>` : ''}
      </div>
      <div id="seq_macro_verify_out" style="padding:0 18px;"></div>
      <div style="padding:12px 18px;border-top:1px solid #30363d;display:flex;gap:10px;justify-content:flex-end;">
        <button class="sim-btn" id="seq_macro_verify">验证（跑宏对比）</button>
        <button class="sim-btn" id="seq_macro_optimize">优化排序（搜索）</button>
        <button class="sim-btn" id="seq_macro_copy">复制到剪贴板</button>
        <button class="sim-btn primary" id="seq_macro_apply">写入循环宏文本</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  overlay.querySelector('#seq_macro_close').onclick = () => overlay.remove();
  overlay.querySelector('#seq_macro_copy').onclick = () => {
    navigator.clipboard.writeText(overlay.querySelector('#seq_macro_text').value);
  };
  // 运行宏对比一次，返回 simulate 响应
  async function runMacroOnce(macroText, duration) {
    const maxSlots = Math.ceil(duration / 0.25) + 20;
    const r = await fetch('/api/simulate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        haste_level: parseInt(getAttrs().haste_level) || 0,
        sequence: Array(maxSlots).fill('__macro__'),
        macro_text: macroText,
        macro_duration: duration,
        talents: getSelectedTalents(),
        recipes: getSelectedRecipes(),
        channel_ticks: {}, timing_offsets: {}, qijin_buffs: {},
        network_delay: parseInt(document.getElementById('sim_delay').value) || 0,
        attributes: getAttrs(), target: getTarget(),
        initial_rage: adminInitialRage,
        boss_attack_interval: getBossAttackInterval(),
        hanjia_expectation: isHanjiaExpectationEnabled(), tiegu_mode: getTieguMode(), experimental: isExperimental(),
        equipment: getEquipmentMap(),
        team_buffs: getTeamBuffs(),
        formation: getCurrentFormation(),
      }),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json();
  }

  // 枚举所有"同页内相邻规则两两交换"的候选
  function generateAdjacentSwaps(text) {
    const lines = text.split('\n');
    const pageStarts = [];
    lines.forEach((l, i) => { if (/^#page\b/.test(l)) pageStarts.push(i); });
    if (pageStarts.length === 0 || pageStarts[0] > 0) pageStarts.unshift(-1);
    pageStarts.push(lines.length);
    const swaps = [];
    for (let p = 0; p < pageStarts.length - 1; p++) {
      const start = pageStarts[p] + 1;
      const end = pageStarts[p + 1];
      const ruleIdxs = [];
      for (let i = start; i < end; i++) {
        if (/^\s*\/(cast|fcast)\b/.test(lines[i])) ruleIdxs.push(i);
      }
      for (let k = 0; k < ruleIdxs.length - 1; k++) {
        const copy = lines.slice();
        const a = ruleIdxs[k], b = ruleIdxs[k + 1];
        [copy[a], copy[b]] = [copy[b], copy[a]];
        swaps.push({ text: copy.join('\n'), page: p, pair: [k, k + 1] });
      }
    }
    return swaps;
  }

  overlay.querySelector('#seq_macro_optimize').onclick = async () => {
    const btn = overlay.querySelector('#seq_macro_optimize');
    const out = overlay.querySelector('#seq_macro_verify_out');
    const ta = overlay.querySelector('#seq_macro_text');
    const duration = (lastSimResult.fight_time || 60);
    btn.disabled = true;
    const origDps = lastSimResult.dps || 0;
    let best = { text: ta.value, dps: null };
    let totalRuns = 0;
    try {
      // 基线
      out.innerHTML = `<div style="color:#8b949e;font-size:12px;padding:8px 0;">跑基线…</div>`;
      const baseline = await runMacroOnce(best.text, duration);
      best.dps = baseline.dps || 0;
      totalRuns++;
      // 爬山：每轮枚举所有相邻交换，取最优；若有改进则继续，最多 3 轮
      for (let pass = 1; pass <= 3; pass++) {
        const cands = generateAdjacentSwaps(best.text);
        if (cands.length === 0) break;
        out.innerHTML = `<div style="color:#8b949e;font-size:12px;padding:8px 0;">第 ${pass} 轮搜索：${cands.length} 个候选…</div>`;
        const results = await Promise.all(cands.map(c =>
          runMacroOnce(c.text, duration).then(r => ({ text: c.text, dps: r.dps || 0 })).catch(() => null)
        ));
        totalRuns += cands.length;
        const valid = results.filter(r => r);
        valid.sort((a, b) => b.dps - a.dps);
        if (valid.length === 0 || valid[0].dps <= best.dps + 1) break;
        best = valid[0];
      }
      ta.value = best.text;
      // 最终对比
      const finalRes = await runMacroOnce(best.text, duration);
      totalRuns++;
      const ratio = origDps > 0 ? (best.dps / origDps) : 0;
      const color = ratio >= 0.95 ? '#3fb950' : (ratio >= 0.9 ? '#c9a847' : '#f85149');
      let html = `<div style="padding:10px 0;border-top:1px solid #30363d;">
        <div style="color:${color};font-weight:600;font-size:13px;margin-bottom:6px;">
          优化后 DPS: 原 ${Math.round(origDps).toLocaleString()} → 宏 ${Math.round(best.dps).toLocaleString()} （${(ratio * 100).toFixed(1)}%）
          <span style="color:#8b949e;font-weight:400;margin-left:8px;">共跑 ${totalRuns} 次 simulate</span>
        </div></div>`;
      out.innerHTML = html;
      renderVerifyDiff(out, lastSimResult, finalRes);
    } catch (e) {
      out.innerHTML = `<div style="color:#f85149;font-size:12px;padding:8px 0;">优化失败：${escapeHtml(e.message)}</div>`;
    } finally {
      btn.disabled = false;
    }
  };

  overlay.querySelector('#seq_macro_verify').onclick = async () => {
    const text = overlay.querySelector('#seq_macro_text').value;
    const out = overlay.querySelector('#seq_macro_verify_out');
    out.innerHTML = '<div style="color:#8b949e;font-size:12px;padding:8px 0;">跑宏中…</div>';
    try {
      const origDuration = (lastSimResult.fight_time || 60);
      // 每个 __macro__ 占位符只触发 1 次 cast；按最短 GCD ≈0.5s 估所需数量，后端按 macro_duration 截断
      const maxSlots = Math.ceil(origDuration / 0.5) + 10;
      const r = await fetch('/api/simulate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          haste_level: parseInt(getAttrs().haste_level) || 0,
          sequence: Array(maxSlots).fill('__macro__'),
          macro_text: text,
          macro_duration: origDuration,
          talents: getSelectedTalents(),
          recipes: getSelectedRecipes(),
          channel_ticks: {}, timing_offsets: {}, qijin_buffs: {},
          network_delay: parseInt(document.getElementById('sim_delay').value) || 0,
          attributes: getAttrs(),
          target: getTarget(),
          initial_rage: adminInitialRage,
          boss_attack_interval: getBossAttackInterval(),
          hanjia_expectation: isHanjiaExpectationEnabled(), tiegu_mode: getTieguMode(),
          equipment: getEquipmentMap(),
          team_buffs: getTeamBuffs(),
        formation: getCurrentFormation(),
        }),
      });
      if (!r.ok) throw new Error(await r.text());
      const res = await r.json();
      renderVerifyDiff(out, lastSimResult, res);
    } catch (e) {
      out.innerHTML = `<div style="color:#f85149;font-size:12px;padding:8px 0;">验证失败：${escapeHtml(e.message)}</div>`;
    }
  };
  overlay.querySelector('#seq_macro_apply').onclick = () => {
    const text = overlay.querySelector('#seq_macro_text').value;
    // 写入当前循环宏（macro_text 在循环编辑器里通过 #macro_text textarea 持有）
    const ta = document.getElementById('macro_text');
    if (ta) {
      ta.value = text;
      ta.dispatchEvent(new Event('input', { bubbles: true }));
    } else {
      // 没打开宏编辑器：也复制到剪贴板，提示
      navigator.clipboard.writeText(text);
      alert('当前未打开宏编辑器，已复制到剪贴板');
    }
    overlay.remove();
  };
}

function renderVerifyDiff(container, orig, gen) {
  const collectCounts = (tl) => {
    const m = {};
    for (const e of tl || []) {
      if (e.triggered) continue;
      const full = e.name || '';
      const base = full.split('·')[0];
      // 雾海系列保持完整名（不归入旧版阵云）
      const WHL = { '阵云结晦·雾海': 1, '月照连营·雾海': 1, '雁门迢递·雾海': 1 };
      const key = WHL[full] ? full : base;
      const alias = ({ '月照连营': '阵云结晦', '雁门迢递': '阵云结晦', '隐刀': '闪刀', '惊沙': '盾毅' })[key] || key;
      m[alias] = (m[alias] || 0) + 1;
    }
    return m;
  };
  const a = collectCounts(orig.timeline);
  const b = collectCounts(gen.timeline);
  const keys = Array.from(new Set([...Object.keys(a), ...Object.keys(b)])).sort();
  const ratio = gen.dps && orig.dps ? (gen.dps / orig.dps) : 0;
  const color = ratio >= 0.95 ? '#3fb950' : (ratio >= 0.9 ? '#c9a847' : '#f85149');
  let html = `<div style="padding:10px 0;border-top:1px solid #30363d;">
    <div style="color:${color};font-weight:600;font-size:13px;margin-bottom:6px;">
      DPS: 原 ${Math.round(orig.dps || 0).toLocaleString()} → 宏 ${Math.round(gen.dps || 0).toLocaleString()} （${(ratio * 100).toFixed(1)}%）
    </div>
    <table style="width:100%;font-size:12px;border-collapse:collapse;">
      <thead><tr style="color:#8b949e;text-align:left;">
        <th style="padding:3px 6px;">技能</th>
        <th style="padding:3px 6px;">原序列</th>
        <th style="padding:3px 6px;">宏</th>
        <th style="padding:3px 6px;">差</th>
      </tr></thead><tbody>`;
  for (const k of keys) {
    const av = a[k] || 0, bv = b[k] || 0, dv = bv - av;
    const c = Math.abs(dv) > Math.max(2, av * 0.3) ? '#f85149' : (dv === 0 ? '#3fb950' : '#c9a847');
    html += `<tr><td style="padding:2px 6px;">${escapeHtml(k)}</td>
      <td style="padding:2px 6px;">${av}</td>
      <td style="padding:2px 6px;">${bv}</td>
      <td style="padding:2px 6px;color:${c};">${dv > 0 ? '+' : ''}${dv}</td></tr>`;
  }
  html += '</tbody></table></div>';
  container.innerHTML = html;
}

document.getElementById('btn_seq_to_macro')?.addEventListener('click', seqToMacro);

// ═════════════════════════════════════════════════════════════════════════
// PR 2 选项 A: 中心化页面切换工具（替代分散的 .tab[…].click() 调用）
// tab-bar 被 CSS 隐藏，但 DOM 还在，兼容现有 .tab[data-page=X].click() 写法
// ═════════════════════════════════════════════════════════════════════════

window.Jx3Nav = {
  switchPage(pageId) {
    const tab = document.querySelector(`.tab[data-page="${pageId}"]`);
    if (tab) { tab.click(); return; }
    // 兜底：直接切 page.active（当对应 tab 不存在时，如 page-wizard-a）
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    const page = document.getElementById(pageId);
    if (page) page.classList.add('active');
  },
  currentPage() {
    const active = document.querySelector('.page.active');
    return active ? active.id : null;
  },
};

// 模拟器页固定 viewport 高度：page-sim active 时给 body 加 .sim-fullheight，
// 让 .container 变 100vh flex column → page-sim 占据 top-bar 之下剩余空间，不延伸 body
(function initSimFullheight() {
  const apply = () => {
    const onSim = document.getElementById('page-sim')?.classList.contains('active');
    document.body.classList.toggle('sim-fullheight', !!onSim);
  };
  const simPage = document.getElementById('page-sim');
  if (simPage) {
    new MutationObserver(apply).observe(simPage, { attributes: true, attributeFilter: ['class'] });
  }
  // 初次（DOM ready 后 page 可能已 active）
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', apply);
  } else {
    apply();
  }
})();

// ═════════════════════════════════════════════════════════════════════════
// PR 1: 顶部共享输入栏 + Hub 首页 + localStorage 骨架
// ═════════════════════════════════════════════════════════════════════════

(function initTopBarAndHub() {
  // ── 1. 把现有的输入组件 DOM 搬到顶部栏的折叠面板里 ──
  // 不改元素 ID，所以 getAttrs() / getTarget() 仍然能查到；只改 DOM 位置。
  const pBasic = document.getElementById('page-basic');
  const attrPanel = pBasic?.querySelector('.attr-panel');
  const targetCfg = pBasic?.querySelector('.target-config');
  const simToolbar = document.querySelector('#page-sim .sim-toolbar');
  const simDelayField = simToolbar?.querySelector('.sim-field.sim-dropdown');
  const origBtnTalents = document.getElementById('btn_talents');
  const origBtnRecipes = document.getElementById('btn_recipes');

  const panelAttrs = document.getElementById('tb-panel-attrs');

  // 属性：进模态
  if (attrPanel && panelAttrs) panelAttrs.appendChild(attrPanel);

  // 目标：在顶栏建一个 sim-dropdown 结构（与"延迟"保持一致），值映射回原 target_level select
  const slotTarget = document.getElementById('tb_slot_target');
  const origTargetSel = document.getElementById('target_level');
  if (slotTarget && origTargetSel) {
    const opts = Array.from(origTargetSel.options).map(o => ({ value: o.value, text: o.textContent }));
    const current = origTargetSel.value;
    const currentText = opts.find(o => o.value === current)?.text || '134级';
    const wrap = document.createElement('div');
    wrap.className = 'sim-field sim-dropdown';
    wrap.innerHTML = `
      <span class="sim-input sim-dropdown-trigger" id="target_level_label">${currentText}</span>
      <div class="sim-dropdown-menu">
        ${opts.map(o => `<div class="sim-dropdown-item${o.value === current ? ' active' : ''}" data-target-value="${o.value}">${o.text}</div>`).join('')}
      </div>`;
    slotTarget.appendChild(wrap);
    wrap.querySelectorAll('.sim-dropdown-item').forEach(item => {
      item.addEventListener('click', () => {
        const v = item.dataset.targetValue;
        origTargetSel.value = v;
        origTargetSel.dispatchEvent(new Event('change', { bubbles: true }));
        document.getElementById('target_level_label').textContent = item.textContent;
        wrap.querySelectorAll('.sim-dropdown-item').forEach(i => i.classList.remove('active'));
        item.classList.add('active');
      });
    });
  }
  if (targetCfg) targetCfg.style.display = 'none'; // 防御加成输入、结果显示保留在 DOM 但不可见

  // 把"目标" inline 组件从全局顶栏搬到 page-sim 的 sim-toolbar
  // （初始化已完成，移动 DOM 节点保留事件绑定和子 dropdown UI 不变）
  const simTargetAnchor = document.getElementById('sim_target_anchor');
  if (slotTarget && simTargetAnchor) {
    simTargetAnchor.parentNode.insertBefore(slotTarget, simTargetAnchor);
    slotTarget.classList.add('sim-tb-inline');
  }

  // 延迟/奇穴/秘籍 保留在 sim-toolbar（循环模拟作为独立工作流，入口自足）
  // 属性由配装器产出，顶栏入口也一并隐藏。
  // 对应的全局顶栏按钮/占位隐藏，避免重复入口。Phase 6 会彻底清理顶栏。
  const tbAttrsBtn   = document.querySelector('.tb-btn[data-tb-panel="attrs"]');
  const tbTalentsBtn = document.querySelector('.tb-btn[data-tb-panel="talents"]');
  const tbRecipesBtn = document.querySelector('.tb-btn[data-tb-panel="recipes"]');
  const tbSlotDelay  = document.getElementById('tb_slot_delay');
  if (tbAttrsBtn)   tbAttrsBtn.style.display   = 'none';
  if (tbTalentsBtn) tbTalentsBtn.style.display = 'none';
  if (tbRecipesBtn) tbRecipesBtn.style.display = 'none';
  if (tbSlotDelay)  tbSlotDelay.style.display  = 'none';
  void simDelayField; void origBtnTalents; void origBtnRecipes;  // 不再使用

  // ── 2. 顶部栏按钮 → modal 弹窗 ──
  const tbBtns = document.querySelectorAll('.top-bar .tb-btn[data-tb-panel]');
  const tbPanels = document.querySelectorAll('.tb-panels .tb-panel');

  // 动态创建 backdrop（一次）
  let backdrop = document.querySelector('.tb-backdrop');
  if (!backdrop) {
    backdrop = document.createElement('div');
    backdrop.className = 'tb-backdrop';
    document.body.appendChild(backdrop);
  }

  // 给每个 panel 补标题和关闭按钮（若还没加过）
  const PANEL_TITLES = {
    'tb-panel-attrs':   '属性面板',
  };
  tbPanels.forEach(p => {
    if (p.querySelector('.tb-panel-close')) return;
    const title = document.createElement('div');
    title.className = 'tb-panel-title';
    title.textContent = PANEL_TITLES[p.id] || '';
    const close = document.createElement('button');
    close.className = 'tb-panel-close';
    close.type = 'button';
    close.innerHTML = '×';
    close.addEventListener('click', closeAllPanels);
    p.insertBefore(close, p.firstChild);
    p.insertBefore(title, close);
  });

  function closeAllPanels() {
    tbPanels.forEach(p => p.classList.remove('open'));
    tbBtns.forEach(b => b.classList.remove('active'));
    backdrop.classList.remove('active');
  }
  tbBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = btn.dataset.tbPanel;
      const panel = document.getElementById('tb-panel-' + key);
      const wasOpen = panel?.classList.contains('open');
      closeAllPanels();
      if (!wasOpen && panel) {
        panel.classList.add('open');
        btn.classList.add('active');
        backdrop.classList.add('active');
      }
    });
  });
  backdrop.addEventListener('click', closeAllPanels);
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && backdrop.classList.contains('active')) {
      closeAllPanels();
    }
  });

  // ESC 关闭最近一层 .talent-overlay.open（奇穴 / 战斗统计 / 导入 picker / 等）
  // 走每个 modal 自己的 .talent-close.click()，复用原 close 逻辑（不直接 remove，免得漏清状态）
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const overlays = document.querySelectorAll('.talent-overlay.open');
    if (!overlays.length) return;
    const top = overlays[overlays.length - 1];
    const closeBtn = top.querySelector('.talent-close');
    if (closeBtn) closeBtn.click();
    else top.remove();
  });

  // ── 3. 顶部栏 summary 同步 ──
  function refreshSummaries() {
    // 属性按钮只显示标签，不显示摘要
    // 目标 / 延迟现在是内联控件，不需要摘要同步
    try {
      const ts = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
      const el = document.getElementById('tb_summary_talents');
      if (el) el.textContent = `${ts.length} 项`;
      const th = document.getElementById('talents_hint');
      if (th) th.textContent = ts.length ? `已选 ${ts.length} 项` : '未配置';
    } catch (_) {}
    try {
      const rs = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
      const el = document.getElementById('tb_summary_recipes');
      if (el) el.textContent = `${rs.length} 项`;
      const rh = document.getElementById('recipes_hint');
      if (rh) rh.textContent = rs.length ? `已选 ${rs.length} 项` : '未配置';
    } catch (_) {}
  }

  const watchedIds = ['li_dao','shen_fa','base_attack','weapon_damage','surplus_value',
   'crit_level','crit_effect_level','overcome_level','strain_level','haste_level',
   'target_level','target_defense_bonus','sim_delay'];
  // 配装更换 / 属性手填变化 → debounce 触发 runSimulate（仅 page-sim active 时）
  // 多个属性同时改（applyConfig dispatch 12 个 input）只跑一次
  let _attrChangeRunSimTimer = null;
  const _scheduleRunSimOnAttrChange = () => {
    clearTimeout(_attrChangeRunSimTimer);
    _attrChangeRunSimTimer = setTimeout(() => {
      const onSimPage = document.getElementById('page-sim')?.classList.contains('active');
      if (onSimPage && typeof runSimulate === 'function') {
        try { runSimulate(); } catch {}
      }
    }, 400);
  };
  watchedIds.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.addEventListener('input', refreshSummaries);
      el.addEventListener('change', refreshSummaries);
      el.addEventListener('change', _scheduleRunSimOnAttrChange);
    }
  });
  const delayLabel = document.getElementById('sim_delay_label');
  if (delayLabel && window.MutationObserver) {
    const mo = new MutationObserver(refreshSummaries);
    mo.observe(delayLabel, { childList: true, characterData: true, subtree: true });
  }
  setTimeout(refreshSummaries, 0);
  window._refreshTopBarSummaries = refreshSummaries;

  // ── 4. Hub 页按钮 ──
  document.querySelectorAll('.hub-tool[data-hub-goto]').forEach(b => {
    b.addEventListener('click', () => {
      window.Jx3Nav?.switchPage(b.dataset.hubGoto);
    });
  });

  // 顶栏 🏠 Hub 按钮 + 快速切换下拉
  // 注：C 向导用 body.wizard-mode + #wizard-shell 悬浮顶栏；离开向导前须先 exit，否则 shell 会残留在 hub
  function leaveWizardIfActive() {
    try {
      if (window.Jx3PlazaWizard?.isActive?.()) window.Jx3PlazaWizard.exit();
    } catch {}
  }
  document.getElementById('tb_home')?.addEventListener('click', () => {
    leaveWizardIfActive();
    window.Jx3Nav?.switchPage('page-hub');
  });
  document.querySelectorAll('#tb_quick_switch .sim-dropdown-item').forEach(item => {
    item.addEventListener('click', () => {
      leaveWizardIfActive();
      const p = item.dataset.quickPage;
      if (p) window.Jx3Nav?.switchPage(p);
      const label = document.getElementById('tb_quick_label');
      if (label) label.textContent = item.textContent.trim();
    });
  });
  // 快速切换 label 同步当前页名（每次切页后更新）
  const quickLabels = {
    'page-hub': '🎯 主页',
    'page-basic': '📊 技能数值',
    'page-sim': '📊 循环模拟',
    'page-opt': '🛠 宏优化器',
    'page-rl': '🤖 RL 训练',
    'page-rlana': '📈 RL 分析',
    'page-rlrun': '🎬 RL 回放',
    'page-wizard-a': '🎯 循环蒸馏',
    'page-wizard-b': '⚙️ 宏优化',
    'page-wizard-c': '⚔ 配装搜索',
    'page-history': '📚 历史库',
    'page-equip': '⚔️ 配装器',
    'page-plaza': '🏟️ 战斗广场',
    'page-plaza-step2': '🏟️ 战斗广场 · 第1步',
    'page-plaza-step4': '🏟️ 战斗广场 · 第4步',
  };
  function syncQuickLabel() {
    const cur = window.Jx3Nav?.currentPage();
    const label = document.getElementById('tb_quick_label');
    if (label && cur) label.textContent = quickLabels[cur] || cur;
  }
  // 监听 .page class 变化（粗暴但直接）
  const pageObs = new MutationObserver(syncQuickLabel);
  document.querySelectorAll('.page').forEach(p => pageObs.observe(p, { attributes: true, attributeFilter: ['class'] }));
  syncQuickLabel();
  document.querySelectorAll('.hub-card[data-hub-action]').forEach(card => {
    const btn = card.querySelector('.hub-card-btn');
    btn?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (btn.disabled) return;
      const action = card.dataset.hubAction;
      if (action === 'workflow-a') {
        window.Jx3WizardA?.enter();
      } else if (action === 'workflow-b') {
        window.Jx3WizardB?.enter();
      } else if (action === 'workflow-c') {
        window.Jx3Nav?.switchPage('page-plaza');
      } else if (action === 'workflow-d') {
        window.Jx3Nav?.switchPage('page-sim');
      } else if (action === 'workflow-equip-search') {
        window.Jx3Nav?.switchPage('page-wizard-c');
      }
    });
  });

  // ── 5. 上次工作流恢复徽章 —— 每次有 persist() 时实时刷新 ──
  // 不缓存 tbResume 引用：后续有 wireResumeBadgeToWizard() 会 cloneNode 替换节点，
  // 缓存会指向已脱离 DOM 的旧节点，导致顶栏文本不更新
  function refreshResumeBadge() {
    const tbResume = document.getElementById('tb_resume');
    const last = window.Jx3State?.loadLastStep?.();
    const badgeA = document.getElementById('hub_badge_a');
    const badgeB = document.getElementById('hub_badge_b');
    if (badgeA) badgeA.style.display = 'none';
    if (badgeB) badgeB.style.display = 'none';
    if (!last || !last.workflow || !last.step) {
      if (tbResume) tbResume.style.display = 'none';
      return;
    }
    if (tbResume) {
      tbResume.textContent = `上次: ${last.workflow} / 步骤 ${last.step} ▸`;
      tbResume.style.display = '';
    }
    const b = last.workflow === 'A' ? badgeA : badgeB;
    if (b) { b.textContent = `继续 · 步骤 ${last.step}`; b.style.display = ''; }
  }
  window.Jx3RefreshResume = refreshResumeBadge;
  refreshResumeBadge();
  // 启动时从后端 userdata/resume.json 拉取（若存在则覆盖 localStorage），再刷徽章
  window.Jx3State?.pullResumeFromServer?.().then(() => refreshResumeBadge());

  // ── 6. 共享输入持久化到 localStorage ──
  function collectSharedInputs() {
    try {
      return {
        attrs: (typeof getAttrs === 'function') ? getAttrs() : {},
        target: (typeof getTarget === 'function') ? getTarget() : {},
        talents: (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [],
        recipes: (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [],
        delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      };
    } catch (_) { return null; }
  }
  function pushSharedToLS() {
    const payload = collectSharedInputs();
    if (payload) window.Jx3State?.saveSharedInputs?.(payload);
  }
  watchedIds.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', pushSharedToLS);
  });
  const stored = window.Jx3State?.loadSharedInputs?.();
  if (stored && stored.attrs) {
    Object.entries(stored.attrs).forEach(([k, v]) => {
      const el = document.getElementById(k);
      if (el && v != null) el.value = v;
    });
    if (stored.target) {
      const tl = document.getElementById('target_level');
      if (tl && stored.target.level != null) tl.value = stored.target.level;
      const tb = document.getElementById('target_defense_bonus');
      if (tb && stored.target.defense_bonus != null) tb.value = stored.target.defense_bonus;
    }
    if (stored.delay != null) {
      const sd = document.getElementById('sim_delay');
      if (sd) sd.value = stored.delay;
    }
  }
  setTimeout(refreshSummaries, 100);
})();

// ═════════════════════════════════════════════════════════════════════════
// PR 2: 工作流 A 的 Wizard 骨架（状态机 + 导航 + 持久化）
// ═════════════════════════════════════════════════════════════════════════

(function initWizardA() {
  const TOTAL_STEPS = 7;
  const WORKFLOW = 'A';
  // 新映射（7 步）：
  //   A-1 奇穴/秘籍/目标/延迟   A-2 配装         A-3 循环（sim 嵌入）
  //   A-4 载入 timeline          A-5 生成 + 配置  A-6 迭代 + 验证    A-7 输出
  const STEP_ROTATION = 3;   // sim-slot 嵌入点
  const STEP_LOAD     = 4;   // timeline-load UI
  const STEP_GENERATE = 5;
  const STEP_ITERATE  = 6;
  const STEP_OUTPUT   = 7;

  const wz = {
    current: 1,
    completed: new Set(),
    payload: {},
  };

  // ── DOM refs ──
  const pageWz = document.getElementById('page-wizard-a');
  if (!pageWz) return;
  const progSteps = pageWz.querySelectorAll('.wz-prog-step');
  const sideSteps = pageWz.querySelectorAll('.wz-side-step');
  const stepPanels = pageWz.querySelectorAll('.wz-step-panel');
  const btnPrev = pageWz.querySelector('#wz_prev');
  const btnNext = pageWz.querySelector('#wz_next');
  const status = pageWz.querySelector('#wz_status');

  // ── 渲染 ──
  function render() {
    // 根据 payload / 全局状态推断 completed
    //   step 1 (奇穴/秘籍/目标/延迟)：至少选了 1 个奇穴或秘籍（软判定）
    //   step 2 (配装)：有 equipment slots
    //   step 3 (循环)：sim 有序列 或 宏文本非空
    //   step 4 (载入 timeline)：有 payload.timeline
    //   step 5 (生成)：macroReady
    //   step 6 (迭代)：iterAttempted
    const macroReady = !!(wz.payload.generated?.macro_text || wz.payload.iterated_macro);
    const iterAttempted = Array.isArray(wz.payload.iter_history) && wz.payload.iter_history.length > 0;
    const talentsCount = ((typeof getSelectedTalents === 'function') ? getSelectedTalents() : []).length;
    const recipesCount = ((typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : []).length;
    const step1Done = talentsCount > 0 || recipesCount > 0;
    const eq = window.Jx3Equip?.getCurrentConfig?.();
    const step2Done = !!(eq && eq.slots && Object.keys(eq.slots).length > 0);
    let step3Done = false;
    try {
      const seq = (typeof readSequence === 'function') ? readSequence() : [];
      step3Done = seq.length > 0;
    } catch {}
    if (!step3Done) {
      const hasMacroText = ['general','shield','blade'].some(k => (typeof macroPages !== 'undefined') && macroPages[k] && macroPages[k].trim());
      if (hasMacroText) step3Done = true;
    }
    if (step1Done) wz.completed.add(1);
    if (step2Done) wz.completed.add(2);
    if (step3Done) wz.completed.add(3);
    if (wz.payload.timeline) wz.completed.add(STEP_LOAD);
    if (macroReady) wz.completed.add(STEP_GENERATE);
    if (iterAttempted) wz.completed.add(STEP_ITERATE);
    progSteps.forEach(el => {
      const s = parseInt(el.dataset.step);
      el.classList.toggle('active', s === wz.current);
      el.classList.toggle('done', wz.completed.has(s) && s !== wz.current);
    });
    sideSteps.forEach(el => {
      const s = parseInt(el.dataset.step);
      el.classList.toggle('active', s === wz.current);
      el.classList.toggle('done', wz.completed.has(s) && s !== wz.current);
    });
    stepPanels.forEach(p => {
      p.classList.toggle('active', parseInt(p.dataset.step) === wz.current);
    });
    if (wz.current === STEP_OUTPUT && typeof renderStep4 === 'function') renderStep4();
    if (wz.current === 1 && typeof renderA1Summary === 'function') renderA1Summary();
    if (wz.current === 2 && typeof renderA2Summary === 'function') renderA2Summary();
    btnPrev.disabled = wz.current <= 1;
    if (wz.current >= TOTAL_STEPS) {
      btnNext.textContent = '完成';
    } else {
      btnNext.textContent = '下一步 →';
    }
    // 当前步完成条件达成时，下一步按钮高亮
    const curDone = (wz.current === 1 && step1Done)
                 || (wz.current === 2 && step2Done)
                 || (wz.current === 3 && step3Done)
                 || (wz.current === STEP_LOAD && wz.payload.timeline)
                 || (wz.current === STEP_GENERATE && macroReady)
                 || (wz.current === STEP_ITERATE && iterAttempted);
    btnNext.classList.toggle('wz-next-ready', !!curDone && wz.current < TOTAL_STEPS);
    status.textContent = `第 ${wz.current} 步 / 共 ${TOTAL_STEPS} 步` +
      (wz.completed.size ? ` · 已完成 ${wz.completed.size}` : '');
  }

  // ── 持久化 ──
  function persist() {
    const a = (typeof getAttrs === 'function') ? getAttrs() : {};
    const t = (typeof getTarget === 'function') ? getTarget() : {};
    const ts = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const rs = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
    const hash = window.Jx3State?.attrsHash?.(a, t, ts, rs) || '';
    window.Jx3State?.saveLastStep?.({
      workflow: WORKFLOW,
      step: wz.current,
      completed: Array.from(wz.completed),
      attrsHash: hash,
      payload: wz.payload,
    });
    window.Jx3RefreshResume?.();
  }

  function restore() {
    const last = window.Jx3State?.loadLastStep?.();
    if (!last || last.workflow !== WORKFLOW) return false;
    // 从旧 4 步保存的 last_step 迁移到新 7 步：原 1→4、2→5、3→6、4→7
    const remap = (n) => (n <= 0) ? 1 : (n <= 4 ? n + 3 : n);
    const savedStep = last.step || 1;
    wz.current = Math.min(remap(savedStep), TOTAL_STEPS);
    const savedCompleted = (last.completed || []).map(remap).filter(s => s <= TOTAL_STEPS);
    wz.completed = new Set(savedCompleted);
    wz.payload = last.payload || {};
    return true;
  }

  // ── 跳转 ──
  function goto(step, opts = {}) {
    if (step < 1 || step > TOTAL_STEPS) return;
    // 允许任意跳转；前进到未完成步时不标 completed
    wz.current = step;
    if (opts.markPrevDone) {
      for (let i = 1; i < step; i++) wz.completed.add(i);
    }
    render();
    persist();
  }

  btnPrev.addEventListener('click', () => goto(wz.current - 1));
  btnNext.addEventListener('click', () => {
    // 推进时把当前步标记 completed
    wz.completed.add(wz.current);
    if (wz.current >= TOTAL_STEPS) {
      // 完成整个 wizard：提示 + 回到 Hub
      alert('🎉 已完成全部 7 步。');
      render();
      persist();
      return;
    }
    goto(wz.current + 1);
  });
  progSteps.forEach(el => {
    el.addEventListener('click', () => goto(parseInt(el.dataset.step)));
  });
  sideSteps.forEach(el => {
    el.addEventListener('click', () => goto(parseInt(el.dataset.step)));
  });

  // 返回 Hub
  pageWz.querySelector('#wz_exit_hub')?.addEventListener('click', () => {
    persist(); // 退出前持久化
    document.querySelector('.tab[data-page="page-hub"]')?.click();
  });

  // ── 对外 API：Hub 按钮调用 ──
  window.Jx3WizardA = {
    enter(resume = false) {
      if (resume) {
        restore();
      } else {
        wz.current = 1;
        wz.completed = new Set();
        wz.payload = {};
      }
      window.Jx3Nav?.switchPage('page-wizard-a');
      render();
      persist();
      // 进入 Workflow A 时，若 Step 3 的 sim 序列为空但有自动保存 → 尝试载入一次
      const tryRestore = async () => {
        const container = document.getElementById('sim_sequence');
        const hasItems = container && container.querySelector('.sim-seq-item');
        if (hasItems) return true;
        if (!localStorage.getItem('jx3_autosave_loop_v1')) return true;
        try { return !!(await window.Jx3LoopAutosave?.restore?.()); } catch { return false; }
      };
      setTimeout(async () => { (await tryRestore()) || setTimeout(tryRestore, 400); }, 100);
    },
    current: () => wz.current,
    payload: () => wz.payload,
  };

  render();

  // ═══════════════ Step 1：奇穴 / 秘籍 / 目标 / 延迟 ═══════════════
  // chip + 打开全局 modal；目标/延迟用 hover 下拉
  function renderA1Summary() {
    // 奇穴 chips
    const tIds = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const tSum = document.getElementById('wza1_talents_summary');
    const tChips = document.getElementById('wza1_talents_chips');
    if (tSum) tSum.textContent = `已选 ${tIds.length} 个`;
    if (tChips) {
      if (!tIds.length) {
        tChips.innerHTML = '<span class="pc2-chips-empty">尚未选择</span>';
      } else {
        const list = (typeof talentList !== 'undefined') ? talentList : [];
        let unresolved = 0;
        const html = tIds.map(id => {
          const info = list.find(x => x.id === id);
          if (!info) unresolved++;
          return `<span class="pc2-chip">${escapeHtml(info?.name || ('#' + id))}</span>`;
        }).join('');
        tChips.innerHTML = html;
        if (unresolved && list.length === 0 && window.Jx3Plaza?.ensureTalentRecipeLists) {
          window.Jx3Plaza.ensureTalentRecipeLists().then(renderA1Summary);
        }
      }
    }
    // 秘籍 chips（按技能合并）
    const rIds = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
    const rSum = document.getElementById('wza1_recipes_summary');
    const rChips = document.getElementById('wza1_recipes_chips');
    if (rSum) rSum.textContent = `已选 ${rIds.length} 条`;
    if (rChips) {
      if (!rIds.length) {
        rChips.innerHTML = '<span class="pc2-chips-empty">尚未选择</span>';
      } else {
        const list = (typeof recipeList !== 'undefined') ? recipeList : [];
        const bySkill = {};
        let unresolved = 0;
        for (const id of rIds) {
          const info = list.find(x => x.id === id);
          if (!info) { unresolved++; continue; }
          bySkill[info.skill] = (bySkill[info.skill] || 0) + 1;
        }
        const parts = Object.entries(bySkill)
          .map(([sk, n]) => `<span class="pc2-chip">${escapeHtml(sk)} × ${n}</span>`);
        if (unresolved) parts.push(`<span class="pc2-chip pc2-chip-dim">未识别 × ${unresolved}</span>`);
        rChips.innerHTML = parts.join('');
        if (unresolved && list.length === 0 && window.Jx3Plaza?.ensureTalentRecipeLists) {
          window.Jx3Plaza.ensureTalentRecipeLists().then(renderA1Summary);
        }
      }
    }
    // 目标 label
    const lvl = document.getElementById('target_level');
    const wzaTargetLabel = document.getElementById('wza1_target_label');
    if (lvl && wzaTargetLabel) {
      const opt = lvl.options?.[lvl.selectedIndex];
      wzaTargetLabel.textContent = opt ? opt.textContent : (lvl.value || '—');
    }
    // 延迟 label
    const dv = document.getElementById('sim_delay')?.value || '0';
    const wzaDelayLabel = document.getElementById('wza1_delay_label');
    if (wzaDelayLabel) {
      const item = document.querySelector(`#wza1_delay_menu .sim-dropdown-item[data-value="${dv}"]`);
      wzaDelayLabel.textContent = item ? item.textContent : `${dv}ms`;
      document.querySelectorAll('#wza1_delay_menu .sim-dropdown-item').forEach(i => {
        i.classList.toggle('active', i.dataset.value === dv);
      });
    }
  }
  // 打开全局 modal
  document.getElementById('wza1_talents_btn')?.addEventListener('click', () => {
    document.getElementById('btn_talents')?.click();
    if (window.Jx3Plaza?.ensureTalentRecipeLists) {
      window.Jx3Plaza.ensureTalentRecipeLists().then(renderA1Summary);
    }
  });
  document.getElementById('wza1_recipes_btn')?.addEventListener('click', () => {
    document.getElementById('btn_recipes')?.click();
    if (window.Jx3Plaza?.ensureTalentRecipeLists) {
      window.Jx3Plaza.ensureTalentRecipeLists().then(renderA1Summary);
    }
  });
  // talent / recipe overlay 关闭时刷 chips
  ['talent_overlay', 'recipe_overlay'].forEach(id => {
    const hook = (el) => {
      if (!el || el.__wza1Obs) return;
      el.__wza1Obs = new MutationObserver(() => {
        if (pageWz.classList.contains('active') && wz.current === 1 && !el.classList.contains('open')) {
          renderA1Summary();
        }
      });
      el.__wza1Obs.observe(el, { attributes: true, attributeFilter: ['class'] });
    };
    const existing = document.getElementById(id);
    if (existing) hook(existing);
    else {
      const obs = new MutationObserver(() => {
        const el = document.getElementById(id);
        if (el) { hook(el); obs.disconnect(); }
      });
      obs.observe(document.body, { childList: true, subtree: true });
    }
  });
  // 目标下拉菜单（镜像全局 target_level 选项）
  function buildWza1TargetMenu() {
    const menu = document.getElementById('wza1_target_menu');
    const lvl = document.getElementById('target_level');
    if (!menu || !lvl) return;
    const opts = Array.from(lvl.options);
    menu.innerHTML = opts.map(o =>
      `<div class="sim-dropdown-item${o.selected ? ' active' : ''}" data-value="${o.value}">${escapeHtml(o.textContent)}</div>`
    ).join('');
    menu.querySelectorAll('.sim-dropdown-item').forEach(item => {
      item.addEventListener('click', () => {
        lvl.value = item.dataset.value;
        lvl.dispatchEvent(new Event('change', { bubbles: true }));
        renderA1Summary();
      });
    });
  }
  buildWza1TargetMenu();
  document.getElementById('target_level')?.addEventListener('change', () => {
    if (pageWz.classList.contains('active') && wz.current === 1) renderA1Summary();
  });
  // 延迟下拉
  document.querySelectorAll('#wza1_delay_menu .sim-dropdown-item').forEach(item => {
    item.addEventListener('click', () => {
      const v = item.dataset.value;
      const sd = document.getElementById('sim_delay');
      if (sd) {
        sd.value = v;
        sd.dispatchEvent(new Event('change', { bubbles: true }));
      }
      // 同步 sim-toolbar inline label
      const sdLabel = document.getElementById('sim_delay_label');
      if (sdLabel) sdLabel.textContent = item.textContent;
      document.querySelectorAll('.sim-dropdown-item').forEach(i => {
        if (i.dataset.value === v) i.classList.add('active');
        else i.classList.remove('active');
      });
      renderA1Summary();
    });
  });

  // ═══════════════ Step 2：配装 ═══════════════
  function renderA2Summary() {
    const chips = document.getElementById('wza2_equip_chips');
    if (!chips) return;
    const cfg = window.Jx3Equip?.getCurrentConfig?.();
    if (!cfg || !cfg.slots || !Object.keys(cfg.slots).length) {
      chips.innerHTML = '<span class="pc2-chips-empty">尚未配装 — 点下方按钮进入配装器</span>';
      return;
    }
    const slotNames = {
      hat: '帽', clothes: '衣', belt: '腰', wrist: '腕', bottoms: '裤', shoes: '鞋',
      weapon: '武器', pendant: '项链', ring_1: '戒1', ring_2: '戒2', waist_pendant: '腰坠', ornament: '暗器',
    };
    const parts = [];
    const slots = cfg.slots || {};
    for (const [k, v] of Object.entries(slots)) {
      if (!v) continue;
      const short = slotNames[k] || k;
      const name = (typeof v === 'object' && v !== null) ? (v.name || '?') : String(v);
      parts.push(`<span class="pc2-chip">${escapeHtml(short)}：${escapeHtml(name)}</span>`);
    }
    if (cfg.stoneName) parts.push(`<span class="pc2-chip">五彩石：${escapeHtml(cfg.stoneName)}</span>`);
    chips.innerHTML = parts.length ? parts.join('') : '<span class="pc2-chips-empty">装备为空</span>';
  }
  document.getElementById('wza2_go_equip')?.addEventListener('click', () => {
    window.Jx3Nav?.switchPage('page-equip');
  });
  document.getElementById('wza2_refresh')?.addEventListener('click', () => renderA2Summary());

  // ═══════════════ 原 Step 1：嵌入循环模拟 + 载入 timeline ═══════════════
  const btnUseSim = document.getElementById('wz_tl_use_sim');
  const btnUseJson = document.getElementById('wz_tl_use_json');
  const btnClear = document.getElementById('wz_tl_clear');
  const fileInput = document.getElementById('wz_tl_file');
  const tlInfo = document.getElementById('wz_tl_info');
  const tlStatus = document.getElementById('wz_tl_status');
  const simSlot = document.getElementById('wz_sim_slot');
  const pageSim = document.getElementById('page-sim');
  const origSimParent = pageSim?.parentNode;

  // 把循环模拟 DOM 搬进/搬出 Wizard step 1 slot
  function embedSimInStep1() {
    if (!simSlot || !pageSim) return;
    if (!simSlot.contains(pageSim)) simSlot.appendChild(pageSim);
  }
  function restoreSimToOriginal() {
    if (!pageSim || !origSimParent) return;
    if (origSimParent !== pageSim.parentNode) origSimParent.appendChild(pageSim);
  }

  function syncSimEmbed() {
    const wzActive = pageWz.classList.contains('active');
    const isRotationStep = wz.current === STEP_ROTATION;  // A-3
    if (wzActive && isRotationStep) embedSimInStep1();
    else restoreSimToOriginal();
  }

  // render 和页切换后都同步一次
  const origRender = render;
  render = function() {
    origRender();
    syncSimEmbed();
  };
  // 监听 page-wizard-a 的 active class 变化（进出 Wizard）
  new MutationObserver(syncSimEmbed).observe(pageWz, { attributes: true, attributeFilter: ['class'] });
  // 进/出 page-sim 本身也要同步（防止 #page-sim 被移走后标签页切到它时空白）
  if (pageSim) {
    new MutationObserver(() => {
      if (pageSim.classList.contains('active')) restoreSimToOriginal();
    }).observe(pageSim, { attributes: true, attributeFilter: ['class'] });
  }

  function renderTimelineInfo() {
    const tl = wz.payload.timeline;
    if (!tl || !Array.isArray(tl) || tl.length === 0) {
      tlInfo.style.display = 'none';
      btnClear.disabled = true;
      if (tlStatus) tlStatus.textContent = '未载入';
      return;
    }
    const meta = wz.payload.timeline_meta || {};
    const castCount = tl.filter(e => !e.triggered).length;
    const ft = (meta.fight_time || 0).toFixed(2);
    const dps = meta.dps ? Math.round(meta.dps).toLocaleString() : '?';
    tlInfo.style.display = 'block';
    tlInfo.innerHTML = `
      <div>事件总数：<span class="wz-tl-ok">${tl.length}</span>（含主动 cast <span class="wz-tl-ok">${castCount}</span>）</div>
      <div>战斗时长：${ft}s · DPS：${dps}</div>
      <div>来源：${meta.source || '未知'}</div>
    `;
    btnClear.disabled = false;
    if (tlStatus) tlStatus.textContent = '已载入';
  }

  function useCurrentSim(opts = {}) {
    if (typeof lastSimResult === 'undefined' || !lastSimResult || !Array.isArray(lastSimResult.timeline) || lastSimResult.timeline.length === 0) {
      if (!opts.silent) alert('还没跑过模拟。先在下面的循环模拟区跑一次，再点这个按钮。');
      return false;
    }
    wz.payload.timeline = lastSimResult.timeline;
    wz.payload.timeline_meta = {
      fight_time: lastSimResult.fight_time,
      dps: lastSimResult.dps,
      source: opts.auto ? '循环模拟自动载入' : '循环模拟当前结果',
    };
    // 捕获当时用的宏文本（若有）作为参考宏，验证时按场景重跑
    try {
      const refMacro = (typeof buildMacroText === 'function') ? buildMacroText() : '';
      wz.payload.reference_macro = refMacro && refMacro.trim() ? refMacro : null;
    } catch (_) { wz.payload.reference_macro = null; }
    // 新生成结果意味着旧的生成宏需要作废
    delete wz.payload.generated;
    wz.completed.add(STEP_LOAD);
    wz.completed.delete(STEP_GENERATE);
    renderTimelineInfo();
    persist();
    render();
    return true;
  }

  btnUseSim?.addEventListener('click', () => useCurrentSim({ silent: false, auto: false }));

  // 当下方嵌入的循环模拟跑完 → 自动吸入 timeline（用户位于 A-3 嵌入页或 A-4 载入页时）
  window.addEventListener('jx3-sim-complete', () => {
    if (!pageWz.classList.contains('active')) return;
    if (wz.current !== STEP_ROTATION && wz.current !== STEP_LOAD) return;
    useCurrentSim({ silent: true, auto: true });
  });

  btnUseJson?.addEventListener('click', () => fileInput?.click());

  fileInput?.addEventListener('change', async (e) => {
    const f = e.target.files?.[0];
    if (!f) return;
    try {
      const text = await f.text();
      const data = JSON.parse(text);
      const timeline = Array.isArray(data) ? data : data.timeline;
      if (!Array.isArray(timeline)) throw new Error('JSON 里没找到 timeline 数组');
      wz.payload.timeline = timeline;
      wz.payload.timeline_meta = {
        fight_time: data.fight_time || 0,
        dps: data.dps || 0,
        source: `JSON 文件: ${f.name}`,
      };
      wz.completed.add(STEP_LOAD);
      renderTimelineInfo();
      persist();
      render();
    } catch (err) {
      alert('解析失败：' + err.message);
    }
    e.target.value = '';
  });

  btnClear?.addEventListener('click', () => {
    delete wz.payload.timeline;
    delete wz.payload.timeline_meta;
    wz.completed.delete(STEP_LOAD);
    renderTimelineInfo();
    persist();
    render();
  });

  renderTimelineInfo();
  syncSimEmbed();

  // ═══════════════ Step 5：生成选项 ═══════════════
  const ALL_SKILLS = [
    '盾击', '盾猛', '盾压', '盾飞', '盾回',
    '盾刀', '斩刀', '绝刀', '劫刀', '闪刀',
    '血怒', '阵云结晦', '业火麟光', '撼地', '天下宏愿',
    '盾舞', '盾毅', '惊沙', '偃守孤旌'
  ];
  const DEFAULT_CONSISTENCY = currentMount?.workflow_a?.default_consistency?.length
    ? currentMount.workflow_a.default_consistency
    : ['血怒', '业火麟光', '偃守孤旌'];

  function renderConsistencyGrid() {
    const grid = document.getElementById('wz_consistency_grid');
    if (!grid) return;
    const selected = new Set(wz.payload.gen_options?.consistency_sensitive_skills || DEFAULT_CONSISTENCY);
    grid.innerHTML = ALL_SKILLS.map(name => `
      <label>
        <input type="checkbox" data-skill="${name}" ${selected.has(name) ? 'checked' : ''}>
        ${name}
      </label>
    `).join('');
    grid.querySelectorAll('input[type="checkbox"]').forEach(cb => {
      cb.addEventListener('change', saveOptions);
    });
  }

  function collectOptions() {
    const num = (id, fb) => { const v = parseFloat(document.getElementById(id)?.value); return isNaN(v) ? fb : v; };
    const numI = (id, fb) => { const v = parseInt(document.getElementById(id)?.value); return isNaN(v) ? fb : v; };
    const checked = (id) => !!document.getElementById(id)?.checked;
    const consistency = [...document.querySelectorAll('#wz_consistency_grid input[type="checkbox"]:checked')]
      .map(cb => cb.dataset.skill);
    return {
      max_terms: numI('wz_max_terms', 2),
      max_clauses: numI('wz_max_clauses', 3),
      min_gain: num('wz_min_gain', 0.05),
      min_cover_pct: num('wz_min_cover', 1.0),
      max_chars_per_page: numI('wz_max_chars', 128),
      consistency_sensitive_skills: consistency,
      consistency_min_gain_mult: num('wz_cons_gain_mult', 3.0),
      consistency_max_terms_bonus: numI('wz_cons_terms_bonus', 2),
      consistency_cast_diff_priority: num('wz_cons_priority', 5.0),
      use_copeland_priority: checked('wz_use_copeland'),
      use_off_gcd_treatment: checked('wz_use_off_gcd'),
      use_v2: checked('wz_use_v2'),
    };
  }

  function applyOptions(opts) {
    if (!opts) return;
    const setVal = (id, v) => { const el = document.getElementById(id); if (el && v != null) el.value = v; };
    const setChk = (id, v) => { const el = document.getElementById(id); if (el && v != null) el.checked = !!v; };
    setVal('wz_max_terms', opts.max_terms);
    setVal('wz_max_clauses', opts.max_clauses);
    setVal('wz_min_gain', opts.min_gain);
    setVal('wz_min_cover', opts.min_cover_pct);
    setVal('wz_max_chars', opts.max_chars_per_page);
    setVal('wz_cons_gain_mult', opts.consistency_min_gain_mult);
    setVal('wz_cons_terms_bonus', opts.consistency_max_terms_bonus);
    setVal('wz_cons_priority', opts.consistency_cast_diff_priority);
    setChk('wz_use_copeland', opts.use_copeland_priority);
    setChk('wz_use_off_gcd', opts.use_off_gcd_treatment);
    setChk('wz_use_v2', opts.use_v2);
  }

  function saveOptions() {
    wz.payload.gen_options = collectOptions();
    persist();
  }

  // 所有数值/勾选输入的 change 都触发保存
  ['wz_max_terms','wz_max_clauses','wz_min_gain','wz_min_cover','wz_max_chars',
   'wz_cons_gain_mult','wz_cons_terms_bonus','wz_cons_priority',
   'wz_use_copeland','wz_use_off_gcd','wz_use_v2'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', saveOptions);
  });

  // 初始渲染 consistency 网格 + 回填（如果 payload 里已有）
  applyOptions(wz.payload.gen_options);
  renderConsistencyGrid();

  // 进入 Step 5（生成）时把当前表单值固化到 payload
  btnNext.addEventListener('click', () => {
    if (wz.current === STEP_GENERATE) {
      saveOptions();
    }
  }, true); // capture 阶段，先于主 next 处理器

  // ═══════════════ Step 5：生成 + 诊断 ═══════════════
  const btnGenRun = document.getElementById('wz_gen_run');
  const btnGenCopy = document.getElementById('wz_gen_copy');
  const genStatus = document.getElementById('wz_gen_status');
  const genMacroWrap = document.getElementById('wz_gen_macro_wrap');
  const genMacroEl = document.getElementById('wz_gen_macro');
  const genPagesEl = document.getElementById('wz_gen_pages_summary');
  const genStatsWrap = document.getElementById('wz_gen_stats_wrap');
  const genStatsEl = document.getElementById('wz_gen_stats');
  const genDroppedWrap = document.getElementById('wz_gen_dropped_wrap');
  const genDroppedEl = document.getElementById('wz_gen_dropped');
  const genDiagWrap = document.getElementById('wz_gen_diag_wrap');
  const genDiagEl = document.getElementById('wz_gen_diag');

  async function runGeneration() {
    if (!wz.payload.timeline || !Array.isArray(wz.payload.timeline)) {
      alert('Step 4 还没载入 timeline');
      return;
    }
    genStatus.textContent = '生成中…';
    btnGenRun.disabled = true;
    btnGenCopy.disabled = true;
    const body = {
      timeline: wz.payload.timeline.map(e => ({
        name: e.name,
        triggered: !!e.triggered,
        is_main: e.is_main !== false,
        state_before: e.state_before || null,
      })),
      options: wz.payload.gen_options || {},
    };
    try {
      const r = await fetch('/api/macro/from_sequence', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!r.ok) throw new Error(await r.text());
      const resp = await r.json();
      wz.payload.generated = resp;
      wz.completed.add(STEP_GENERATE);
      renderGenResult(resp);
      persist();
      render();
      genStatus.textContent = '完成';
    } catch (e) {
      genStatus.textContent = '失败: ' + e.message;
    } finally {
      btnGenRun.disabled = false;
    }
  }

  function renderGenResult(resp) {
    // 宏文本
    genMacroWrap.style.display = 'block';
    genMacroEl.value = resp.macro_text || '';
    btnGenCopy.disabled = !resp.macro_text;

    // 页字数摘要：格式化为 title 右侧的 "盾(193/128) 刀(68/128)"
    const charsEl = document.getElementById('wz_gen_chars_inline');
    if (charsEl) charsEl.innerHTML = formatPagesInline(resp.pages || []);
    if (genPagesEl) genPagesEl.style.display = 'none'; // 废弃旧块（HTML 可能还残留）

    // 统计
    genStatsWrap.style.display = 'block';
    const s = resp.stats || {};
    const v2Lines = [];
    if (s.opener_trimmed) v2Lines.push(`开场裁剪: ${s.opener_trimmed} 条`);
    if (s.multi_start_trials) v2Lines.push(`多起点: ${s.multi_start_trials} 次择优`);
    if (s.cross_page_skills?.length) v2Lines.push(`跨页技能: ${s.cross_page_skills.join(', ')}`);
    const v2Html = v2Lines.length ? `<div style="color:#c9a847;margin-top:4px">${v2Lines.join(' · ')}</div>` : '';
    genStatsEl.innerHTML = `
      <div>主动 cast: ${s.total_main_casts || 0}</div>
      <div>用于学习: ${s.used_casts || 0}</div>
      <div>涉及技能: ${s.skill_count || 0}</div>
      ${v2Html}
    `;

    // 丢弃规则
    const dropped = resp.dropped_rules || [];
    if (dropped.length) {
      genDroppedWrap.style.display = 'block';
      genDroppedEl.innerHTML = dropped.map(d => `
        <div style="color:#8b949e;font-size:12px;padding:4px 0;border-bottom:1px solid #2a2f37">
          <span style="color:#c9a847">${escapeHtml(d.rule)}</span>
          · ${escapeHtml(d.reason)} · 覆盖 ${d.coverage_pct.toFixed(1)}%
        </div>
      `).join('');
    } else {
      genDroppedWrap.style.display = 'none';
    }

    // 规则诊断表
    const diags = resp.rule_diagnostics || [];
    if (diags.length) {
      genDiagWrap.style.display = 'block';
      renderDiagTable(diags);
    } else {
      genDiagWrap.style.display = 'none';
    }
  }

  function renderDiagTable(diags) {
    const tagBadge = (txt, color) =>
      `<span class="wz-diag-tag" style="background:${color}15;color:${color};border:1px solid ${color}40">${txt}</span>`;
    let html = `<thead><tr>
      <th>页</th><th>技能</th><th>条件</th>
      <th title="正样本数（该技能被释放的次数）">正</th>
      <th title="负样本数（同桶其他技能释放且本技能当时可释放的次数）">负</th>
      <th>F1</th><th>Copeland</th><th>标签</th>
    </tr></thead><tbody>`;
    diags.forEach((d, i) => {
      const tags = [];
      if (d.off_gcd) tags.push(tagBadge('off-GCD', '#79c0ff'));
      if (d.stance_switcher) tags.push(tagBadge('切姿态', '#c9a847'));
      if (d.consistency_sensitive) tags.push(tagBadge('一致性', '#ff7b72'));
      if (!d.is_main) tags.push(tagBadge('非主', '#8b949e'));
      const f1Cls = d.f1 >= 0.5 ? 'ok' : (d.f1 >= 0.2 ? 'warn' : 'bad');
      html += `<tr class="wz-diag-row" data-idx="${i}">
        <td>${escapeHtml(d.stance)}</td>
        <td><b>${escapeHtml(d.skill)}</b></td>
        <td class="wz-cond-col" title="${escapeHtml(d.condition)}">${escapeHtml(d.condition)}</td>
        <td>${d.positives}</td>
        <td>${d.negatives}</td>
        <td class="wz-f1-${f1Cls}">${d.f1.toFixed(3)}</td>
        <td>${d.copeland >= 0 ? '+' : ''}${d.copeland}</td>
        <td>${tags.join(' ')}</td>
      </tr>
      <tr class="wz-diag-expand" data-idx="${i}" style="display:none">
        <td colspan="8">${renderCandidates(d.candidates_top || [], d.notes || [])}</td>
      </tr>`;
    });
    html += '</tbody>';
    genDiagEl.innerHTML = html;
    // expand on row click
    genDiagEl.querySelectorAll('.wz-diag-row').forEach(row => {
      row.addEventListener('click', () => {
        const idx = row.dataset.idx;
        const ex = genDiagEl.querySelector(`.wz-diag-expand[data-idx="${idx}"]`);
        if (ex) ex.style.display = ex.style.display === 'none' ? 'table-row' : 'none';
      });
    });
  }

  function renderCandidates(cands, notes) {
    const notesHtml = notes.length ? `<div style="color:#c9a847;font-size:12px;margin-bottom:6px">${notes.map(escapeHtml).join(' · ')}</div>` : '';
    if (!cands.length) return notesHtml + '<div class="wz-hint" style="padding:8px">无候选</div>';
    let html = notesHtml + '<div style="display:grid;grid-template-columns:auto 1fr auto;gap:6px 16px;padding:8px 4px;font-size:12px;">';
    cands.forEach(c => {
      const mark = c.selected ? '<span style="color:#3fb950">✓</span>' : '<span style="color:#6a7280">·</span>';
      const f1Color = c.f1 >= 0.5 ? '#3fb950' : (c.f1 >= 0.2 ? '#c9a847' : '#6a7280');
      html += `<div>${mark}</div>
        <div style="font-family:ui-monospace,Consolas,monospace;${c.selected ? 'color:#e6edf3' : 'color:#8b949e'}">${escapeHtml(c.expr)}</div>
        <div style="color:${f1Color}">F1=${c.f1.toFixed(3)}</div>`;
    });
    html += '</div>';
    return html;
  }

  btnGenRun?.addEventListener('click', runGeneration);
  btnGenCopy?.addEventListener('click', () => {
    const txt = genMacroEl.value;
    if (!txt) return;
    navigator.clipboard?.writeText(txt);
    genStatus.textContent = '已复制';
    setTimeout(() => { genStatus.textContent = ''; }, 1200);
  });

  // 语法染色（复用优化器里的 highlightMacroText / highlightMacroLine）
  const wzHl = document.getElementById('wz_gen_macro_hl');
  function wzRenderHl() {
    if (!wzHl || !genMacroEl) return;
    wzHl.innerHTML = (typeof highlightMacroText === 'function'
      ? highlightMacroText(genMacroEl.value)
      : escapeHtml(genMacroEl.value)) + '\n';
  }
  if (genMacroEl) {
    genMacroEl.addEventListener('input', wzRenderHl);
    genMacroEl.addEventListener('scroll', () => {
      if (wzHl) { wzHl.scrollTop = genMacroEl.scrollTop; wzHl.scrollLeft = genMacroEl.scrollLeft; }
    });
  }
  // 每次渲染结果后也刷新高亮层
  const origRenderGenResult = renderGenResult;
  renderGenResult = function(resp) {
    origRenderGenResult(resp);
    wzRenderHl();
    setTimeout(syncStep2Heights, 0);
  };

  // ── Step 2：把右列（规则诊断）的高度同步到左列（宏文本+统计+丢弃）──
  function syncStep2Heights() {
    const left = document.querySelector('.wz-step2-left');
    const right = document.querySelector('.wz-step2-right');
    if (!left || !right) return;
    const h = left.offsetHeight;
    if (h <= 0) return;
    right.style.maxHeight = h + 'px';
    right.style.height = h + 'px';
    right.style.overflow = 'hidden';
    // 内部 scroll 区域 fill
    const wrap = right.querySelector('#wz_gen_diag_wrap');
    if (wrap) {
      wrap.style.display = 'flex';
      wrap.style.flexDirection = 'column';
      wrap.style.height = '100%';
      wrap.style.minHeight = '0';
    }
    const scroll = right.querySelector('.wz-diag-scroll');
    if (scroll) {
      scroll.style.maxHeight = 'none';
      scroll.style.flex = '1 1 auto';
      scroll.style.minHeight = '0';
    }
  }
  // 左列尺寸变化时同步（textarea resize / 内容变化）
  if (window.ResizeObserver) {
    const left = document.querySelector('.wz-step2-left');
    if (left) new ResizeObserver(syncStep2Heights).observe(left);
  }
  // Step 5（生成）首次进入也同步
  window.addEventListener('load', () => setTimeout(syncStep2Heights, 100));
  // 切到 Step 5 时触发
  const origSyncSimEmbed2 = syncSimEmbed;
  syncSimEmbed = function() {
    origSyncSimEmbed2();
    if (pageWz.classList.contains('active') && wz.current === STEP_GENERATE) {
      setTimeout(syncStep2Heights, 50);
    }
  };

  // Step 3 不用列间同步 —— 场景表在 CSS 里独立限高滚动就够了

  // ═══════════════ Step 6：验证 + 迭代 ═══════════════
  const DELAY_OPTIONS = [0, 23, 60, 90, 120];
  const RAGE_OPTIONS = [0, 30, 50, 100];
  const DUR_OPTIONS = [60, 120, 240, 300, 600];
  const SC_DEFAULT_DELAYS = [0, 60, 120];
  const SC_DEFAULT_RAGES = [0, 30, 50, 100];
  const SC_DEFAULT_DURS = [120, 300];

  function renderCbList(containerId, values, selected, suffix = '') {
    const el = document.getElementById(containerId);
    if (!el) return;
    const sel = new Set(selected);
    el.innerHTML = values.map(v => `
      <label>
        <input type="checkbox" data-v="${v}" ${sel.has(v) ? 'checked' : ''}> ${v}${suffix}
      </label>
    `).join('');
    el.querySelectorAll('input').forEach(cb => {
      cb.addEventListener('change', updateScenarioCount);
    });
  }
  function readCbList(containerId) {
    return [...document.querySelectorAll(`#${containerId} input:checked`)]
      .map(cb => parseFloat(cb.dataset.v));
  }
  function updateScenarioCount() {
    const n = readCbList('wz_sc_delays').length
            * readCbList('wz_sc_rages').length
            * readCbList('wz_sc_durations').length;
    const el = document.getElementById('wz_sc_count');
    if (el) el.textContent = `组合数：${n}`;
    // 持久化
    wz.payload.scenarios = {
      delays: readCbList('wz_sc_delays'),
      rages: readCbList('wz_sc_rages'),
      durations: readCbList('wz_sc_durations'),
    };
    persist();
  }

  function initScenarioControls() {
    // 一次性重置：本版本更新了怒气/时长的默认值，强制所有用户用新默认
    const RESET_FLAG = 'jx3_scenarios_v2_reset';
    if (!localStorage.getItem(RESET_FLAG)) {
      delete wz.payload.scenarios;
      try { localStorage.setItem(RESET_FLAG, '1'); } catch (_) {}
    }
    const sc = wz.payload.scenarios || {};
    renderCbList('wz_sc_delays', DELAY_OPTIONS, sc.delays || SC_DEFAULT_DELAYS, 'ms');
    renderCbList('wz_sc_rages', RAGE_OPTIONS, sc.rages || SC_DEFAULT_RAGES);
    renderCbList('wz_sc_durations', DUR_OPTIONS, sc.durations || SC_DEFAULT_DURS, 's');
    updateScenarioCount();
  }
  initScenarioControls();

  // 跑单次 simulate（返回 simulate 响应）
  // 默认 lite=true：启用 lite + lite_keep_timeline，跳过 state_before/after/runtime_stats 构造与序列化，
  // 但保留 timeline 事件（含 .name / .skill_id / .triggered），适用于蒸馏 / 多目标精调 workflow 的
  // cast count 比较 + DPS 计算（这俩 workflow 是 simulateOnce 的全部消费者）。
  // 若调用方需要 hover 详情等 full 数据，显式传 lite: false。
  async function simulateOnce({ macroText, delay, initialRage, duration, pauses, lite = true }) {
    const maxSlots = Math.ceil(duration / 0.25) + 20;
    const r = await fetch('/api/simulate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        haste_level: parseInt(getAttrs().haste_level) || 0,
        sequence: Array(maxSlots).fill('__macro__'),
        macro_text: macroText,
        macro_duration: duration,
        talents: getSelectedTalents(),
        recipes: getSelectedRecipes(),
        channel_ticks: {}, timing_offsets: {}, qijin_buffs: {},
        network_delay: delay,
        attributes: getAttrs(),
        target: getTarget(),
        initial_rage: initialRage,
        pauses: Array.isArray(pauses) ? pauses : [],
        equipment: getEquipmentMap(),
        team_buffs: getTeamBuffs(),
        formation: getCurrentFormation(),
        lite,
        lite_keep_timeline: lite,
      }),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json();
  }
  window.Jx3SimulateOnce = simulateOnce;

  // 按技能名合并连段（与诊断一致）
  function collectCastCounts(timeline) {
    const m = {};
    const alias = { '月照连营': '阵云结晦', '雁门迢递': '阵云结晦', '隐刀': '闪刀', '惊沙': '盾毅' };
    const WHL = { '阵云结晦·雾海': 1, '月照连营·雾海': 1, '雁门迢递·雾海': 1 };
    for (const e of timeline || []) {
      if (e.triggered) continue;
      const full = e.name || '';
      const base = full.split('·')[0];
      const key = WHL[full] ? full : base;
      const k = alias[key] || key;
      m[k] = (m[k] || 0) + 1;
    }
    return m;
  }
  window.Jx3CollectCastCounts = collectCastCounts;

  function renderCastDiff(origCounts, genCounts, targetEl) {
    const keys = [...new Set([...Object.keys(origCounts), ...Object.keys(genCounts)])].sort();
    let html = `<table class="wz-diag-table">
      <thead><tr><th>技能</th><th>原序列</th><th>宏</th><th>差</th></tr></thead><tbody>`;
    for (const k of keys) {
      const a = origCounts[k] || 0;
      const b = genCounts[k] || 0;
      const d = b - a;
      const tol = Math.max(2, a * 0.3);
      const color = Math.abs(d) > tol ? '#f85149' : (d === 0 ? '#3fb950' : '#c9a847');
      html += `<tr>
        <td>${escapeHtml(k)}</td>
        <td>${a}</td><td>${b}</td>
        <td style="color:${color}">${d > 0 ? '+' : ''}${d}</td>
      </tr>`;
    }
    html += '</tbody></table>';
    targetEl.innerHTML = html;
  }

  // 多场景验证结果的状态（供 sort 复用）
  let _lastVerifyRows = null;
  let _lastVerifyOrigCounts = null;
  let _lastVerifySort = { col: 'delay', dir: 'asc' };

  function renderScenarioTable(rows, origCounts, col, dir) {
    _lastVerifySort = { col, dir };
    const sorted = rows.slice().sort((a, b) => {
      const va = a[col];
      const vb = b[col];
      // null（失败行）始终排在最后
      if (va == null && vb == null) return 0;
      if (va == null) return 1;
      if (vb == null) return -1;
      const cmp = va - vb;
      return dir === 'asc' ? cmp : -cmp;
    });
    const arrow = (c) => c === col ? (dir === 'asc' ? ' ▲' : ' ▼') : '';
    let html = `<table class="wz-diag-table wz-verify-table"><thead><tr>
      <th data-sort="delay" class="wz-sortable">延迟${arrow('delay')}</th>
      <th data-sort="rage" class="wz-sortable">怒气${arrow('rage')}</th>
      <th data-sort="duration" class="wz-sortable">时长${arrow('duration')}</th>
      <th data-sort="origDps" class="wz-sortable">原 DPS${arrow('origDps')}</th>
      <th data-sort="dps" class="wz-sortable">宏 DPS${arrow('dps')}</th>
      <th data-sort="ratio" class="wz-sortable">vs 原${arrow('ratio')}</th>
    </tr></thead><tbody>`;
    sorted.forEach((r, i) => {
      if (r.err) {
        html += `<tr class="wz-ver-row"><td>${r.delay}ms</td><td>${r.rage}</td><td>${r.duration}s</td><td colspan="3" style="color:#f85149">失败: ${escapeHtml(r.err)}</td></tr>`;
        return;
      }
      const rc = r.ratio >= 0.95 ? '#3fb950' : (r.ratio >= 0.9 ? '#c9a847' : '#f85149');
      html += `<tr class="wz-ver-row" data-row-idx="${i}">
        <td>${r.delay}ms</td>
        <td>${r.rage}</td>
        <td>${r.duration}s</td>
        <td>${Math.round(r.origDps || 0).toLocaleString()}</td>
        <td>${Math.round(r.dps).toLocaleString()}</td>
        <td style="color:${rc}">${(r.ratio * 100).toFixed(1)}%</td>
      </tr>`;
    });
    html += '</tbody></table>';
    const container = document.getElementById('wz_ver_per_scenario');
    container.innerHTML = html;
    // 绑定排序
    container.querySelectorAll('th.wz-sortable').forEach(th => {
      th.addEventListener('click', () => {
        const c = th.dataset.sort;
        const nextDir = (_lastVerifySort.col === c && _lastVerifySort.dir === 'asc') ? 'desc' : 'asc';
        renderScenarioTable(_lastVerifyRows, _lastVerifyOrigCounts, c, nextDir);
      });
    });
    // 绑定 hover：tooltip 用每行自己的 origCounts（按场景重跑的原宏结果），
    // 没有则退回全局 fallback
    container.querySelectorAll('.wz-ver-row[data-row-idx]').forEach(tr => {
      tr.addEventListener('mouseenter', e => {
        const row = sorted[parseInt(tr.dataset.rowIdx)];
        showCastTooltip(e, row, row?.origCounts || origCounts);
      });
      tr.addEventListener('mousemove', updateTooltipPos);
      tr.addEventListener('mouseleave', hideCastTooltip);
    });
  }

  // hover tooltip 显示 cast diff
  function showCastTooltip(e, row, origCounts) {
    if (!row || !row.castCounts) return;
    let tip = document.getElementById('wz_ver_tooltip');
    if (!tip) {
      tip = document.createElement('div');
      tip.id = 'wz_ver_tooltip';
      tip.className = 'wz-ver-tooltip';
      document.body.appendChild(tip);
    }
    if (!origCounts) {
      tip.innerHTML = '<div class="wz-hint">无参考 timeline，无法对比</div>';
    } else {
      const keys = [...new Set([...Object.keys(origCounts), ...Object.keys(row.castCounts)])].sort();
      let inner = `<div style="font-size:11px;color:#8b949e;margin-bottom:6px;">
        ${row.delay}ms · 怒气 ${row.rage} · ${row.duration}s · DPS ${Math.round(row.dps).toLocaleString()}
      </div>`;
      inner += '<table class="wz-ver-tooltip-table"><thead><tr><th>技能</th><th>原</th><th>宏</th><th>差</th></tr></thead><tbody>';
      for (const k of keys) {
        const a = origCounts[k] || 0;
        const b = row.castCounts[k] || 0;
        const d = b - a;
        const tol = Math.max(2, a * 0.3);
        const color = Math.abs(d) > tol ? '#f85149' : (d === 0 ? '#3fb950' : '#c9a847');
        inner += `<tr><td>${escapeHtml(k)}</td><td>${a}</td><td>${b}</td><td style="color:${color}">${d > 0 ? '+' : ''}${d}</td></tr>`;
      }
      inner += '</tbody></table>';
      tip.innerHTML = inner;
    }
    tip.style.display = 'block';
    updateTooltipPos(e);
  }
  function updateTooltipPos(e) {
    const tip = document.getElementById('wz_ver_tooltip');
    if (!tip || tip.style.display === 'none') return;
    const pad = 12;
    const tw = tip.offsetWidth;
    const th = tip.offsetHeight;
    let x = e.clientX + pad;
    let y = e.clientY + pad;
    if (x + tw > window.innerWidth - 8) x = e.clientX - tw - pad;
    if (y + th > window.innerHeight - 8) y = e.clientY - th - pad;
    tip.style.left = x + 'px';
    tip.style.top = y + 'px';
  }
  function hideCastTooltip() {
    const tip = document.getElementById('wz_ver_tooltip');
    if (tip) tip.style.display = 'none';
  }

  async function verifyQuick() {
    // 优先用 Step 6 迭代后的宏；否则用 Step 5 生成的
    const macroText = wz.payload.iterated_macro
      || wz.payload.generated?.macro_text
      || document.getElementById('wz_gen_macro')?.value;
    if (!macroText) { alert('没有宏可验证。先在 Step 5 生成一个。'); return; }
    const ref = wz.payload.timeline_meta;
    if (!wz.payload.timeline) { alert('没有原序列，没法对比 cast diff。先在 Step 4 载入 timeline。'); return; }
    const refMacro = wz.payload.reference_macro;
    const verStatus = document.getElementById('wz_ver_status');
    const btn = document.getElementById('wz_ver_quick');
    btn.disabled = true;
    verStatus.textContent = refMacro ? '跑中（原宏+生成宏）…' : '跑中…';
    try {
      const scConf = {
        delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
        initialRage: adminInitialRage || 0,
        duration: ref?.fight_time || 60,
      };
      // 如果 Step 4 是跑宏载入的（有 reference_macro），原宏也按当前场景跑一次用于对比
      // 否则退回用载入时的 timeline 当基线
      const [genResp, origResp] = await Promise.all([
        simulateOnce({ macroText, ...scConf }),
        refMacro ? simulateOnce({ macroText: refMacro, ...scConf }) : Promise.resolve(null),
      ]);
      const origTimeline = origResp ? origResp.timeline : wz.payload.timeline;
      const origDps = origResp ? origResp.dps : (ref?.dps || 0);
      const origCounts = collectCastCounts(origTimeline);
      const genCounts = collectCastCounts(genResp.timeline);
      const ratio = origDps ? (genResp.dps / origDps) : 0;
      const color = ratio >= 0.95 ? '#3fb950' : (ratio >= 0.9 ? '#c9a847' : '#f85149');
      const basisNote = refMacro ? '原宏按当前场景重跑' : '原序列取自 Step 4 载入时';
      document.getElementById('wz_ver_result_wrap').style.display = 'block';
      document.getElementById('wz_ver_summary').innerHTML = `
        <div style="color:${color};font-weight:600;font-size:14px;padding:8px 0">
          快速验证 · ${basisNote}<br>
          DPS: 原 ${Math.round(origDps).toLocaleString()} → 宏 ${Math.round(genResp.dps || 0).toLocaleString()}
          （<b>${(ratio * 100).toFixed(1)}%</b>）
        </div>`;
      document.getElementById('wz_ver_per_scenario').innerHTML = '';
      renderCastDiff(origCounts, genCounts, document.getElementById('wz_ver_cast_diff'));
      wz.completed.add(STEP_ITERATE);
      persist();
      render();
      verStatus.textContent = '完成';
    } catch (e) {
      verStatus.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }

  // 批量模拟：一次 HTTP 请求跑多个场景（v2 模式用）
  async function batchSimulate(macroText, combos) {
    const maxDur = Math.max(...combos.map(c => c.duration));
    const maxSlots = Math.ceil(maxDur / 0.25) + 20;
    const base = {
      haste_level: parseInt(getAttrs().haste_level) || 0,
      sequence: Array(maxSlots).fill('__macro__'),
      macro_text: macroText,
      macro_duration: maxDur,
      talents: getSelectedTalents(),
      recipes: getSelectedRecipes(),
      channel_ticks: {}, timing_offsets: {}, qijin_buffs: {},
      network_delay: 0,
      attributes: getAttrs(),
      target: getTarget(),
      initial_rage: 0,
      pauses: [],
      tiegu_mode: getTieguMode(), experimental: isExperimental(),
      hanjia_expectation: isHanjiaExpectationEnabled(),
      equipment: getEquipmentMap(),
      team_buffs: getTeamBuffs(),
        formation: getCurrentFormation(),
    };
    const scenarios = combos.map(c => ({
      network_delay: c.delay,
      initial_rage: c.initialRage,
      macro_duration: c.duration,
    }));
    const r = await fetch('/api/macro/batch_simulate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ base, scenarios }),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json(); // BatchSimResult[]
  }

  async function verifyFull() {
    const macroText = wz.payload.iterated_macro
      || wz.payload.generated?.macro_text
      || document.getElementById('wz_gen_macro')?.value;
    if (!macroText) { alert('没有宏可验证'); return; }
    const ref = wz.payload.timeline_meta;
    const sc = wz.payload.scenarios || {};
    const delays = sc.delays || SC_DEFAULT_DELAYS;
    const rages = sc.rages || SC_DEFAULT_RAGES;
    const durs = sc.durations || SC_DEFAULT_DURS;
    const combos = [];
    for (const d of delays) for (const r of rages) for (const du of durs) {
      combos.push({ delay: d, initialRage: r, duration: du });
    }
    if (combos.length === 0) { alert('场景组合数为 0，先在多场景配置里勾选'); return; }
    const refMacro = wz.payload.reference_macro;
    const verStatus = document.getElementById('wz_ver_status');
    const btn = document.getElementById('wz_ver_full');
    btn.disabled = true;
    const useV2 = !!document.getElementById('wz_use_v2')?.checked;
    const totalCalls = combos.length * (refMacro ? 2 : 1);
    verStatus.textContent = useV2
      ? `跑中 (v2 批量 · ${combos.length} 个场景${refMacro ? ' × 原+生成' : ''})…`
      : `跑中 (${combos.length} 个场景 × ${refMacro ? '原+生成' : '生成'}，共 ${totalCalls} 次)…`;
    try {
      let results;
      if (useV2) {
        // v2: 批量 API — 一次请求跑所有场景
        const [genBatch, origBatch] = await Promise.all([
          batchSimulate(macroText, combos),
          refMacro ? batchSimulate(refMacro, combos) : Promise.resolve(null),
        ]);
        results = combos.map((c, i) => {
          const genR = genBatch[i];
          const origR = origBatch ? origBatch[i] : null;
          return {
            combo: c,
            resp: { dps: genR.dps, timeline: null, fight_time: genR.fight_time },
            origResp: origR ? { dps: origR.dps, timeline: null, fight_time: origR.fight_time } : null,
            castCounts: genR.cast_counts,
            origCounts: origR ? origR.cast_counts : null,
          };
        });
      } else {
        // v1: 原始逐个请求（已有 Promise.all 并行）
        results = await Promise.all(combos.map(async c => {
          const [genR, origR] = await Promise.all([
            simulateOnce({ macroText, ...c }).catch(e => ({ __err: e.message })),
            refMacro ? simulateOnce({ macroText: refMacro, ...c }).catch(e => ({ __err: e.message })) : Promise.resolve(null),
          ]);
          if (genR.__err) return { combo: c, err: genR.__err };
          return { combo: c, resp: genR, origResp: origR && !origR.__err ? origR : null };
        }));
      }
      const ok = results.filter(r => !r.err);
      const dpsArr = ok.map(r => r.resp.dps || 0);
      const mean = dpsArr.reduce((a, b) => a + b, 0) / (dpsArr.length || 1);
      const min = dpsArr.length ? Math.min(...dpsArr) : 0;
      const max = dpsArr.length ? Math.max(...dpsArr) : 0;
      const stdev = Math.sqrt(dpsArr.reduce((a, b) => a + (b - mean) ** 2, 0) / (dpsArr.length || 1));
      const fallbackRefDps = ref?.dps || 0;
      // 每行的 ratio（基于该场景重跑的原宏 DPS）—— 和表格显示保持一致
      const ratios = ok.map(r => {
        const oDps = r.origResp ? r.origResp.dps : fallbackRefDps;
        return oDps ? ((r.resp.dps || 0) / oDps) : 0;
      });
      const minRatio = ratios.length ? Math.min(...ratios) : 0;
      const meanRatio = ratios.length ? ratios.reduce((a, b) => a + b, 0) / ratios.length : 0;
      const color = minRatio >= 0.9 ? '#3fb950' : (minRatio >= 0.8 ? '#c9a847' : '#f85149');
      document.getElementById('wz_ver_result_wrap').style.display = 'block';
      document.getElementById('wz_ver_summary').innerHTML = `
        <div style="font-size:13px;padding:8px 0;color:#e6edf3;">
          <b>多场景完整验证</b> · ${combos.length} 个场景<br>
          DPS 均值 <b>${Math.round(mean).toLocaleString()}</b> · 最小 <span style="color:${color}"><b>${Math.round(min).toLocaleString()}</b></span>
          · 最大 ${Math.round(max).toLocaleString()} · 标准差 ${Math.round(stdev).toLocaleString()}<br>
          vs 原宏：均值 <b>${(meanRatio * 100).toFixed(1)}%</b> · 最坏 <b style="color:${color}">${(minRatio * 100).toFixed(1)}%</b>
          <span style="color:#6a7280">（各行以该场景的原宏 DPS 为基线）</span>
        </div>`;
      // 每场景表（含 hover 技能对比 + 表头排序）
      // 原宏 cast 基线：优先用当场景重跑结果（更公平），否则退回 Step 4 载入的 timeline
      const fallbackOrigCounts = wz.payload.timeline ? collectCastCounts(wz.payload.timeline) : null;
      const rows = results.map(r => {
        if (r.err) {
          return {
            delay: r.combo.delay, rage: r.combo.initialRage, duration: r.combo.duration,
            dps: null, ratio: null, err: r.err, castCounts: null, origCounts: null, origDps: null,
          };
        }
        const dps = r.resp.dps || 0;
        const oDps = r.origResp ? r.origResp.dps : fallbackRefDps;
        // v2 批量结果已含 castCounts/origCounts；v1 需从 timeline 提取
        const cc = r.castCounts || (r.resp.timeline ? collectCastCounts(r.resp.timeline) : null);
        const oc = r.origCounts || (r.origResp?.timeline ? collectCastCounts(r.origResp.timeline) : fallbackOrigCounts);
        return {
          delay: r.combo.delay, rage: r.combo.initialRage, duration: r.combo.duration,
          dps, origDps: oDps,
          ratio: oDps ? (dps / oDps) : 0,
          err: null,
          castCounts: cc,
          origCounts: oc,
        };
      });
      _lastVerifyRows = rows;
      _lastVerifyOrigCounts = fallbackOrigCounts;
      renderScenarioTable(rows, null, 'delay', 'asc');
      document.getElementById('wz_ver_cast_diff').innerHTML = '';
      wz.completed.add(STEP_ITERATE);
      persist();
      render();
      verStatus.textContent = '完成';
    } catch (e) {
      verStatus.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }

  document.getElementById('wz_ver_quick')?.addEventListener('click', verifyQuick);
  document.getElementById('wz_ver_full')?.addEventListener('click', verifyFull);

  // ═══════════════ Step 6 迭代：冗余剪枝 ═══════════════
  // "当前最佳宏"：迭代结果优先；否则取 Step 5 生成的
  function getCurrentBestMacro() {
    return wz.payload.iterated_macro
      || wz.payload.generated?.macro_text
      || document.getElementById('wz_gen_macro')?.value;
  }

  async function pruneRedundant() {
    const btn = document.getElementById('wz_it_prune');
    const status = document.getElementById('wz_it_status');
    const log = document.getElementById('wz_it_log');
    const wrap = document.getElementById('wz_it_result_wrap');

    // 起点：如果之前已迭代过就在那个结果上继续；否则用生成的
    const currentMacro = getCurrentBestMacro();
    if (!currentMacro) { alert('没有宏可剪枝。先在 Step 5 生成。'); return; }
    const ref = wz.payload.timeline_meta;
    const duration = ref?.fight_time || 120;
    const scConf = {
      delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      initialRage: adminInitialRage || 0,
      duration,
    };
    // 一致性敏感清单（从生成选项取）
    const sensitive = new Set(wz.payload.gen_options?.consistency_sensitive_skills
      || currentMount?.workflow_a?.consistency_sensitive_skills
      || ['血怒', '业火麟光', '偃守孤旌']);

    btn.disabled = true;
    wrap.style.display = 'block';
    log.innerHTML = '';
    status.textContent = '基线中…';

    function appendLog(html) {
      const div = document.createElement('div');
      div.className = 'wz-prune-log-line';
      div.innerHTML = html;
      log.appendChild(div);
    }

    try {
      // 基线
      const base = await simulateOnce({ macroText: currentMacro, ...scConf });
      const baseCounts = collectCastCounts(base.timeline);
      let bestMacro = currentMacro;
      let bestDps = base.dps || 0;
      appendLog(`<b>基线</b> DPS=${Math.round(bestDps).toLocaleString()}`);

      // 多轮：每轮拉候选 → 并行评估 → 选最优安全删除 → 下一轮
      const MAX_ROUNDS = 5;
      const ACCEPT_DPS_TOL = 0.002;   // 允许 0.2% 噪声
      const SENSITIVE_DRIFT_TOL = 1;
      const NORMAL_DRIFT_TOL = 2;

      let totalRemoved = 0;
      for (let round = 1; round <= MAX_ROUNDS; round++) {
        status.textContent = `第 ${round} 轮…`;
        const candR = await fetch('/api/macro/prune_candidates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ macro_text: bestMacro }),
        });
        if (!candR.ok) throw new Error(await candR.text());
        const candJson = await candR.json();
        let candidates = candJson.candidates || [];
        // 硬性保护：一致性敏感技能的条件一律不让剪枝碰（留给 cast-diff 反馈去微调）
        const beforeFilter = candidates.length;
        candidates = candidates.filter(c => !sensitive.has(c.skill));
        if (beforeFilter !== candidates.length) {
          appendLog(`<span style="color:#8b949e">第 ${round} 轮：跳过敏感技能 ${beforeFilter - candidates.length} 个候选</span>`);
        }
        if (candidates.length === 0) {
          appendLog(`<span style="color:#8b949e">第 ${round} 轮：无可剪枝的候选</span>`);
          break;
        }

        // 并行评估所有候选
        status.textContent = `第 ${round} 轮：评估 ${candidates.length} 个候选…`;
        const evals = await Promise.all(candidates.map(async c => {
          try {
            const r = await simulateOnce({ macroText: c.after_macro, ...scConf });
            return { cand: c, dps: r.dps || 0, counts: collectCastCounts(r.timeline) };
          } catch (e) {
            return null;
          }
        }));
        const ok = evals.filter(x => x);

        // 找最优"可接受"的：DPS 不跌太多 + 敏感技能 drift 在容忍内
        // 并且：一致性敏感技能的条件原则上**不动**——除非该原子属于"重复条件"
        // （OR 分支里其他子句已能覆盖相同正样本集）
        const acceptable = ok.filter(e => {
          if ((bestDps - e.dps) / Math.max(bestDps, 1) > ACCEPT_DPS_TOL) return false;
          for (const skill of Object.keys(baseCounts)) {
            const tol = sensitive.has(skill) ? SENSITIVE_DRIFT_TOL : NORMAL_DRIFT_TOL;
            const diff = Math.abs((baseCounts[skill] || 0) - (e.counts[skill] || 0));
            if (diff > tol) return false;
          }
          // 敏感技能：只允许删"无意义"原子（删了之后该技能的 cast 数完全不变）
          if (sensitive.has(e.cand.skill)) {
            const before = baseCounts[e.cand.skill] || 0;
            const after = e.counts[e.cand.skill] || 0;
            if (before !== after) return false;
          }
          return true;
        });
        if (acceptable.length === 0) {
          appendLog(`<span style="color:#c9a847">第 ${round} 轮：${candidates.length} 个候选中无一可安全删除</span>`);
          break;
        }
        // 排序优先级：
        // 1) 一致性敏感技能（血怒/业火麟光等）放到最后再剪 —— 同分时非敏感优先
        // 2) 相同敏感性下，DPS 高的优先
        acceptable.sort((a, b) => {
          const sA = sensitive.has(a.cand.skill) ? 1 : 0;
          const sB = sensitive.has(b.cand.skill) ? 1 : 0;
          if (sA !== sB) return sA - sB;          // 非敏感先（sA=0 排前）
          return b.dps - a.dps;
        });
        const picked = acceptable[0];
        const delta = picked.dps - bestDps;
        bestDps = picked.dps;
        bestMacro = picked.cand.after_macro;
        totalRemoved++;
        appendLog(`<span style="color:#3fb950">第 ${round} 轮</span> 删除 <code>${escapeHtml(picked.cand.atom)}</code>（${escapeHtml(picked.cand.skill)}），Δ DPS = <b style="color:${delta >= 0 ? '#3fb950' : '#c9a847'}">${delta >= 0 ? '+' : ''}${delta.toFixed(0)}</b>`);
      }

      // 运算符归一化：>= → >、<= → < 省字符
      //   rage 整数：rage>=N ≡ rage>(N-1)、rage<=N ≡ rage<(N+1)（无损）
      //   (t)bufftime 浮点：直接去 "="（丢掉 remaining==N 精确相等的极罕见边界）
      const normalized = normalizeOperators(bestMacro);
      const normChars = normalized.length;
      const origChars = bestMacro.length;
      if (normChars < origChars) {
        appendLog(`<span style="color:#79c0ff">运算符归一化</span>：>=/<= → >/< 省了 <b>${origChars - normChars}</b> 字`);
        bestMacro = normalized;
      }

      // 把迭代结果写到 Step 6 的独立字段，不触动 Step 5
      const origMacro = wz.payload.generated?.macro_text || currentMacro;
      wz.payload.iterated_macro = bestMacro;
      wz.payload.iterated_meta = {
        base_dps: base.dps || 0,
        final_dps: bestDps,
        atoms_removed: totalRemoved,
        orig_chars: origMacro.length,
        final_chars: bestMacro.length,
      };
      if (!Array.isArray(wz.payload.iter_history)) wz.payload.iter_history = [];
      wz.payload.iter_history.push({
        ts: Date.now(),
        kind: '冗余剪枝',
        macro: bestMacro,
        meta: { ...wz.payload.iterated_meta },
      });
      if (wz.payload.iter_history.length > 20) wz.payload.iter_history.shift();
      persist();
      renderIteratedResult();
      renderIterHistory();

      status.textContent = `完成：共删除 ${totalRemoved} 个原子 · 最终 DPS ${Math.round(bestDps).toLocaleString()}`;
      appendLog(`<br><b>总结</b>：共删除 <b>${totalRemoved}</b> 个原子，最终 DPS <b>${Math.round(bestDps).toLocaleString()}</b>（基线 ${Math.round(base.dps || 0).toLocaleString()}）`);
    } catch (e) {
      status.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }

  document.getElementById('wz_it_prune')?.addEventListener('click', pruneRedundant);

  // ═══════════════ PR 10：cast-diff 反馈迭代 ═══════════════
  // 以原宏（或载入 timeline）的技能释放数为目标，反复对每个偏差最大的技能
  // 尝试剪枝候选（目前只能走"放宽条件"方向——删原子；"收紧"需要加原子，留给后续）
  // 接受标准：总 |cast diff| 严格下降 且 DPS 跌幅 ≤ 0.5%
  async function castDiffFeedback() {
    const btn = document.getElementById('wz_it_castdiff');
    const status = document.getElementById('wz_it_status');
    const log = document.getElementById('wz_it_log');
    const wrap = document.getElementById('wz_it_result_wrap');

    const currentMacro = getCurrentBestMacro();
    if (!currentMacro) { alert('没有宏可迭代。先在 Step 5 生成。'); return; }
    if (!wz.payload.timeline) { alert('没有原序列参考。先在 Step 4 载入 timeline。'); return; }
    const ref = wz.payload.timeline_meta;
    const duration = ref?.fight_time || 120;
    const scConf = {
      delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      initialRage: adminInitialRage || 0,
      duration,
    };
    const refMacro = wz.payload.reference_macro;

    btn.disabled = true;
    wrap.style.display = 'block';
    log.innerHTML = '';
    status.textContent = '基线中…';

    const appendLog = (html) => {
      const div = document.createElement('div');
      div.className = 'wz-prune-log-line';
      div.innerHTML = html;
      log.appendChild(div);
    };
    // v2-2.6: 加权 cast-diff — 敏感技能权重更高
    const sensitive = new Set(wz.payload.gen_options?.consistency_sensitive_skills
      || currentMount?.workflow_a?.consistency_sensitive_skills
      || ['血怒', '业火麟光', '偃守孤旌']);
    const castDiffPriority = wz.payload.gen_options?.consistency_cast_diff_priority || 5.0;
    const totalAbsDiff = (a, b) => {
      const keys = new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
      let s = 0;
      for (const k of keys) {
        const w = sensitive.has(k) ? castDiffPriority : 1.0;
        s += w * Math.abs((b[k] || 0) - (a[k] || 0));
      }
      return s;
    };

    try {
      // 目标：原宏（或原 timeline）在当前场景下的 cast counts
      const origResp = refMacro ? await simulateOnce({ macroText: refMacro, ...scConf }) : null;
      const targetCounts = origResp ? collectCastCounts(origResp.timeline) : collectCastCounts(wz.payload.timeline);
      const baseResp = await simulateOnce({ macroText: currentMacro, ...scConf });
      let bestMacro = currentMacro;
      let bestDps = baseResp.dps || 0;
      let bestDiff = totalAbsDiff(targetCounts, collectCastCounts(baseResp.timeline));
      appendLog(`<b>基线</b> DPS=${Math.round(bestDps).toLocaleString()} · Σ|cast diff|=${bestDiff}`);

      const MAX_ROUNDS = 5;
      const DPS_DROP_TOL = 0.005;
      let rounds = 0;
      for (let round = 1; round <= MAX_ROUNDS; round++) {
        status.textContent = `第 ${round} 轮…`;
        const candR = await fetch('/api/macro/prune_candidates', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ macro_text: bestMacro }),
        });
        if (!candR.ok) { appendLog('<span style="color:#f85149">候选失败</span>'); break; }
        const cands = (await candR.json()).candidates || [];
        if (cands.length === 0) { appendLog(`第 ${round} 轮：无候选`); break; }

        status.textContent = `第 ${round} 轮：评估 ${cands.length} 个候选…`;
        const evals = await Promise.all(cands.map(async c => {
          try {
            const r = await simulateOnce({ macroText: c.after_macro, ...scConf });
            return { cand: c, dps: r.dps || 0, diff: totalAbsDiff(targetCounts, collectCastCounts(r.timeline)) };
          } catch { return null; }
        }));
        const ok = evals.filter(x => x);
        const acceptable = ok.filter(e => e.diff < bestDiff
          && (bestDps - e.dps) / Math.max(bestDps, 1) <= DPS_DROP_TOL);
        if (acceptable.length === 0) {
          appendLog(`<span style="color:#c9a847">第 ${round} 轮：${cands.length} 个候选中无一降 diff 且保 DPS</span>`);
          break;
        }
        acceptable.sort((a, b) => (a.diff - b.diff) || (b.dps - a.dps));
        const pick = acceptable[0];
        const diffDrop = bestDiff - pick.diff;
        const dpsDelta = pick.dps - bestDps;
        bestDiff = pick.diff; bestDps = pick.dps; bestMacro = pick.cand.after_macro;
        rounds++;
        appendLog(`<span style="color:#3fb950">第 ${round} 轮</span> 删 <code>${escapeHtml(pick.cand.atom)}</code>（${escapeHtml(pick.cand.skill)}）· Σ|diff| −${diffDrop} · Δ DPS ${dpsDelta >= 0 ? '+' : ''}${dpsDelta.toFixed(0)}`);
      }

      const origMacro = wz.payload.generated?.macro_text || currentMacro;
      wz.payload.iterated_macro = bestMacro;
      wz.payload.iterated_meta = {
        base_dps: baseResp.dps || 0, final_dps: bestDps,
        atoms_removed: rounds,
        orig_chars: origMacro.length, final_chars: bestMacro.length,
      };
      if (!Array.isArray(wz.payload.iter_history)) wz.payload.iter_history = [];
      wz.payload.iter_history.push({ ts: Date.now(), kind: 'cast-diff 反馈', macro: bestMacro, meta: { ...wz.payload.iterated_meta } });
      if (wz.payload.iter_history.length > 20) wz.payload.iter_history.shift();
      persist();
      renderIteratedResult();
      renderIterHistory();
      status.textContent = `完成：${rounds} 轮调整 · Σ|cast diff|=${bestDiff}`;
      appendLog(`<br><b>总结</b>：${rounds} 轮，最终 Σ|cast diff|=<b>${bestDiff}</b>，DPS=<b>${Math.round(bestDps).toLocaleString()}</b>`);
    } catch (e) {
      status.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }
  document.getElementById('wz_it_castdiff')?.addEventListener('click', castDiffFeedback);

  // ═══════════════ PR 11：相邻规则 swap 搜索 ═══════════════
  // 每轮：拉所有同页相邻对候选 → 并行 simulate → 选 DPS 最高且 > 当前的那个接受
  // 直到没有改进为止（或 MAX_ROUNDS）
  async function swapSearch() {
    const btn = document.getElementById('wz_it_swap');
    const status = document.getElementById('wz_it_status');
    const log = document.getElementById('wz_it_log');
    const wrap = document.getElementById('wz_it_result_wrap');

    const currentMacro = getCurrentBestMacro();
    if (!currentMacro) { alert('没有宏可调序。先在 Step 5 生成。'); return; }
    const ref = wz.payload.timeline_meta;
    const duration = ref?.fight_time || 120;
    const scConf = {
      delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      initialRage: adminInitialRage || 0,
      duration,
    };

    btn.disabled = true;
    wrap.style.display = 'block';
    log.innerHTML = '';
    status.textContent = '基线中…';

    const appendLog = (html) => {
      const div = document.createElement('div');
      div.className = 'wz-prune-log-line';
      div.innerHTML = html;
      log.appendChild(div);
    };

    try {
      const baseResp = await simulateOnce({ macroText: currentMacro, ...scConf });
      let bestMacro = currentMacro;
      let bestDps = baseResp.dps || 0;
      appendLog(`<b>基线</b> DPS=${Math.round(bestDps).toLocaleString()}`);

      const MAX_ROUNDS = 8;
      const MIN_GAIN_PCT = 0.002; // 至少 0.2% DPS 提升才接受
      let swaps = 0;
      for (let round = 1; round <= MAX_ROUNDS; round++) {
        status.textContent = `第 ${round} 轮…`;
        const r = await fetch('/api/macro/swap_candidates', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ macro_text: bestMacro }),
        });
        if (!r.ok) { appendLog('<span style="color:#f85149">候选失败</span>'); break; }
        const cands = (await r.json()).candidates || [];
        if (cands.length === 0) { appendLog(`第 ${round} 轮：无可交换对`); break; }

        status.textContent = `第 ${round} 轮：评估 ${cands.length} 个 swap…`;
        const evals = await Promise.all(cands.map(async c => {
          try {
            const rr = await simulateOnce({ macroText: c.after_macro, ...scConf });
            return { cand: c, dps: rr.dps || 0 };
          } catch { return null; }
        }));
        const ok = evals.filter(x => x);
        ok.sort((a, b) => b.dps - a.dps);
        const top = ok[0];
        if (!top || (top.dps - bestDps) / Math.max(bestDps, 1) < MIN_GAIN_PCT) {
          appendLog(`<span style="color:#8b949e">第 ${round} 轮：无提升 ≥ ${(MIN_GAIN_PCT * 100).toFixed(1)}% 的 swap</span>`);
          break;
        }
        const gain = top.dps - bestDps;
        bestDps = top.dps; bestMacro = top.cand.after_macro;
        swaps++;
        appendLog(`<span style="color:#3fb950">第 ${round} 轮</span> swap [${escapeHtml(top.cand.skill_a)}] ↔ [${escapeHtml(top.cand.skill_b)}]（页 ${top.cand.page_index}）· +${gain.toFixed(0)} DPS`);
      }

      if (swaps === 0) {
        status.textContent = '完成：无可接受的 swap';
        return;
      }
      const origMacro = wz.payload.generated?.macro_text || currentMacro;
      wz.payload.iterated_macro = bestMacro;
      wz.payload.iterated_meta = {
        base_dps: baseResp.dps || 0, final_dps: bestDps,
        atoms_removed: 0,
        orig_chars: origMacro.length, final_chars: bestMacro.length,
      };
      if (!Array.isArray(wz.payload.iter_history)) wz.payload.iter_history = [];
      wz.payload.iter_history.push({ ts: Date.now(), kind: `swap×${swaps}`, macro: bestMacro, meta: { ...wz.payload.iterated_meta } });
      if (wz.payload.iter_history.length > 20) wz.payload.iter_history.shift();
      persist();
      renderIteratedResult();
      renderIterHistory();
      status.textContent = `完成：${swaps} 次 swap · DPS=${Math.round(bestDps).toLocaleString()}`;
      appendLog(`<br><b>总结</b>：${swaps} 次 swap，DPS 由 ${Math.round(baseResp.dps || 0).toLocaleString()} → <b>${Math.round(bestDps).toLocaleString()}</b>`);
    } catch (e) {
      status.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }
  document.getElementById('wz_it_swap')?.addEventListener('click', swapSearch);

  // ═══════════════ v2-2.7：条件收紧迭代 ═══════════════
  async function tightenSearch() {
    const btn = document.getElementById('wz_it_tighten');
    const status = document.getElementById('wz_it_status');
    const log = document.getElementById('wz_it_log');
    const wrap = document.getElementById('wz_it_result_wrap');

    const currentMacro = getCurrentBestMacro();
    if (!currentMacro) { alert('没有宏可收紧。先在 Step 5 生成。'); return; }
    const ref = wz.payload.timeline_meta;
    const duration = ref?.fight_time || 120;
    const scConf = {
      delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      initialRage: adminInitialRage || 0,
      duration,
    };

    btn.disabled = true;
    wrap.style.display = 'block';
    log.innerHTML = '';
    status.textContent = '基线中…';

    const appendLog = (html) => {
      const div = document.createElement('div');
      div.className = 'wz-prune-log-line';
      div.innerHTML = html;
      log.appendChild(div);
    };

    try {
      const baseResp = await simulateOnce({ macroText: currentMacro, ...scConf });
      const baseCounts = collectCastCounts(baseResp.timeline);
      let bestMacro = currentMacro;
      let bestDps = baseResp.dps || 0;
      appendLog(`<b>基线</b> DPS=${Math.round(bestDps).toLocaleString()}`);

      const MAX_ROUNDS = 5;
      const ACCEPT_DPS_TOL = 0.002;
      let totalTightened = 0;

      for (let round = 1; round <= MAX_ROUNDS; round++) {
        status.textContent = `第 ${round} 轮…`;
        const candR = await fetch('/api/macro/tighten_candidates', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ macro_text: bestMacro }),
        });
        if (!candR.ok) { appendLog('<span style="color:#f85149">候选失败</span>'); break; }
        const cands = (await candR.json()).candidates || [];
        if (cands.length === 0) { appendLog(`第 ${round} 轮：无可收紧候选`); break; }

        status.textContent = `第 ${round} 轮：评估 ${cands.length} 个收紧候选…`;
        const evals = await Promise.all(cands.map(async c => {
          try {
            const r = await simulateOnce({ macroText: c.after_macro, ...scConf });
            return { cand: c, dps: r.dps || 0, counts: collectCastCounts(r.timeline) };
          } catch { return null; }
        }));
        const ok = evals.filter(x => x);
        // 接受：DPS 提升（或至少不跌超 0.2%），且 cast 偏差不恶化
        const acceptable = ok.filter(e => {
          if ((bestDps - e.dps) / Math.max(bestDps, 1) > ACCEPT_DPS_TOL) return false;
          return true;
        });
        if (acceptable.length === 0) {
          appendLog(`<span style="color:#c9a847">第 ${round} 轮：无可接受的收紧</span>`);
          break;
        }
        acceptable.sort((a, b) => b.dps - a.dps);
        const picked = acceptable[0];
        const delta = picked.dps - bestDps;
        bestDps = picked.dps;
        bestMacro = picked.cand.after_macro;
        totalTightened++;
        appendLog(`<span style="color:#3fb950">第 ${round} 轮</span> 收紧 <code>${escapeHtml(picked.cand.original)}</code> → <code>${escapeHtml(picked.cand.tightened)}</code>（${escapeHtml(picked.cand.skill)}），Δ DPS = <b style="color:${delta >= 0 ? '#3fb950' : '#c9a847'}">${delta >= 0 ? '+' : ''}${delta.toFixed(0)}</b>`);
      }

      if (totalTightened > 0) {
        const origMacro = wz.payload.generated?.macro_text || currentMacro;
        wz.payload.iterated_macro = bestMacro;
        wz.payload.iterated_meta = {
          base_dps: baseResp.dps || 0, final_dps: bestDps,
          atoms_removed: 0,
          orig_chars: origMacro.length, final_chars: bestMacro.length,
        };
        if (!Array.isArray(wz.payload.iter_history)) wz.payload.iter_history = [];
        wz.payload.iter_history.push({ ts: Date.now(), kind: `收紧×${totalTightened}`, macro: bestMacro, meta: { ...wz.payload.iterated_meta } });
        if (wz.payload.iter_history.length > 20) wz.payload.iter_history.shift();
        persist();
        renderIteratedResult();
        renderIterHistory();
      }
      status.textContent = `完成：${totalTightened} 次收紧 · DPS=${Math.round(bestDps).toLocaleString()}`;
    } catch (e) {
      status.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }
  document.getElementById('wz_it_tighten')?.addEventListener('click', tightenSearch);

  // ═══════════════ v2-2.10：自适应一键迭代 ═══════════════
  async function autoIterate() {
    const btn = document.getElementById('wz_it_auto');
    const status = document.getElementById('wz_it_status');
    const log = document.getElementById('wz_it_log');
    const wrap = document.getElementById('wz_it_result_wrap');

    if (!getCurrentBestMacro()) { alert('没有宏可迭代。先在 Step 5 生成。'); return; }
    btn.disabled = true;
    wrap.style.display = 'block';
    log.innerHTML = '';

    const appendLog = (html) => {
      const div = document.createElement('div');
      div.className = 'wz-prune-log-line';
      div.innerHTML = html;
      log.appendChild(div);
    };

    try {
      const ref = wz.payload.timeline_meta;
      const duration = ref?.fight_time || 120;
      const scConf = {
        delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
        initialRage: adminInitialRage || 0,
        duration,
      };

      // 诊断当前状态
      const macroText = getCurrentBestMacro();
      const baseResp = await simulateOnce({ macroText, ...scConf });
      const baseDps = baseResp.dps || 0;
      const baseCounts = collectCastCounts(baseResp.timeline);
      const hasTimeline = !!wz.payload.timeline;
      const refCounts = hasTimeline ? collectCastCounts(wz.payload.timeline) : null;
      const castDiff = refCounts ? Object.keys({...baseCounts, ...refCounts}).reduce((s, k) =>
        s + Math.abs((baseCounts[k] || 0) - (refCounts[k] || 0)), 0) : 0;
      const charCount = macroText.length;

      appendLog(`<b>自适应迭代</b> · 基线 DPS=${Math.round(baseDps).toLocaleString()} · cast-diff=${castDiff} · 字数=${charCount}`);

      // 策略：按诊断指标选择迭代子步骤顺序
      const steps = [];
      if (castDiff > 5 && hasTimeline) steps.push('cast-diff');
      steps.push('prune');
      steps.push('swap');
      steps.push('tighten');

      appendLog(`策略：${steps.join(' → ')}`);

      for (const step of steps) {
        status.textContent = `自适应：${step}…`;
        appendLog(`<hr style="border-color:#2a2f37;margin:4px 0"><b>${step}</b>`);
        if (step === 'prune') await pruneRedundant();
        else if (step === 'cast-diff') await castDiffFeedback();
        else if (step === 'swap') await swapSearch();
        else if (step === 'tighten') await tightenSearch();
      }

      status.textContent = '自适应迭代完成';
      appendLog(`<br><b>自适应迭代完成</b> · 最终宏: ${(getCurrentBestMacro() || '').length} 字`);
    } catch (e) {
      status.textContent = '失败: ' + e.message;
    } finally {
      btn.disabled = false;
    }
  }
  document.getElementById('wz_it_auto')?.addEventListener('click', autoIterate);

  // 标题问号提示：按文本前缀匹配挂载 tooltip（放一处便于维护）
  (function attachHelpIcons() {
    const map = [
      ['① 载入 timeline', '手动跑一遍序列或上传现有宏的 timeline JSON，作为生成宏的训练数据。'],
      ['② 生成 + 配置', 'F1 贪心 + OR 减法抽取条件，结合 Copeland 排序和一致性敏感清单产出宏文本。'],
      ['③ 迭代 + 验证', '对生成的宏做安全剪枝 / cast-diff 反馈 / 相邻 swap 优化，再跑多场景验证 DPS 与 cast 偏差。'],
      ['④ 输出', '把最终宏写入循环模拟、保存到 userdata，或送往工作流 B 继续精调。'],
      ['迭代', '三种优化：冗余剪枝（DPS 保持）、cast-diff 反馈（贴近原释放次数）、相邻 swap（搜索更优顺序）。'],
      ['验证', '快速验证跑当前延迟/怒气一次；完整验证笛卡尔积所有多场景配置。'],
      ['宏文本（可编辑）', '生成结果。可手动编辑重跑验证，或展开选项后点生成宏覆盖。'],
      ['统计', '本次生成的宏覆盖了多少条手动 cast、丢弃了多少规则等汇总信息。'],
      ['丢弃规则', '未找到 F1 达标条件、被降级为无条件兜底或字数超限剔除的规则列表。'],
      ['规则诊断', '每条规则的正/负样本数、最终 F1、候选原子 top 12，用来调参考参考。'],
      ['迭代历史', '每次优化产生一条快照，可一键回滚到任意历史版本。'],
      ['最终宏', '当前 Step 6 迭代后的最新版本；如未迭代则使用 Step 5 生成版。'],
      ['动作', '写回主循环模拟（跳转到独立页）/ 保存到 userdata/loops（先按新宏跑一次序列）/ 复制文本。'],
      ['继续优化', '把当前宏送到工作流 B 的多目标优化器（尚未上线）。'],
    ];
    const sel = '.wz-step-title, .wz-part-title, .wz-sec-title';
    document.querySelectorAll(sel).forEach(el => {
      if (el.querySelector('.wz-help')) return;
      const txt = (el.textContent || '').trim();
      const hit = map.find(([prefix]) => txt.startsWith(prefix));
      if (!hit) return;
      const help = document.createElement('span');
      help.className = 'wz-help';
      help.dataset.tip = hit[1];
      help.textContent = '?';
      help.addEventListener('mouseenter', () => showTooltip(help, escapeHtml(hit[1])));
      help.addEventListener('mouseleave', hideTooltip);
      // 若标题内部有 wz-title-row 子元素（已有 span 布局），插到第一个 span 之后
      const firstSpan = el.querySelector(':scope > span');
      if (firstSpan) firstSpan.appendChild(help);
      else el.appendChild(help);
    });
  })();

  // Step 1/3 未点击过的按钮：柔和高亮提示，点一次就取消
  (function setupFreshButtons() {
    const iterIds = ['wz_it_prune', 'wz_it_castdiff', 'wz_it_swap'];
    const verifyIds = ['wz_ver_quick', 'wz_ver_full'];
    const loadIds = ['wz_tl_use_sim', 'wz_tl_use_json'];
    iterIds.concat(verifyIds).concat(loadIds).forEach(id => {
      const b = document.getElementById(id);
      if (b) b.classList.add('wz-btn-fresh');
    });
    iterIds.forEach(id => {
      document.getElementById(id)?.addEventListener('click', function onClick() {
        this.classList.remove('wz-btn-fresh');
      });
    });
    // 验证二选一：任一按钮点过就都取消高亮
    verifyIds.forEach(id => {
      document.getElementById(id)?.addEventListener('click', () => {
        verifyIds.forEach(x => document.getElementById(x)?.classList.remove('wz-btn-fresh'));
      });
    });
    // 载入 timeline 二选一：同理
    loadIds.forEach(id => {
      document.getElementById(id)?.addEventListener('click', () => {
        loadIds.forEach(x => document.getElementById(x)?.classList.remove('wz-btn-fresh'));
      });
    });
  })();

  // ═══════════════ PR 12：Step 7 输出 ═══════════════
  function getFinalMacro() {
    return wz.payload.iterated_macro
      || wz.payload.generated?.macro_text
      || '';
  }

  function renderStep4() {
    const macro = getFinalMacro();
    const sumEl = document.getElementById('wz_out_summary');
    const ta = document.getElementById('wz_out_macro');
    const hl = document.getElementById('wz_out_macro_hl');
    const charsEl = document.getElementById('wz_out_chars_inline');
    const saveNewBtn = document.getElementById('wz_out_save_new');
    const updateOriginBtn = document.getElementById('wz_out_update_origin');
    if (!ta) return;
    if (!macro) {
      sumEl.innerHTML = '<div class="wz-hint">没有可输出的宏。请先完成 Step 5 / Step 6。</div>';
      ta.value = '';
      if (hl) hl.innerHTML = '';
      if (charsEl) charsEl.innerHTML = '';
      ['wz_out_to_loop', 'wz_out_save_userdata', 'wz_out_copy', 'wz_out_save_new', 'wz_out_update_origin'].forEach(id => {
        const b = document.getElementById(id); if (b) b.disabled = true;
      });
      return;
    }
    ['wz_out_to_loop', 'wz_out_save_userdata', 'wz_out_copy', 'wz_out_save_new'].forEach(id => {
      const b = document.getElementById(id); if (b) b.disabled = false;
    });
    // 更新原方案：只有 draft 带了 sourceBuildId 且方案仍存在时可用
    const srcId = wz.payload.sourceBuildId;
    const srcBuild = srcId && window.Jx3Plaza?.get ? window.Jx3Plaza.get(srcId) : null;
    if (updateOriginBtn) {
      updateOriginBtn.disabled = !srcBuild;
      updateOriginBtn.title = srcBuild
        ? `更新原方案「${srcBuild.name}」的宏文本（其它字段不动）`
        : '仅当从某个方案进入本次蒸馏时可用';
    }
    const src = wz.payload.iterated_macro ? 'Step 6 迭代后' : 'Step 5 生成';
    const meta = wz.payload.iterated_meta || {};
    const dps = meta.final_dps || wz.payload.generated?.base_dps || 0;
    sumEl.innerHTML = `
      <div>来源：<b>${src}</b> · 字数 <b>${macro.length}</b>${dps ? ' · DPS <b>' + Math.round(dps).toLocaleString() + '</b>' : ''}</div>
    `;
    ta.value = macro;
    if (hl && typeof highlightMacroText === 'function') hl.innerHTML = highlightMacroText(macro) + '\n';
    if (charsEl) {
      const limit = wz.payload.gen_options?.max_chars_per_page || 128;
      charsEl.innerHTML = formatPagesInline(calcPagesFromText(macro, limit));
    }
  }

  // 把宏文本按 #page 分段写回 macroPages / macroMode（全局状态）
  function setGlobalMacroFromText(text) {
    if (typeof macroPages === 'undefined') return false;
    macroPages.general = '';
    macroPages.shield = '';
    macroPages.blade = '';
    const lines = (text || '').split('\n');
    let cur = null;
    let general = '';
    for (const l of lines) {
      const m = l.match(/^#page\s+(\w+)/);
      if (m) { cur = m[1]; continue; }
      if (cur === 'shield') macroPages.shield += l + '\n';
      else if (cur === 'blade') macroPages.blade += l + '\n';
      else general += l + '\n';
    }
    macroPages.general = general.trim();
    macroPages.shield = macroPages.shield.trim();
    macroPages.blade = macroPages.blade.trim();
    if (typeof macroMode !== 'undefined') {
      window.macroMode = (macroPages.shield || macroPages.blade) ? 'stance' : 'general';
    }
    return true;
  }

  document.getElementById('wz_out_copy')?.addEventListener('click', async () => {
    const macro = getFinalMacro();
    const status = document.getElementById('wz_out_status');
    try {
      await navigator.clipboard.writeText(macro);
      if (status) { status.textContent = '已复制 ✓'; setTimeout(() => status.textContent = '', 1200); }
    } catch (e) {
      if (status) status.textContent = '复制失败：' + e.message;
    }
  });

  document.getElementById('wz_out_to_loop')?.addEventListener('click', async () => {
    const macro = getFinalMacro();
    const status = document.getElementById('wz_out_status');
    if (!macro) return;
    setGlobalMacroFromText(macro);
    // 持久化到 userdata/macros.json
    fetch('/api/macro/save', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
        general: macroPages.general, shield: macroPages.shield, blade: macroPages.blade,
      }),
    }).catch(() => {});
    // 切到独立循环模拟页
    window.Jx3Nav?.switchPage('page-sim');
    if (status) status.textContent = '已切换到循环模拟，按默认时长跑宏中…';
    // 清空现有序列，按默认时长自动跑宏一次
    const container = document.getElementById('sim_sequence');
    if (container) container.innerHTML = '';
    const dur = wz.payload.timeline_meta?.fight_time || 120;
    try {
      if (typeof runMacroSimulate === 'function') await runMacroSimulate(dur);
      if (status) status.textContent = `已写入并跑宏（${dur}s）`;
    } catch (e) {
      if (status) status.textContent = '跑宏失败：' + e.message;
    }
  });

  document.getElementById('wz_out_save_userdata')?.addEventListener('click', async () => {
    const macro = getFinalMacro();
    const status = document.getElementById('wz_out_status');
    if (!macro) return;
    const name = prompt('循环名（自动追加时间戳）：', 'wizard-A');
    if (name === null) return;
    // 先按新宏跑一次宏模拟，让 sim_sequence 里的序列与最终宏一致
    setGlobalMacroFromText(macro);
    if (status) status.textContent = '按新宏跑序列中…';
    const container = document.getElementById('sim_sequence');
    if (container) container.innerHTML = '';
    const dur = wz.payload.timeline_meta?.fight_time || 120;
    try {
      if (typeof runMacroSimulate === 'function') await runMacroSimulate(dur);
    } catch (e) {
      if (status) status.textContent = '跑宏失败：' + e.message;
      return;
    }
    const cfg = (typeof buildLoopConfig === 'function') ? buildLoopConfig() : {};
    cfg.macro = {
      mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
      general: macroPages.general, shield: macroPages.shield, blade: macroPages.blade,
    };
    try {
      const r = await fetch('/api/loop/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, config: cfg }),
      });
      const data = await r.json();
      if (status) status.textContent = data.ok ? `已保存 ✓ ${data.file}` : ('保存失败：' + (data.error || ''));
    } catch (e) {
      if (status) status.textContent = '请求失败：' + e.message;
    }
  });

  // A-7：把当前环境 + 新宏打包成 plaza draft
  function buildPlazaDraftFromCurrent(macroText, name) {
    const cfg = (typeof buildLoopConfig === 'function') ? buildLoopConfig() : {};
    // 宏文本按姿态写回 macroPages 再读，保证三页字段完整
    try { setGlobalMacroFromText(macroText); } catch {}
    const macro = {
      mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
      general: macroPages.general || '',
      shield: macroPages.shield || '',
      blade: macroPages.blade || '',
    };
    return {
      id: null,
      name: name || (window.Jx3Plaza?.nextDefaultName?.() || '方案'),
      mount: (typeof currentMountKey === 'function') ? currentMountKey() : null,
      mount_label: (typeof currentMountLabel === 'function') ? currentMountLabel() : '',
      equipment: window.Jx3Equip?.getCurrentConfig?.() || null,
      talents: (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [],
      recipes: (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [],
      rotation: {
        sequence: cfg.sequence || [],
        macro,
        delay: cfg.network_delay || 0,
        initial_rage: cfg.initial_rage,
        macro_duration: cfg.macro_duration,
        boss_attack_interval: cfg.boss_attack_interval,
      },
      attributes: (typeof getAttrs === 'function') ? getAttrs() : null,
      target: cfg.target || ((typeof getTarget === 'function') ? getTarget() : null),
      snapshot: null,
      confirmedSave: false,
    };
  }

  // A-7：另存为新方案
  document.getElementById('wz_out_save_new')?.addEventListener('click', () => {
    const macro = getFinalMacro();
    const status = document.getElementById('wz_out_plaza_status');
    if (!macro) return;
    if (!window.Jx3Plaza?.add) { if (status) status.textContent = '广场未加载'; return; }
    const defaultName = window.Jx3Plaza.nextDefaultName?.() || '方案';
    const name = prompt('新方案名称：', defaultName);
    if (name === null) return;
    const trimmed = (name || '').trim();
    if (!trimmed) { if (status) status.textContent = '名称不能为空'; return; }
    const draft = buildPlazaDraftFromCurrent(macro, trimmed);
    try {
      const created = window.Jx3Plaza.add(draft);
      wz.payload.sourceBuildId = created.id;
      wz.payload.sourceBuildName = created.name;
      if (status) {
        status.textContent = `已保存到广场 ✓ 「${created.name}」`;
        status.style.color = 'var(--gold)';
        setTimeout(() => { if (status) status.style.color = ''; }, 3000);
      }
      render();
      persist();
    } catch (e) {
      if (status) status.textContent = '保存失败：' + e.message;
    }
  });

  // A-7：更新原方案的宏文本（保留其它字段）
  document.getElementById('wz_out_update_origin')?.addEventListener('click', () => {
    const macro = getFinalMacro();
    const status = document.getElementById('wz_out_plaza_status');
    if (!macro) return;
    const srcId = wz.payload.sourceBuildId;
    if (!srcId || !window.Jx3Plaza?.update) { if (status) status.textContent = '没有原方案记录'; return; }
    const prev = window.Jx3Plaza.get?.(srcId);
    if (!prev) { if (status) status.textContent = '原方案已丢失'; return; }
    if (!confirm(`更新方案「${prev.name}」的宏文本？（其它字段不动，会使 snapshot 失效）`)) return;
    // 把宏文本写回 macroPages，再用三页字段组 patch
    try { setGlobalMacroFromText(macro); } catch {}
    const macroObj = {
      mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
      general: macroPages.general || '',
      shield: macroPages.shield || '',
      blade: macroPages.blade || '',
    };
    try {
      window.Jx3Plaza.update(srcId, {
        rotation: { ...(prev.rotation || {}), macro: macroObj },
        snapshot: null,  // 宏变了，原 snapshot 失效
      });
      if (status) {
        status.textContent = `已更新「${prev.name}」✓（snapshot 已清，广场卡可点重算刷新）`;
        status.style.color = 'var(--gold)';
        setTimeout(() => { if (status) status.style.color = ''; }, 3500);
      }
    } catch (e) {
      if (status) status.textContent = '更新失败：' + e.message;
    }
  });

  // 前往工作流 B：把 A 的最终宏塞进 B payload 的 macro 字段 → 进 Workflow B Step 1
  document.getElementById('wz_out_to_b')?.addEventListener('click', () => {
    const macro = getFinalMacro();
    if (!macro) { alert('先在 Step 5 / 6 产出宏'); return; }
    // 读已有 B payload（保留 baseline / search_history 等），只覆盖 macro + 清掉旧搜索结果
    const last = window.Jx3State?.loadLastStep?.();
    const prevB = (last?.workflow === 'B') ? (last.payload || {}) : {};
    const newPayload = { ...prevB, macro };
    delete newPayload.baseline;
    delete newPayload.search_best;
    delete newPayload.search_history;
    delete newPayload.pareto_archive;
    window.Jx3State?.saveLastStep?.({
      workflow: 'B', step: 1, completed: [],
      attrsHash: last?.attrs_hash || '', payload: newPayload,
    });
    window.Jx3WizardB?.enter?.(true);
  });

  // 把一组 page 字数摘要渲染成 "盾(N/M) 刀(N/M)" 的内联字符串
  function formatPagesInline(pages) {
    if (!pages || pages.length === 0) return '';
    const label = (s) => ({ shield: '盾', blade: '刀', wall: '墙', any: '通用' })[s] || s;
    return pages.map(p => {
      const cls = p.chars > p.limit ? 'wz-chars-bad'
                : (p.chars > p.limit * 0.85 ? 'wz-chars-warn' : 'wz-chars-ok');
      return `<span class="${cls}">${label(p.stance)}(${p.chars}/${p.limit})</span>`;
    }).join(' ');
  }

  // 按 #page 分段计算字数（给 iterated macro 用）
  function calcPagesFromText(text, limit) {
    const lim = limit || 128;
    const lines = (text || '').split('\n');
    const pages = [];
    let stance = 'any';
    let body = '';
    function flush() {
      const trimmed = body.trimEnd();
      if (trimmed.length > 0) {
        pages.push({ stance, chars: trimmed.length, limit: lim, rule_count: trimmed.split('\n').filter(l => l.trim()).length });
      }
      body = '';
    }
    for (const line of lines) {
      const m = line.match(/^\s*#page(?:\s+(\w+))?\s*$/);
      if (m) {
        flush();
        stance = m[1] || 'any';
      } else {
        body += line + '\n';
      }
    }
    flush();
    return pages;
  }
  window.Jx3CalcPages = calcPagesFromText;

  function renderIteratedResult() {
    const wrap = document.getElementById('wz_it_result_wrap');
    const stats = document.getElementById('wz_it_stats');
    const ta = document.getElementById('wz_it_macro');
    const hl = document.getElementById('wz_it_macro_hl');
    const resetBtn = document.getElementById('wz_it_reset');
    const macro = wz.payload.iterated_macro;
    if (!macro) {
      wrap.style.display = 'none';
      if (resetBtn) resetBtn.disabled = true;
      return;
    }
    wrap.style.display = 'block';
    if (resetBtn) resetBtn.disabled = false;
    const meta = wz.payload.iterated_meta || {};
    const dpsDelta = (meta.final_dps || 0) - (meta.base_dps || 0);
    const dpsPct = meta.base_dps ? (dpsDelta / meta.base_dps * 100) : 0;
    const dpsColor = dpsDelta >= 0 ? '#3fb950' : (Math.abs(dpsPct) < 0.5 ? '#c9a847' : '#f85149');
    const charDelta = (meta.final_chars || 0) - (meta.orig_chars || 0);
    const charColor = charDelta <= 0 ? '#3fb950' : '#f85149';
    stats.innerHTML = `
      <div>原宏: <b>${meta.orig_chars || 0}</b> 字 · DPS <b>${Math.round(meta.base_dps || 0).toLocaleString()}</b></div>
      <div>优化后: <b>${meta.final_chars || 0}</b> 字
        <span style="color:${charColor}">(${charDelta >= 0 ? '+' : ''}${charDelta})</span>
        · DPS <b>${Math.round(meta.final_dps || 0).toLocaleString()}</b>
        <span style="color:${dpsColor}">(${dpsDelta >= 0 ? '+' : ''}${Math.round(dpsDelta)} / ${dpsPct >= 0 ? '+' : ''}${dpsPct.toFixed(2)}%)</span>
      </div>
      <div>删除原子: <b>${meta.atoms_removed || 0}</b></div>
    `;
    ta.value = macro;
    if (hl && typeof highlightMacroText === 'function') {
      hl.innerHTML = highlightMacroText(macro) + '\n';
    }
    // 迭代结果的每页字数显示在 title 右侧
    const charsEl = document.getElementById('wz_it_chars_inline');
    if (charsEl) {
      const limit = wz.payload.gen_options?.max_chars_per_page || 128;
      const pages = calcPagesFromText(macro, limit);
      charsEl.innerHTML = formatPagesInline(pages);
    }
  }
  function renderIterHistory() {
    const wrap = document.getElementById('wz_it_history_wrap');
    const box = document.getElementById('wz_it_history');
    if (!wrap || !box) return;
    const hist = wz.payload.iter_history || [];
    if (hist.length === 0) { wrap.style.display = 'none'; box.innerHTML = ''; return; }
    wrap.style.display = 'block';
    const cur = wz.payload.iterated_macro;
    box.innerHTML = hist.slice().reverse().map((h, revIdx) => {
      const idx = hist.length - 1 - revIdx;
      const d = new Date(h.ts);
      const time = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}:${String(d.getSeconds()).padStart(2,'0')}`;
      const m = h.meta || {};
      const dpsDelta = (m.final_dps || 0) - (m.base_dps || 0);
      const dpsColor = dpsDelta >= 0 ? '#3fb950' : '#f85149';
      const charDelta = (m.final_chars || 0) - (m.orig_chars || 0);
      const isCur = h.macro === cur;
      return `<div class="wz-iter-hist-row${isCur ? ' current' : ''}">
        <span class="wz-iter-hist-time">${time}</span>
        <span class="wz-iter-hist-kind">${escapeHtml(h.kind || '迭代')}</span>
        <span class="wz-iter-hist-stat">-${m.atoms_removed || 0}原子 · ${charDelta >= 0 ? '+' : ''}${charDelta}字 · <span style="color:${dpsColor}">${dpsDelta >= 0 ? '+' : ''}${Math.round(dpsDelta)}DPS</span></span>
        <button class="sim-btn wz-iter-hist-rb" data-idx="${idx}" ${isCur ? 'disabled' : ''}>${isCur ? '当前' : '回滚'}</button>
      </div>`;
    }).join('');
    box.querySelectorAll('.wz-iter-hist-rb').forEach(btn => {
      btn.addEventListener('click', () => {
        const i = parseInt(btn.dataset.idx);
        const h = (wz.payload.iter_history || [])[i];
        if (!h) return;
        wz.payload.iterated_macro = h.macro;
        wz.payload.iterated_meta = { ...(h.meta || {}) };
        persist();
        renderIteratedResult();
        renderIterHistory();
      });
    });
  }

  // 页面载入时如果已有迭代结果就恢复
  setTimeout(() => { renderIteratedResult(); renderIterHistory(); }, 120);

  document.getElementById('wz_it_reset')?.addEventListener('click', () => {
    if (!confirm('清除迭代结果？Step 7 会改用 Step 5 生成的原始宏。')) return;
    delete wz.payload.iterated_macro;
    delete wz.payload.iterated_meta;
    wz.payload.iter_history = [];
    const log = document.getElementById('wz_it_log');
    if (log) log.innerHTML = '';
    const status = document.getElementById('wz_it_status');
    if (status) status.textContent = '';
    persist();
    renderIteratedResult();
    renderIterHistory();
  });

  // 运算符归一化：把 >= / <= 转成 >/<，省字符
  function normalizeOperators(text) {
    // rage 是整数：rage>=N → rage>(N-1)；rage<=N → rage<(N+1)。无损
    text = text.replace(/rage>=(\d+)/g, (_, n) => `rage>${Math.max(0, parseInt(n, 10) - 1)}`);
    text = text.replace(/rage<=(\d+)/g, (_, n) => `rage<${parseInt(n, 10) + 1}`);
    // bufftime / tbufftime 是浮点：直接去 "=" 丢掉 remaining==N 的精确相等边界（极罕见）
    text = text.replace(/bufftime:([^<>=~&|\s]+)>=(\d+(?:\.\d+)?)/g, 'bufftime:$1>$2');
    text = text.replace(/bufftime:([^<>=~&|\s]+)<=(\d+(?:\.\d+)?)/g, 'bufftime:$1<$2');
    text = text.replace(/tbufftime:([^<>=~&|\s]+)>=(\d+(?:\.\d+)?)/g, 'tbufftime:$1>$2');
    text = text.replace(/tbufftime:([^<>=~&|\s]+)<=(\d+(?:\.\d+)?)/g, 'tbufftime:$1<$2');
    return text;
  }

  // 进入 Step 5（生成+配置）且未生成过 → 自动生成
  const origSyncSimEmbed = syncSimEmbed;
  syncSimEmbed = function() {
    origSyncSimEmbed();
    if (pageWz.classList.contains('active') && wz.current === STEP_GENERATE && !wz.payload.generated) {
      if (wz.payload.timeline) runGeneration();
    }
    // 若已缓存了结果，切回 Step 5 时重新渲染
    if (pageWz.classList.contains('active') && wz.current === STEP_GENERATE && wz.payload.generated && !genMacroEl.value) {
      renderGenResult(wz.payload.generated);
    }
  };

  // ── Phase 6 · 从 D/C 接入 draft 进 A 工作流 ──
  // 把 draft 的奇穴/秘籍/目标/延迟/配装/循环应用到全局状态，切到 A Step 1（载入 timeline）
  async function applyDraftToGlobal(draft) {
    if (!draft) return;
    // 奇穴/秘籍 tier 查表需要 talentList/recipeList；未加载时先拉取，否则下面的 for 循环
    // 会清空 talentSelection 却因 find 返回 undefined 而塞不回任何 id（用户看到的是被清空）
    try {
      if (window.Jx3Plaza?.ensureTalentRecipeLists) await window.Jx3Plaza.ensureTalentRecipeLists();
    } catch {}
    // 奇穴
    if (Array.isArray(draft.talents) && typeof talentSelection !== 'undefined'
        && Array.isArray(talentList) && talentList.length > 0) {
      for (let t = 1; t <= 10; t++) talentSelection[t] = null;
      talentSelection.mixed.length = 0;
      for (const id of draft.talents) {
        const info = talentList.find(x => x.id === id);
        if (!info) continue;
        if (info.tier === 'mixed' || info.tier === 8 || info.tier === 9 || info.tier === 10) {
          talentSelection.mixed.push(id);
        } else if (typeof info.tier === 'number' && info.tier >= 1 && info.tier <= 7) {
          talentSelection[info.tier] = id;
        }
      }
      try { typeof refreshTalentUI === 'function' && refreshTalentUI(); } catch {}
      try { typeof enforceTalentGating === 'function' && enforceTalentGating(); } catch {}
    }
    // 秘籍
    if (Array.isArray(draft.recipes) && typeof selectedRecipes !== 'undefined'
        && Array.isArray(recipeList) && recipeList.length > 0) {
      for (const k of Object.keys(selectedRecipes)) selectedRecipes[k].clear();
      for (const id of draft.recipes) {
        const info = recipeList.find(x => x.id === id);
        if (!info) continue;
        if (selectedRecipes[info.skill]) selectedRecipes[info.skill].add(id);
      }
      try { typeof refreshRecipeUI === 'function' && refreshRecipeUI(); } catch {}
    }
    // 目标
    if (draft.target) {
      const lvl = document.getElementById('target_level');
      if (lvl && draft.target.level != null) {
        lvl.value = draft.target.level;
        lvl.dispatchEvent(new Event('change', { bubbles: true }));
      }
      const def = document.getElementById('target_defense_bonus');
      if (def && draft.target.defense_bonus != null) def.value = draft.target.defense_bonus;
    }
    // 延迟
    if (draft.rotation?.delay != null) {
      const v = String(draft.rotation.delay);
      const el = document.getElementById('sim_delay');
      if (el) el.value = v;
      const item = document.querySelector(`#page-sim .sim-dropdown-item[data-value="${v}"]`);
      const lab = document.getElementById('sim_delay_label');
      if (lab && item) lab.textContent = item.textContent;
    }
    // 配装（异步；A Step 3 运行模拟时会用它）
    if (draft.equipment && window.Jx3Equip?.applyConfig) {
      try { window.Jx3Equip.applyConfig(draft.equipment); } catch {}
    }
    // 循环序列 / 宏 / 延迟 / 起手怒气 / macro_duration
    if (draft.rotation && typeof applyLoopConfig === 'function') {
      const cfg = {
        version: (typeof LOOP_CONFIG_VERSION !== 'undefined') ? LOOP_CONFIG_VERSION : 1,
        sequence: draft.rotation.sequence || [],
        macro: draft.rotation.macro || {},
        network_delay: draft.rotation.delay,
        initial_rage: draft.rotation.initial_rage,
        macro_duration: draft.rotation.macro_duration,
        boss_attack_interval: draft.rotation.boss_attack_interval,
        target: draft.target || undefined,
      };
      try { applyLoopConfig(cfg); } catch {}
    }
  }

  async function enterWithDraft(draft) {
    await applyDraftToGlobal(draft);
    // 清缓存的 timeline / 生成结果：换了状态需要重新跑
    wz.payload = {};
    wz.completed = new Set();
    // 若 draft 来自广场方案（有 id），记下以便 A-7 的 [更新原方案] 用
    if (draft?.id) {
      wz.payload.sourceBuildId = draft.id;
      wz.payload.sourceBuildName = draft.name || '';
    }
    // 前 3 步（奇穴/秘籍、配装、循环）已从 draft 预填，直接落 A-4 载入
    wz.current = STEP_LOAD;
    wz.completed.add(1);
    wz.completed.add(2);
    wz.completed.add(3);
    window.Jx3Nav?.switchPage('page-wizard-a');
    render();
    persist();
    // 状态栏提示
    const hint = document.getElementById('wz_tl_status');
    if (hint) {
      hint.textContent = '环境已预填（Step 1~3）。点 "✓ 使用上次模拟结果" 载入 timeline 进入蒸馏';
      hint.style.color = 'var(--gold)';
      setTimeout(() => { if (hint) hint.style.color = ''; }, 5000);
    }
  }

  window.Jx3WorkflowA = window.Jx3WorkflowA || {};
  window.Jx3WorkflowA.enterWithDraft = enterWithDraft;
})();

// Hub A 卡片现在接入 Wizard
(function wireHubAToWizard() {
  const card = document.querySelector('.hub-card[data-hub-action="workflow-a"]');
  if (!card) return;
  const btn = card.querySelector('.hub-card-btn');
  if (!btn) return;
  // 覆盖 PR 1 里的 alert 行为
  const newBtn = btn.cloneNode(true);
  btn.parentNode.replaceChild(newBtn, btn);
  newBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const last = window.Jx3State?.loadLastStep?.();
    const resume = last && last.workflow === 'A' && last.step > 1;
    window.Jx3WizardA?.enter(resume);
  });
})();

// 顶栏 "上次" 徽章接入 Wizard
(function wireResumeBadgeToWizard() {
  const tbResume = document.getElementById('tb_resume');
  if (!tbResume) return;
  // 清掉 PR 1 里的 alert 监听器（克隆替换即可）
  const newBtn = tbResume.cloneNode(true);
  tbResume.parentNode.replaceChild(newBtn, tbResume);
  newBtn.addEventListener('click', () => {
    const last = window.Jx3State?.loadLastStep?.();
    if (last?.workflow === 'A') {
      window.Jx3WizardA?.enter(true);
    } else if (last?.workflow === 'B') {
      window.Jx3WizardB?.enter(true);
    }
  });
})();

// ─────────────────────────────────────────────────────────────────────────────
// 自动保存：循环模拟页（序列 / 奇穴 / 秘籍 / 宏 / 延迟 / 起始怒气）→ localStorage
// 页面刷新或重开自动恢复；用户想完全重置可点顶栏「清空自动保存」或 Hub 上的按钮。
// ─────────────────────────────────────────────────────────────────────────────
(function initLoopAutosave() {
  const KEY = 'jx3_autosave_loop_v1';
  const STATUS_ID = 'loop_autosave_status';
  let saveTimer = null;
  let restoring = false;

  function setStatus(text, color) {
    const el = document.getElementById(STATUS_ID);
    if (!el) return;
    el.textContent = text;
    el.style.color = color || '#8b949e';
  }

  function save() {
    if (restoring) return;
    try {
      if (typeof buildLoopConfig !== 'function') return;
      const cfg = buildLoopConfig();
      // 序列为空 + 没有宏 + 没有起始怒气时不写（避免覆盖有意义的旧存档）
      const empty = (!cfg.sequence || cfg.sequence.length === 0)
        && !(cfg.macro && (cfg.macro.general || cfg.macro.shield || cfg.macro.blade))
        && cfg.initial_rage == null;
      if (empty) { console.log('[autosave] 跳过空快照'); return; }
      // 盖上当前心法/版本标记，防止切心法后 restore 覆盖新心法的 defaults
      try {
        if (typeof currentMount === 'object' && currentMount) {
          cfg._mount = currentMount.mount;
          cfg._version = currentMount.version;
        }
      } catch {}
      localStorage.setItem(KEY, JSON.stringify(cfg));
      console.log('[autosave] 已保存', cfg.sequence?.length || 0, '项序列');
      setStatus('自动保存 ✓ ' + new Date().toLocaleTimeString(), '#3fb950');
    } catch (e) {
      setStatus('自动保存失败', '#f85149');
    }
  }
  function scheduleSave() {
    if (saveTimer) clearTimeout(saveTimer);
    saveTimer = setTimeout(save, 500);
  }

  async function restore() {
    try {
      const raw = localStorage.getItem(KEY);
      if (!raw) { console.log('[autosave] 无自动保存'); return false; }
      const cfg = JSON.parse(raw);
      // 若存档带 _mount，必须等 fetchCurrentMount 真正完成再判断；
      // currentMount 有个默认初值（FenShanJin），不能用它 truthy 就当就绪
      if (cfg._mount) {
        try {
          await Promise.race([
            (typeof currentMountReady !== 'undefined') ? currentMountReady : Promise.resolve(),
            new Promise(r => setTimeout(r, 2000)),  // 最多等 2s 兜底
          ]);
        } catch {}
        if (!currentMount?.mount) {
          console.log('[autosave] currentMount 未就绪，跳过恢复');
          return false;
        }
        if (cfg._mount !== currentMount.mount
            || (cfg._version && cfg._version !== currentMount.version)) {
          console.log('[autosave] 心法不匹配，跳过恢复', cfg._mount, '→', currentMount.mount);
          setStatus('已切心法，自动保存暂不恢复', '#c9a847');
          return false;
        }
      }
      if (typeof applyLoopConfig !== 'function') { console.warn('[autosave] applyLoopConfig 未就绪'); return false; }
      restoring = true;
      applyLoopConfig(cfg);
      setStatus('已恢复上次自动保存', '#79c0ff');
      console.log('[autosave] 已恢复', cfg.sequence?.length || 0, '项序列');
      // 触发一次模拟，让时间轴/结果面板也刷新出来
      if (typeof runSimulate === 'function') {
        setTimeout(() => { try { runSimulate(); } catch {} }, 50);
      }
      return true;
    } catch (e) {
      console.warn('[autosave] 恢复失败:', e);
      return false;
    } finally {
      setTimeout(() => { restoring = false; }, 300);
    }
  }

  // MutationObserver：序列 DOM 变化 → 触发保存
  const container = document.getElementById('sim_sequence');
  if (container) {
    const mo = new MutationObserver(scheduleSave);
    mo.observe(container, { childList: true, subtree: true, attributes: true, attributeFilter: ['data-skill', 'data-timing-offset', 'data-qijin-buff', 'data-pre-time', 'data-pre-release'] });
  }
  // 延迟 / 起手怒气怒气 / 宏 / 秘籍 / 奇穴相关事件全走同一事件总线（input/change + 自定义）
  ['change', 'input'].forEach(ev => {
    document.addEventListener(ev, (e) => {
      const t = e.target;
      if (!t || !t.id) return;
      if (['sim_delay', 'target_level', 'target_defense_bonus'].includes(t.id)) scheduleSave();
    }, true);
  });
  // 外部操作（秘籍弹窗确认 / 奇穴切换 / 宏保存）调用 save() 需手动触发 —— 简单办法：page visibility 变化也存一次
  document.addEventListener('visibilitychange', () => { if (document.hidden) save(); });
  window.addEventListener('beforeunload', save);

  // 暴露给 Hub 清空按钮调用
  window.Jx3LoopAutosave = {
    clear() { localStorage.removeItem(KEY); setStatus('已清空自动保存', '#c9a847'); },
    save, restore,
  };

  // 初始恢复（等所有 init 跑完）
  setTimeout(restore, 200);
})();

// ═══════════════════════════════════════════════════════════════════════════
// PR 13：工作流 B Wizard（宏多目标精调）— 骨架 + Step 1 载入宏
// ═══════════════════════════════════════════════════════════════════════════
(function initWizardB() {
  const WORKFLOW = 'B';
  const TOTAL_STEPS = 5;
  const pageWz = document.getElementById('page-wizard-b');
  if (!pageWz) return;
  const simulateOnce = (...a) => window.Jx3SimulateOnce(...a);
  const collectCastCounts = (...a) => window.Jx3CollectCastCounts(...a);
  const wz = { current: 1, completed: new Set(), payload: {} };
  const progSteps = pageWz.querySelectorAll('.wz-prog-step');
  const stepPanels = pageWz.querySelectorAll('.wz-step-panel');
  const btnPrev = pageWz.querySelector('#wzb_prev');
  const btnNext = pageWz.querySelector('#wzb_next');
  const status = pageWz.querySelector('#wzb_status');

  function persist() {
    window.Jx3State?.saveLastStep?.({
      workflow: WORKFLOW,
      step: wz.current,
      completed: Array.from(wz.completed),
      attrsHash: '',
      payload: wz.payload,
    });
    window.Jx3RefreshResume?.();
  }
  function restore() {
    const last = window.Jx3State?.loadLastStep?.();
    if (!last || last.workflow !== WORKFLOW) return false;
    wz.current = Math.min(last.step || 1, TOTAL_STEPS);
    wz.completed = new Set((last.completed || []).filter(s => s <= TOTAL_STEPS));
    wz.payload = last.payload || {};
    return true;
  }

  function render() {
    const hasMacro = !!(wz.payload.macro && wz.payload.macro.trim());
    const hasBaseline = !!wz.payload.baseline;
    const hasSearched = !!wz.payload.search_best
      || (wz.payload.search_history?.length > 0)
      || (wz.payload.pareto_archive?.length > 0);
    // 完成条件自动勾选
    if (hasMacro) wz.completed.add(1);
    if (hasBaseline) wz.completed.add(2);
    if (hasSearched) wz.completed.add(3);
    // Step 4（参数精调）没有强制完成标记，到 Step 5 算完成
    progSteps.forEach(el => {
      const s = parseInt(el.dataset.step);
      el.classList.toggle('active', s === wz.current);
      el.classList.toggle('done', wz.completed.has(s) && s !== wz.current);
    });
    stepPanels.forEach(p => {
      p.classList.toggle('active', parseInt(p.dataset.step) === wz.current);
    });
    btnPrev.disabled = wz.current <= 1;
    // Step 4 不走下一步按钮：要么跳过（按侧栏 Step 5），要么点 Top 10/里程碑 的 → Step 5 按钮
    if (wz.current === 4) {
      btnNext.textContent = '↓ 从下方选一条宏 → Step 5';
      btnNext.disabled = true;
      btnNext.classList.add('wz-next-placeholder');
      btnNext.classList.remove('wz-next-ready');
    } else {
      btnNext.disabled = false;
      btnNext.classList.remove('wz-next-placeholder');
      btnNext.textContent = wz.current >= TOTAL_STEPS ? '完成' : '下一步 →';
      const curDone = (wz.current === 1 && hasMacro)
                   || (wz.current === 2 && hasBaseline)
                   || (wz.current === 3 && hasSearched);
      btnNext.classList.toggle('wz-next-ready', !!curDone && wz.current < TOTAL_STEPS);
    }
    status.textContent = `第 ${wz.current} 步 / 共 ${TOTAL_STEPS} 步` +
      (wz.completed.size ? ` · 已完成 ${wz.completed.size}` : '');
  }

  function goto(step) {
    if (step < 1 || step > TOTAL_STEPS) return;
    wz.current = step;
    render(); persist();
  }
  btnPrev.addEventListener('click', () => goto(wz.current - 1));
  btnNext.addEventListener('click', () => {
    wz.completed.add(wz.current);
    if (wz.current >= TOTAL_STEPS) { render(); persist(); return; }
    goto(wz.current + 1);
  });
  progSteps.forEach(el => el.addEventListener('click', () => goto(parseInt(el.dataset.step))));
  pageWz.querySelector('#wzb_exit_hub')?.addEventListener('click', () => {
    persist();
    window.Jx3Nav?.switchPage('page-hub');
  });

  // ── Step 1：载入宏 ──
  const macroTa = pageWz.querySelector('#wzb_macro');
  const macroHl = pageWz.querySelector('#wzb_macro_hl');
  const charsEl = pageWz.querySelector('#wzb_macro_chars');
  const loopSel = pageWz.querySelector('#wzb_src_loop_sel');
  const loadStatus = pageWz.querySelector('#wzb_load_status');

  function updateMacroView() {
    const text = macroTa.value;
    wz.payload.macro = text;
    if (macroHl && typeof highlightMacroText === 'function') {
      macroHl.innerHTML = highlightMacroText(text) + '\n';
    }
    if (charsEl) {
      const limit = 128;
      const pages = (window.Jx3CalcPages)
        ? window.Jx3CalcPages(text, limit)
        : [{ stance: 'any', chars: text.length, limit }];
      const label = (s) => ({ shield: '盾', blade: '刀', wall: '墙', any: '通用' })[s] || s;
      charsEl.innerHTML = pages.map(p => {
        const cls = p.chars > p.limit ? 'wz-chars-bad'
                  : (p.chars > p.limit * 0.85 ? 'wz-chars-warn' : 'wz-chars-ok');
        return `<span class="${cls}">${label(p.stance)}(${p.chars}/${p.limit})</span>`;
      }).join(' ');
    }
    persist();
    render();
  }
  macroTa?.addEventListener('input', updateMacroView);

  // 把 {mode, general, shield, blade} 还原成带 #page 分段的宏文本
  function macroObjToText(mc) {
    if (!mc) return '';
    if (mc.mode === 'stance') {
      let t = '';
      if (mc.shield) t += '#page shield\n' + mc.shield + '\n';
      if (mc.blade) t += '#page blade\n' + mc.blade + '\n';
      return t.trim();
    }
    return (mc.general || '').trim();
  }

  // 从已保存的默认宏（/api/macro/load → userdata/macros.json）载入
  pageWz.querySelector('#wzb_src_from_saved')?.addEventListener('click', async () => {
    try {
      const r = await fetch('/api/macro/load');
      const data = await r.json();
      const text = macroObjToText(data);
      if (!text) { loadStatus.textContent = '尚未保存默认宏'; loadStatus.style.color = '#c9a847'; return; }
      macroTa.value = text;
      updateMacroView();
      loadStatus.textContent = '已从已保存默认宏载入';
      loadStatus.style.color = '#3fb950';
    } catch (e) {
      loadStatus.textContent = '请求失败：' + e.message;
    }
  });

  // 预设宏下拉
  const presetSel = pageWz.querySelector('#wzb_src_preset_sel');
  async function refreshPresetList() {
    if (!presetSel) return;
    try {
      let list = (typeof MACRO_PRESETS !== 'undefined' && Array.isArray(MACRO_PRESETS)) ? MACRO_PRESETS : null;
      if (!list || list.length === 0) {
        const r = await fetch('/api/macro/presets');
        list = await r.json().catch(() => []);
      }
      presetSel.innerHTML = '<option value="">-- 预设宏 --</option>' +
        (list || []).map((p, i) => `<option value="${i}">${escapeHtml(p.name || ('预设' + i))}</option>`).join('');
      presetSel._list = list || [];
    } catch {
      presetSel.innerHTML = '<option value="">加载失败</option>';
    }
  }
  presetSel?.addEventListener('change', () => {
    const idx = parseInt(presetSel.value);
    const list = presetSel._list || [];
    const p = list[idx];
    if (!p) return;
    const text = macroObjToText(p);
    if (!text) { loadStatus.textContent = '预设内容为空'; loadStatus.style.color = '#c9a847'; return; }
    macroTa.value = text;
    updateMacroView();
    loadStatus.textContent = '已载入预设：' + (p.name || '');
    loadStatus.style.color = '#3fb950';
  });

  // 从工作流 A 的输出载入
  pageWz.querySelector('#wzb_src_from_a')?.addEventListener('click', () => {
    const last = window.Jx3State?.loadLastStep?.();
    let m = '';
    if (last?.workflow === 'A' && last.payload) {
      m = last.payload.iterated_macro || last.payload.generated?.macro_text || '';
    }
    if (!m) {
      loadStatus.textContent = '未检测到工作流 A 输出';
      loadStatus.style.color = '#c9a847';
      return;
    }
    macroTa.value = m;
    updateMacroView();
    loadStatus.textContent = '已从工作流 A 载入';
    loadStatus.style.color = '#3fb950';
  });

  async function refreshLoopList() {
    loopSel.innerHTML = '<option value="">-- 加载中 --</option>';
    try {
      const r = await fetch('/api/loop/list');
      const data = await r.json();
      const files = data.files || [];
      loopSel.innerHTML = '<option value="">-- userdata/loops 选择 --</option>' +
        files.map(f => `<option value="${escapeHtml(f)}">${escapeHtml(f)}</option>`).join('');
      if (files.length === 0) loopSel.innerHTML = '<option value="">（userdata/loops 为空）</option>';
    } catch (e) {
      loopSel.innerHTML = '<option value="">加载失败</option>';
    }
  }
  pageWz.querySelector('#wzb_src_refresh')?.addEventListener('click', refreshLoopList);
  loopSel?.addEventListener('change', async () => {
    const name = loopSel.value;
    if (!name) return;
    try {
      const r = await fetch('/api/loop/load?name=' + encodeURIComponent(name));
      const data = await r.json();
      if (data.error) { loadStatus.textContent = '加载失败：' + data.error; return; }
      // cfg.macro 可能是 {mode,general,shield,blade} 对象 → 重建文本
      const mc = data.macro || {};
      let text = '';
      if (mc.mode === 'stance') {
        if (mc.shield) text += '#page shield\n' + mc.shield + '\n';
        if (mc.blade) text += '#page blade\n' + mc.blade + '\n';
      } else {
        text = mc.general || '';
      }
      macroTa.value = text.trim();
      updateMacroView();
      loadStatus.textContent = '已从 ' + name + ' 载入';
      loadStatus.style.color = '#3fb950';
    } catch (e) {
      loadStatus.textContent = '请求失败：' + e.message;
    }
  });

  // 载入按钮二选一高亮
  ['wzb_src_from_a', 'wzb_src_loop_sel'].forEach(id => {
    const el = pageWz.querySelector('#' + id);
    if (el) el.classList.add('wz-btn-fresh');
  });
  pageWz.querySelector('#wzb_src_from_a')?.addEventListener('click', () => {
    pageWz.querySelector('#wzb_src_from_a')?.classList.remove('wz-btn-fresh');
    loopSel?.classList.remove('wz-btn-fresh');
  });
  loopSel?.addEventListener('change', () => {
    pageWz.querySelector('#wzb_src_from_a')?.classList.remove('wz-btn-fresh');
    loopSel.classList.remove('wz-btn-fresh');
  });

  // ─── Step 2：目标 + 场景 + 基线 ───
  const OBJ_IDS = ['dps', 'robust', 'chars', 'fidelity'];
  const WZB_DEFAULT_DELAYS = [23, 60];
  const WZB_DEFAULT_RAGES = [0, 100];
  const WZB_DEFAULT_DURS = [120, 300];
  const WZB_DEFAULT_PAUSES = [0, 30];
  const WZB_ALL_DELAYS = [0, 23, 60, 90, 120];
  const WZB_ALL_RAGES = [0, 30, 50, 100];
  const WZB_ALL_DURS = [60, 120, 240, 300, 600];
  const WZB_ALL_PAUSES = [0, 5, 10, 30];

  function getObjectives() {
    const objs = {};
    for (const k of OBJ_IDS) {
      const cb = document.getElementById('wzb_obj_' + k);
      const w = document.getElementById('wzb_obj_' + k + '_w');
      objs[k] = { enabled: !!cb?.checked, weight: parseFloat(w?.value) || 0 };
    }
    return objs;
  }
  function getScenarios() {
    const pick = (id) => [...document.querySelectorAll('#' + id + ' input:checked')].map(c => Number(c.value));
    return {
      delays: pick('wzb_sc_delays'),
      rages: pick('wzb_sc_rages'),
      durations: pick('wzb_sc_durations'),
      pauses: pick('wzb_sc_pauses'),
    };
  }
  function buildScenarioGrid(id, all, defaults) {
    const host = document.getElementById(id);
    if (!host) return;
    host.innerHTML = all.map(v => {
      const on = defaults.includes(v);
      return `<label class="wz-cb-inline"><input type="checkbox" value="${v}" ${on ? 'checked' : ''}>${v}</label>`;
    }).join('');
  }
  function updateSCCount() {
    const s = getScenarios();
    const p = (s.pauses && s.pauses.length) ? s.pauses.length : 1;
    const n = s.delays.length * s.rages.length * s.durations.length * p;
    const el = document.getElementById('wzb_sc_count');
    if (el) {
      el.textContent = `场景数：${n}（${s.delays.length} × ${s.rages.length} × ${s.durations.length} × 停手${p}）`;
      el.style.color = n === 0 ? '#f85149' : (n > 48 ? '#c9a847' : '#8b949e');
    }
  }
  buildScenarioGrid('wzb_sc_delays', WZB_ALL_DELAYS, WZB_DEFAULT_DELAYS);
  buildScenarioGrid('wzb_sc_rages', WZB_ALL_RAGES, WZB_DEFAULT_RAGES);
  buildScenarioGrid('wzb_sc_durations', WZB_ALL_DURS, WZB_DEFAULT_DURS);
  buildScenarioGrid('wzb_sc_pauses', WZB_ALL_PAUSES, WZB_DEFAULT_PAUSES);
  updateSCCount();
  ['wzb_sc_delays', 'wzb_sc_rages', 'wzb_sc_durations', 'wzb_sc_pauses'].forEach(id => {
    document.getElementById(id)?.addEventListener('change', () => { updateSCCount(); persist(); });
  });
  OBJ_IDS.forEach(k => {
    const cb = document.getElementById('wzb_obj_' + k);
    const num = document.getElementById('wzb_obj_' + k + '_w');
    const range = document.getElementById('wzb_obj_' + k + '_r');
    cb?.addEventListener('change', persist);
    // 数字输入 ↔ 滑块双向绑定
    if (num && range) {
      num.addEventListener('input', () => { range.value = num.value; persist(); });
      range.addEventListener('input', () => { num.value = range.value; persist(); });
    }
  });

  async function runBaseline() {
    const btn = document.getElementById('wzb_baseline_run');
    const status = document.getElementById('wzb_baseline_status');
    const result = document.getElementById('wzb_baseline_result');
    const macro = wz.payload.macro;
    if (!macro) { alert('先在 Step 1 载入或粘贴宏'); return; }
    const sc = getScenarios();
    const pausesDim = (sc.pauses && sc.pauses.length > 0) ? sc.pauses : [0];
    const combos = [];
    for (const d of sc.delays) for (const r of sc.rages) for (const du of sc.durations) for (const pa of pausesDim) {
      const pauses = pa > 0 ? [[du * 0.3, pa]] : [];
      combos.push({ delay: d, initialRage: r, duration: du, pauseSec: pa, pauses });
    }
    if (combos.length === 0) { status.textContent = '至少勾一个场景'; status.style.color = '#f85149'; return; }
    btn.disabled = true;
    status.textContent = `跑 ${combos.length} 个场景…`;
    status.style.color = '#79c0ff';
    try {
      const rows = await Promise.all(combos.map(async c => {
        try {
          const r = await simulateOnce({ macroText: macro, ...c });
          return { ...c, dps: r.dps || 0, counts: collectCastCounts(r.timeline) };
        } catch (e) { return { ...c, err: e.message }; }
      }));
      const dps = rows.filter(x => !x.err).map(x => x.dps);
      const mean = dps.reduce((a, b) => a + b, 0) / Math.max(dps.length, 1);
      const variance = dps.reduce((a, b) => a + (b - mean) ** 2, 0) / Math.max(dps.length, 1);
      const std = Math.sqrt(variance);
      const cv = mean > 0 ? std / mean : 0;
      const min_dps = dps.length > 0 ? Math.min(...dps) : 0;
      wz.payload.baseline = {
        macro, scenarios: sc, rows,
        mean_dps: mean, min_dps, std_dps: std, cv, char_count: macro.length,
        ts: Date.now(),
      };
      wz.completed.add(2);
      persist(); render();
      status.textContent = `完成 · 均 DPS ${Math.round(mean).toLocaleString()} · 最差 ${Math.round(min_dps).toLocaleString()} · CV ${(cv * 100).toFixed(2)}%`;
      status.style.color = '#3fb950';
      // 明细
      let html = `<div class="wz-sec-title" style="font-size:12px;">场景明细</div>
        <table class="wz-diag-table"><thead><tr>
          <th>延迟</th><th>怒气</th><th>时长</th><th>停手</th><th>DPS</th>
        </tr></thead><tbody>`;
      rows.forEach(r => {
        const pa = r.pauseSec ? `${r.pauseSec}s` : '—';
        if (r.err) html += `<tr><td>${r.delay}ms</td><td>${r.initialRage}</td><td>${r.duration}s</td><td>${pa}</td><td style="color:#f85149">失败: ${escapeHtml(r.err)}</td></tr>`;
        else html += `<tr><td>${r.delay}ms</td><td>${r.initialRage}</td><td>${r.duration}s</td><td>${pa}</td><td>${Math.round(r.dps).toLocaleString()}</td></tr>`;
      });
      html += '</tbody></table>';
      result.innerHTML = html;
      result.style.display = 'block';
    } catch (e) {
      status.textContent = '失败：' + e.message;
      status.style.color = '#f85149';
    } finally { btn.disabled = false; }
  }
  document.getElementById('wzb_baseline_run')?.addEventListener('click', runBaseline);
  document.getElementById('wzb_baseline_run')?.classList.add('wz-btn-fresh');
  document.getElementById('wzb_baseline_run')?.addEventListener('click', function() { this.classList.remove('wz-btn-fresh'); });

  // 暴露给 Step 3 搜索阶段读取
  wz._getObjectives = getObjectives;
  wz._getScenarios = getScenarios;

  // ─── Step 3：邻域爬山 / Pareto 搜索 ───
  let searchAbort = false;

  // 把 stat 转成目标向量：所有"越大越好"（robust/chars/fidelity 取反/取倒）
  function statToObjVec(stat, baseline) {
    const baseTotal = Object.values(baseline.rows[0]?.counts || {}).reduce((a, b) => a + b, 0) || 1;
    return {
      dps: stat.mean_dps,
      // robust 直接用 min_dps：Pareto 支配时"最差场景至少不变差"比 CV 更能守住长战
      robust: stat.min_dps,
      chars: baseline.char_count / Math.max(stat.char_count, 1),
      fidelity: 1 - Math.min(stat.avg_cast_diff / baseTotal, 1),
    };
  }
  // 严格支配：a 每个启用目标 ≥ b，且至少一项 >
  function dominates(a, b, objs) {
    let strictBetter = false;
    for (const k of ['dps', 'robust', 'chars', 'fidelity']) {
      if (!objs[k]?.enabled) continue;
      if (a[k] < b[k]) return false;
      if (a[k] > b[k]) strictBetter = true;
    }
    return strictBetter;
  }
  // 把候选插入 archive：剔除被它支配的，若它被任一 archive 支配就丢弃
  function insertIntoArchive(archive, cand, objs) {
    for (const a of archive) {
      if (dominates(a.vec, cand.vec, objs)) return false;
    }
    for (let i = archive.length - 1; i >= 0; i--) {
      if (dominates(cand.vec, archive[i].vec, objs)) archive.splice(i, 1);
    }
    archive.push(cand);
    return true;
  }
  // ── 仪表盘 + 历史 ──
  function renderDashboard() {
    const baseline = wz.payload.baseline;
    const best = wz.payload.search_best;
    const set = (id, text, color) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.textContent = text;
      if (color) el.style.color = color;
    };
    if (baseline) {
      set('wzb_dash_base_mean', Math.round(baseline.mean_dps).toLocaleString());
      set('wzb_dash_base_min', Math.round(baseline.min_dps || 0).toLocaleString());
      set('wzb_dash_base_cv', (baseline.cv * 100).toFixed(2) + '%');
      set('wzb_dash_base_chars', String(baseline.char_count));
    }
    if (best && best.stat && baseline) {
      set('wzb_dash_cur_mean', Math.round(best.stat.mean_dps).toLocaleString());
      set('wzb_dash_cur_min', Math.round(best.stat.min_dps || 0).toLocaleString());
      set('wzb_dash_cur_cv', (best.stat.cv * 100).toFixed(2) + '%');
      set('wzb_dash_cur_chars', String(best.stat.char_count));
      const dMean = best.stat.mean_dps - baseline.mean_dps;
      const dMin = (best.stat.min_dps || 0) - (baseline.min_dps || 0);
      const dCv = (best.stat.cv || 0) - (baseline.cv || 0);
      const dChars = best.stat.char_count - baseline.char_count;
      const color = (v, invert) => {
        if (v === 0) return '#8b949e';
        const better = invert ? v < 0 : v > 0;
        return better ? '#3fb950' : '#f85149';
      };
      set('wzb_dash_cur_mean_d', `${dMean >= 0 ? '+' : ''}${Math.round(dMean)}`, color(dMean, false));
      set('wzb_dash_cur_min_d', `${dMin >= 0 ? '+' : ''}${Math.round(dMin)}`, color(dMin, false));
      set('wzb_dash_cur_cv_d', `${dCv >= 0 ? '+' : ''}${(dCv * 100).toFixed(2)}%`, color(dCv, true));
      set('wzb_dash_cur_chars_d', `${dChars >= 0 ? '+' : ''}${dChars}`, color(dChars, true));
    } else {
      ['wzb_dash_cur_mean', 'wzb_dash_cur_min', 'wzb_dash_cur_cv', 'wzb_dash_cur_chars'].forEach(id => set(id, '—'));
      ['wzb_dash_cur_mean_d', 'wzb_dash_cur_min_d', 'wzb_dash_cur_cv_d', 'wzb_dash_cur_chars_d'].forEach(id => set(id, ''));
    }
  }

  function pushSearchHistory(kind) {
    const best = wz.payload.search_best;
    if (!best) return;
    if (!Array.isArray(wz.payload.search_history)) wz.payload.search_history = [];
    wz.payload.search_history.push({ ts: Date.now(), kind, macro: best.macro, stat: { ...best.stat }, fit: best.fit });
    if (wz.payload.search_history.length > 20) wz.payload.search_history.shift();
  }

  // 行级 diff：{ added, removed, moves[] }
  // moves 在集合完全相同但顺序不同时产生，形如 "A ↔ B"（相邻对换）或 "[i] A → [j] A"（位置变化）
  function macroLineDiff(a, b) {
    const toList = (s) => (s || '').split('\n').map(l => l.trim()).filter(l => l && !l.startsWith('#'));
    const la = toList(a), lb = toList(b);
    const sa = new Set(la), sb = new Set(lb);
    const removed = [...sa].filter(l => !sb.has(l));
    const added = [...sb].filter(l => !sa.has(l));
    const moves = [];
    if (removed.length === 0 && added.length === 0 && la.length === lb.length) {
      // 同集合 + 同长度 → 检查顺序差异
      for (let i = 0; i < la.length; i++) {
        if (la[i] !== lb[i]) {
          // 相邻对换优化
          if (i + 1 < la.length && la[i] === lb[i + 1] && la[i + 1] === lb[i]) {
            moves.push(`[${i + 1}↔${i + 2}] ${la[i]} ⇄ ${la[i + 1]}`);
            i++; // 跳过下一行
          } else {
            const newIdx = lb.indexOf(la[i]);
            moves.push(`[${i + 1} → ${newIdx + 1}] ${la[i]}`);
          }
        }
      }
    }
    return { removed, added, moves };
  }

  function renderSearchHistory() {
    const box = document.getElementById('wzb_unified_history');
    if (!box) return;
    // 合并：Pareto 档案每个解 + 爬山 history。都带 {macro, stat, kind, ts}
    const merged = [];
    (wz.payload.pareto_archive || []).forEach((p) => merged.push({
      ts: p.ts || 0, kind: 'Pareto', macro: p.macro, stat: p.stat, isPareto: true,
    }));
    (wz.payload.search_history || []).forEach(h => merged.push({ ...h, isPareto: false }));
    if (merged.length === 0) { box.innerHTML = '<div class="wz-hint">还没有历史记录。点「开始搜索」产生候选。</div>'; return; }
    const cur = wz.payload.search_best?.macro;
    const origMacro = wz.payload.baseline?.macro || wz.payload.macro || '';
    const baseline = wz.payload.baseline;
    // 按时间降序（最新置顶），相同 ts 按 DPS 降序
    merged.sort((a, b) => {
      const dt = (b.ts || 0) - (a.ts || 0);
      if (dt !== 0) return dt;
      return (b.stat?.mean_dps || 0) - (a.stat?.mean_dps || 0);
    });
    // 同一 macro 多次出现时保留最新一条（排序后第一条）；但爬山条目永远保留
    const seen = new Set();
    const deduped = [];
    for (const m of merged) {
      if (m.isPareto && seen.has(m.macro)) continue;
      seen.add(m.macro);
      deduped.push(m);
    }
    merged.length = 0;
    merged.push(...deduped);
    // 最多显示 40 条，避免 Pareto 档案膨胀刷屏
    if (merged.length > 40) merged.length = 40;
    // 原宏永远置顶（方便对比）
    if (origMacro && baseline) {
      merged.unshift({
        ts: baseline.ts || 0,
        kind: '原宏',
        macro: origMacro,
        stat: { mean_dps: baseline.mean_dps, min_dps: baseline.min_dps, cv: baseline.cv, char_count: baseline.char_count, avg_cast_diff: 0 },
        isOriginal: true,
      });
    }
    box.innerHTML = merged.map((h, i) => {
      const isCur = h.macro === cur;
      const dps = Math.round(h.stat?.mean_dps || 0).toLocaleString();
      const minDps = Math.round(h.stat?.min_dps || 0).toLocaleString();
      const cvPct = h.stat?.cv != null ? (h.stat.cv * 100).toFixed(2) + '%' : '—';
      const time = h.ts ? (() => { const d = new Date(h.ts); return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`; })() : '—';
      let diffHtml = '';
      if (h.isOriginal) {
        diffHtml = '<span style="color:#8b949e;font-size:11px;">基线原宏 —— 回滚到这里可还原出发点</span>';
      } else {
        const diff = macroLineDiff(origMacro, h.macro);
        if (diff.removed.length === 0 && diff.added.length === 0 && diff.moves.length === 0) {
          diffHtml = '<span style="color:#6e7681;font-size:11px;">（与原宏相同）</span>';
        } else {
          const cap = (arr) => arr.length > 3 ? arr.slice(0, 3).concat(['…+' + (arr.length - 3)]) : arr;
          diffHtml = [
            ...cap(diff.removed).map(l => `<div class="wzb-diff-line wzb-diff-removed">− ${escapeHtml(l)}</div>`),
            ...cap(diff.added).map(l => `<div class="wzb-diff-line wzb-diff-added">+ ${escapeHtml(l)}</div>`),
            ...cap(diff.moves).map(l => `<div class="wzb-diff-line wzb-diff-moved">⇄ ${escapeHtml(l)}</div>`),
          ].join('');
        }
      }
      let kindBadge;
      if (h.isOriginal) kindBadge = `<span class="wzb-hist-badge wzb-original">原宏</span>`;
      else if (h.isPareto) kindBadge = `<span class="wzb-hist-badge wzb-pareto">${escapeHtml(h.kind)}</span>`;
      else kindBadge = `<span class="wzb-hist-badge wzb-climb">${escapeHtml(h.kind)}</span>`;
      return `<div class="wz-iter-hist-row wzb-hist-row${isCur ? ' current' : ''}${h.isOriginal ? ' is-original' : ''}" data-merged-idx="${i}" style="cursor:pointer;">
        <div class="wzb-hist-main">
          ${kindBadge}
          <span class="wz-iter-hist-time">${time}</span>
          <span class="wzb-hist-pick">${isCur ? '✓ 当前' : '点选'}</span>
        </div>
        <div class="wzb-hist-stat-line">均 ${dps} · 最差 ${minDps} · CV ${cvPct} · ${h.stat?.char_count || '?'}字</div>
        <div class="wzb-hist-diff">${diffHtml}</div>
      </div>`;
    }).join('');
    box.querySelectorAll('[data-merged-idx]').forEach(row => {
      row.addEventListener('click', () => {
        const i = parseInt(row.dataset.mergedIdx);
        const h = merged[i];
        if (!h) return;
        wz.payload.search_best = { macro: h.macro, stat: { ...h.stat }, fit: 0, history: [] };
        persist();
        updateBestMacroUI();
        renderDashboard();
        renderSearchHistory();
        syncOptMacroToTextarea();
      });
    });
  }

  // Step 4 的宏优化器自动同步：每当最佳宏变化都 push 一次到 #opt_macro_text
  function syncOptMacroToTextarea() {
    const macro = wz.payload.search_best?.macro;
    if (!macro) return;
    writeMacroToGlobal(macro);
    const optTa = document.getElementById('opt_macro_text');
    if (optTa && optTa.value !== macro) {
      optTa.value = macro;
      optTa.dispatchEvent(new Event('input'));
    }
  }

  function updateBestMacroUI() {
    const macro = wz.payload.search_best?.macro || '';
    const ta = document.getElementById('wzb_best_macro');
    const hl = document.getElementById('wzb_best_hl');
    const chars = document.getElementById('wzb_best_chars_inline');
    if (ta) ta.value = macro;
    if (hl && typeof highlightMacroText === 'function') hl.innerHTML = highlightMacroText(macro) + '\n';
    if (chars && window.Jx3CalcPages) {
      const pages = window.Jx3CalcPages(macro, 128);
      const label = (s) => ({ shield: '盾', blade: '刀', wall: '墙', any: '通用' })[s] || s;
      chars.innerHTML = pages.map(p => {
        const cls = p.chars > p.limit ? 'wz-chars-bad' : (p.chars > p.limit * 0.85 ? 'wz-chars-warn' : 'wz-chars-ok');
        return `<span class="${cls}">${label(p.stance)}(${p.chars}/${p.limit})</span>`;
      }).join(' ');
    }
    const resetBtn = document.getElementById('wzb_search_reset');
    if (resetBtn) resetBtn.disabled = !wz.payload.search_best;
  }

  async function runVerify() {
    const status = document.getElementById('wzb_verify_status');
    const box = document.getElementById('wzb_verify_result');
    const btn = document.getElementById('wzb_verify_run');
    const baseline = wz.payload.baseline;
    const best = wz.payload.search_best;
    if (!baseline) { status.textContent = '先在 Step 2 跑基线'; return; }
    if (!best) { status.textContent = '没有搜索结果可验证'; return; }
    btn.disabled = true;
    status.textContent = '跑全场景对比中…';
    try {
      const rows = await Promise.all(baseline.rows.filter(r => !r.err).map(async b => {
        try {
          const r = await simulateOnce({ macroText: best.macro, delay: b.delay, initialRage: b.initialRage, duration: b.duration, pauses: b.pauses || [] });
          const counts = collectCastCounts(r.timeline);
          let diff = 0;
          const keys = new Set([...Object.keys(b.counts || {}), ...Object.keys(counts)]);
          for (const k of keys) diff += Math.abs((b.counts[k] || 0) - (counts[k] || 0));
          return { ...b, curDps: r.dps || 0, castDiff: diff };
        } catch { return { ...b, err: true }; }
      }));
      let html = '<table class="wz-diag-table"><thead><tr><th>延迟</th><th>怒气</th><th>时长</th><th>停手</th><th>基线DPS</th><th>当前DPS</th><th>Δ</th><th>cast-diff</th></tr></thead><tbody>';
      rows.forEach(r => {
        const pa = r.pauseSec ? `${r.pauseSec}s` : '—';
        if (r.err) { html += `<tr><td>${r.delay}ms</td><td>${r.initialRage}</td><td>${r.duration}s</td><td>${pa}</td><td colspan="4" style="color:#f85149">失败</td></tr>`; return; }
        const delta = r.curDps - r.dps;
        const color = delta >= 0 ? '#3fb950' : '#f85149';
        html += `<tr><td>${r.delay}ms</td><td>${r.initialRage}</td><td>${r.duration}s</td><td>${pa}</td>
          <td>${Math.round(r.dps).toLocaleString()}</td>
          <td>${Math.round(r.curDps).toLocaleString()}</td>
          <td style="color:${color}">${delta >= 0 ? '+' : ''}${Math.round(delta)}</td>
          <td>${r.castDiff}</td></tr>`;
      });
      html += '</tbody></table>';
      box.innerHTML = html;
      box.style.display = 'block';
      status.textContent = '完成';
    } catch (e) {
      status.textContent = '失败：' + e.message;
    } finally { btn.disabled = false; }
  }
  document.getElementById('wzb_verify_run')?.addEventListener('click', runVerify);
  document.getElementById('wzb_search_reset')?.addEventListener('click', () => {
    if (!confirm('清除搜索结果和历史？')) return;
    delete wz.payload.search_best;
    wz.payload.search_history = [];
    wz.payload.pareto_archive = [];
    updateBestMacroUI();
    renderDashboard();
    renderSearchHistory();
    const box = document.getElementById('wzb_verify_result');
    if (box) { box.innerHTML = ''; box.style.display = 'none'; }
    persist();
  });


  // fitness: 加权和。稳定性改用 min_dps / baseline.mean_dps（最差场景 DPS 占比），比 CV 更直观可比
  function computeFitness(candStat, baseline, objs) {
    let score = 0;
    if (objs.dps.enabled) score += objs.dps.weight * (candStat.mean_dps / Math.max(baseline.mean_dps, 1));
    if (objs.robust.enabled) {
      // 稳定性：最差场景 DPS / baseline 均 DPS，放大 2× 让它更敏感
      const minRatio = candStat.min_dps / Math.max(baseline.mean_dps, 1);
      score += objs.robust.weight * 2.0 * minRatio;
    }
    if (objs.chars.enabled) score += objs.chars.weight * (baseline.char_count / Math.max(candStat.char_count, 1));
    if (objs.fidelity.enabled) {
      const baseTotal = Object.values(baseline.rows[0]?.counts || {}).reduce((a, b) => a + b, 0) || 1;
      score += objs.fidelity.weight * (1 - Math.min(candStat.avg_cast_diff / baseTotal, 1));
    }
    return score;
  }

  // 宏 → 指标的 memoize 缓存：相同宏不重跑，解决"宏顺序/内容相同但指标漂移"
  const _evalCache = new Map();
  async function evalMacroOnScenarios(macro, scenarios, baselineRows /*, sampleCap 已废弃 */) {
    // 全场景评估：不再抽样。相同宏有缓存直接返回，避免重复 simulate。
    const pausesDim = (scenarios.pauses && scenarios.pauses.length > 0) ? scenarios.pauses : [0];
    const combos = [];
    for (const d of scenarios.delays) for (const r of scenarios.rages) for (const du of scenarios.durations) for (const pa of pausesDim) {
      // 停手位置：战斗中段随机 → 用 duration*0.3 作为固定起点（deterministic，避免缓存失效）
      const pauses = pa > 0 ? [[du * 0.3, pa]] : [];
      combos.push({ delay: d, initialRage: r, duration: du, pauses });
    }
    if (combos.length === 0) return null;
    const cacheKey = macro + '|' + combos.map(c => `${c.delay}_${c.initialRage}_${c.duration}_${JSON.stringify(c.pauses)}`).join(',');
    if (_evalCache.has(cacheKey)) return _evalCache.get(cacheKey);
    const picked = combos;
    const rows = await Promise.all(picked.map(async c => {
      try {
        const r = await simulateOnce({ macroText: macro, ...c });
        return { ...c, dps: r.dps || 0, counts: collectCastCounts(r.timeline) };
      } catch { return null; }
    }));
    const ok = rows.filter(x => x);
    if (ok.length === 0) return null;
    const dps = ok.map(x => x.dps);
    const mean = dps.reduce((a, b) => a + b, 0) / dps.length;
    const min_dps = Math.min(...dps);
    const std = Math.sqrt(dps.reduce((a, b) => a + (b - mean) ** 2, 0) / dps.length);
    const cv = mean > 0 ? std / mean : 0;
    let totalDiff = 0;
    for (const r of ok) {
      const bRow = baselineRows.find(b => b.delay === r.delay && b.initialRage === r.initialRage && b.duration === r.duration)
                || baselineRows[0];
      if (bRow && bRow.counts) {
        const keys = new Set([...Object.keys(r.counts), ...Object.keys(bRow.counts)]);
        for (const k of keys) totalDiff += Math.abs((r.counts[k] || 0) - (bRow.counts[k] || 0));
      }
    }
    const avg_cast_diff = totalDiff / ok.length;
    const result = { mean_dps: mean, min_dps, cv, char_count: macro.length, avg_cast_diff, scenarios_sampled: ok.length };
    _evalCache.set(cacheKey, result);
    return result;
  }

  async function genNeighbors(macro) {
    // 剪枝候选 + swap 候选合并，各保留一半
    const out = [];
    try {
      const r1 = await fetch('/api/macro/prune_candidates', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ macro_text: macro }) });
      const d1 = await r1.json();
      (d1.candidates || []).forEach(c => out.push({ kind: 'prune', macro: c.after_macro, label: `删 ${c.atom}（${c.skill}）` }));
    } catch {}
    try {
      const r2 = await fetch('/api/macro/swap_candidates', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ macro_text: macro }) });
      const d2 = await r2.json();
      (d2.candidates || []).forEach(c => out.push({ kind: 'swap', macro: c.after_macro, label: `swap ${c.skill_a}↔${c.skill_b}` }));
    } catch {}
    return out;
  }

  async function runSearch() {
    searchAbort = false;
    const paretoMode = !!document.getElementById('wzb_pareto_mode')?.checked;
    const btn = document.getElementById('wzb_search_run');
    const stopBtn = document.getElementById('wzb_search_stop');
    const status = document.getElementById('wzb_search_status');
    const progEl = document.getElementById('wzb_search_progress');
    const bestTa = document.getElementById('wzb_best_macro');
    const bestHl = document.getElementById('wzb_best_hl');

    if (!wz.payload.macro) { alert('先在 Step 1 载入宏'); return; }
    if (!wz.payload.baseline) { alert('先在 Step 2 跑基线'); return; }
    const objs = getObjectives();
    if (!Object.values(objs).some(o => o.enabled)) { alert('至少启用一个目标'); return; }
    const scenarios = getScenarios();
    const G = parseInt(document.getElementById('wzb_gen_count').value) || 15;
    const K = parseInt(document.getElementById('wzb_neigh_cap').value) || 12;
    // 场景抽样上限已废弃（全场景 + 缓存）
    const earlyStop = document.getElementById('wzb_stop_no_improve').checked;

    btn.disabled = true; stopBtn.disabled = false;
    progEl.innerHTML = '';

    let curMacro = wz.payload.macro;
    const baseline = wz.payload.baseline;
    // baseline fitness 作为起点
    let curStat = { mean_dps: baseline.mean_dps, min_dps: baseline.min_dps || baseline.mean_dps, cv: baseline.cv, char_count: baseline.char_count, avg_cast_diff: 0 };
    let curFit = computeFitness(curStat, baseline, objs);
    let bestMacro = curMacro, bestFit = curFit, bestStat = curStat;
    bestTa.value = bestMacro;
    if (bestHl && typeof highlightMacroText === 'function') bestHl.innerHTML = highlightMacroText(bestMacro) + '\n';

    let noImproveRounds = 0;
    const history = [{ gen: 0, fit: curFit, dps: curStat.mean_dps }];
    status.textContent = `第 0 代 · fitness ${curFit.toFixed(4)} · DPS ${Math.round(curStat.mean_dps).toLocaleString()}`;

    // Pareto 档案（仅 paretoMode 用）：初始塞入 baseline 当前解
    const archive = [];
    if (paretoMode) {
      archive.push({ macro: curMacro, stat: curStat, vec: statToObjVec(curStat, baseline) });
    }

    try {
      for (let g = 1; g <= G; g++) {
        if (searchAbort) { status.textContent = `已中断（第 ${g - 1} 代）`; break; }
        status.textContent = `第 ${g} / ${G} 代 · 产生邻居…`;
        // Pareto 模式：从档案里随机挑一个当 parent 产生邻居
        const parentMacro = (paretoMode && archive.length > 0)
          ? archive[Math.floor(Math.random() * archive.length)].macro
          : curMacro;
        let neighs = await genNeighbors(parentMacro);
        if (neighs.length === 0) { status.textContent = `第 ${g} 代：无邻居，退出`; break; }
        if (neighs.length > K) neighs = neighs.sort(() => Math.random() - 0.5).slice(0, K);
        status.textContent = `第 ${g} 代 · 评估 ${neighs.length} 个邻居…`;
        const evals = await Promise.all(neighs.map(async n => {
          if (searchAbort) return null;
          const st = await evalMacroOnScenarios(n.macro, scenarios, baseline.rows);
          if (!st) return null;
          return { n, st, fit: computeFitness(st, baseline, objs), vec: statToObjVec(st, baseline) };
        }));
        const ok = evals.filter(x => x);

        if (paretoMode) {
          let added = 0;
          for (const e of ok) {
            if (insertIntoArchive(archive, { macro: e.n.macro, stat: e.st, vec: e.vec }, objs)) added++;
          }
          history.push({ gen: g, fit: 0, dps: archive[0]?.stat.mean_dps || 0, accepted: added > 0 ? `+${added}` : null });
          status.textContent = `第 ${g} 代 · Pareto 档案 ${archive.length}（+${added}）`;
          // 每代实时刷新历史面板：镜像 archive 到 payload，renderSearchHistory 会按 macro 去重
          if (added > 0) {
            const nowTs = Date.now();
            wz.payload.pareto_archive = archive.map((a, ai) => ({ ...a, ts: a.ts || (nowTs + ai) }));
            renderSearchHistory();
          }
          if (added === 0) noImproveRounds++; else noImproveRounds = 0;
          if (earlyStop && noImproveRounds >= 3) { status.textContent += ' · 早停'; break; }
          continue;
        }

        ok.sort((a, b) => b.fit - a.fit);
        const top = ok[0];
        if (!top || top.fit <= curFit) {
          noImproveRounds++;
          history.push({ gen: g, fit: curFit, dps: curStat.mean_dps });
          status.textContent = `第 ${g} 代：无提升（连续 ${noImproveRounds} 代）`;
          if (earlyStop && noImproveRounds >= 3) { status.textContent += ' · 早停'; break; }
          continue;
        }
        noImproveRounds = 0;
        curMacro = top.n.macro;
        curStat = top.st; curFit = top.fit;
        history.push({ gen: g, fit: curFit, dps: curStat.mean_dps, accepted: top.n.label });
        if (curFit > bestFit) {
          bestFit = curFit; bestMacro = curMacro; bestStat = curStat;
          bestTa.value = bestMacro;
          if (bestHl && typeof highlightMacroText === 'function') bestHl.innerHTML = highlightMacroText(bestMacro) + '\n';
          // 每次真提升时实时写回 + 更新历史/仪表盘
          wz.payload.search_best = { macro: bestMacro, stat: bestStat, fit: bestFit, history };
          pushSearchHistory(`爬山 g=${g}`);
          renderDashboard();
          renderSearchHistory();
        }
        status.textContent = `第 ${g} 代 · fitness ${curFit.toFixed(4)} · DPS ${Math.round(curStat.mean_dps).toLocaleString()} · ${top.n.label}`;
      }

      if (paretoMode) {
        // 取档案里 DPS 最高的当默认输出
        const sorted = archive.slice().sort((a, b) => b.stat.mean_dps - a.stat.mean_dps);
        const top = sorted[0];
        if (top) {
          bestMacro = top.macro; bestStat = top.stat; bestFit = 0;
          bestTa.value = bestMacro;
          if (bestHl && typeof highlightMacroText === 'function') bestHl.innerHTML = highlightMacroText(bestMacro) + '\n';
        }
        progEl.innerHTML = `<div>Pareto 档案 <b>${archive.length}</b> 个非支配解 · 默认输出 DPS 最高者 <b>${Math.round(bestStat.mean_dps).toLocaleString()}</b></div>`;
        // 一次性写入档案（带稳定的 ts），交给 renderSearchHistory 渲染统一历史
        const nowTs = Date.now();
        wz.payload.pareto_archive = archive.map((a, i) => ({ ...a, ts: nowTs + i }));
      } else {
        progEl.innerHTML = `<div>最终 fitness <b>${bestFit.toFixed(4)}</b> · DPS <b>${Math.round(bestStat.mean_dps).toLocaleString()}</b> · CV <b>${(bestStat.cv * 100).toFixed(2)}%</b> · 字数 <b>${bestStat.char_count}</b></div>
          <div style="color:#8b949e;margin-top:6px;">迭代历史（${history.length - 1} 代）：${history.slice(1).map(h => (h.accepted ? '✓' : '—')).join('')}</div>`;
        delete wz.payload.pareto_archive;
      }
      wz.payload.search_best = { macro: bestMacro, stat: bestStat, fit: bestFit, history };
      // 爬山模式每次提升时已增量 push；Pareto 档案也已实时镜像，结束时不再重复 push
      wz.completed.add(3);
      persist(); render();
      updateBestMacroUI();
      renderDashboard();
      renderSearchHistory();
      syncOptMacroToTextarea();
    } catch (e) {
      status.textContent = '失败：' + e.message;
    } finally {
      btn.disabled = false; stopBtn.disabled = true;
    }
  }
  document.getElementById('wzb_search_run')?.addEventListener('click', runSearch);
  document.getElementById('wzb_search_stop')?.addEventListener('click', () => { searchAbort = true; });
  document.getElementById('wzb_search_run')?.classList.add('wz-btn-fresh');
  document.getElementById('wzb_search_run')?.addEventListener('click', function() { this.classList.remove('wz-btn-fresh'); });

  // ─── Step 4：输出 ───
  function getFinalMacroB() {
    return wz.payload.search_best?.macro || wz.payload.macro || '';
  }
  function renderStep4B() {
    const macro = getFinalMacroB();
    const sum = document.getElementById('wzb_out_summary');
    const ta = document.getElementById('wzb_out_macro');
    const hl = document.getElementById('wzb_out_macro_hl');
    const chars = document.getElementById('wzb_out_chars_inline');
    if (!ta) return;
    const disableIds = ['wzb_out_to_loop', 'wzb_out_save_macro', 'wzb_out_save_userdata', 'wzb_out_copy'];
    if (!macro) {
      sum.innerHTML = '<div class="wz-hint">无结果。先完成 Step 1 / Step 3。</div>';
      ta.value = ''; if (hl) hl.innerHTML = ''; if (chars) chars.innerHTML = '';
      disableIds.forEach(id => { const b = document.getElementById(id); if (b) b.disabled = true; });
      return;
    }
    disableIds.forEach(id => { const b = document.getElementById(id); if (b) b.disabled = false; });
    const best = wz.payload.search_best;
    const baseline = wz.payload.baseline;
    let info = '';
    if (best && baseline) {
      const dpsGain = best.stat.mean_dps - baseline.mean_dps;
      const dpsPct = baseline.mean_dps ? (dpsGain / baseline.mean_dps * 100) : 0;
      const charDelta = best.stat.char_count - baseline.char_count;
      const dpsColor = dpsGain >= 0 ? '#3fb950' : '#f85149';
      const hasFit = best.fit && best.fit > 0;
      const iterN = (best.history?.length || 0) - 1;
      const sourceTag = wz.payload.pareto_archive?.length
        ? 'Pareto 档案挑选'
        : (iterN > 0 ? `爬山 ${iterN} 代` : '手动选择 / 回滚');
      info = `
        <div>基线：DPS <b>${Math.round(baseline.mean_dps).toLocaleString()}</b> · CV <b>${(baseline.cv * 100).toFixed(2)}%</b> · 字数 <b>${baseline.char_count}</b></div>
        <div>搜索后：DPS <b>${Math.round(best.stat.mean_dps).toLocaleString()}</b>
          <span style="color:${dpsColor}">(${dpsGain >= 0 ? '+' : ''}${Math.round(dpsGain)} / ${dpsPct >= 0 ? '+' : ''}${dpsPct.toFixed(2)}%)</span>
          · CV <b>${(best.stat.cv * 100).toFixed(2)}%</b>
          · 字数 <b>${best.stat.char_count}</b> <span style="color:${charDelta <= 0 ? '#3fb950' : '#f85149'}">(${charDelta >= 0 ? '+' : ''}${charDelta})</span></div>
        <div class="wz-hint">来源：${sourceTag}${hasFit ? ` · fitness ${best.fit.toFixed(4)}` : ''}</div>
      `;
    } else {
      info = '<div class="wz-hint">未跑搜索，输出的是 Step 1 载入的原宏。</div>';
    }
    sum.innerHTML = info;
    ta.value = macro;
    if (hl && typeof highlightMacroText === 'function') hl.innerHTML = highlightMacroText(macro) + '\n';
    if (chars && window.Jx3CalcPages) {
      const pages = window.Jx3CalcPages(macro, 128);
      const label = (s) => ({ shield: '盾', blade: '刀', wall: '墙', any: '通用' })[s] || s;
      chars.innerHTML = pages.map(p => {
        const cls = p.chars > p.limit ? 'wz-chars-bad' : (p.chars > p.limit * 0.85 ? 'wz-chars-warn' : 'wz-chars-ok');
        return `<span class="${cls}">${label(p.stance)}(${p.chars}/${p.limit})</span>`;
      }).join(' ');
    }
  }

  // 把宏文本分段写回全局 macroPages
  function setGlobalMacroFromTextB(text) {
    if (typeof macroPages === 'undefined') return;
    macroPages.general = ''; macroPages.shield = ''; macroPages.blade = '';
    const lines = (text || '').split('\n');
    let cur = null, general = '';
    for (const l of lines) {
      const m = l.match(/^#page\s+(\w+)/);
      if (m) { cur = m[1]; continue; }
      if (cur === 'shield') macroPages.shield += l + '\n';
      else if (cur === 'blade') macroPages.blade += l + '\n';
      else general += l + '\n';
    }
    macroPages.general = general.trim();
    macroPages.shield = macroPages.shield.trim();
    macroPages.blade = macroPages.blade.trim();
    if (typeof macroMode !== 'undefined') {
      window.macroMode = (macroPages.shield || macroPages.blade) ? 'stance' : 'general';
    }
  }

  document.getElementById('wzb_out_copy')?.addEventListener('click', async () => {
    const macro = getFinalMacroB();
    const status = document.getElementById('wzb_out_status');
    try {
      await navigator.clipboard.writeText(macro);
      status.textContent = '已复制 ✓'; setTimeout(() => status.textContent = '', 1200);
    } catch (e) { status.textContent = '复制失败'; }
  });

  document.getElementById('wzb_out_save_macro')?.addEventListener('click', async () => {
    const macro = getFinalMacroB();
    const status = document.getElementById('wzb_out_status');
    setGlobalMacroFromTextB(macro);
    try {
      const r = await fetch('/api/macro/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
          general: macroPages.general, shield: macroPages.shield, blade: macroPages.blade,
        }),
      });
      status.textContent = r.ok ? '已保存为默认宏 ✓' : '保存失败';
    } catch (e) { status.textContent = '请求失败：' + e.message; }
  });

  document.getElementById('wzb_out_to_loop')?.addEventListener('click', async () => {
    const macro = getFinalMacroB();
    const status = document.getElementById('wzb_out_status');
    if (!macro) return;
    setGlobalMacroFromTextB(macro);
    fetch('/api/macro/save', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
        general: macroPages.general, shield: macroPages.shield, blade: macroPages.blade,
      }),
    }).catch(() => {});
    window.Jx3Nav?.switchPage('page-sim');
    status.textContent = '已切换到循环模拟，跑宏中…';
    const container = document.getElementById('sim_sequence');
    if (container) container.innerHTML = '';
    const durs = wz.payload.baseline?.scenarios?.durations;
    const dur = (Array.isArray(durs) && durs.length > 0) ? Math.max(...durs) : 120;
    try {
      if (typeof runMacroSimulate === 'function') await runMacroSimulate(dur);
      status.textContent = `已写入并跑宏（${dur}s）`;
    } catch (e) { status.textContent = '跑宏失败：' + e.message; }
  });

  document.getElementById('wzb_out_save_userdata')?.addEventListener('click', async () => {
    const macro = getFinalMacroB();
    const status = document.getElementById('wzb_out_status');
    if (!macro) return;
    const name = prompt('循环名（自动追加时间戳）：', 'wizard-B');
    if (name === null) return;
    setGlobalMacroFromTextB(macro);
    status.textContent = '按新宏跑序列中…';
    const container = document.getElementById('sim_sequence');
    if (container) container.innerHTML = '';
    const durs2 = wz.payload.baseline?.scenarios?.durations;
    const dur2 = (Array.isArray(durs2) && durs2.length > 0) ? Math.max(...durs2) : 120;
    try {
      if (typeof runMacroSimulate === 'function') await runMacroSimulate(dur2);
    } catch (e) { status.textContent = '跑宏失败：' + e.message; return; }
    const cfg = (typeof buildLoopConfig === 'function') ? buildLoopConfig() : {};
    cfg.macro = {
      mode: (macroPages.shield || macroPages.blade) ? 'stance' : 'general',
      general: macroPages.general, shield: macroPages.shield, blade: macroPages.blade,
    };
    try {
      const r = await fetch('/api/loop/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, config: cfg }),
      });
      const data = await r.json();
      status.textContent = data.ok ? `已保存 ✓ ${data.file}` : ('保存失败：' + (data.error || ''));
    } catch (e) { status.textContent = '请求失败：' + e.message; }
  });

  // 在 render 里触发 Step 3/5 渲染
  const origRenderB = render;
  let lastStep = null;
  render = function() {
    origRenderB();
    if (wz.current === 3) { updateBestMacroUI(); renderDashboard(); renderSearchHistory(); }
    if (wz.current === 5) renderStep4B();
    // Step 4 进入/离开时管理 page-opt 的嵌入位置
    syncOptEmbed();
    // 首次进入 Step 4 时自动载入最新宏
    if (wz.current === 4 && lastStep !== 4) loadMacroToOpt();
    lastStep = wz.current;
  };

  // ─── Step 4：跳转到独立宏优化器（不再 DOM-move，避免泄漏到其他页）───
  function pickLatestMacro() {
    return wz.payload.search_best?.macro
        || wz.payload.macro
        || '';
  }

  function writeMacroToGlobal(macro) {
    if (typeof macroPages === 'undefined') return;
    macroPages.general = ''; macroPages.shield = ''; macroPages.blade = '';
    const lines = (macro || '').split('\n');
    let cur = null, general = '';
    for (const l of lines) {
      const m = l.match(/^#page\s+(\w+)/);
      if (m) { cur = m[1]; continue; }
      if (cur === 'shield') macroPages.shield += l + '\n';
      else if (cur === 'blade') macroPages.blade += l + '\n';
      else general += l + '\n';
    }
    macroPages.general = general.trim();
    macroPages.shield = macroPages.shield.trim();
    macroPages.blade = macroPages.blade.trim();
    if (typeof macroMode !== 'undefined') {
      window.macroMode = (macroPages.shield || macroPages.blade) ? 'stance' : 'general';
    }
  }

  // DOM-move 方案（参考 Wizard A 对 #page-sim 的处理）：
  // - 只把 #page-opt DOM 搬进 slot，从不给它加 .active（靠 CSS 强制显示）
  // - 离开 Wizard B 或 Step 4 时立即搬回原父节点
  // - 外部把 page-opt 切到 active（跳转下拉点 🛠 宏优化器）时也立即搬回
  const optPage = document.getElementById('page-opt');
  const optSlot = document.getElementById('wzb_opt_slot');
  const optOrigParent = optPage?.parentNode;

  function embedOpt() {
    if (!optPage || !optSlot) return;
    if (!optSlot.contains(optPage)) optSlot.appendChild(optPage);
  }
  function restoreOpt() {
    if (!optPage || !optOrigParent) return;
    if (optOrigParent !== optPage.parentNode) optOrigParent.appendChild(optPage);
    restoreOptGaCells();
  }
  function syncOptEmbed() {
    const wzActive = pageWz.classList.contains('active');
    const atStep4 = wz.current === 4;
    if (wzActive && atStep4) embedOpt();
    else restoreOpt();
  }
  // 监听 Wizard B class 变化（进/出 Wizard B 时触发）
  new MutationObserver(syncOptEmbed).observe(pageWz, { attributes: true, attributeFilter: ['class'] });
  // 监听 page-opt 本身的 active：如果被外部切到 active（跳转下拉），立刻搬回原位，否则
  // 它会出现在 wz_sim_slot 里且其他页显示时也可见
  if (optPage) {
    new MutationObserver(() => {
      if (optPage.classList.contains('active')) restoreOpt();
    }).observe(optPage, { attributes: true, attributeFilter: ['class'] });
  }

  function loadMacroToOpt() {
    const macro = pickLatestMacro();
    const status = document.getElementById('wzb_opt_status');
    if (!macro) { if (status) status.textContent = '尚无可用宏'; return false; }
    writeMacroToGlobal(macro);
    // 同步到宏优化器的 textarea（触发它的自动分析）
    const optTa = document.getElementById('opt_macro_text');
    if (optTa) {
      let full = '';
      if (macroPages.shield || macroPages.blade) {
        if (macroPages.shield) full += '#page shield\n' + macroPages.shield + '\n';
        if (macroPages.blade) full += '#page blade\n' + macroPages.blade + '\n';
        full = full.trim();
      } else {
        full = macroPages.general || '';
      }
      optTa.value = full;
      optTa.dispatchEvent(new Event('input'));
    }
    // 继承 Step 2 的场景集 → 宏优化器
    const sc = wz.payload.baseline?.scenarios;
    if (sc && Array.isArray(sc.durations) && sc.durations.length > 0) {
      const dmin = Math.min(...sc.durations);
      const dmax = Math.max(...sc.durations);
      const dmnEl = document.getElementById('opt_duration_min');
      const dmxEl = document.getElementById('opt_duration_max');
      const sampEl = document.getElementById('opt_samples');
      if (dmnEl) { dmnEl.value = dmin; dmnEl.dispatchEvent(new Event('input')); }
      if (dmxEl) { dmxEl.value = dmax; dmxEl.dispatchEvent(new Event('input')); }
      if (sampEl) {
        sampEl.value = Math.min(10, Math.max(sc.durations.length, 3));
        sampEl.dispatchEvent(new Event('input'));
      }
      // 顶栏 sim_delay（旧优化器读这里）= Step 2 延迟集的中位数
      if (Array.isArray(sc.delays) && sc.delays.length > 0) {
        const sorted = sc.delays.slice().sort((a, b) => a - b);
        const median = sorted[Math.floor(sorted.length / 2)];
        const delayInput = document.getElementById('sim_delay');
        const delayLabel = document.getElementById('sim_delay_label');
        if (delayInput) delayInput.value = String(median);
        const item = document.querySelector(`.sim-dropdown-item[data-value="${median}"]`);
        if (item && delayLabel) delayLabel.textContent = item.textContent;
        document.querySelectorAll('.sim-dropdown-item[data-value]').forEach(i => {
          i.classList.toggle('active', i.dataset.value === String(median));
        });
      }
      // 起手怒气起始怒气（旧优化器读 adminInitialRage）= 中位数
      if (Array.isArray(sc.rages) && sc.rages.length > 0) {
        const sortedR = sc.rages.slice().sort((a, b) => a - b);
        const median = sortedR[Math.floor(sortedR.length / 2)];
        window.adminInitialRage = median;
        adminInitialRage = median;
        if (typeof updateAdminRageLabel === 'function') updateAdminRageLabel();
      }
    }
    // 已继承的 GA 输入直接隐藏（时长/采样），避免用户误改
    ['opt_duration_min', 'opt_duration_max', 'opt_samples'].forEach(id => {
      const el = document.getElementById(id);
      if (el) {
        const cell = el.closest('.opt-ga-cell');
        if (cell) cell.style.display = 'none';
      }
    });
    if (status) status.textContent = `已载入：${wz.payload.search_best ? 'Step 3 搜索结果' : 'Step 1 原宏'} · ${macro.length} 字 · 场景 ${wz.payload.baseline?.scenarios?.durations?.length || '?'} 档时长已继承`;
    return true;
  }

  // 离开 Step 4 时恢复这些输入可见，避免用户去独立优化器页面时看到空栏
  function restoreOptGaCells() {
    ['opt_duration_min', 'opt_duration_max', 'opt_samples'].forEach(id => {
      const el = document.getElementById(id);
      if (el) {
        const cell = el.closest('.opt-ga-cell');
        if (cell) cell.style.display = '';
      }
    });
  }
  document.getElementById('wzb_opt_reload')?.addEventListener('click', loadMacroToOpt);

  // 宏文本弹窗：打开时把 .opt-sec[data-sec="macro"] DOM-move 到 modal slot；关闭时搬回
  const macroModal = document.getElementById('wzb_macro_modal');
  const macroModalSlot = document.getElementById('wzb_macro_modal_slot');
  let macroSecOrigParent = null;
  function openMacroModal() {
    const sec = document.querySelector('.opt-sec[data-sec="macro"]');
    if (!sec || !macroModal || !macroModalSlot) return;
    if (!macroSecOrigParent) macroSecOrigParent = sec.parentNode;
    // 让 modal 内的 sec 显示出来（覆盖 display:none）
    sec.style.display = '';
    macroModalSlot.appendChild(sec);
    macroModal.style.display = 'flex';
  }
  function closeMacroModal() {
    const sec = macroModalSlot?.querySelector('.opt-sec[data-sec="macro"]');
    if (sec && macroSecOrigParent) {
      sec.style.display = '';
      macroSecOrigParent.appendChild(sec);
    }
    if (macroModal) macroModal.style.display = 'none';
  }
  document.getElementById('wzb_show_macro_btn')?.addEventListener('click', openMacroModal);
  document.getElementById('wzb_macro_modal_close')?.addEventListener('click', closeMacroModal);
  macroModal?.addEventListener('click', (e) => { if (e.target === macroModal) closeMacroModal(); });

  window.Jx3WizardB = {
    enter(resume = false) {
      if (resume) restore();
      else { wz.current = 1; wz.completed = new Set(); wz.payload = {}; }
      window.Jx3Nav?.switchPage('page-wizard-b');
      // 恢复 textarea
      if (macroTa && wz.payload.macro != null) {
        macroTa.value = wz.payload.macro;
        updateMacroView();
      }
      refreshLoopList();
      refreshPresetList();
      // 首次进入（无既存 macro）时，默认加载宏设置里保存的默认宏
      if (!wz.payload.macro) {
        fetch('/api/macro/load').then(r => r.json()).then(data => {
          const text = macroObjToText(data);
          if (text && !macroTa.value) {
            macroTa.value = text;
            updateMacroView();
            loadStatus.textContent = '已自动载入默认宏';
            loadStatus.style.color = '#79c0ff';
          }
        }).catch(() => {});
      }
      render(); persist();
    },
  };
  render();
})();

// ═══════════════════════════════════════════════════════════════════════════
// 工作流 D：配装搜索（page-wizard-c，独立页面）
// ═══════════════════════════════════════════════════════════════════════════
(function initWizardC() {
  const page = document.getElementById('page-wizard-c');
  if (!page) return;

  // ── hover tooltip 防闪 + 富样式工具 ──
  //   1. 150ms 延迟：快速划过不触发，避免连续闪现
  //   2. anchor 锁：异步 promise 解析时若已 mouseleave 不显示
  //   3. wide=true：g-tooltip 切多行模式（white-space: normal, max-width: 360px）
  let _wzcHoverAnchor = null;
  let _wzcHoverTimer = null;
  function wzcShowHover(anchor, htmlOrPromise, wide = false) {
    clearTimeout(_wzcHoverTimer);
    _wzcHoverAnchor = anchor;
    _wzcHoverTimer = setTimeout(() => {
      if (_wzcHoverAnchor !== anchor) return;
      Promise.resolve(htmlOrPromise).then(html => {
        if (_wzcHoverAnchor !== anchor) return;
        if (!html) return;
        if (wide) {
          gTooltip.style.whiteSpace = 'normal';
          gTooltip.style.maxWidth = '360px';
        }
        showTooltip(anchor, html);
      }).catch(() => {});
    }, 150);
  }
  function wzcHideHover() {
    clearTimeout(_wzcHoverTimer);
    _wzcHoverAnchor = null;
    hideTooltip();
  }

  // POS_LIST / POS_LABEL / POS_TO_SUB 已抽到顶层（全局），各 IIFE 直接用

  const state = {
    hasteTiers: null,            // 24 帧基底的 tier 数组
    // 三轴 chip 各自独立追踪：每条轴选哪些 tier
    selectedChipsByAxis: { 24: new Set(), 16: new Set(), 8: new Set() },
    hasteSegments: [],           // 派生：合并相邻/重叠后的搜索区间数组 [{min,max},...]；空 = 无段位约束
    perSlot: {},                 // pos → { mode, count, candidates, currentId, currentName, filter }
    // 用户在候选池表第二列手动切换的"当前装备"覆盖（仅 wzc 内生效；ENCHANT_* 不在此处）
    //   { POS: { equip_id, name, level, set_id, set_name, belong_school, magic_kind } }
    //   _wzcActiveCfg 会把这些合并进 cfg.slots[POS]，下游 syncCurrentEquip / hover / runSearch 自动生效
    slotOverrides: {},
    lastResult: null,
    lastFitModel: null,    // S6 拟合模型 { mean, ref_dps, grad, hess, axis_min, axis_max, axis_labels, pool_size }
    lastFitMetrics: null,  // 拟合质量 { r_squared, rmse, mae, top10_overlap, fit_samples, validation_samples }
    expandedCurveIdx: new Set(),  // 展开了"属性收益曲线"的结果行 idx 集合
    meta: { schools: [], kinds: [] },  // /api/equip/meta（chips 数据源；首次进入页面时拉一次）
    // 环境覆盖：source = 'loop'（跟随循环模拟） | 'import'（用 importedConfig）
    //   imported* 仅 source=import 时生效；macro_text / talents / recipes 来自此
    //   其它字段（target/duration/boss/embedding）由 input 当前值直接驱动，与 source 解耦
    env: {
      source: 'loop',
      importedFile: null,
      importedMacro: null,       // string
      importedTalents: null,     // u32[]
      importedRecipes: null,     // u32[]
      importedEquipment: null,   // { slots, stoneId, stoneName, mount } | null
    },
  };

  // 默认 filter
  //   品级 ≥ 35000（含苍云 35300 品 T套上衣等门派套装；高于此苍云 PVE 上衣已无）
  //   schools: 武器走"苍云"门派；其他走 通用 + 苍云（让门派套装上衣等也进候选池）
  //   kinds:   武器不限；其他用 mount 对应的 [通用 主属性, 门派 magic_kind]
  //   battle_types: PVE（默认；PVP/PVX 玩家在 modal 里加）
  function defaultFilterFor(pos) {
    const isWeapon = (pos === 'PRIMARY_WEAPON' || pos === 'SECONDARY_WEAPON');
    return {
      min_level: 35000,
      max_level: 0,
      schools: new Set(isWeapon ? ['苍云'] : ['通用', '苍云']),
      kinds:   new Set(isWeapon ? [] : defaultKindsForMount()),
      attrs:   new Set(),
      battle_types: new Set(['PVE']),
      keyword: '',
      only_set: false,
      categories: new Set(),
    };
  }
  // 滑条端点（与 configurator 一致；step=100）
  const WZC_FM_LEVEL_MIN = 22000;
  const WZC_FM_LEVEL_MAX = 44000;

  POS_LIST.forEach(pos => {
    // excluded: 用户在 modal 预览里勾掉的 equip_id（即使经 filter 匹配也不进候选池）
    // 锁定模式下的子开关：lockEnchant/lockEnhance/lockStone
    //   ON = 锁定该项（用配装器里的值）； OFF = 搜索/不带
    //   小附魔默认 OFF（沿袭旧 search_locked_enh 默认开启搜索）；大附魔/五彩石默认 ON
    state.perSlot[pos] = {
      mode: 'enum', candidates: [], currentId: null, currentName: '', filter: null, excluded: new Set(),
      lockEnchant: true, lockEnhance: false, lockStone: true,
    };
  });

  // ─── 持久化（filter / excluded / mode / 最近一次搜索结果）─────────────────
  // 保存 key 含心法标识，避免切心法后串状态。
  const WZC_STORAGE_VER = 1;
  function _wzcStorageKey() {
    const m = (typeof currentMount !== 'undefined' && currentMount?.mount) || 'FenShanJin';
    return `jx3_wzc_state_v${WZC_STORAGE_VER}_${m}`;
  }
  function _serFilter(f) {
    if (!f) return null;
    return {
      min_level: f.min_level, max_level: f.max_level,
      schools: [...f.schools], kinds: [...f.kinds],
      attrs: [...f.attrs], battle_types: [...f.battle_types],
      keyword: f.keyword || '', only_set: !!f.only_set,
      categories: f.categories ? [...f.categories] : [],
    };
  }
  function _deserFilter(o) {
    if (!o) return null;
    return {
      min_level: o.min_level | 0,
      max_level: o.max_level | 0,
      schools: new Set(o.schools || []),
      kinds:   new Set(o.kinds || []),
      attrs:   new Set(o.attrs || []),
      battle_types: new Set(o.battle_types || []),
      keyword: o.keyword || '',
      only_set: !!o.only_set,
      categories: new Set(o.categories || []),
    };
  }
  let _wzcSaveTimer = null;
  function saveWzcState() {
    if (_wzcSaveTimer) clearTimeout(_wzcSaveTimer);
    _wzcSaveTimer = setTimeout(() => {
      try {
        const bucketSize = parseInt(document.getElementById('wzc_bucket_size')?.value, 10);
        const usePareto = document.getElementById('wzc_use_pareto')?.checked;
        const inheritEnchants = document.getElementById('wzc_inherit_enchants')?.checked;
        const out = {
          perSlot: {},
          lastResult: state.lastResult || null,
          lastResultAt: state.lastResultAt || null,
          lastResultElapsed: state.lastResultElapsed || null,
          lastSearchCtx: state.lastSearchCtx || null,
          bucketSize: Number.isFinite(bucketSize) ? bucketSize : 500,
          usePareto: usePareto !== false,
          inheritEnchants: inheritEnchants !== false,
          env: {
            source: state.env.source,
            importedFile: state.env.importedFile,
            importedMacro: state.env.importedMacro,
            importedTalents: state.env.importedTalents,
            importedRecipes: state.env.importedRecipes,
            importedEquipment: state.env.importedEquipment,
            target_level: document.getElementById('wzc_target_level')?.value || '',
            duration:     document.getElementById('wzc_duration')?.value || '',
            embed:        getEnvEmbed(),
          },
        };
        for (const pos of POS_LIST) {
          const ps = state.perSlot[pos];
          out.perSlot[pos] = {
            mode: ps.mode,
            filter: _serFilter(ps.filter),
            excluded: ps.excluded ? [...ps.excluded] : [],
            lockEnchant: ps.lockEnchant !== false,
            lockEnhance: ps.lockEnhance === true,
            lockStone:   ps.lockStone   !== false,
          };
        }
        out.slotOverrides = state.slotOverrides || {};
        localStorage.setItem(_wzcStorageKey(), JSON.stringify(out));
      } catch (e) { console.warn('[wzc] saveState 失败', e); }
    }, 200);
  }
  function loadWzcState() {
    try {
      const raw = localStorage.getItem(_wzcStorageKey());
      if (!raw) return;
      const o = JSON.parse(raw);
      for (const pos of POS_LIST) {
        const psSaved = o.perSlot?.[pos];
        if (!psSaved) continue;
        const ps = state.perSlot[pos];
        if (psSaved.mode) ps.mode = psSaved.mode;
        if (psSaved.filter) ps.filter = _deserFilter(psSaved.filter);
        if (psSaved.excluded) ps.excluded = new Set(psSaved.excluded);
        if (typeof psSaved.lockEnchant === 'boolean') ps.lockEnchant = psSaved.lockEnchant;
        if (typeof psSaved.lockEnhance === 'boolean') ps.lockEnhance = psSaved.lockEnhance;
        if (typeof psSaved.lockStone   === 'boolean') ps.lockStone   = psSaved.lockStone;
      }
      if (o.lastResult) {
        state.lastResult = o.lastResult;
        state.lastResultAt = o.lastResultAt || null;
        state.lastResultElapsed = o.lastResultElapsed || null;
        state.lastSearchCtx = o.lastSearchCtx || null;
      }
      if (o.slotOverrides && typeof o.slotOverrides === 'object') {
        state.slotOverrides = {};
        for (const [pos, ov] of Object.entries(o.slotOverrides)) {
          if (ov && typeof ov === 'object' && Number.isFinite(ov.equip_id)) {
            state.slotOverrides[pos] = ov;
          }
        }
      }
      // 把 bucket_size / use_pareto 恢复到 input（如果元素已渲染）
      if (Number.isFinite(o.bucketSize)) {
        const el = document.getElementById('wzc_bucket_size');
        if (el) el.value = o.bucketSize;
      }
      if (typeof o.usePareto === 'boolean') {
        const el = document.getElementById('wzc_use_pareto');
        if (el) el.checked = o.usePareto;
      }
      if (typeof o.inheritEnchants === 'boolean') {
        const el = document.getElementById('wzc_inherit_enchants');
        if (el) el.checked = o.inheritEnchants;
      }
      if (o.env) {
        if (o.env.source === 'import' || o.env.source === 'loop') state.env.source = o.env.source;
        state.env.importedFile    = o.env.importedFile || null;
        state.env.importedMacro   = o.env.importedMacro || null;
        state.env.importedTalents = Array.isArray(o.env.importedTalents) ? o.env.importedTalents : null;
        state.env.importedRecipes = Array.isArray(o.env.importedRecipes) ? o.env.importedRecipes : null;
        state.env.importedEquipment = (o.env.importedEquipment && typeof o.env.importedEquipment === 'object') ? o.env.importedEquipment : null;
        const setVal = (id, v) => { const el = document.getElementById(id); if (el && v != null && v !== '') el.value = v; };
        setVal('wzc_target_level', o.env.target_level);
        setVal('wzc_duration',     o.env.duration);
        if (o.env.embed) {
          const r = document.querySelector(`input[name="wzc_embed"][value="${o.env.embed}"]`);
          if (r) r.checked = true;
        }
      }
    } catch (e) { console.warn('[wzc] loadState 失败', e); }
  }

  // 把 filter 序列化成 /api/equip/search 接口需要的对象（Set → Array）
  function filterToBody(f, pos) {
    return {
      sub_type: POS_TO_SUB[pos],
      min_level: f.min_level | 0,
      max_level: f.max_level | 0,
      schools: [...f.schools],
      kinds:   [...f.kinds],
      attrs:   [...f.attrs],
      battle_types: [...f.battle_types],
      keyword: f.keyword || '',
      categories: f.categories ? [...f.categories] : [],
    };
  }

  // 主属性（决定候选池的 magic_kind 默认）
  // 同时返回门派 magic_kind（"外功" / "防御"），覆盖 通用_身法 + 苍云_外功 双轴
  function defaultKindsForMount() {
    const m = (typeof currentMount !== 'undefined' && currentMount?.mount) || 'FenShanJin';
    if (m === 'TieGuYi')    return ['防御'];        // 通用 防御 + 苍云 防御 都是 防御 magic_kind
    if (m === 'FenShanJin') return ['身法', '外功']; // 通用 身法 + 苍云门派外攻 外功
    return [];
  }
  // 兼容（已废弃，保留以避免破坏性引用）
  function defaultKindForMount() { return defaultKindsForMount()[0] || ''; }
  function getMountId() {
    const m = (typeof currentMount !== 'undefined' && currentMount?.mount) || 'FenShanJin';
    return m === 'TieGuYi' ? 10389 : 10390;
  }

  // ─── Phase A 加速槽 + Phase B 偏导槽 候选（外攻 build 固定属性集）────────────
  //   HASTE_SLOTS 进 Phase A 紫·急速 enhance pair；其它槽进 Phase B 偏导 argmax
  //   PHASE_B_ATTRS 来自用户确认的 2026.04 赛季外攻 build 表
  const WZC_HASTE_SLOTS = ['HAT', 'SHOES', 'SECONDARY_WEAPON'];
  // 紫色加速附魔的属性标签：帽子/鞋子叫"急速"，远武叫"加速"
  const WZC_HASTE_LABELS = ['急速', '加速'];
  // 各槽位 DPS 相关副属性（实际数据里的标签，外功 build；铁骨衣 体质→外攻 算 DPS 项）
  const WZC_PHASE_B_ATTRS = {
    // 加速槽：兜底 DPS 增益（Phase A 没选急速时由 Phase B 兜底选这些）
    HAT:              ['外攻', '破招'],
    SHOES:            ['外攻', '破招'],
    SECONDARY_WEAPON: ['力道', '身法', '外破'],
    // 上衣/腰带：紫色全防御类；蓝色节日附魔 远风·X·无双 是 DPS 项；体质（→外攻）也算
    JACKET:  ['无双', '体质'],
    BELT:    ['无双', '体质'],
    WRIST:   ['会心', '力道', '外破', '无双', '身法', '体质'],
    BOTTOMS: ['会心', '力道', '外破', '无双', '身法', '体质'],
    NECKLACE:['体质', '力道', '身法'],
    PENDANT: ['会心', '体质'],                              // 暗影只有 体质/会心/化劲
    RING_1:  ['力道', '身法', '外攻'],
    RING_2:  ['力道', '身法', '外攻'],
    PRIMARY_WEAPON: ['外攻', '武伤'],
  };

  const _wzcEnhCache = new Map();
  async function wzcGetEnhances(subType) {
    if (_wzcEnhCache.has(subType)) return _wzcEnhCache.get(subType);
    const r = await fetch('/api/equip/enhances', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sub_type: subType }),
    });
    const list = r.ok ? await r.json() : [];
    const arr = Array.isArray(list) ? list : [];
    _wzcEnhCache.set(subType, arr);
    return arr;
  }

  // 按 wantedAttrs 取每个属性下 (score, id) 最大的 enhance（最新最高品质）
  //   不再依赖前缀/后缀魔法（风语·/暗影·/绣/铸 等）—— 直接看名字里的属性 label
  //   属性 label 提取规则：
  //     1. 优先括号内：（X）或 (X)
  //     2. 否则取最后一个 · 之后的部分（例如 远风·衣·无双 → 无双）
  //   废弃 ID 跳过（名字含"废弃"）
  function wzcFindBestEnhance(list, wantedAttrs) {
    const want = new Set(wantedAttrs);
    const best = new Map();
    for (const e of list) {
      const nm = e.name || '';
      if (nm.includes('废弃')) continue;
      let attr = null;
      const m = nm.match(/[（(]([^）)]+)[）)]/);
      if (m) {
        attr = m[1];
      } else {
        const parts = nm.split('·');
        attr = parts[parts.length - 1];
      }
      if (!attr || !want.has(attr)) continue;
      const sc = e.score || 0;
      const id = e.id || 0;
      const cur = best.get(attr);
      if (!cur || cur.score < sc || (cur.score === sc && cur.id < id)) {
        best.set(attr, e);
      }
    }
    return [...best.values()];
  }

  // auto-derive Phase A 加速 enhance + Phase B 非加速 enhance 候选
  //   - haste_enhance_ids 只对枚举的加速槽（锁定的 HAT/SHOES/远武 加速附魔保持用户设置）
  //   - enhance_candidates 含所有 WZC_PHASE_B_ATTRS 槽位的候选 ID；
  //     调用方按 per-slot 的 lockEnhance 子开关进一步过滤
  async function wzcDerivePhaseInputs(enumPositions) {
    const enumSet = new Set(enumPositions);
    const haste_enhance_ids = {};
    const enhance_candidates = {};

    // Phase A：加速槽 急速/加速 附魔（仅枚举槽）
    await Promise.all(WZC_HASTE_SLOTS.filter(p => enumSet.has(p)).map(async pos => {
      const list = await wzcGetEnhances(POS_TO_SUB[pos]);
      const best = wzcFindBestEnhance(list, WZC_HASTE_LABELS);
      if (best.length > 0) haste_enhance_ids[pos] = best[0].id;
    }));

    // Phase B：非加速槽偏导候选（含锁定槽；锁定槽的纳入由 per-slot lockEnhance 子开关决定）
    await Promise.all(Object.keys(WZC_PHASE_B_ATTRS).map(async pos => {
      const list = await wzcGetEnhances(POS_TO_SUB[pos]);
      const best = wzcFindBestEnhance(list, WZC_PHASE_B_ATTRS[pos]);
      if (best.length > 0) enhance_candidates[pos] = best.map(e => e.id);
    }));

    return { haste_enhance_ids, enhance_candidates };
  }

  // 渲染 1. 环境
  // ─── 环境覆盖：input/radio 当前值；fallback 跟随循环模拟页 ───────────
  // input 没初始化前（页面首次渲染） 用 fallback 值预填，之后保留用户修改。
  function getEnvValue(id, fallback) {
    const el = document.getElementById(id);
    if (!el) return fallback;
    const v = parseFloat(el.value);
    return Number.isFinite(v) ? v : fallback;
  }
  function getEnvEmbed() {
    const r = document.querySelector('input[name="wzc_embed"]:checked');
    return r ? parseInt(r.value, 10) || 6 : 6;
  }
  // 当前生效的 macro / talents / recipes（按 source 选）
  function getActiveLoopInputs() {
    if (state.env.source === 'import' && state.env.importedMacro != null) {
      return {
        macro_text: state.env.importedMacro || '',
        talents:    state.env.importedTalents || [],
        recipes:    state.env.importedRecipes || [],
      };
    }
    return {
      macro_text: (typeof buildMacroText === 'function') ? buildMacroText() : '',
      talents:    (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [],
      recipes:    (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [],
    };
  }

  function renderEnv() {
    const mountLabel = (currentMount?.mount_label || '—') + ' · ' + (currentMount?.version_label || '');
    document.getElementById('wzc_mount_label').textContent = mountLabel;

    // 首次进入：input 没值时用 fallback 预填；用户改过后不覆盖
    const tgt = (typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 };
    const dur = (typeof macroLastDuration !== 'undefined' && macroLastDuration > 0) ? macroLastDuration : 300;
    const fillIfEmpty = (id, val) => {
      const el = document.getElementById(id);
      if (el && (el.value === '' || el.value == null)) el.value = val;
    };
    fillIfEmpty('wzc_target_level', tgt.level);
    fillIfEmpty('wzc_duration',     dur);

    // 来源 + 已导入文件名（统一为按钮模式：默认跟随循环模拟，点 [导入存档] 弹 picker，
    // 选完后显示文件名 + [取消导入]）
    const labelEl  = document.getElementById('wzc_source_label');
    const pickBtn  = document.getElementById('wzc_import_pick');
    const clearBtn = document.getElementById('wzc_import_clear');
    const isImport = state.env.source === 'import' && !!state.env.importedFile;
    if (labelEl) {
      labelEl.textContent = isImport ? `已导入：${state.env.importedFile}` : '跟随循环模拟';
      labelEl.style.color = isImport ? 'var(--gold)' : '';
    }
    if (pickBtn)  pickBtn.style.display  = isImport ? 'none' : '';
    if (clearBtn) clearBtn.style.display = isImport ? '' : 'none';

    // 奇穴 / 秘籍计数（按当前 source 算）
    const act = getActiveLoopInputs();
    document.getElementById('wzc_tr_label').textContent = `${act.talents.length} 奇穴 / ${act.recipes.length} 秘籍`;

    // 团辅计数（走全局 _teamBuffSelections，跟主页面共享；importedConfig 暂不接入）
    const tbLabelEl = document.getElementById('wzc_tb_label');
    if (tbLabelEl) {
      const tbCount = (typeof getTeamBuffs === 'function') ? getTeamBuffs().length : 0;
      const tbOn = !!window._teamBuffsGlobalEnabled;
      tbLabelEl.textContent = tbOn ? `已启用 ${tbCount} 条` : '已启用 0 条（全局关闭）';
      tbLabelEl.style.color = tbOn ? '' : 'var(--text-muted)';
    }
  }

  // 加速档位三轴独立 chip + 多区间合并模型
  // state.hasteTiersMulti      = { 24: [...], 16: [...], 8: [...] } 三轴 tier 数据
  // state.selectedChipsByAxis  = { 24: Set<tier>, 16: ..., 8: ... } 每轴独立选中
  // state.hasteSegments        = [{min,max},...] 派生：所有选中 chip 的 [haste_min, haste_max] 排序+合并相邻/重叠
  //                              空数组 = 无段位约束（提交时不传 target_haste 限制）
  //   提交时 target_haste = state.hasteSegments（数组；后端 Vec<HasteRange>）

  function _hasteAxisTiers(orig) {
    return state.hasteTiersMulti?.[orig] || [];
  }

  function _findTier(orig, tier) {
    return _hasteAxisTiers(orig).find(t => t.tier === tier);
  }

  // 全局临界点：三轴 haste_min ∪ {0, cap+1哨兵}，去重排序
  function _hasteCriticalPoints() {
    const cap = state.hasteCap || 100000;
    const set = new Set([0, cap + 1]);
    for (const orig of [24, 16, 8]) {
      for (const t of _hasteAxisTiers(orig)) {
        if (t.haste_min <= cap) set.add(t.haste_min);
      }
    }
    return Array.from(set).sort((a, b) => a - b);
  }

  // 每个选中的 chip → 全局微段 [haste_min, 下一个全局临界点 - 1]
  // 多个微段排序合并相邻/重叠 → hasteSegments
  function recomputeHasteRange() {
    const cap = state.hasteCap || 100000;
    const points = _hasteCriticalPoints();
    const intervals = [];
    for (const orig of [24, 16, 8]) {
      for (const tier of state.selectedChipsByAxis[orig]) {
        const t = _findTier(orig, tier);
        if (!t) continue;
        const idx = points.indexOf(t.haste_min);
        const nextPoint = (idx >= 0 && idx + 1 < points.length) ? points[idx + 1] : (cap + 1);
        const max = Math.min(cap, nextPoint - 1);
        intervals.push({ min: t.haste_min, max });
      }
    }
    if (intervals.length === 0) {
      state.hasteSegments = [];
      return;
    }
    intervals.sort((a, b) => a.min - b.min || a.max - b.max);
    const merged = [{ ...intervals[0] }];
    for (let i = 1; i < intervals.length; i++) {
      const last = merged[merged.length - 1];
      const cur = intervals[i];
      if (cur.min <= last.max + 1) last.max = Math.max(last.max, cur.max);
      else merged.push({ ...cur });
    }
    state.hasteSegments = merged;
  }

  function toggleChip(orig, tier) {
    const sel = state.selectedChipsByAxis[orig];
    if (sel.has(tier)) sel.delete(tier);
    else sel.add(tier);
    recomputeHasteRange();
    refreshHasteSlider();
  }

  function selectAllChips() {
    for (const orig of [24, 16, 8]) {
      for (const t of _hasteAxisTiers(orig)) state.selectedChipsByAxis[orig].add(t.tier);
    }
    recomputeHasteRange();
    refreshHasteSlider();
  }

  function clearAllChips() {
    for (const orig of [24, 16, 8]) state.selectedChipsByAxis[orig].clear();
    recomputeHasteRange();
    refreshHasteSlider();
  }

  // 同步该 haste 位置的三轴：把所有 haste_min === haste 的 chip 一起 toggle
  // 全部已选 → 全部取消；否则 → 全部加入
  function syncHasteAtPoint(haste_min) {
    const targets = [];
    for (const orig of [24, 16, 8]) {
      for (const t of _hasteAxisTiers(orig)) {
        if (t.haste_min === haste_min) targets.push([orig, t.tier]);
      }
    }
    if (targets.length === 0) return;
    const allSelected = targets.every(([orig, tier]) => state.selectedChipsByAxis[orig].has(tier));
    for (const [orig, tier] of targets) {
      if (allSelected) state.selectedChipsByAxis[orig].delete(tier);
      else state.selectedChipsByAxis[orig].add(tier);
    }
    recomputeHasteRange();
    refreshHasteSlider();
  }

  // 找出"≥2 轴共享"的 haste_min（含三轴皆有），渲染对应的同步小按钮
  function renderHasteSyncButtons() {
    const cap = state.hasteCap || 100000;
    const positions = _hasteComputePositions();
    const countByHaste = new Map();
    for (const orig of [24, 16, 8]) {
      for (const t of _hasteAxisTiers(orig)) {
        countByHaste.set(t.haste_min, (countByHaste.get(t.haste_min) || 0) + 1);
      }
    }
    const line = document.querySelector('.wzc-haste-sync-line');
    if (!line) return;
    line.innerHTML = '';
    for (const [h, n] of countByHaste) {
      if (n < 2 || h > cap) continue;
      const btn = document.createElement('div');
      btn.className = 'wzc-haste-sync-btn';
      btn.textContent = '↕';
      btn.dataset.hasteMin = String(h);
      btn.dataset.tbTip = `同步 haste = ${h} 三轴上的 ${n} 个段位（已全选则全取消）`;
      const pct = positions.get(h) ?? (h / cap * 100);
      btn.style.left = pct + '%';
      if (pct <= 2) btn.style.transform = 'translate(0, -50%)';
      else if (pct >= 98) btn.style.transform = 'translate(-100%, -50%)';
      btn.addEventListener('click', () => syncHasteAtPoint(h));
      btn.addEventListener('mouseenter', () => showTooltip(btn, btn.dataset.tbTip));
      btn.addEventListener('mouseleave', hideTooltip);
      line.appendChild(btn);
    }
  }

  async function loadHasteTiers() {
    try {
      const r = await fetch('/api/equip/haste_tiers'); // 默认返回 24+16
      if (!r.ok) return;
      const j = await r.json();
      const r8 = await fetch('/api/equip/haste_tiers?original_frames=8');
      const j8 = r8.ok ? await r8.json() : { tiers: [] };
      state.hasteCap = j.haste_cap || 100000;
      const find = (orig) => j.by_base_frames?.find(b => b.original_frames === orig)?.tiers || [];
      state.hasteTiersMulti = {
        24: find(24),
        16: find(16),
        8: j8.tiers || [],
      };
      // 收集 snap 点
      const minSet = new Set([0]);
      const maxSet = new Set([state.hasteCap]);
      for (const orig of [24, 16, 8]) {
        for (const t of state.hasteTiersMulti[orig]) {
          minSet.add(t.haste_min);
          maxSet.add(t.haste_max);
        }
      }
      state.hasteSnapMin = Array.from(minSet).sort((a, b) => a - b);
      state.hasteSnapMax = Array.from(maxSet).sort((a, b) => a - b);
      // 默认选 1.5s 2 段
      state.selectedChipsByAxis = { 24: new Set(), 16: new Set(), 8: new Set() };
      if (state.hasteTiersMulti[24].some(t => t.tier === 2)) {
        state.selectedChipsByAxis[24].add(2);
      }
      recomputeHasteRange();
      renderHasteTicks();
      renderHasteSyncButtons();
      refreshHasteSlider();
      const bindOnce = (id, fn) => {
        const el = document.getElementById(id);
        if (el && !el._wzcBound) { el._wzcBound = true; el.addEventListener('click', fn); }
      };
      bindOnce('wzc_haste_select_all', selectAllChips);
      bindOnce('wzc_haste_clear_all',  clearAllChips);
    } catch (e) { console.warn('haste tiers 拉取失败', e); }
  }

  // chip 位置计算：每段 haste_min ∪ {0, cap}（不含 haste_max，避免相邻 dot 紧贴）
  function _hasteComputePositions() {
    const cap = state.hasteCap || 100000;
    const MIN_GAP_PCT = 6;
    const points = Array.from(new Set([0, cap, ...(state.hasteSnapMin || [])]))
      .filter(v => v <= cap && v >= 0)
      .sort((a, b) => a - b);
    let lastPct = -100;
    const map = new Map();
    for (const haste of points) {
      let pct = haste / cap * 100;
      if (pct < lastPct + MIN_GAP_PCT) pct = lastPct + MIN_GAP_PCT;
      if (pct > 100) pct = 100;
      lastPct = pct;
      map.set(haste, pct);
    }
    state.hasteSnapMap = map;
    state.hasteSnapDots = Array.from(map.keys()).sort((a, b) => a - b);
    return map;
  }

  function renderHasteTicks() {
    const cap = state.hasteCap || 100000;
    const positions = _hasteComputePositions();
    // 段位号大写汉字映射
    const CN_TIER = ['零', '壹', '贰', '叁', '肆', '伍', '陆', '柒', '捌', '玖'];
    const tierLabel = (n) => (n >= 0 && n < CN_TIER.length) ? CN_TIER[n] : String(n);
    for (const orig of [24, 16, 8]) {
      const line = document.querySelector(`.wzc-haste-tick-line[data-row="${orig}"]`);
      if (!line) continue;
      const tiers = state.hasteTiersMulti[orig] || [];
      line.innerHTML = '';
      for (const t of tiers) {
        if (t.haste_min > cap) continue;
        const chip = document.createElement('div');
        chip.className = 'wzc-haste-tick';
        const pct = positions.get(t.haste_min) ?? (t.haste_min / cap * 100);
        chip.style.left = pct + '%';
        if (pct <= 2) chip.style.transform = 'translate(0, -50%)';
        else if (pct >= 98) chip.style.transform = 'translate(-100%, -50%)';
        chip.textContent = t.tier === 0 ? '零' : `${tierLabel(t.tier)} · ${t.haste_min}`;
        chip.dataset.axisOrig = String(orig);
        chip.dataset.tier = String(t.tier);
        chip.dataset.hasteMin = t.haste_min;
        chip.dataset.tbTip = `${t.tier} 段 · ${t.actual_frames}帧 · GCD ${t.actual_seconds.toFixed(4)}s<br>haste ∈ [${t.haste_min}, ${Math.min(t.haste_max, cap)}]`;
        chip.addEventListener('click', () => toggleChip(orig, t.tier));
        chip.addEventListener('mouseenter', () => showTooltip(chip, chip.dataset.tbTip));
        chip.addEventListener('mouseleave', hideTooltip);
        line.appendChild(chip);
      }
    }
  }

  function refreshHasteSlider() {
    const cap = state.hasteCap || 100000;
    const positions = state.hasteSnapMap || _hasteComputePositions();
    const dots = state.hasteSnapDots || [];
    const pctOf = (h) => positions.get(h) ?? (h / cap * 100);
    // 区间显示
    const segs = state.hasteSegments || [];
    const segText = document.getElementById('wzc_haste_segments');
    if (segText) {
      segText.textContent = segs.length === 0
        ? '无段位约束（任意 haste）'
        : segs.map(s => `[${s.min}, ${s.max}]`).join(', ');
    }
    // 选中区间色块：每个 hasteSegment 一个；位置按 pct，宽度到 next 临界点的 pct
    const fillsContainer = document.querySelector('.wzc-haste-range-fills');
    if (fillsContainer) {
      fillsContainer.innerHTML = '';
      for (const seg of segs) {
        const fill = document.createElement('div');
        fill.className = 'wzc-haste-range-fill';
        const lPct = pctOf(seg.min);
        const nextH = dots.find(h => h > seg.max) ?? cap;
        const rPct = pctOf(nextH);
        fill.style.left = lPct + '%';
        fill.style.width = Math.max(0, rPct - lPct) + '%';
        fillsContainer.appendChild(fill);
      }
    }
    // chip 高亮：每个 chip 仅按自己轴的 selectedChipsByAxis 决定
    document.querySelectorAll('.wzc-haste-tick').forEach(chip => {
      const orig = parseInt(chip.dataset.axisOrig);
      const tier = parseInt(chip.dataset.tier);
      const sel = state.selectedChipsByAxis[orig];
      chip.classList.toggle('wzc-haste-tick-selected', !!sel && sel.has(tier));
    });
  }

  // 候选池：从配装器同步当前装备 + 给每部位拉 top N 候选
  // 当 source==='import' 且导入了 plaza 方案的装备时，"当前装备"列以导入方案为准；
  // 否则用配装器（Jx3Equip.getCurrentConfig）。perSlot 的 lock/enum / 候选池配置不动。
  function _wzcActiveCfg() {
    const imp = (state.env?.source === 'import' && state.env?.importedEquipment) ? state.env.importedEquipment : null;
    const base = imp || window.Jx3Equip?.getCurrentConfig?.() || null;
    if (!base) return null;
    const overrides = state.slotOverrides || {};
    const posKeys = Object.keys(overrides);
    if (posKeys.length === 0) return base;
    // 浅拷贝 cfg + slots，避免污染原引用（getCurrentConfig 返回的是配装器内部对象）
    const cloned = { ...base, slots: { ...(base.slots || {}) } };
    for (const pos of posKeys) {
      const ov = overrides[pos];
      if (!ov || !Number.isFinite(ov.equip_id)) continue;
      const orig = cloned.slots[pos] || {};
      // 默认场景（单件切换 picker）：只覆 base item，附魔保留 orig
      // 「结果卡 → 应用为基线」会把搜出来的 enchant_id / enhance_id 也写到 override，此时一并覆盖
      cloned.slots[pos] = {
        ...orig,
        equip_id: ov.equip_id,
        name: ov.name || orig.name,
        level: ov.level != null ? ov.level : orig.level,
        set_id: ov.set_id != null ? ov.set_id : orig.set_id,
        set_name: ov.set_name != null ? ov.set_name : orig.set_name,
        belong_school: ov.belong_school != null ? ov.belong_school : orig.belong_school,
        magic_kind: ov.magic_kind != null ? ov.magic_kind : orig.magic_kind,
        ...(ov.enchant_id != null ? { enchant_id: ov.enchant_id } : {}),
        ...(ov.enhance_id != null ? { enhance_id: ov.enhance_id } : {}),
      };
    }
    return cloned;
  }
  // 清空所有覆盖（数据源切换 / 顶部"清空覆盖"按钮调）
  function clearSlotOverrides() {
    state.slotOverrides = {};
    saveWzcState();
    syncCurrentEquip();
    renderCandsTable();
    updateOverridesToolbar();
  }
  // 更新"清空覆盖"按钮可见性（仅 overrides 非空时显示）
  function updateOverridesToolbar() {
    const btn = document.getElementById('wzc_clear_overrides');
    if (!btn) return;
    const n = Object.keys(state.slotOverrides || {}).length;
    btn.style.display = n > 0 ? '' : 'none';
    btn.title = n > 0 ? `清空 ${n} 件手动切换的"当前装备"，全部恢复主源` : '';
  }
  function syncCurrentEquip() {
    const cfg = _wzcActiveCfg();
    if (!cfg) return;
    POS_LIST.forEach(pos => {
      const slot = cfg.slots?.[pos];
      state.perSlot[pos].currentId = slot?.equip_id || null;
      state.perSlot[pos].currentName = slot?.name || '';
    });
  }

  async function fetchCandsForSlot(pos) {
    const ps = state.perSlot[pos];
    if (!ps.filter) ps.filter = defaultFilterFor(pos);
    const body = filterToBody(ps.filter, pos);
    try {
      const r = await fetch('/api/equip/search', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!r.ok) return [];
      let items = await r.json();
      if (ps.filter.only_set) items = items.filter(it => it.set_id && it.set_id > 0);
      // 应用用户剔除
      const ex = ps.excluded || new Set();
      if (ex.size > 0) items = items.filter(it => !ex.has(it.id));
      return items;
    } catch { return []; }
  }

  // 加载装备元数据（schools / kinds chips 数据源）
  async function loadWzcMeta() {
    if (state.meta.schools.length > 0) return;
    try {
      const r = await fetch('/api/equip/meta');
      if (!r.ok) return;
      const j = await r.json();
      state.meta.schools = j.schools || [];
      state.meta.kinds = j.kinds || [];
    } catch (e) { console.warn('wzc meta 拉取失败', e); }
  }

  // ─── Filter Modal ───────────────────────────────────────────────────
  // 打开时显示当前 pos 的 filter；保存到 ps.filter；触发候选刷新。
  let _wzcFmCurrentPos = null;
  let _wzcFmDraft = null;          // 编辑中的临时 filter（取消则丢弃）
  let _wzcFmPreviewTimer = null;   // 防抖 preview

  async function openFilterModal(pos) {
    await loadWzcMeta();
    _wzcFmCurrentPos = pos;
    const ps = state.perSlot[pos];
    if (!ps.filter) ps.filter = defaultFilterFor(pos);
    if (!ps.excluded) ps.excluded = new Set();
    // 直接引用 state（auto-save 模型 —— 改一下立即写回 + localStorage 持久化）
    // _wzcFmDraft 仍以 filter 字段为主，外加 excluded 别名指向 state.perSlot[pos].excluded
    _wzcFmDraft = ps.filter;
    _wzcFmDraft.excluded = ps.excluded;
    document.getElementById('wzc_fm_pos_label').textContent = `${POS_LABEL[pos]} (${pos})`;
    renderFilterModal();
    document.getElementById('wzc_filter_modal').style.display = 'flex';
    refreshFilterPreview();
  }

  // 关闭 modal —— auto-save 已生效，关闭时按当前 filter 重抓该部位候选并刷新行
  async function closeFilterModal() {
    document.getElementById('wzc_filter_modal').style.display = 'none';
    const pos = _wzcFmCurrentPos;
    _wzcFmCurrentPos = null;
    if (_wzcFmDraft) delete _wzcFmDraft.excluded;  // 拆掉别名，filter 不带 excluded 字段
    _wzcFmDraft = null;
    if (pos) {
      await refreshCandsForSlot(pos);
      renderCandsTable();
    }
  }

  // 把 _wzcFmDraft 同步到 modal DOM（chips active / inputs）
  function renderFilterModal() {
    const f = _wzcFmDraft;
    if (!f) return;
    // 品级双滑条：max_level=0 表示无上限，对应右端
    const lo = Math.max(WZC_FM_LEVEL_MIN, Math.min(WZC_FM_LEVEL_MAX, f.min_level || WZC_FM_LEVEL_MIN));
    const hi = (f.max_level && f.max_level > 0) ? Math.max(WZC_FM_LEVEL_MIN, Math.min(WZC_FM_LEVEL_MAX, f.max_level)) : WZC_FM_LEVEL_MAX;
    document.getElementById('wzc_fm_min_level').value = lo;
    document.getElementById('wzc_fm_max_level').value = hi;
    syncWzcFmRange();
    document.getElementById('wzc_fm_keyword').value = f.keyword || '';
    document.getElementById('wzc_fm_only_set').checked = !!f.only_set;
    // schools chips
    const schoolBox = document.getElementById('wzc_fm_schools');
    const schoolOrder = ['通用', '精简', '无修', '苍云', '天策', '少林', '明教'];
    const schools = [...state.meta.schools].filter(s => s && s !== '——').sort((a, b) => {
      const ia = schoolOrder.indexOf(a), ib = schoolOrder.indexOf(b);
      if (ia === -1 && ib === -1) return a.localeCompare(b);
      if (ia === -1) return 1;
      if (ib === -1) return -1;
      return ia - ib;
    });
    schoolBox.innerHTML = schools.map(s =>
      `<button class="eq-chip${f.schools.has(s) ? ' active' : ''}" data-school="${escapeHtml(s)}">${escapeHtml(s)}</button>`
    ).join('') || '<span class="wzc-hint">（meta 未加载）</span>';
    // kinds chips
    const kindBox = document.getElementById('wzc_fm_kinds');
    const kinds = [...state.meta.kinds].filter(k => k && k !== '——' && k !== '通用');
    kindBox.innerHTML = kinds.map(k =>
      `<button class="eq-chip${f.kinds.has(k) ? ' active' : ''}" data-kind="${escapeHtml(k)}">${escapeHtml(k)}</button>`
    ).join('') || '<span class="wzc-hint">（meta 未加载）</span>';
    // attrs / battle / categories 已固定写在 HTML，只需同步 active
    document.querySelectorAll('#wzc_fm_attrs .eq-chip').forEach(btn => {
      btn.classList.toggle('active', f.attrs.has(btn.dataset.attr));
    });
    document.querySelectorAll('#wzc_fm_battle .eq-chip').forEach(btn => {
      btn.classList.toggle('active', f.battle_types.has(btn.dataset.battle));
    });
    if (!f.categories) f.categories = new Set();
    document.querySelectorAll('#wzc_fm_categories .eq-chip').forEach(btn => {
      btn.classList.toggle('active', f.categories.has(btn.dataset.cat));
    });
    // 绑事件
    schoolBox.querySelectorAll('.eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        const s = btn.dataset.school;
        if (f.schools.has(s)) f.schools.delete(s); else f.schools.add(s);
        btn.classList.toggle('active');
        scheduleFilterPreview();
      });
    });
    kindBox.querySelectorAll('.eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        const k = btn.dataset.kind;
        if (f.kinds.has(k)) f.kinds.delete(k); else f.kinds.add(k);
        btn.classList.toggle('active');
        scheduleFilterPreview();
      });
    });
  }

  // 任何 filter / excluded 改动都走这里 → 自动持久化 + 防抖刷预览
  function scheduleFilterPreview() {
    saveWzcState();
    if (_wzcFmPreviewTimer) clearTimeout(_wzcFmPreviewTimer);
    _wzcFmPreviewTimer = setTimeout(refreshFilterPreview, 250);
  }

  // 双滑条同步：clamp + 计算 fill 区间 + 写回 _wzcFmDraft
  function syncWzcFmRange() {
    if (!_wzcFmDraft) return;
    const minEl = document.getElementById('wzc_fm_min_level');
    const maxEl = document.getElementById('wzc_fm_max_level');
    const fill  = document.getElementById('wzc_fm_range_fill');
    const minLab = document.getElementById('wzc_fm_min_level_val');
    const maxLab = document.getElementById('wzc_fm_max_level_val');
    if (!minEl || !maxEl || !fill) return;
    let lo = parseInt(minEl.value, 10);
    let hi = parseInt(maxEl.value, 10);
    if (!Number.isFinite(lo)) lo = WZC_FM_LEVEL_MIN;
    if (!Number.isFinite(hi)) hi = WZC_FM_LEVEL_MAX;
    if (lo > hi) { [lo, hi] = [hi, lo]; minEl.value = lo; maxEl.value = hi; }
    minLab.textContent = lo;
    maxLab.textContent = (hi >= WZC_FM_LEVEL_MAX) ? `${hi}+` : hi;
    const span = WZC_FM_LEVEL_MAX - WZC_FM_LEVEL_MIN;
    const leftPct  = ((lo - WZC_FM_LEVEL_MIN) / span) * 100;
    const rightPct = ((WZC_FM_LEVEL_MAX - hi) / span) * 100;
    fill.style.left  = leftPct  + '%';
    fill.style.right = rightPct + '%';
    _wzcFmDraft.min_level = lo;
    // 滑条到顶端时存 0（"不限上限"），方便后端跳过 max_level 过滤
    _wzcFmDraft.max_level = (hi >= WZC_FM_LEVEL_MAX) ? 0 : hi;
  }

  async function refreshFilterPreview() {
    if (!_wzcFmCurrentPos || !_wzcFmDraft) return;
    const listEl = document.getElementById('wzc_fm_preview_list');
    const cntEl = document.getElementById('wzc_fm_preview_count');
    listEl.textContent = '查询中…';
    const body = filterToBody(_wzcFmDraft, _wzcFmCurrentPos);
    try {
      const r = await fetch('/api/equip/search', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!r.ok) { listEl.textContent = `请求失败 (HTTP ${r.status})`; cntEl.textContent = ''; return; }
      let items = await r.json();
      if (_wzcFmDraft.only_set) items = items.filter(it => it.set_id && it.set_id > 0);
      const matched = items.length;
      const ex = _wzcFmDraft.excluded;
      const enabledCount = items.filter(it => !ex.has(it.id)).length;
      cntEl.innerHTML = `匹配 <b>${matched}</b> 件 · 启用 <b style="color:var(--gold)">${enabledCount}</b>${ex.size > 0 ? ` · <span style="color:var(--warning)">剔除 ${ex.size}</span>` : ''}`;
      const top = items.slice(0, 60);
      if (top.length === 0) {
        listEl.innerHTML = '<span class="wzc-hint">无匹配</span>';
      } else {
        listEl.innerHTML = `
          <div class="wzc-fm-preview-toolbar">
            <button class="sim-btn wzc-mini-btn" id="wzc_fm_select_all">全部启用</button>
            <button class="sim-btn wzc-mini-btn" id="wzc_fm_select_none">全部剔除</button>
            <span class="wzc-hint">勾掉的装备不会进候选池（仅本部位）${matched > 60 ? ` · 列表截前 60 件，匹配总 ${matched}` : ''}</span>
          </div>
          ${top.map(it => {
            const checked = !ex.has(it.id);
            return `
              <label class="wzc-fm-preview-item${checked ? '' : ' excluded'}">
                <input type="checkbox" data-eid="${it.id}" ${checked ? 'checked' : ''}>
                <span class="wzc-fm-preview-name">${escapeHtml(it.name || ('#' + it.id))}</span>
                <span class="wzc-fm-preview-tag">Lv${it.level || '?'} · ${escapeHtml(it.belong_school || '')} ${escapeHtml(it.magic_kind || '')}${it.set_id ? ` · 套装${it.set_name ? '「'+escapeHtml(it.set_name)+'」' : ''}` : ''}</span>
              </label>
            `;
          }).join('')}
        `;
        // 绑事件
        listEl.querySelectorAll('input[type="checkbox"][data-eid]').forEach(cb => {
          cb.addEventListener('change', () => {
            const eid = parseInt(cb.dataset.eid, 10);
            if (cb.checked) ex.delete(eid); else ex.add(eid);
            cb.closest('.wzc-fm-preview-item').classList.toggle('excluded', !cb.checked);
            // 仅刷新计数，不重拉
            const newEnabled = items.filter(it => !ex.has(it.id)).length;
            cntEl.innerHTML = `匹配 <b>${matched}</b> 件 · 启用 <b style="color:var(--gold)">${newEnabled}</b>${ex.size > 0 ? ` · <span style="color:var(--warning)">剔除 ${ex.size}</span>` : ''}`;
          });
        });
        // 装备 hover：show tooltip with item details（用 Jx3Equip 公共 API）
        listEl.querySelectorAll('.wzc-fm-preview-item').forEach((label, i) => {
          const it = top[i];
          if (!it || !_wzcFmCurrentPos) return;
          label.style.cursor = 'help';
          label.addEventListener('mouseenter', () => {
            wzcShowHover(label,
              window.Jx3Equip?.buildItemTooltip?.(_wzcFmCurrentPos, { equip_id: it.id }) || '',
              true);
          });
          label.addEventListener('mouseleave', wzcHideHover);
        });
        document.getElementById('wzc_fm_select_all').addEventListener('click', () => {
          for (const it of items) ex.delete(it.id);
          refreshFilterPreview();
        });
        document.getElementById('wzc_fm_select_none').addEventListener('click', () => {
          for (const it of items) ex.add(it.id);
          refreshFilterPreview();
        });
      }
    } catch (e) {
      listEl.textContent = '网络错误';
      cntEl.textContent = '';
    }
  }

  // attrs / battle / 文本 input / 重置 / 取消 / 应用 / 应用所有 —— 一次性绑定
  function initFilterModalEvents() {
    document.getElementById('wzc_fm_close').addEventListener('click', closeFilterModal);
    // 点 overlay 空白处（不是 panel 内）也关闭
    document.getElementById('wzc_filter_modal').addEventListener('click', e => {
      if (e.target.id === 'wzc_filter_modal') closeFilterModal();
    });
    // ESC 关闭
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && _wzcFmCurrentPos) closeFilterModal();
    });

    document.querySelectorAll('#wzc_fm_attrs .eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!_wzcFmDraft) return;
        const a = btn.dataset.attr;
        if (_wzcFmDraft.attrs.has(a)) _wzcFmDraft.attrs.delete(a); else _wzcFmDraft.attrs.add(a);
        btn.classList.toggle('active');
        scheduleFilterPreview();
      });
    });
    document.querySelectorAll('#wzc_fm_battle .eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!_wzcFmDraft) return;
        const b = btn.dataset.battle;
        if (_wzcFmDraft.battle_types.has(b)) _wzcFmDraft.battle_types.delete(b);
        else _wzcFmDraft.battle_types.add(b);
        btn.classList.toggle('active');
        scheduleFilterPreview();
      });
    });
    document.querySelectorAll('#wzc_fm_categories .eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!_wzcFmDraft) return;
        if (!_wzcFmDraft.categories) _wzcFmDraft.categories = new Set();
        const c = btn.dataset.cat;
        if (_wzcFmDraft.categories.has(c)) _wzcFmDraft.categories.delete(c);
        else _wzcFmDraft.categories.add(c);
        btn.classList.toggle('active');
        scheduleFilterPreview();
      });
    });
    // 全选/全不选：作用于所有筛选 chip（schools/kinds/attrs/battle/categories）。
    // schools/kinds chip 由 renderFilterModal 按 meta 动态生成，DOM 内查询即可。
    document.getElementById('wzc_fm_filter_all').addEventListener('click', () => {
      if (!_wzcFmDraft) return;
      if (!_wzcFmDraft.categories) _wzcFmDraft.categories = new Set();
      document.querySelectorAll('#wzc_fm_schools .eq-chip').forEach(btn => {
        _wzcFmDraft.schools.add(btn.dataset.school); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_fm_kinds .eq-chip').forEach(btn => {
        _wzcFmDraft.kinds.add(btn.dataset.kind); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_fm_attrs .eq-chip').forEach(btn => {
        _wzcFmDraft.attrs.add(btn.dataset.attr); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_fm_battle .eq-chip').forEach(btn => {
        _wzcFmDraft.battle_types.add(btn.dataset.battle); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_fm_categories .eq-chip').forEach(btn => {
        _wzcFmDraft.categories.add(btn.dataset.cat); btn.classList.add('active');
      });
      scheduleFilterPreview();
    });
    document.getElementById('wzc_fm_filter_none').addEventListener('click', () => {
      if (!_wzcFmDraft) return;
      if (!_wzcFmDraft.categories) _wzcFmDraft.categories = new Set();
      _wzcFmDraft.schools.clear();
      _wzcFmDraft.kinds.clear();
      _wzcFmDraft.attrs.clear();
      _wzcFmDraft.battle_types.clear();
      _wzcFmDraft.categories.clear();
      document.querySelectorAll('#wzc_fm_schools .eq-chip, #wzc_fm_kinds .eq-chip, #wzc_fm_attrs .eq-chip, #wzc_fm_battle .eq-chip, #wzc_fm_categories .eq-chip').forEach(btn => btn.classList.remove('active'));
      scheduleFilterPreview();
    });

    // 品级双滑条 —— 同步 fill + 写回 _wzcFmDraft（max=44000 时存 0 表示"不限上限"）
    ['wzc_fm_min_level', 'wzc_fm_max_level'].forEach(id => {
      document.getElementById(id).addEventListener('input', () => {
        syncWzcFmRange();
        scheduleFilterPreview();
      });
    });
    document.getElementById('wzc_fm_keyword').addEventListener('input', e => {
      if (_wzcFmDraft) _wzcFmDraft.keyword = e.target.value;
      scheduleFilterPreview();
    });
    document.getElementById('wzc_fm_only_set').addEventListener('change', e => {
      if (_wzcFmDraft) _wzcFmDraft.only_set = e.target.checked;
      scheduleFilterPreview();
    });

    document.getElementById('wzc_fm_reset').addEventListener('click', () => {
      if (!_wzcFmCurrentPos) return;
      // 直接覆盖 state（auto-save 模型）：filter 回默认、excluded 清空
      const def = defaultFilterFor(_wzcFmCurrentPos);
      state.perSlot[_wzcFmCurrentPos].filter = def;
      state.perSlot[_wzcFmCurrentPos].excluded = new Set();
      _wzcFmDraft = def;
      _wzcFmDraft.excluded = state.perSlot[_wzcFmCurrentPos].excluded;
      renderFilterModal();
      scheduleFilterPreview();
    });

    // ✓ 完成 —— auto-save 已生效，直接关闭（关闭时 closeFilterModal 会刷新该部位候选）
    document.getElementById('wzc_fm_apply').addEventListener('click', () => {
      closeFilterModal();
    });
    // 📋 同步到所有部位 —— 把当前 filter（不含 excluded）下发到所有部位
    document.getElementById('wzc_fm_apply_all').addEventListener('click', async () => {
      if (!_wzcFmDraft) return;
      const f = _wzcFmDraft;
      for (const pos of POS_LIST) {
        if (pos === _wzcFmCurrentPos) continue;  // 当前部位已经是 f 本身
        state.perSlot[pos].filter = {
          min_level: f.min_level, max_level: f.max_level,
          schools: new Set(f.schools), kinds: new Set(f.kinds),
          attrs: new Set(f.attrs), battle_types: new Set(f.battle_types),
          keyword: f.keyword, only_set: !!f.only_set,
        };
      }
      saveWzcState();
      closeFilterModal();
      await refreshAllCands();
      renderCandsTable();
    });
  }
  initFilterModalEvents();

  // ─── Slot Picker Modal（候选池第二列点击触发，单选切换"当前装备"覆盖）─────────
  // 只覆盖 base item；ENCHANT_* / 镶嵌沿用主源（_wzcActiveCfg 在合并时保留这些字段）。
  // 筛选条件用独立 draft（_wzcPkFilter），不写回 ps.filter（避免污染候选池搜索）。
  // 数据源切换 / 用户点"清空覆盖"会清掉 state.slotOverrides。
  let _wzcPkCurrentPos = null;
  let _wzcPkItems = [];       // 已拉到的装备列表（按 _wzcPkFilter 筛过，前端再按关键字 / only_orange 过滤）
  let _wzcPkFilter = null;    // 独立 filter draft（picker 内部专用）
  let _wzcPkRefetchTimer = null;
  let _wzcPkSort = { key: 'dps_delta', dir: 'desc' };   // 默认按 DPS Δ 倒序
  let _wzcPkDpsCache = new Map();          // equip_id → dps（本次 picker 打开周期内有效；切 pos 清空）
  let _wzcPkBaselineDps = null;            // 基线 dps = lastSimResult.dps（首次跑 picker 时锁定）
  let _wzcPkDpsBatchToken = 0;             // batch token：切 pos / refetch / 关闭时递增，丢弃在途

  function _wzcPkCloneFilter(f) {
    return {
      min_level: f.min_level | 0,
      max_level: f.max_level | 0,
      schools: new Set(f.schools),
      kinds:   new Set(f.kinds),
      attrs:   new Set(f.attrs),
      battle_types: new Set(f.battle_types),
      keyword: '',
      only_set: !!f.only_set,
      only_orange: false,                // 仅在 picker 内部用，不来自候选池筛选
      categories: new Set(f.categories || []),
    };
  }

  async function openSlotPicker(pos) {
    await loadWzcMeta();
    _wzcPkCurrentPos = pos;
    // 切 pos 清空 dps cache + 取消在途 batch（每个 picker 周期 cache 独立）
    _wzcPkDpsCache.clear();
    _wzcPkBaselineDps = null;
    _wzcPkDpsBatchToken++;
    document.getElementById('wzc_pk_pos_label').textContent = `${POS_LABEL[pos]} (${pos})`;
    const kwEl = document.getElementById('wzc_pk_keyword');
    if (kwEl) kwEl.value = '';
    const onlyOrangeEl = document.getElementById('wzc_pk_only_orange');
    if (onlyOrangeEl) onlyOrangeEl.checked = false;
    // 复制 ps.filter 作为 picker draft 初始值（不修改 ps.filter）
    const ps = state.perSlot[pos];
    if (!ps.filter) ps.filter = defaultFilterFor(pos);
    _wzcPkFilter = _wzcPkCloneFilter(ps.filter);
    _wzcPkRenderFilter();
    document.getElementById('wzc_pk_count').textContent = '查询中…';
    document.getElementById('wzc_pk_empty').textContent = '查询中…';
    document.getElementById('wzc_pk_empty').style.display = '';
    document.getElementById('wzc_pk_table').style.display = 'none';
    document.getElementById('wzc_picker_modal').style.display = 'flex';
    await _wzcPkRefetch();
  }

  // 把 _wzcPkFilter 同步到 modal DOM（chips active / inputs / slider），并绑定 chip 点击
  function _wzcPkRenderFilter() {
    const f = _wzcPkFilter;
    if (!f) return;
    // 品级滑条
    const lo = Math.max(WZC_FM_LEVEL_MIN, Math.min(WZC_FM_LEVEL_MAX, f.min_level || WZC_FM_LEVEL_MIN));
    const hi = (f.max_level && f.max_level > 0) ? Math.max(WZC_FM_LEVEL_MIN, Math.min(WZC_FM_LEVEL_MAX, f.max_level)) : WZC_FM_LEVEL_MAX;
    document.getElementById('wzc_pk_min_level').value = lo;
    document.getElementById('wzc_pk_max_level').value = hi;
    _wzcPkSyncRange();
    document.getElementById('wzc_pk_only_set').checked = !!f.only_set;
    document.getElementById('wzc_pk_only_orange').checked = !!f.only_orange;
    // schools chips（动态生成）
    const schoolBox = document.getElementById('wzc_pk_schools');
    const schoolOrder = ['通用', '精简', '无修', '苍云', '天策', '少林', '明教'];
    const schools = [...state.meta.schools].filter(s => s && s !== '——').sort((a, b) => {
      const ia = schoolOrder.indexOf(a), ib = schoolOrder.indexOf(b);
      if (ia === -1 && ib === -1) return a.localeCompare(b);
      if (ia === -1) return 1;
      if (ib === -1) return -1;
      return ia - ib;
    });
    schoolBox.innerHTML = schools.map(s =>
      `<button class="eq-chip${f.schools.has(s) ? ' active' : ''}" data-school="${escapeHtml(s)}">${escapeHtml(s)}</button>`
    ).join('') || '<span class="wzc-hint">（meta 未加载）</span>';
    // kinds chips（动态生成）
    const kindBox = document.getElementById('wzc_pk_kinds');
    const kinds = [...state.meta.kinds].filter(k => k && k !== '——' && k !== '通用');
    kindBox.innerHTML = kinds.map(k =>
      `<button class="eq-chip${f.kinds.has(k) ? ' active' : ''}" data-kind="${escapeHtml(k)}">${escapeHtml(k)}</button>`
    ).join('') || '<span class="wzc-hint">（meta 未加载）</span>';
    // 静态 chips 的 active 同步
    document.querySelectorAll('#wzc_pk_attrs .eq-chip').forEach(btn => {
      btn.classList.toggle('active', f.attrs.has(btn.dataset.attr));
    });
    document.querySelectorAll('#wzc_pk_battle .eq-chip').forEach(btn => {
      btn.classList.toggle('active', f.battle_types.has(btn.dataset.battle));
    });
    document.querySelectorAll('#wzc_pk_categories .eq-chip').forEach(btn => {
      btn.classList.toggle('active', f.categories.has(btn.dataset.cat));
    });
    // 动态 chip 绑事件（schools/kinds 每次 render 都要重绑，innerHTML 替换导致旧 handler 丢失）
    schoolBox.querySelectorAll('.eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        const s = btn.dataset.school;
        if (f.schools.has(s)) f.schools.delete(s); else f.schools.add(s);
        btn.classList.toggle('active');
        _wzcPkSchedRefetch();
      });
    });
    kindBox.querySelectorAll('.eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        const k = btn.dataset.kind;
        if (f.kinds.has(k)) f.kinds.delete(k); else f.kinds.add(k);
        btn.classList.toggle('active');
        _wzcPkSchedRefetch();
      });
    });
  }

  function _wzcPkSyncRange() {
    if (!_wzcPkFilter) return;
    const minEl = document.getElementById('wzc_pk_min_level');
    const maxEl = document.getElementById('wzc_pk_max_level');
    const fill  = document.getElementById('wzc_pk_range_fill');
    const minLab = document.getElementById('wzc_pk_min_level_val');
    const maxLab = document.getElementById('wzc_pk_max_level_val');
    if (!minEl || !maxEl || !fill) return;
    let lo = parseInt(minEl.value, 10);
    let hi = parseInt(maxEl.value, 10);
    if (!Number.isFinite(lo)) lo = WZC_FM_LEVEL_MIN;
    if (!Number.isFinite(hi)) hi = WZC_FM_LEVEL_MAX;
    if (lo > hi) { [lo, hi] = [hi, lo]; minEl.value = lo; maxEl.value = hi; }
    minLab.textContent = lo;
    maxLab.textContent = (hi >= WZC_FM_LEVEL_MAX) ? `${hi}+` : hi;
    const span = WZC_FM_LEVEL_MAX - WZC_FM_LEVEL_MIN;
    const leftPct  = ((lo - WZC_FM_LEVEL_MIN) / span) * 100;
    const rightPct = ((WZC_FM_LEVEL_MAX - hi) / span) * 100;
    fill.style.left  = leftPct  + '%';
    fill.style.right = rightPct + '%';
    _wzcPkFilter.min_level = lo;
    _wzcPkFilter.max_level = (hi >= WZC_FM_LEVEL_MAX) ? 0 : hi;
  }

  function _wzcPkSchedRefetch() {
    if (_wzcPkRefetchTimer) clearTimeout(_wzcPkRefetchTimer);
    _wzcPkRefetchTimer = setTimeout(_wzcPkRefetch, 250);
  }

  async function _wzcPkRefetch() {
    const pos = _wzcPkCurrentPos;
    if (!pos || !_wzcPkFilter) return;
    const tableEl = document.getElementById('wzc_pk_table');
    const emptyEl = document.getElementById('wzc_pk_empty');
    const cntEl = document.getElementById('wzc_pk_count');
    tableEl.style.display = 'none';
    emptyEl.style.display = '';
    emptyEl.textContent = '查询中…';
    cntEl.textContent = '—';
    // 筛选改变 → 旧 dps cache 仍可复用（同 equip_id），但取消在途 batch 防止旧任务覆盖新列表
    _wzcPkDpsBatchToken++;
    const body = filterToBody(_wzcPkFilter, pos);
    try {
      const r = await fetch('/api/equip/search', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!r.ok) {
        _wzcPkItems = [];
        emptyEl.textContent = `请求失败 (HTTP ${r.status})`;
        cntEl.textContent = '';
        return;
      }
      let items = await r.json();
      if (_wzcPkFilter.only_set) items = items.filter(it => it.set_id && it.set_id > 0);
      _wzcPkItems = items;
      _wzcPkRender();
    } catch (e) {
      _wzcPkItems = [];
      emptyEl.textContent = '网络错误';
      cntEl.textContent = '';
    }
  }

  // picker 列表 row 比较器（配装器 compareItems 的 wzc 版）
  function _wzcPkCompareItems(a, b) {
    const { key, dir } = _wzcPkSort;
    if (!key) return 0;
    const sign = dir === 'asc' ? 1 : -1;
    if (key === 'dps_delta') {
      const da = _wzcPkDpsCache.get(a.id);
      const db = _wzcPkDpsCache.get(b.id);
      const aValid = (da != null && !Number.isNaN(da));
      const bValid = (db != null && !Number.isNaN(db));
      if (!aValid && !bValid) return 0;
      if (!aValid) return 1;
      if (!bValid) return -1;
      return sign * (da - db);
    }
    let va, vb;
    if (key === 'name')              { va = a.name || ''; vb = b.name || ''; }
    else if (key === 'magic_type')   { va = a.magic_type || ''; vb = b.magic_type || ''; }
    else if (key === 'belong_school'){ va = a.belong_school || ''; vb = b.belong_school || ''; }
    else if (key === 'set_name')     { va = a.set_name || ''; vb = b.set_name || ''; }
    else if (key === 'level')        { va = a.level || 0; vb = b.level || 0; }
    if (typeof va === 'string') return sign * va.localeCompare(vb, 'zh');
    return sign * (va - vb);
  }

  function _wzcPkUpdateSortIndicators() {
    const head = document.querySelector('#wzc_pk_table thead');
    if (!head) return;
    head.querySelectorAll('th[data-sort-key]').forEach(th => {
      const k = th.dataset.sortKey;
      th.classList.toggle('sort-asc',  _wzcPkSort.key === k && _wzcPkSort.dir === 'asc');
      th.classList.toggle('sort-desc', _wzcPkSort.key === k && _wzcPkSort.dir === 'desc');
    });
  }

  // 单元格 DPS Δ 渲染（同配装器 renderDpsCell）
  function _wzcPkRenderDpsCell(itemId, dps, baseline) {
    const cell = document.querySelector(`#wzc_pk_tbody .eq-dps-cell[data-dps-id="${itemId}"]`);
    if (!cell) return;
    if (baseline == null) {
      cell.innerHTML = '<span class="eq-dps-pending" title="无 baseline：先到循环模拟跑一次">—</span>';
      return;
    }
    if (dps == null) {
      cell.innerHTML = '<span class="eq-dps-fail" title="计算失败">—</span>';
      return;
    }
    const delta = dps - baseline;
    const tol = Math.max(Math.abs(baseline) * 0.005, 50);
    let cls = 'eq-dps-zero';
    let prefix = '';
    if (delta > tol) { cls = 'eq-dps-up';   prefix = '+'; }
    else if (delta < -tol) { cls = 'eq-dps-down'; prefix = ''; }
    const txt = prefix + Math.round(delta).toLocaleString();
    cell.innerHTML = `<span class="${cls}" title="DPS=${Math.round(dps).toLocaleString()}">${txt}</span>`;
  }

  function _wzcPkRender() {
    const pos = _wzcPkCurrentPos;
    if (!pos) return;
    // baseline 由 _wzcPkSchedDps 异步算（首次 render 时为 null，cache 命中行显示 "—"，
    // baseline ready 后 _wzcPkSchedDps 会回填）
    const cntEl = document.getElementById('wzc_pk_count');
    const tableEl = document.getElementById('wzc_pk_table');
    const tbody = document.getElementById('wzc_pk_tbody');
    const emptyEl = document.getElementById('wzc_pk_empty');
    const kw = (document.getElementById('wzc_pk_keyword')?.value || '').trim().toLowerCase();
    let items = _wzcPkItems;
    if (kw) {
      items = items.filter(it =>
        (it.name || '').toLowerCase().includes(kw) ||
        (it.set_name || '').toLowerCase().includes(kw) ||
        (it.magic_type || '').toLowerCase().includes(kw)
      );
    }
    if (_wzcPkFilter?.only_orange) {
      items = items.filter(it => (it.quality || 0) >= 5);
    }
    const total = items.length;
    cntEl.innerHTML = `<b>${total}</b> 件${kw ? ` · 关键字 "${escapeHtml(kw)}"` : ''}`;
    if (total === 0) {
      tableEl.style.display = 'none';
      emptyEl.style.display = '';
      emptyEl.innerHTML = '无匹配 — 调宽筛选条件 或 清空关键字 / 橙装';
      return;
    }
    const cap = Math.min(items.length, 200);
    let visible = items.slice(0, cap);
    if (_wzcPkSort.key) visible = [...visible].sort(_wzcPkCompareItems);

    // 当前生效装备 + 当前 override 高亮
    const cfg = _wzcActiveCfg();
    const curId = cfg?.slots?.[pos]?.equip_id || null;
    const overrideId = state.slotOverrides?.[pos]?.equip_id || null;
    tableEl.style.display = '';
    emptyEl.style.display = 'none';
    tbody.innerHTML = visible.map(it => {
      const cls = (it.quality || 0) >= 5 ? 'eq-name-orange' : 'eq-name-purple';
      const isCur = it.id === curId;
      const isOv = it.id === overrideId;
      const rowCls = isOv ? 'is-override' : (isCur ? 'is-current' : '');
      const tag = isOv ? '[已覆盖]' : (isCur ? '[当前]' : '');
      return `<tr data-eid="${it.id}" class="${rowCls}">
        <td class="${cls}">${escapeHtml(it.name || ('#' + it.id))}${tag ? ` <span class="wzc-pk-cur-tag">${tag}</span>` : ''}</td>
        <td>${escapeHtml(it.magic_type || '')}</td>
        <td>${escapeHtml(it.belong_school || '')}</td>
        <td>${escapeHtml(it.set_name || '')}</td>
        <td class="eq-lv">${it.level || '?'}</td>
        <td class="eq-dps-cell" data-dps-id="${it.id}"><span class="eq-dps-pending">·</span></td>
      </tr>`;
    }).join('');
    // 行 click → 选定；hover → 装备 tooltip
    tbody.querySelectorAll('tr').forEach((row, i) => {
      const it = visible[i];
      if (!it) return;
      row.addEventListener('click', () => _wzcPkSelect(it));
      row.addEventListener('mouseenter', () => {
        wzcShowHover(row,
          window.Jx3Equip?.buildItemTooltip?.(pos, { equip_id: it.id }) || '',
          true);
      });
      row.addEventListener('mouseleave', wzcHideHover);
    });
    _wzcPkUpdateSortIndicators();
    // 已缓存的 DPS Δ 直接回填；未跑的 schedulePreviewDps 跑
    for (const it of visible) {
      const dps = _wzcPkDpsCache.get(it.id);
      if (dps != null) _wzcPkRenderDpsCell(it.id, dps, _wzcPkBaselineDps);
    }
    _wzcPkSchedDps(visible);
  }

  // ── DPS Δ：baseline + 候选都按 wzc 环境（循环来源）+ _wzcActiveCfg 装备（含 slotOverrides）跑 ──
  // 不读 window._lastSimBody（主页面的，跟 wzc 环境不一定一致；override 时主页面 baseline 也不准）。
  // 循环来源：跟 wzc 环境区"循环来源"配置一致（getActiveLoopInputs 已封装）
  //   source=loop → 主页面当前 macro / talents / recipes
  //   source=import → state.env.importedMacro / importedTalents / importedRecipes
  // equipment：用 _wzcActiveCfg().slots 拼 { POS, ENCHANT_POS } map（含用户 override）。
  let _wzcPkSrcBody = null;   // baseline body 模板（picker 周期内复用，candidate worker 派生）

  function _wzcBuildSimBody() {
    const cfg = _wzcActiveCfg();
    if (!cfg) return null;
    const equipment = {};
    for (const [pos, slot] of Object.entries(cfg.slots || {})) {
      if (slot?.equip_id) equipment[pos] = slot.equip_id;
      if (slot?.enchant_id) equipment[`ENCHANT_${pos}`] = slot.enchant_id;
    }
    const act = getActiveLoopInputs();
    const useMacro = !!(act.macro_text && act.macro_text.trim());
    const duration = parseInt(document.getElementById('wzc_duration')?.value, 10) || 60;
    const maxSlots = Math.ceil(duration / 0.25) + 20;
    const sequence = useMacro ? Array(maxSlots).fill('__macro__') : ['盾击'];
    const baseTarget = (typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 };
    const targetLevel = parseInt(document.getElementById('wzc_target_level')?.value, 10) || baseTarget.level;
    const target = { ...baseTarget, level: targetLevel };
    const attributes = (typeof getAttrs === 'function') ? getAttrs() : {};
    return {
      haste_level: attributes.haste_level || 0,
      sequence,
      macro_text: useMacro ? act.macro_text : undefined,
      macro_duration: useMacro ? duration : undefined,
      talents: act.talents,
      recipes: act.recipes,
      network_delay: parseInt(document.getElementById('sim_delay')?.value, 10) || 0,
      attributes,
      target,
      initial_rage: (typeof adminInitialRage !== 'undefined') ? (adminInitialRage || 0) : 0,
      boss_attack_interval: (typeof getBossAttackInterval === 'function') ? getBossAttackInterval() : 0,
      hanjia_expectation: (typeof isHanjiaExpectationEnabled === 'function') ? isHanjiaExpectationEnabled() : false,
      tiegu_mode: (typeof getTieguMode === 'function') ? getTieguMode() : 0,
      experimental: (typeof isExperimental === 'function') ? isExperimental() : false,
      equipment,
      team_buffs: (typeof getTeamBuffs === 'function') ? getTeamBuffs() : [],
      formation: (typeof getCurrentFormation === 'function') ? getCurrentFormation() : null,
      lite: true,
      lite_keep_timeline: false,
    };
  }

  async function _wzcPkComputeBaselineDps() {
    _wzcPkSrcBody = _wzcBuildSimBody();
    if (!_wzcPkSrcBody) { _wzcPkBaselineDps = null; return null; }
    try {
      const r = await fetch('/api/simulate', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_wzcPkSrcBody),
      });
      if (!r.ok) { _wzcPkBaselineDps = null; return null; }
      const json = await r.json();
      _wzcPkBaselineDps = json.dps;
      return json.dps;
    } catch { _wzcPkBaselineDps = null; return null; }
  }

  async function _wzcPkSchedDps(visible) {
    const pos = _wzcPkCurrentPos;
    if (!pos) return;
    // baseline 还没算 → 先跑 baseline simulate（首次进 picker 必经一次，~几百 ms）
    if (_wzcPkBaselineDps == null) {
      document.querySelectorAll('#wzc_pk_tbody .eq-dps-cell').forEach(c => {
        c.innerHTML = '<span class="eq-dps-pending" title="正在计算 baseline (wzc 当前装备 + 循环来源)…">⏳</span>';
      });
      await _wzcPkComputeBaselineDps();
      if (_wzcPkCurrentPos !== pos) return;          // picker 已切 pos 或关闭
      if (_wzcPkBaselineDps == null) {
        document.querySelectorAll('#wzc_pk_tbody .eq-dps-cell').forEach(c => {
          c.innerHTML = '<span class="eq-dps-fail" title="baseline 计算失败 — 检查 wzc 环境（循环来源 / 装备 / 时长）">—</span>';
        });
        return;
      }
      // baseline ready：回填已 cache 行（之前 baseline=null 时 _wzcPkRender 内显示了 "—"）
      for (const it of visible) {
        const dps = _wzcPkDpsCache.get(it.id);
        if (dps != null) _wzcPkRenderDpsCell(it.id, dps, _wzcPkBaselineDps);
      }
    }
    if (!_wzcPkSrcBody) return;
    const myToken = ++_wzcPkDpsBatchToken;
    const queue = visible.filter(it => !_wzcPkDpsCache.has(it.id));
    const concurrency = 6;
    async function worker() {
      while (queue.length) {
        if (myToken !== _wzcPkDpsBatchToken) return;
        const it = queue.shift();
        try {
          // 从 baseline body 派生：只覆盖目标 pos 的 equip_id，附魔 / 其他部位不动
          const body = JSON.parse(JSON.stringify(_wzcPkSrcBody));
          body.equipment = { ...(body.equipment || {}) };
          body.equipment[pos] = it.id;
          const r = await fetch('/api/simulate', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body),
          });
          if (myToken !== _wzcPkDpsBatchToken) return;
          if (!r.ok) throw new Error(`HTTP ${r.status}`);
          const json = await r.json();
          if (myToken !== _wzcPkDpsBatchToken) return;
          const dps = json.dps;
          _wzcPkDpsCache.set(it.id, dps);
          _wzcPkRenderDpsCell(it.id, dps, _wzcPkBaselineDps);
          _wzcPkSchedDpsResort();
        } catch (e) {
          if (myToken !== _wzcPkDpsBatchToken) return;
          _wzcPkRenderDpsCell(it.id, null, _wzcPkBaselineDps);
        }
      }
    }
    await Promise.all(Array.from({ length: concurrency }, () => worker()));
  }

  // 节流 DOM 重排：每跑完一行 DPS Δ 触发一次（仅 sort.key === 'dps_delta' 时）
  let _wzcPkDpsResortTimer = null;
  function _wzcPkSchedDpsResort() {
    if (_wzcPkSort.key !== 'dps_delta') return;
    clearTimeout(_wzcPkDpsResortTimer);
    _wzcPkDpsResortTimer = setTimeout(() => {
      const tbody = document.getElementById('wzc_pk_tbody');
      if (!tbody) return;
      const rows = [...tbody.children];
      rows.sort((a, b) => {
        const aId = parseInt(a.dataset.eid, 10);
        const bId = parseInt(b.dataset.eid, 10);
        const da = _wzcPkDpsCache.get(aId);
        const db = _wzcPkDpsCache.get(bId);
        const sign = _wzcPkSort.dir === 'asc' ? 1 : -1;
        const av = (da != null && !Number.isNaN(da));
        const bv = (db != null && !Number.isNaN(db));
        if (!av && !bv) return 0;
        if (!av) return 1;
        if (!bv) return -1;
        return sign * (da - db);
      });
      for (const r of rows) tbody.appendChild(r);
    }, 100);
  }

  function _wzcPkSelect(it) {
    const pos = _wzcPkCurrentPos;
    if (!pos || !it) return;
    // 选的就是主源装备 → 等价于清除 override
    const baseCfg = (state.env?.source === 'import' && state.env?.importedEquipment)
      ? state.env.importedEquipment
      : window.Jx3Equip?.getCurrentConfig?.();
    const baseId = baseCfg?.slots?.[pos]?.equip_id || null;
    if (it.id === baseId) {
      delete state.slotOverrides[pos];
    } else {
      state.slotOverrides[pos] = {
        equip_id: it.id,
        name: it.name || '',
        level: it.level,
        set_id: it.set_id,
        set_name: it.set_name,
        belong_school: it.belong_school,
        magic_kind: it.magic_kind,
      };
    }
    saveWzcState();
    syncCurrentEquip();
    updateRowAndTotals(pos);
    updateOverridesToolbar();
    closeSlotPicker();
  }

  function closeSlotPicker() {
    document.getElementById('wzc_picker_modal').style.display = 'none';
    _wzcPkCurrentPos = null;
    _wzcPkItems = [];
    _wzcPkDpsBatchToken++;   // 关闭即丢在途 batch
  }

  function initSlotPickerEvents() {
    document.getElementById('wzc_pk_close').addEventListener('click', closeSlotPicker);
    document.getElementById('wzc_pk_cancel').addEventListener('click', closeSlotPicker);
    // 恢复主源装备：清掉该部位 override（不动 picker 筛选）
    document.getElementById('wzc_pk_reset').addEventListener('click', () => {
      const pos = _wzcPkCurrentPos;
      if (!pos) return;
      delete state.slotOverrides[pos];
      saveWzcState();
      syncCurrentEquip();
      updateRowAndTotals(pos);
      updateOverridesToolbar();
      closeSlotPicker();
    });
    // 重置筛选：把 picker draft 还原成本部位候选池筛选
    document.getElementById('wzc_pk_reset_filter').addEventListener('click', () => {
      const pos = _wzcPkCurrentPos;
      if (!pos) return;
      const ps = state.perSlot[pos];
      if (!ps.filter) ps.filter = defaultFilterFor(pos);
      _wzcPkFilter = _wzcPkCloneFilter(ps.filter);
      _wzcPkRenderFilter();
      _wzcPkSchedRefetch();
    });
    // 品级双滑条
    document.getElementById('wzc_pk_min_level').addEventListener('input', () => {
      _wzcPkSyncRange();
      _wzcPkSchedRefetch();
    });
    document.getElementById('wzc_pk_max_level').addEventListener('input', () => {
      _wzcPkSyncRange();
      _wzcPkSchedRefetch();
    });
    // 静态 chips：attrs / battle / categories（schools / kinds 是动态生成，绑在 _wzcPkRenderFilter）
    document.querySelectorAll('#wzc_pk_attrs .eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!_wzcPkFilter) return;
        const a = btn.dataset.attr;
        if (_wzcPkFilter.attrs.has(a)) _wzcPkFilter.attrs.delete(a); else _wzcPkFilter.attrs.add(a);
        btn.classList.toggle('active');
        _wzcPkSchedRefetch();
      });
    });
    document.querySelectorAll('#wzc_pk_battle .eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!_wzcPkFilter) return;
        const b = btn.dataset.battle;
        if (_wzcPkFilter.battle_types.has(b)) _wzcPkFilter.battle_types.delete(b);
        else _wzcPkFilter.battle_types.add(b);
        btn.classList.toggle('active');
        _wzcPkSchedRefetch();
      });
    });
    document.querySelectorAll('#wzc_pk_categories .eq-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        if (!_wzcPkFilter) return;
        const c = btn.dataset.cat;
        if (_wzcPkFilter.categories.has(c)) _wzcPkFilter.categories.delete(c);
        else _wzcPkFilter.categories.add(c);
        btn.classList.toggle('active');
        _wzcPkSchedRefetch();
      });
    });
    // 只看套装
    document.getElementById('wzc_pk_only_set').addEventListener('change', e => {
      if (!_wzcPkFilter) return;
      _wzcPkFilter.only_set = !!e.target.checked;
      _wzcPkSchedRefetch();
    });
    // 只看橙装（前端过滤，不重抓）
    document.getElementById('wzc_pk_only_orange').addEventListener('change', e => {
      if (!_wzcPkFilter) return;
      _wzcPkFilter.only_orange = !!e.target.checked;
      _wzcPkRender();
    });
    // 全选 / 全不选 chips（schools/kinds/attrs/battle/categories 一起切，跟配装器同语义）
    document.getElementById('wzc_pk_filter_all').addEventListener('click', () => {
      if (!_wzcPkFilter) return;
      document.querySelectorAll('#wzc_pk_schools .eq-chip').forEach(btn => {
        _wzcPkFilter.schools.add(btn.dataset.school); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_pk_kinds .eq-chip').forEach(btn => {
        _wzcPkFilter.kinds.add(btn.dataset.kind); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_pk_attrs .eq-chip').forEach(btn => {
        _wzcPkFilter.attrs.add(btn.dataset.attr); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_pk_battle .eq-chip').forEach(btn => {
        _wzcPkFilter.battle_types.add(btn.dataset.battle); btn.classList.add('active');
      });
      document.querySelectorAll('#wzc_pk_categories .eq-chip').forEach(btn => {
        _wzcPkFilter.categories.add(btn.dataset.cat); btn.classList.add('active');
      });
      _wzcPkSchedRefetch();
    });
    document.getElementById('wzc_pk_filter_none').addEventListener('click', () => {
      if (!_wzcPkFilter) return;
      _wzcPkFilter.schools.clear(); _wzcPkFilter.kinds.clear();
      _wzcPkFilter.attrs.clear();   _wzcPkFilter.battle_types.clear();
      _wzcPkFilter.categories.clear();
      document.querySelectorAll('#wzc_picker_modal .eq-chip').forEach(btn => btn.classList.remove('active'));
      _wzcPkSchedRefetch();
    });
    // 列头点击切排序（第一次 desc → asc → 清空）
    const pkHead = document.querySelector('#wzc_pk_table thead');
    if (pkHead) {
      pkHead.addEventListener('click', e => {
        const th = e.target.closest('th[data-sort-key]');
        if (!th) return;
        const k = th.dataset.sortKey;
        if (_wzcPkSort.key !== k) _wzcPkSort = { key: k, dir: 'desc' };
        else if (_wzcPkSort.dir === 'desc') _wzcPkSort = { key: k, dir: 'asc' };
        else _wzcPkSort = { key: null, dir: 'desc' };
        _wzcPkRender();
      });
    }
    // 关键字：前端实时过滤已加载列表（不重抓）
    let pkKwTimer = null;
    document.getElementById('wzc_pk_keyword').addEventListener('input', () => {
      if (pkKwTimer) clearTimeout(pkKwTimer);
      pkKwTimer = setTimeout(_wzcPkRender, 120);
    });
    document.getElementById('wzc_picker_modal').addEventListener('click', e => {
      if (e.target.id === 'wzc_picker_modal') closeSlotPicker();
    });
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && _wzcPkCurrentPos) closeSlotPicker();
    });
  }
  initSlotPickerEvents();

  function renderCandsRow(pos) {
    const ps = state.perSlot[pos];
    const lockChecked = ps.mode === 'lock';
    if (!ps.filter) ps.filter = defaultFilterFor(pos);
    const f = ps.filter;
    // 简短 filter summary
    const summaryParts = [];
    if (f.schools.size) summaryParts.push([...f.schools].join('+'));
    if (f.kinds.size) summaryParts.push([...f.kinds].join('+'));
    if (f.attrs.size) summaryParts.push([...f.attrs].join('/'));
    if (f.keyword) summaryParts.push('"' + f.keyword + '"');
    if (f.only_set) summaryParts.push('只看套装');
    if (f.min_level && f.min_level !== 22000) summaryParts.push(`Lv≥${f.min_level}`);
    if (f.max_level && f.max_level > 0) summaryParts.push(`Lv≤${f.max_level}`);
    const summary = summaryParts.join(' · ') || '默认';
    const cands = ps.candidates || [];
    const exN = (ps.excluded && ps.excluded.size) ? ps.excluded.size : 0;
    const exTag = exN > 0 ? ` <span class="wzc-hint">· 剔除 ${exN}</span>` : '';
    const previewText = cands.length > 0
      ? `<b>${cands.length} 件</b>${exTag}：${cands.slice(0, 4).map(it => escapeHtml(it.name || it.id)).join(' / ')}${cands.length > 4 ? ` … +${cands.length - 4}` : ''}`
      : '<span class="wzc-hint">未拉取（点"筛选"或"全部刷新"）</span>';
    // 已锁定：永远可点（用户可解锁）；当前未锁但没装备：禁用（无法进入 lock）
    const lockDisabled = (lockChecked || ps.currentId) ? '' : 'disabled';
    const subTitle = (kind, on) => {
      if (kind === 'enchant') return on ? '当前：锁定大附魔（用配装器值）。点击切换为不带大附魔。' : '当前：不带大附魔。点击切换为锁定（用配装器值）。';
      if (kind === 'enhance') return on ? '当前：锁定小附魔（用配装器值）。点击切换为偏导自动选最优。' : '当前：搜索最优小附魔（Phase B 偏导）。点击切换为锁定。';
      if (kind === 'stone')   return on ? '当前：锁定五彩石（用配装器值）。点击切换为不带五彩石。' : '当前：不带五彩石。点击切换为锁定。';
      return '';
    };
    const subBtn = (kind, on, label) =>
      `<button class="wzc-sub-toggle ${on ? 'on' : ''}" data-sub="${kind}" data-pos="${pos}" title="${subTitle(kind, on)}">${label}</button>`;
    const subGroup = lockChecked
      ? `<div class="wzc-lock-sub">
           ${subBtn('enchant', !!ps.lockEnchant, '大附魔')}
           ${subBtn('enhance', !!ps.lockEnhance, '小附魔')}
           ${pos === 'PRIMARY_WEAPON' ? subBtn('stone', !!ps.lockStone, '五彩石') : ''}
         </div>`
      : '';
    const isOverridden = !!state.slotOverrides?.[pos];
    const curEquipInner = isOverridden
      ? `<span class="wzc-cur-equip-badge" title="已手动切换，点击 ↻ 重置回主源">✎</span>
         <span class="wzc-cur-equip-name">${escapeHtml(ps.currentName || '（未装备）')}</span>
         <button class="wzc-cur-equip-reset" data-reset-pos="${pos}" title="重置该部位为主源装备">↻</button>`
      : `<span class="wzc-cur-equip-name">${escapeHtml(ps.currentName || '（未装备）')}</span>`;
    return `
      <tr data-pos="${pos}">
        <td><b>${POS_LABEL[pos]}</b><br><span class="wzc-pos-tag">${pos}</span></td>
        <td><span class="wzc-cur-equip${isOverridden ? ' overridden' : ''}" data-pick-pos="${pos}" title="点击切换该部位的"当前装备"（仅 wzc 内生效，不动配装器）">${curEquipInner}</span></td>
        <td>
          <button class="wzc-lock-toggle ${lockChecked ? 'on' : ''}" data-lock-pos="${pos}" ${lockDisabled} title="${lockChecked ? '当前：锁定该部位装备。点击切回枚举。' : '当前：枚举该部位。点击切换为锁定（使用配装器里的当前装备）。'}">
            ${lockChecked ? '🔒 已锁定' : '🔓 枚举中'}
          </button>
          ${subGroup}
        </td>
        <td>
          <button class="sim-btn wzc-mini-btn" data-filter-pos="${pos}" ${lockChecked ? 'disabled' : ''} title="编辑筛选条件：${escapeHtml(summary)}">🔍 筛选</button>
          <div class="wzc-filter-summary" title="${escapeHtml(summary)}">${escapeHtml(summary)}</div>
        </td>
        <td class="wzc-cands-preview" data-cands-preview="${pos}">${lockChecked ? escapeHtml(`[锁定] ${ps.currentName || '（未装备）'}`) : previewText}</td>
      </tr>
    `;
  }

  function bindLockToggleHandlers(scope) {
    const root = scope || document;
    root.querySelectorAll('button[data-lock-pos]').forEach(btn => {
      btn.addEventListener('click', () => {
        const pos = btn.dataset.lockPos;
        const ps = state.perSlot[pos];
        if (!ps) return;
        // 没装备时不允许进入 lock
        if (!ps.currentId && ps.mode !== 'lock') return;
        ps.mode = (ps.mode === 'lock') ? 'enum' : 'lock';
        saveWzcState();
        updateRowAndTotals(pos);
        refreshCandsForSlot(pos);
      });
    });
    root.querySelectorAll('button.wzc-sub-toggle').forEach(btn => {
      btn.addEventListener('click', () => {
        const pos = btn.dataset.pos;
        const sub = btn.dataset.sub;
        const ps = state.perSlot[pos];
        if (!ps) return;
        if (sub === 'enchant') ps.lockEnchant = !ps.lockEnchant;
        else if (sub === 'enhance') ps.lockEnhance = !ps.lockEnhance;
        else if (sub === 'stone')   ps.lockStone   = !ps.lockStone;
        saveWzcState();
        updateRowAndTotals(pos);
      });
    });
  }

  function renderCandsTable() {
    document.getElementById('wzc_cands_body').innerHTML = POS_LIST.map(renderCandsRow).join('');
    bindLockToggleHandlers();
    document.querySelectorAll('button[data-filter-pos]').forEach(btn => {
      btn.addEventListener('click', () => openFilterModal(btn.dataset.filterPos));
    });
    bindSlotPickHandlers();
    bindCandsHover();
    updateOverridesToolbar();
    updateComboSummary();
  }
  // 第二列"当前装备"click → 弹 picker；reset 按钮单独 click 清除该部位 override
  function bindSlotPickHandlers(scope) {
    const root = scope || document;
    root.querySelectorAll('.wzc-cur-equip[data-pick-pos]').forEach(el => {
      el.addEventListener('click', e => {
        // 点击内部 reset 按钮时由 reset handler 处理，不要再弹 picker
        if (e.target.closest('.wzc-cur-equip-reset')) return;
        openSlotPicker(el.dataset.pickPos);
      });
    });
    root.querySelectorAll('.wzc-cur-equip-reset[data-reset-pos]').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const pos = btn.dataset.resetPos;
        if (!pos) return;
        delete state.slotOverrides[pos];
        saveWzcState();
        syncCurrentEquip();
        updateRowAndTotals(pos);
        updateOverridesToolbar();
      });
    });
  }
  function bindCandsHover() {
    // 第二列"当前装备"hover：显示当前生效装备的完整详情（含 override）
    document.querySelectorAll('#wzc_cands_body tr[data-pos]').forEach(tr => {
      const pos = tr.dataset.pos;
      if (!state.perSlot[pos]?.currentId) return;
      const wrapper = tr.querySelector('.wzc-cur-equip');
      if (!wrapper) return;
      wrapper.addEventListener('mouseenter', () => {
        const eq = _wzcActiveCfg();
        const slotCfg = eq?.slots?.[pos];
        if (!slotCfg) return;
        wzcShowHover(wrapper,
          window.Jx3Equip?.buildItemTooltip?.(pos, slotCfg, { stoneName: eq?.stoneName }) || '',
          true);
      });
      wrapper.addEventListener('mouseleave', wzcHideHover);
    });
  }

  async function refreshCandsForSlot(pos) {
    const ps = state.perSlot[pos];
    if (ps.mode !== 'enum') return;
    ps.candidates = await fetchCandsForSlot(pos);
    updateRowAndTotals(pos);
  }
  function updateRowAndTotals(pos) {
    // 整行重渲染（候选预览要显示 count + 4 件名）
    const tr = document.querySelector(`tr[data-pos="${pos}"]`);
    if (tr) {
      // outerHTML 替换会丢失节点引用；改成 replaceWith 后重新查询新行作用域绑事件
      const wrapper = document.createElement('tbody');
      wrapper.innerHTML = renderCandsRow(pos);
      const newTr = wrapper.firstElementChild;
      tr.replaceWith(newTr);
      newTr.querySelectorAll(`button[data-filter-pos="${pos}"]`).forEach(btn => {
        btn.addEventListener('click', () => openFilterModal(btn.dataset.filterPos));
      });
      bindLockToggleHandlers(newTr);
      bindSlotPickHandlers(newTr);
    }
    bindCandsHover();
    updateOverridesToolbar();
    updateComboSummary();
  }
  function updateComboSummary() {
    let total = 1;
    let enumPositions = 0;
    let posWithoutCands = 0;
    POS_LIST.forEach(pos => {
      const ps = state.perSlot[pos];
      if (ps.mode === 'enum') {
        const n = ps.candidates.length;
        if (n === 0) { posWithoutCands++; return; }
        total *= n;
        enumPositions++;
      }
    });
    const el = document.getElementById('wzc_combo_summary');
    let msg = `枚举部位 ${enumPositions} / ${POS_LIST.length}，候选总组合 <b>${total.toLocaleString()}</b>`;
    let cls = '';
    const SMART_THRESHOLD = 1e6;   // 与后端 SMART_MODE_THRESHOLD 一致
    if (posWithoutCands > 0) {
      msg += ` <span style="color:#f85149">⚠ ${posWithoutCands} 个枚举部位无候选 — 调宽筛选</span>`;
      cls = 'warn';
    } else if (total > 1e10) {
      msg += ` <span style="color:#f85149">🚫 组合数过大（>1e10），后端会跑很久 — 收紧筛选</span>`;
      cls = 'danger';
    } else if (total > SMART_THRESHOLD && total > 0) {
      msg += ` <span style="color:var(--gold)">⚡ 将启用智能模式（梯度预筛）</span>`;
    } else if (total > 0 && enumPositions > 0) {
      msg += ` <span style="color:#3fb950">🎯 将使用完整模拟</span>`;
    }
    el.innerHTML = msg;
    // 同时刷新右侧属性预览（基于当前配装器装备 + 当前 talents）
    updateAttrPreview();
  }

  // ── 候选池右侧属性预览：实时从配装器读 cfg.slots 调 calculatePanel 算 ──
  let _wzcAttrPreviewToken = 0;
  let _wzcAttrPreviewTimer = null;
  function updateAttrPreview() {
    if (_wzcAttrPreviewTimer) clearTimeout(_wzcAttrPreviewTimer);
    _wzcAttrPreviewTimer = setTimeout(_wzcAttrPreviewRender, 200);   // 防抖
  }
  async function _wzcAttrPreviewRender() {
    const myToken = ++_wzcAttrPreviewToken;
    const el = document.getElementById('wzc_attr_preview')?.querySelector('.wzc-attr-preview-body');
    if (!el) return;
    // 用 _wzcActiveCfg（已合并 slotOverrides + import 装备）以反映用户在 wzc 内的单件切换
    const cfg = _wzcActiveCfg();
    if (!cfg || !cfg.slots || !Object.keys(cfg.slots).length) {
      el.innerHTML = '<div class="wzc-hint">配装器内无装备</div>';
      return;
    }
    const tlts = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const mountId = (typeof getCurrentMountId === 'function') ? getCurrentMountId()
                  : (currentMount?.mount === 'TieGuYi' ? 10389 : 10390);
    el.innerHTML = '<div class="wzc-hint">计算中…</div>';
    try {
      const resp = await window.Jx3Equip?.calculatePanel?.(cfg.slots, cfg.stoneId || 0, mountId, tlts);
      if (myToken !== _wzcAttrPreviewToken) return;
      if (!resp?.panel) { el.innerHTML = '<div class="wzc-hint">计算失败</div>'; return; }
      const p = resp.panel;
      const r = resp.raw || {};
      const num = v => Math.round(v || 0).toLocaleString();
      const pct = v => ((v || 0) * 100).toFixed(2) + '%';
      const isTiegu = currentMount?.mount === 'TieGuYi' || currentMount?.mount_label === '铁骨衣';
      // 行带 data-attr-key，hover 显示等级 / 公式（与配装器/结果卡一致）
      const row = (key, k, v) => `<div class="wzc-attr-row" data-attr-key="${key}"><span>${k}</span><b>${v}</b></div>`;
      const lines = [];
      lines.push(`<div class="wzc-attr-section-title">面板</div>`);
      lines.push(row('atk',       '攻击', num(p.physics_attack_power)));
      lines.push(row('agi',       '身法', num(p.agility ?? r.agility)));
      if (isTiegu) {
        lines.push(row('vit',     '体质', num(p.vitality ?? r.vitality)));
        lines.push(row('hp',      '气血', num(p.max_life)));
      }
      lines.push(row('crit',      '会心', pct(p.crit_rate)));
      lines.push(row('crit_eff',  '会效', pct(p.crit_effect)));
      lines.push(row('oc',        '破防', pct(p.overcome_rate)));
      lines.push(row('strain',    '无双', pct(p.strain_rate)));
      lines.push(row('haste',     '加速', pct(p.haste_rate)));
      lines.push(row('surplus',   '破招', num(p.surplus_value)));
      if (isTiegu) {
        lines.push(row('parry',     '招架', pct(p.parry_rate)));
        lines.push(row('parry_val', '拆招', num(p.parry_value)));
        lines.push(row('pshield',   '外防', pct(p.physics_shield_rate)));
        lines.push(row('mshield',   '内防', pct(p.magic_shield_rate)));
      }
      el.innerHTML = lines.join('');
      // 行 hover：复用全局 jx3BuildAttrTooltip（共享 helper，与配装器/结果卡一致）
      el.querySelectorAll('.wzc-attr-row[data-attr-key]').forEach(rowEl => {
        const key = rowEl.dataset.attrKey;
        rowEl.style.cursor = 'help';
        rowEl.addEventListener('mouseenter', () => {
          const html = jx3BuildAttrTooltip(key, r, p);
          if (html) showTooltip(rowEl, html);
        });
        rowEl.addEventListener('mouseleave', hideTooltip);
      });
    } catch (e) {
      if (myToken !== _wzcAttrPreviewToken) return;
      el.innerHTML = `<div class="wzc-hint" style="color:#f85149">计算异常：${escapeHtml(e.message)}</div>`;
    }
  }

  // 全部刷新候选
  async function refreshAllCands() {
    await Promise.all(POS_LIST.map(pos => refreshCandsForSlot(pos)));
  }
  document.getElementById('wzc_clear_overrides').addEventListener('click', () => {
    if (Object.keys(state.slotOverrides || {}).length === 0) return;
    clearSlotOverrides();
  });
  document.getElementById('wzc_all_lock').addEventListener('click', () => {
    POS_LIST.forEach(pos => {
      const ps = state.perSlot[pos];
      if (ps.currentId) ps.mode = 'lock';
    });
    saveWzcState();
    renderCandsTable();
  });
  document.getElementById('wzc_all_enum').addEventListener('click', () => {
    POS_LIST.forEach(pos => state.perSlot[pos].mode = 'enum');
    saveWzcState();
    renderCandsTable();
  });
  document.getElementById('wzc_all_refresh').addEventListener('click', async () => {
    const btn = document.getElementById('wzc_all_refresh');
    btn.disabled = true;
    const oldText = btn.textContent;
    btn.textContent = '⏳ 拉取中…';
    await refreshAllCands();
    renderCandsTable();
    btn.disabled = false;
    btn.textContent = oldText;
  });
  // ═══ 进度条 v2（重写）═══
  // 简化原则：
  //   1. setInterval 无脑每 300ms fetch 一次（不递归 setTimeout、不 abort 标志位）
  //   2. 任何错误只 console，不动 DOM；让 fetch 自己跑
  //   3. POST 完成时 clearInterval + 最后一次 sync render
  //   4. 进度条 DOM 全用 inline style，不依赖外部 CSS class
  let _wzcPollHandle = null;
  // 阶段时间戳：startElapsed/endElapsed 是相对 search 起点的 ms
  // 后端只回总 elapsed_ms，这里靠 phase 转换来推断每段起止时间
  // samples: 每阶段保留最近 N 个 (elapsed, count) 样本做滑动窗口速率
  //   累积速率会被早期 rayon 热身偏置 + 后期单 sim 变慢拖累 → ETA 越算越多
  //   滑动窗口对最近 5~10 秒做线性回归，更接近瞬时速率
  let _wzcPhaseTimings = null;
  const _WZC_RATE_WINDOW_MS = 8000;   // 滑动窗口长度
  const _WZC_RATE_MIN_SAMPLES = 2;
  function wzcResetPhaseTimings() {
    _wzcPhaseTimings = {
      enumerate: { state: 'pending', startElapsed: null, endElapsed: null, samples: [] },
      pareto:    { state: 'pending', startElapsed: null, endElapsed: null, samples: [] },
      rank:      { state: 'pending', startElapsed: null, endElapsed: null, samples: [] },
      simulate:  { state: 'pending', startElapsed: null, endElapsed: null, samples: [] },
      phase_b:   { state: 'pending', startElapsed: null, endElapsed: null, samples: [] },
    };
  }
  // 滑动窗口速率：基于最近 _WZC_RATE_WINDOW_MS 内的样本计算 unit/s
  // 返回 null 表示样本不足
  function _wzcWindowRate(samples, nowElapsed) {
    if (!samples || samples.length < _WZC_RATE_MIN_SAMPLES) return null;
    // 丢弃窗口外样本（保留 >= now - window 的）
    const cutoff = nowElapsed - _WZC_RATE_WINDOW_MS;
    while (samples.length > _WZC_RATE_MIN_SAMPLES && samples[0].t < cutoff) samples.shift();
    if (samples.length < _WZC_RATE_MIN_SAMPLES) return null;
    const oldest = samples[0];
    const newest = samples[samples.length - 1];
    const dt = newest.t - oldest.t;
    const dc = newest.c - oldest.c;
    if (dt <= 0 || dc <= 0) return null;
    return dc / dt * 1000;   // unit/s
  }
  function _wzcPushSample(phase, nowElapsed, count) {
    const t = _wzcPhaseTimings?.[phase];
    if (!t) return;
    const last = t.samples[t.samples.length - 1];
    // 同样本去重（相邻 poll 进度可能没动）
    if (last && last.c === count && nowElapsed - last.t < 500) return;
    t.samples.push({ t: nowElapsed, c: count });
    // 上限 64 个，避免无限增长
    if (t.samples.length > 64) t.samples.shift();
  }
  const _WZC_PHASE_ORDER = ['enumerate', 'pareto', 'rank', 'simulate', 'phase_b'];
  function _wzcFmtDur(ms) {
    if (ms == null || !isFinite(ms) || ms < 0) return '—';
    if (ms < 950) return ms.toFixed(0) + 'ms';
    if (ms < 9500) return (ms/1000).toFixed(1) + 's';
    if (ms < 60000) return (ms/1000).toFixed(0) + 's';
    if (ms < 3600000) {
      const m = Math.floor(ms/60000);
      const s = Math.floor((ms%60000)/1000);
      return s > 0 ? `${m}m${s}s` : `${m}m`;
    }
    const h = Math.floor(ms/3600000);
    const m = Math.floor((ms%3600000)/60000);
    return m > 0 ? `${h}h${m}m` : `${h}h`;
  }
  function _wzcSetPhase(name, state, time, detail, fillPct) {
    const el = document.querySelector(`.wzc-phase[data-phase="${name}"]`);
    if (!el) return;
    el.setAttribute('data-state', state);
    const icon = el.querySelector('.wzc-phase-icon');
    icon.textContent = state === 'done' ? '✓' : (state === 'active' ? '⟳' : '○');
    el.querySelector('.wzc-phase-time').textContent = time || '—';
    el.querySelector('.wzc-phase-detail').textContent = detail || '';
    if (state !== 'done') {
      el.querySelector('.wzc-phase-fill').style.width = (fillPct || 0).toFixed(1) + '%';
    }
  }

  // 搜索完成时一次性渲染所有阶段框（独立于 polling 是否捕获中间状态）
  function wzcRenderDoneFromStats(s, elapsed) {
    // enumerate
    const enumDetail = `${(s.total_combinations || 0).toLocaleString()} 种 · 入选 ${(s.after_haste_pruning || 0).toLocaleString()} · 去重 ${(s.unique_keys || 0).toLocaleString()}`;
    _wzcSetPhase('enumerate', 'done', _wzcFmtDur(s.time_calc_ms || 0), enumDetail, 100);

    // 候选筛选（Pareto）
    const paretoDetail = `${(s.unique_keys || 0).toLocaleString()} → ${(s.after_pareto || 0).toLocaleString()}`;
    _wzcSetPhase('pareto', 'done', _wzcFmtDur(s.time_pareto_ms || 0), paretoDetail, 100);

    // 属性预筛：仅在 smart_mode（池子 > 1千万）启用
    if (s.smart_mode) {
      const rankDetail = `${(s.after_pareto || 0).toLocaleString()} → ${(s.after_rank || 0).toLocaleString()}`;
      _wzcSetPhase('rank', 'done', _wzcFmtDur(s.time_rank_ms || 0), rankDetail, 100);
    } else {
      _wzcSetPhase('rank', 'pending', '—', '未启用（池子 < 1千万，全模拟）', 0);
    }

    // DPS 测算
    const simDetail = `${(s.simulated || 0).toLocaleString()} 完成`;
    _wzcSetPhase('simulate', 'done', _wzcFmtDur(s.time_simulate_ms || 0), simDetail, 100);

    // 附魔挑选（Phase B 偏导）
    const pbRan = (s.phase_b_bases || 0) > 0;
    if (pbRan) {
      const pbDetail = `${(s.phase_b_bases || 0).toLocaleString()} 个 base · ${(s.phase_b_simulated || 0).toLocaleString()} sim`;
      _wzcSetPhase('phase_b', 'done', _wzcFmtDur(s.time_phase_b_ms || 0), pbDetail, 100);
    } else {
      _wzcSetPhase('phase_b', 'pending', '—', '未启用', 0);
    }

    // 总览
    const sumEl = document.getElementById('wzc_phase_summary');
    if (sumEl) {
      sumEl.textContent = `✓ 全部完成 · 总耗时 ${_wzcFmtDur(elapsed)}`;
      sumEl.style.color = '#3fb950';
    }
  }
  function wzcUpdateProgress(p) {
    const box = document.getElementById('wzc_pbox');
    if (!box) { console.error('[wzc] progress DOM missing'); return; }
    box.style.display = 'block';
    const sumEl = document.getElementById('wzc_phase_summary');
    if (!_wzcPhaseTimings) wzcResetPhaseTimings();

    if (!p) { if (sumEl) sumEl.textContent = '正在准备…'; return; }
    const elapsed = p.elapsed_ms || 0;
    const cur = p.phase;

    // —— 搜索完成：用 result.stats 一次性渲染所有阶段 ——
    //   不依赖 polling 是否捕获到每个中间状态。耗时短时 polling 可能直接看到 'done'，
    //   按此路径渲染保证所有阶段框正确显示。
    if (cur === 'done' && p.result?.stats) {
      wzcRenderDoneFromStats(p.result.stats, elapsed);
      return;
    }

    // —— 维护每段 state / 时间戳（在搜索期间）——
    if (cur === 'done') {
      // result 还没写进来（极少；下一 tick 会进上面的分支）
      for (const ph of _WZC_PHASE_ORDER) {
        const t = _wzcPhaseTimings[ph];
        if (t.state === 'active' && t.endElapsed == null) t.endElapsed = elapsed;
        if (t.state !== 'pending') t.state = 'done';
      }
    } else if (_WZC_PHASE_ORDER.includes(cur)) {
      const curIdx = _WZC_PHASE_ORDER.indexOf(cur);
      for (let i = 0; i < _WZC_PHASE_ORDER.length; i++) {
        const t = _wzcPhaseTimings[_WZC_PHASE_ORDER[i]];
        if (i < curIdx) {
          if (t.startElapsed == null) t.startElapsed = 0;
          if (t.endElapsed == null)   t.endElapsed = elapsed;
          t.state = 'done';
        } else if (i === curIdx) {
          if (t.startElapsed == null) t.startElapsed = elapsed;
          t.state = 'active';
        } else {
          t.state = 'pending';
        }
      }
    }

    // —— 渲染各段 ——
    // 枚举
    {
      const t = _wzcPhaseTimings.enumerate;
      const explored = (p.enumerated || 0) + (p.branch_skipped || 0);
      const total = p.total_combos || 0;
      const pct = total > 0 ? Math.min(100, explored / total * 100) : 0;
      const detail = total > 0
        ? `${explored.toLocaleString()}/${total.toLocaleString()} · 入选 ${(p.after_haste_pruning||0).toLocaleString()} · 去重 ${(p.unique||0).toLocaleString()}`
        : '等待开始';
      if (t.state === 'done') {
        const dur = (t.endElapsed || elapsed) - (t.startElapsed || 0);
        _wzcSetPhase('enumerate', 'done', _wzcFmtDur(dur), detail, 100);
      } else if (t.state === 'active') {
        const phaseElapsed = elapsed - (t.startElapsed || 0);
        _wzcPushSample('enumerate', elapsed, explored);
        // 滑动窗口速率（套/s）；窗口不够样本时回退累积
        const rateWin = _wzcWindowRate(t.samples, elapsed);
        const rateCum = phaseElapsed > 0 ? explored / phaseElapsed * 1000 : 0;
        const rate = (rateWin && rateWin > 0) ? rateWin : rateCum;
        const remaining = Math.max(0, total - explored);
        const eta = rate > 0 ? remaining / rate * 1000 : null;
        const rateStr = rate > 0 ? `${Math.round(rate).toLocaleString()} 套/s` : '—';
        const time = eta != null
          ? `${_wzcFmtDur(phaseElapsed)} · 剩 ~${_wzcFmtDur(eta)} · ${rateStr}`
          : `${_wzcFmtDur(phaseElapsed)} · ${rateStr}`;
        _wzcSetPhase('enumerate', 'active', time, detail, pct);
      } else {
        _wzcSetPhase('enumerate', 'pending', '—', '等待开始', 0);
      }
    }
    // Pareto：active 期间 backend 用 simulated/target_simulated 推已处理的"点数"进度
    {
      const t = _wzcPhaseTimings.pareto;
      const isPareto = cur === 'pareto';
      const sim = isPareto ? (p.simulated || 0) : 0;
      const tar = isPareto ? (p.target_simulated || 0) : 0;
      const pct = tar > 0 ? sim / tar * 100 : 0;
      const detail = t.state === 'done'
        ? `${(p.unique||0).toLocaleString()} → ${(p.after_pareto||0).toLocaleString()}`
        : (t.state === 'active'
            ? (tar > 0
                ? `${sim.toLocaleString()}/${tar.toLocaleString()} (${pct.toFixed(0)}%)`
                : `唯一 ${(p.unique||0).toLocaleString()} 中…`)
            : '等待');
      if (t.state === 'done') {
        const dur = (t.endElapsed || elapsed) - (t.startElapsed || 0);
        _wzcSetPhase('pareto', 'done', _wzcFmtDur(dur), detail, 100);
      } else if (t.state === 'active') {
        const phaseElapsed = elapsed - (t.startElapsed || 0);
        if (tar > 0) {
          _wzcPushSample('pareto', elapsed, sim);
          const rateWin = _wzcWindowRate(t.samples, elapsed);
          const rateCum = phaseElapsed > 0 ? sim / phaseElapsed * 1000 : 0;
          const rate = (rateWin && rateWin > 0) ? rateWin : rateCum;
          const eta = rate > 0 ? (tar - sim) / rate * 1000 : null;
          const time = eta != null ? `${_wzcFmtDur(phaseElapsed)} · 剩 ~${_wzcFmtDur(eta)}` : _wzcFmtDur(phaseElapsed);
          _wzcSetPhase('pareto', 'active', time, detail, pct);
        } else {
          // fallback：无点数进度时用经验 ETA（≈4μs/件）
          const etaTotal = (p.unique || 0) * 0.0043;
          const eta = Math.max(0, etaTotal - phaseElapsed);
          const pulsePct = etaTotal > 0 ? Math.min(95, phaseElapsed / etaTotal * 100) : 50;
          const time = `${_wzcFmtDur(phaseElapsed)} · 剩 ~${_wzcFmtDur(eta * 1000)}`;
          _wzcSetPhase('pareto', 'active', time, detail, pulsePct);
        }
      } else {
        _wzcSetPhase('pareto', 'pending', '—', '等待', 0);
      }
    }
    // 属性预筛（rank）：30 次 sim 拿梯度（3 层 × 10）+ 全池打分排序
    //   保留数优先用 progress.after_rank（live 期间已写入），fallback result.stats
    {
      const t = _wzcPhaseTimings.rank;
      const sim = (cur === 'rank') ? (p.simulated || 0) : 0;
      const tar = (cur === 'rank') ? (p.target_simulated || 0) : 0;
      const pct = tar > 0 ? sim / tar * 100 : 0;
      const after = p.after_rank || p.result?.stats?.after_rank || 0;
      const detail = t.state === 'done'
        ? `保留前 ${after.toLocaleString()} 名`
        : (t.state === 'active'
            ? (tar > 0 ? `${sim}/${tar} 次梯度采样` : '采样中…')
            : '等待');
      if (t.state === 'done') {
        const dur = (t.endElapsed || elapsed) - (t.startElapsed || 0);
        _wzcSetPhase('rank', 'done', _wzcFmtDur(dur), detail, 100);
      } else if (t.state === 'active') {
        const phaseElapsed = elapsed - (t.startElapsed || 0);
        _wzcSetPhase('rank', 'active', _wzcFmtDur(phaseElapsed), detail, pct);
      } else {
        _wzcSetPhase('rank', 'pending', '—', '等待', 0);
      }
    }
    // 模拟（Phase A 全 sim）
    //   注意：Phase A 的 simulated/target_simulated 与 Phase B 的同字段共用进度状态，
    //   后端切到 phase_b 时 target_simulated 重置为 top_k_phase_b（默认 200）；
    //   此处只在 simulate 段 active 时才推样本，避免被 phase_b 阶段污染速率窗口。
    {
      const t = _wzcPhaseTimings.simulate;
      const sim = p.simulated || 0;
      const tar = p.target_simulated || 0;
      const pct = tar > 0 ? sim / tar * 100 : 0;
      const detail = tar > 0 ? `${sim.toLocaleString()}/${tar.toLocaleString()} (${pct.toFixed(0)}%)` : '等待';
      if (t.state === 'done') {
        const dur = (t.endElapsed || elapsed) - (t.startElapsed || 0);
        // p.simulated 在 phase 切到 phase_b 时被后端重置为 0；用 active 期间累记的 peakCount
        const finalSim = (p.result?.stats?.simulated) || t.peakCount || sim;
        _wzcSetPhase('simulate', 'done', _wzcFmtDur(dur), `${finalSim.toLocaleString()} 完成`, 100);
      } else if (t.state === 'active') {
        const phaseElapsed = elapsed - (t.startElapsed || 0);
        _wzcPushSample('simulate', elapsed, sim);
        if (sim > (t.peakCount || 0)) t.peakCount = sim;
        const rateWin = _wzcWindowRate(t.samples, elapsed);
        const rateCum = phaseElapsed > 0 ? sim / phaseElapsed * 1000 : 0;
        const rate = (rateWin && rateWin > 0) ? rateWin : rateCum;
        const eta = rate > 0 ? (tar - sim) / rate * 1000 : null;
        const rateStr = rate > 0 ? `${Math.round(rate).toLocaleString()}/s` : '—';
        const time = eta != null ? `${_wzcFmtDur(phaseElapsed)} · 剩 ~${_wzcFmtDur(eta)} · ${rateStr}` : _wzcFmtDur(phaseElapsed);
        _wzcSetPhase('simulate', 'active', time, detail, pct);
      } else {
        _wzcSetPhase('simulate', 'pending', '—', '等待', 0);
      }
    }
    // Phase B（偏导后处理：top-K 装备 → 9 维梯度 + 最佳非加速 enhance argmax + 1 final sim）
    {
      const t = _wzcPhaseTimings.phase_b;
      const sim = p.simulated || 0;
      const tar = p.target_simulated || 0;
      const pct = tar > 0 ? sim / tar * 100 : 0;
      const detail = tar > 0 ? `${sim.toLocaleString()}/${tar.toLocaleString()} 配置 (${pct.toFixed(0)}%)` : '等待';
      if (t.state === 'done') {
        const dur = (t.endElapsed || elapsed) - (t.startElapsed || 0);
        const fb = p.result?.stats?.phase_b_simulated;
        _wzcSetPhase('phase_b', 'done', _wzcFmtDur(dur), fb != null ? `${fb.toLocaleString()} 完成` : `${sim.toLocaleString()} 完成`, 100);
      } else if (t.state === 'active') {
        const phaseElapsed = elapsed - (t.startElapsed || 0);
        const eta = (sim > 0 && tar > 0) ? (tar - sim) / sim * phaseElapsed : null;
        const time = eta != null ? `${_wzcFmtDur(phaseElapsed)} · 剩 ~${_wzcFmtDur(eta)}` : _wzcFmtDur(phaseElapsed);
        _wzcSetPhase('phase_b', 'active', time, detail, pct);
      } else {
        _wzcSetPhase('phase_b', 'pending', '—', '等待', 0);
      }
    }

    // —— 总览 ——
    if (sumEl) {
      if (cur === 'done') {
        sumEl.textContent = `✓ 全部完成 · 总耗时 ${_wzcFmtDur(elapsed)}`;
        sumEl.style.color = '#3fb950';
      } else {
        // ETA 用滑动窗口速率 —— 累积速率会被早期/末段非线性偏置带走
        let etaTotal = null;
        if (cur === 'enumerate' && p.total_combos > 0) {
          const explored = (p.enumerated || 0) + (p.branch_skipped || 0);
          const t = _wzcPhaseTimings.enumerate;
          const phaseElapsed = elapsed - (t.startElapsed || 0);
          const rateWin = _wzcWindowRate(t.samples, elapsed);
          const rateCum = phaseElapsed > 0 && explored > 0 ? explored / phaseElapsed * 1000 : 0;
          const rate = (rateWin && rateWin > 0) ? rateWin : rateCum;
          etaTotal = rate > 0 ? (p.total_combos - explored) / rate * 1000 : null;
        } else if (cur === 'simulate' && p.target_simulated > 0) {
          const t = _wzcPhaseTimings.simulate;
          const phaseElapsed = elapsed - (t.startElapsed || 0);
          const rateWin = _wzcWindowRate(t.samples, elapsed);
          const rateCum = phaseElapsed > 0 && p.simulated > 0 ? p.simulated / phaseElapsed * 1000 : 0;
          const rate = (rateWin && rateWin > 0) ? rateWin : rateCum;
          etaTotal = rate > 0 ? (p.target_simulated - p.simulated) / rate * 1000 : null;
        }
        const phaseLabel = {
          enumerate: '装备组合 计算中',
          pareto:    '候选筛选 进行中',
          rank:      '属性预筛 进行中',
          simulate:  'DPS 测算 进行中',
          phase_b:   '附魔挑选 进行中',
        }[cur] || `当前: ${cur || '启动中'}`;
        sumEl.textContent = etaTotal != null
          ? `${phaseLabel} · 已用 ${_wzcFmtDur(elapsed)} · 当前阶段剩 ~${_wzcFmtDur(etaTotal)}`
          : `${phaseLabel} · 已用 ${_wzcFmtDur(elapsed)}`;
        sumEl.style.color = 'var(--gold)';
      }
    }
  }
  // Polling：POST 已经立即返回（backend spawn 后台任务），所以这里 GET /progress 不会被 POST 占连接。
  // 残留 done 识别：用 backend 的 started_at_ms 与 polling 启动时刻比较，
  //   started_at_ms < pollStart → 上一轮残留；否则视为本轮（即使本轮极快已完成）。
  //   这比 `seenNonDone` 标志稳：小池子搜索 < 一个 tick 间隔时，第一 poll 就 done，
  //   `seenNonDone` 永远 false 会让结果永远不渲染。
  function wzcStartPolling() {
    if (_wzcPollHandle) clearInterval(_wzcPollHandle);
    const pollStart = Date.now();
    let inFlight = false;
    let doneCount = 0;
    let resultRendered = false;
    const tick = async () => {
      if (inFlight) return;
      inFlight = true;
      try {
        const r = await fetch('/api/equip/auto_optimize/progress', { cache: 'no-store' });
        if (r.ok) {
          const p = await r.json();
          console.log('[wzc] poll', p.phase, p.simulated, '/', p.target_simulated, p.elapsed_ms+'ms', 'paused=', p.paused, 'cancelled=', p.cancelled, 'started_at=', p.started_at_ms);
          // 残留 done 识别：started_at_ms < pollStart - 1s → 上一轮残留
          //   宽 1s 是为了 POST 还在飞、backend 没刷 started_at_ms 时不误判
          const isStale = p.phase === 'done'
            && typeof p.started_at_ms === 'number' && p.started_at_ms > 0
            && p.started_at_ms < pollStart - 1000;
          if (isStale) {
            const sumEl = document.getElementById('wzc_phase_summary');
            if (sumEl) { sumEl.textContent = '正在准备…'; sumEl.style.color = 'var(--text-muted)'; }
            return;
          }
          wzcUpdateProgress(p);
          // 同步 暂停/取消 按钮文字
          const pauseBtn = document.getElementById('wzc_pause');
          if (pauseBtn) pauseBtn.textContent = p.paused ? '▶ 继续' : '⏸ 暂停';
          if (p.phase === 'done') {
            if (!resultRendered && p.result) {
              resultRendered = true;
              const elapsed = (p.elapsed_ms / 1000).toFixed(2);
              state.lastResult = p.result;
              state.lastResultAt = Date.now();
              state.lastResultElapsed = elapsed;
              saveWzcState();   // 持久化结果
              renderResult(p.result, elapsed);
              console.log('[wzc] result rendered + saved');
            }
            doneCount++;
            if (doneCount >= 2) {
              clearInterval(_wzcPollHandle);
              _wzcPollHandle = null;
              // 恢复按钮
              const runBtn = document.getElementById('wzc_run');
              const pauseBtn2 = document.getElementById('wzc_pause');
              const cancelBtn = document.getElementById('wzc_cancel');
              if (runBtn) runBtn.disabled = false;
              if (pauseBtn2) pauseBtn2.style.display = 'none';
              if (cancelBtn) cancelBtn.style.display = 'none';
              console.log('[wzc] polling stopped (phase=done seen)');
            }
          } else {
            doneCount = 0;
          }
        } else {
          console.warn('[wzc] http', r.status);
        }
      } catch (e) {
        console.error('[wzc] poll err', e);
      } finally {
        inFlight = false;
      }
    };
    _wzcPollHandle = setInterval(tick, 300);
    tick();
    console.log('[wzc] polling started, interval id =', _wzcPollHandle);
  }

  // 控制接口：cancel / pause / resume
  async function wzcControl(action) {
    try {
      const r = await fetch('/api/equip/auto_optimize/control', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action }),
      });
      const j = await r.json();
      console.log('[wzc] control', action, '→', j);
    } catch (e) {
      console.error('[wzc] control err', e);
    }
  }
  document.getElementById('wzc_pause')?.addEventListener('click', async () => {
    const btn = document.getElementById('wzc_pause');
    const isPaused = btn.textContent.indexOf('继续') >= 0;
    await wzcControl(isPaused ? 'resume' : 'pause');
    // 文字立即翻转（poll 也会刷新）
    btn.textContent = isPaused ? '⏸ 暂停' : '▶ 继续';
  });
  document.getElementById('wzc_cancel')?.addEventListener('click', async () => {
    if (!confirm('确定要终止当前搜索吗？已完成的部分模拟会作为结果保留。')) return;
    await wzcControl('cancel');
  });

  // 调试钩子
  window._wzc_debug = {
    get state() { return state; },
    get pollHandle() { return _wzcPollHandle; },
    forceTick: async () => {
      const r = await fetch('/api/equip/auto_optimize/progress');
      const p = r.ok ? await r.json() : null;
      console.log('[wzc] forceTick', p);
      wzcUpdateProgress(p);
      return p;
    },
  };

  // ─── 通用属性收益接口（暴露给配装器 / 模拟器 / 广场 / 宏优化器复用） ───
  // 业务流程由调用方组装（DPS 来源 / 装备 dict / Attributes 各页面不同），
  // 这里只提供：(1) loading 状态管理 + fetch (2) drawer 渲染
  //
  //   buildBody: async () => SimulateRequest body（含拟合参数 order/pert_delta/axis_scale）
  //   title: drawer 顶部标题前缀（DPS 后缀由 ref_dps 自动追加）
  //   button: 触发按钮 DOM，loading 期间显示 "⏳ 计算中…"
  async function _runFitCurveAndShow({ buildBody, title, button }) {
    const origBtnText = button?.textContent;
    if (button) { button.disabled = true; button.textContent = '⏳ 计算中…'; }
    try {
      const body = await buildBody();
      const resp = await fetch('/api/equip/fit_curve', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!resp.ok) throw new Error(await resp.text());
      const data = await resp.json();
      if (!data.feasible || !data.fit_model) throw new Error(data.error || '拟合失败');
      const dpsTitle = `${title || '属性收益曲线'} · DPS ${Math.round(data.ref_dps).toLocaleString()}`;
      _wzcOpenCurveDrawer(dpsTitle, data.fit_model, data.sim_count, data.elapsed_ms);
    } catch (err) {
      console.error('[fit_curve]', err);
      alert('属性收益计算失败：' + (err?.message || err));
    } finally {
      if (button) { button.disabled = false; if (origBtnText) button.textContent = origBtnText; }
    }
  }

  // 把当前 raw（来自 /api/equip/calculate）转成 SimulateRequest.attributes 字段
  function _wzcRawToAttrs(r) {
    return {
      li_dao: r.strength || 0,
      shen_fa: r.agility || 0,
      vitality: r.vitality || 0,
      gen_gu: 44, yuan_qi: 44,
      base_attack: r.base_attack || 0,
      base_magical_attack: r.base_magical_attack || 0,
      weapon_damage: r.weapon_damage || 0,
      surplus_value: r.surplus_value || 0,
      crit_level: r.crit_level || 0,
      crit_effect_level: r.crit_effect_level || 0,
      overcome_level: r.overcome_level || 0,
      strain_level: r.strain_level || 0,
      haste_level: r.haste_level || 0,
      parry_value: r.parry_value || 0,
      parry_level: r.parry_level || 0,
    };
  }

  // 把配装器风格的 cfg.slots → fit_curve 用的 equipment dict（POS + ENCHANT_POS）
  function _wzcSlotsToEquipDict(slots) {
    const eq = {};
    Object.entries(slots || {}).forEach(([pos, slot]) => {
      if (slot?.equip_id) eq[pos] = slot.equip_id;
      if (slot?.enchant_id) eq[`ENCHANT_${pos}`] = slot.enchant_id;
    });
    return eq;
  }

  // 暴露通用接口
  window.Jx3FitCurve = {
    /** 给定 buildBody / title / button，跑 fit_curve 并显示 drawer */
    runAndShow: _runFitCurveAndShow,
    /** raw → Attributes 转换（fit_curve body.attributes 字段） */
    rawToAttrs: _wzcRawToAttrs,
    /** cfg.slots → equipment dict（含 ENCHANT_*） */
    slotsToEquipDict: _wzcSlotsToEquipDict,
  };

  // ─── 导入循环：从 userdata/loops/ 选一个 JSON，把 macro / talents / recipes / env 一并加载 ─────
  // _wzcMacroFromCfg / _wzcFlattenTalents / _wzcFlattenRecipes 已移除；
  // 调用方改用全局 stanceMacroToString / flattenTalents / flattenRecipes

  function _closeWzcImportModal() {
    const o = document.getElementById('wzc_import_overlay');
    if (o) o.remove();
  }

  // 从 plaza build 或 loop 存档 cfg 抽出循环来源（macro / talents / recipes / target / duration）
  function _wzcExtractEnvFromBuild(b) {
    const rot = b?.rotation || {};
    const cfg = { macro: rot.macro, talents: b?.talents, recipes: b?.recipes, target: b?.target,
                  macro_duration: rot.macro_duration };
    const env = _wzcExtractEnvFromCfg(cfg);
    // plaza build 携带完整装备（slots / stoneId / stoneName / mount），导入后接管 wzc 的"当前装备"列
    env.equipment = b?.equipment || null;
    return env;
  }
  function _wzcExtractEnvFromCfg(cfg) {
    return {
      macro:    stanceMacroToString(cfg),
      talents:  flattenTalents(cfg?.talents),
      recipes:  flattenRecipes(cfg?.recipes),
      target:   cfg?.target || null,
      duration: cfg?.macro_duration != null ? cfg.macro_duration : cfg?.duration,
      equipment: null,   // loop 存档（buildLoopConfig）不含装备
    };
  }

  async function openImportPicker() {
    _closeWzcImportModal();
    const overlay = document.createElement('div');
    overlay.id = 'wzc_import_overlay';
    overlay.className = 'modal-overlay';
    // 与 openImportLoopModal / openEquipPickerModal 一致的左右双栏：左列表 + 右预览
    overlay.innerHTML = `
      <div class="talent-modal equip-picker-modal" style="min-width:680px;max-width:880px">
        <div class="talent-header">
          <span>导入循环来源</span>
          <button class="talent-close" type="button">&times;</button>
        </div>
        <div class="talent-body" style="display:flex;gap:12px">
          <div id="wzc_imp_body" style="flex:1.4;min-width:0;max-height:520px;overflow:auto">
            <div class="equip-picker-empty">正在加载…</div>
          </div>
          <div id="wzc_imp_preview" style="flex:1;min-width:0;border-left:1px solid var(--border-soft);padding-left:12px;font-size:12px;color:var(--text-muted);max-height:520px;overflow:auto">
            <div style="color:var(--text-muted);text-align:center;padding:30px 6px">点击左侧某行查看预览</div>
          </div>
        </div>
        <div class="equip-picker-actions">
          <button class="sim-btn" id="wzc_imp_cancel">取消</button>
          <span class="equip-picker-spacer"></span>
          <button class="sim-btn primary" id="wzc_imp_apply" disabled>应用</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const close = _closeWzcImportModal;
    overlay.querySelector('.talent-close')?.addEventListener('click', close);
    overlay.querySelector('#wzc_imp_cancel')?.addEventListener('click', close);
    overlay.addEventListener('click', e => { if (e.target === overlay) close(); });

    const body = overlay.querySelector('#wzc_imp_body');
    const previewEl = overlay.querySelector('#wzc_imp_preview');
    const applyBtn = overlay.querySelector('#wzc_imp_apply');

    // 与 openImportLoopModal 一致的预览：目标 / 时长 / 网络延迟 / 起始怒气 / Boss 间隔 /
    //   奇穴秘籍数 / 序列项数 / 宏字符数。来自 plaza Build 时再从 build.* 取计数。
    function macroSummary(macro) {
      if (!macro) return '（无宏）';
      if (typeof macro === 'string') return macro.length > 0 ? `${macro.length} 字符` : '（空）';
      const stance = macro.shield || macro.blade;
      if (stance) {
        const parts = [];
        if (macro.shield) parts.push(`擎盾 ${macro.shield.length}c`);
        if (macro.blade)  parts.push(`擎刀 ${macro.blade.length}c`);
        return `多页：${parts.join(' / ')}`;
      }
      const len = (macro.general || '').length;
      return len > 0 ? `${len} 字符` : '（空）';
    }
    function renderPreview(cfg, label) {
      const tCnt = flattenTalents(cfg?.talents).length;
      const rCnt = flattenRecipes(cfg?.recipes).length;
      const macroText = macroSummary(cfg?.macro);
      const tgt = cfg?.target || {};
      const dur = cfg?.macro_duration ?? cfg?.duration;
      const seqN = Array.isArray(cfg?.sequence) ? cfg.sequence.length : 0;
      previewEl.innerHTML = `
        <div style="color:var(--gold);font-weight:600;font-size:13px;margin-bottom:8px">${escapeHtml(label || '预览')}</div>
        <div style="display:grid;grid-template-columns:auto 1fr;gap:4px 10px;color:var(--text)">
          <span style="color:var(--text-muted)">目标</span><span>Lv${tgt.level ?? '—'} 防御加成 ${tgt.defense_bonus ?? 0}</span>
          <span style="color:var(--text-muted)">时长</span><span>${dur != null ? dur + 's' : '—'}</span>
          <span style="color:var(--text-muted)">网络延迟</span><span>${cfg?.network_delay ?? 0} ms</span>
          <span style="color:var(--text-muted)">起始怒气</span><span>${cfg?.initial_rage ?? 0}</span>
          <span style="color:var(--text-muted)">Boss 间隔</span><span>${cfg?.boss_attack_interval ?? 0}s</span>
          <span style="color:var(--text-muted)">奇穴</span><span>${tCnt} 个</span>
          <span style="color:var(--text-muted)">秘籍</span><span>${rCnt} 个</span>
          <span style="color:var(--text-muted)">序列</span><span>${seqN} 项</span>
          <span style="color:var(--text-muted)">宏文本</span><span>${escapeHtml(macroText)}</span>
        </div>
      `;
    }
    async function showPreviewForRow(picked) {
      if (!picked) {
        previewEl.innerHTML = '<div style="color:var(--text-muted);text-align:center;padding:30px 6px">点击左侧某行查看预览</div>';
        return;
      }
      try {
        if (picked.dataset.source === 'build') {
          const b = window.Jx3Plaza?.get?.(picked.dataset.id);
          if (!b) { previewEl.innerHTML = `<div style="color:#f85149;padding:8px">方案已丢失</div>`; return; }
          // plaza build 的 talents/recipes 是扁平数组，rotation 含 macro 对象
          const cfg = {
            macro: b.rotation?.macro,
            talents: b.talents,
            recipes: b.recipes,
            target: b.target,
            macro_duration: b.rotation?.macro_duration,
            network_delay: b.rotation?.delay,
            initial_rage: b.rotation?.initial_rage,
            boss_attack_interval: b.rotation?.boss_attack_interval,
            sequence: b.rotation?.sequence,
          };
          renderPreview(cfg, b.name || '(未命名方案)');
        } else if (picked.dataset.source === 'loop') {
          const fname = picked.dataset.file;
          previewEl.innerHTML = '<div style="color:var(--text-muted);padding:8px">加载中…</div>';
          const r = await fetch('/api/loop/load?name=' + encodeURIComponent(fname));
          const data = await r.json();
          if (data.error) { previewEl.innerHTML = `<div style="color:#f85149;padding:8px">加载失败：${escapeHtml(data.error)}</div>`; return; }
          renderPreview(data, fname);
        }
      } catch (e) {
        previewEl.innerHTML = `<div style="color:#f85149;padding:8px">请求失败：${escapeHtml(e.message)}</div>`;
      }
    }

    async function fetchLoopFiles() {
      try {
        const r = await fetch('/api/loop/list');
        if (!r.ok) return [];
        const j = await r.json();
        return Array.isArray(j?.files) ? j.files : [];
      } catch { return []; }
    }

    function renderBody(builds, loopFiles) {
      const esc = escapeHtml;
      let html = '';
      // 方案文件（plaza builds）
      html += '<div class="equip-picker-section-title">方案文件</div>';
      html += '<table class="equip-picker-table"><thead><tr><th>名称</th><th>创建时间</th><th>概览</th></tr></thead><tbody>';
      if (builds.length === 0) {
        html += `<tr class="ep-row-empty"><td colspan="3">暂无方案。在战斗广场新建方案，或从结果卡 [📤 广场] 发送后会出现在这里。</td></tr>`;
      } else {
        for (const b of builds) {
          const macro = stanceMacroToString({ macro: b.rotation?.macro });
          const tCnt = (b.talents || []).length;
          const rCnt = Array.isArray(b.recipes) ? b.recipes.length : 0;
          const hasMacro = !!(macro && macro.trim());
          html += `<tr class="ep-row" data-source="build" data-pickable="${hasMacro ? 1 : 0}" data-id="${esc(b.id)}">
            <td><span class="ep-cell-name">${esc(b.name || '(未命名)')}</span>${hasMacro ? '' : '<span class="ep-cell-tag">无宏</span>'}</td>
            <td class="ep-cell-dim">${fmtTs(b.created_at)}</td>
            <td>${tCnt} 奇穴 / ${rCnt} 秘籍${b.rotation?.macro_duration ? ` · ${b.rotation.macro_duration}s` : ''}</td>
          </tr>`;
        }
      }
      html += '</tbody></table>';
      // userdata/loops 文件
      html += '<div class="equip-picker-section-title" style="margin-top:14px">userdata/loops/ 存档</div>';
      html += '<table class="equip-picker-table"><thead><tr><th>文件名</th><th></th><th></th></tr></thead><tbody>';
      if (loopFiles.length === 0) {
        html += `<tr class="ep-row-empty"><td colspan="3">暂无存档（在循环模拟页保存循环后会出现在这里）。</td></tr>`;
      } else {
        for (const f of loopFiles) {
          html += `<tr class="ep-row" data-source="loop" data-pickable="1" data-file="${esc(f)}">
            <td><span class="ep-cell-name">${esc(f)}</span></td>
            <td></td><td></td>
          </tr>`;
        }
      }
      html += '</tbody></table>';
      return html;
    }

    function bindRowSelect() {
      body.querySelectorAll('.ep-row[data-pickable="1"]').forEach(row => {
        row.addEventListener('click', () => {
          body.querySelectorAll('.ep-row.selected').forEach(r => r.classList.remove('selected'));
          row.classList.add('selected');
          applyBtn.disabled = false;
          showPreviewForRow(row);
        });
        row.addEventListener('dblclick', () => {
          row.click();
          applyBtn.click();
        });
      });
    }

    const builds = (window.Jx3Plaza?.list?.() || []);
    const loopFiles = await fetchLoopFiles();
    body.innerHTML = renderBody(builds, loopFiles);
    bindRowSelect();

    applyBtn.addEventListener('click', async () => {
      const picked = body.querySelector('.ep-row.selected');
      if (!picked) return;
      let env = null;
      let label = '';
      try {
        if (picked.dataset.source === 'build') {
          const b = window.Jx3Plaza?.get?.(picked.dataset.id);
          if (!b) throw new Error('方案已丢失');
          env = _wzcExtractEnvFromBuild(b);
          label = b.name || '(未命名方案)';
        } else if (picked.dataset.source === 'loop') {
          const fname = picked.dataset.file;
          const r = await fetch('/api/loop/load?name=' + encodeURIComponent(fname));
          const data = await r.json();
          if (data.error) throw new Error(data.error);
          env = _wzcExtractEnvFromCfg(data);
          label = fname;
        }
      } catch (e) {
        alert('导入失败：' + e.message);
        return;
      }
      if (!env || !env.macro) { alert('该来源没有宏文本'); return; }
      state.env.source          = 'import';
      state.env.importedFile    = label;
      state.env.importedMacro   = env.macro;
      state.env.importedTalents = env.talents || [];
      state.env.importedRecipes = env.recipes || [];
      state.env.importedEquipment = env.equipment || null;
      const setVal = (id, v) => { if (v != null && v !== '') { const el = document.getElementById(id); if (el) el.value = v; } };
      if (env.target?.level != null) setVal('wzc_target_level', env.target.level);
      if (env.duration != null) setVal('wzc_duration', env.duration);
      // 装备来源切到导入方案：清空 wzc 内单件覆盖（用户决策：换源 = 重置参考装备），
      // 刷新候选池表的"当前装备"列；perSlot 的 lock/enum 状态保留不动
      state.slotOverrides = {};
      syncCurrentEquip();
      renderCandsTable();
      renderEnv();
      saveWzcState();
      close();
    });
  }

  // 跑搜索（v3：polling 跟页面生命周期，不绑搜索）
  async function runSearch() {
    const btn = document.getElementById('wzc_run');
    btn.disabled = true;

    const fixed = {};
    const cands = {};
    // 装备来源：source==='import' 且导入方案带装备时用导入装备，否则用配装器
    // 这样基线 + lock 部位 + 候选位的 default_enchants 都跟随导入方案
    const cfg = _wzcActiveCfg() || { slots: {} };
    // 大/小附魔默认继承当前配装（user toggle 决定是否启用）
    const inheritEnchants = !!document.getElementById('wzc_inherit_enchants')?.checked;
    const default_enchants = {};
    const default_enhances = {};
    // 锁定槽位中"小附魔不锁"的集合 → 进 enhance_candidates 让 Phase B 搜索
    const unlockEnhanceLocked = new Set();
    let stoneIdToSend = cfg.stoneId || 0;
    POS_LIST.forEach(pos => {
      const ps = state.perSlot[pos];
      if (ps.mode === 'lock') {
        const src = cfg.slots[pos];
        if (!src) return;
        // 子开关：lockEnchant=false → 清空大附魔；lockEnhance=false → 清空小附魔（让 Phase B 选）
        const slotCopy = { ...src };
        if (!ps.lockEnchant) slotCopy.enchant_id = 0;
        if (!ps.lockEnhance) {
          slotCopy.enhance_id = 0;
          unlockEnhanceLocked.add(pos);
        }
        fixed[pos] = slotCopy;
        // 主武器：lockStone=false → 不带五彩石（仅主武器有此 sub-toggle）
        if (pos === 'PRIMARY_WEAPON' && !ps.lockStone) stoneIdToSend = 0;
      } else if (ps.candidates.length > 0) {
        cands[pos] = ps.candidates.map(it => it.id);
        // 仅枚举位才需要传递 default_enchants/enhances（lock 位的 SlotConfig 已自带）
        if (inheritEnchants && cfg.slots[pos]) {
          const eid = cfg.slots[pos].enchant_id || 0;
          const enh = cfg.slots[pos].enhance_id || 0;
          if (eid > 0) default_enchants[pos] = eid;
          if (enh > 0) default_enhances[pos] = enh;
        }
      }
    });
    if (Object.keys(cands).length === 0) {
      alert('没有可枚举部位的候选。先点候选池工具栏里的"全部刷新候选"按当前筛选拉取，或针对单个部位点"🔍 筛选"。');
      btn.disabled = false;
      return;
    }
    // 环境字段：input 当前值优先；macro/talents/recipes 跟 source（loop / import）
    const env = getActiveLoopInputs();
    const macroText = env.macro_text || '';
    const envTalents = env.talents;
    const envRecipes = env.recipes;
    if (!macroText.trim()) {
      alert(state.env.source === 'import'
        ? '导入的存档没有宏文本'
        : '当前循环没有宏文本，请到「循环模拟」页填好后再回来');
      btn.disabled = false;
      return;
    }
    // 多区间：空数组 = 无段位约束（fallback 到 [0, cap]）；后端 target_haste 接受 Vec<HasteRange>
    const cap = state.hasteCap || 100000;
    const hasteSegments = (state.hasteSegments && state.hasteSegments.length > 0)
      ? state.hasteSegments.map(s => ({ min: s.min, max: s.max }))
      : [{ min: 0, max: cap }];
    const dur = getEnvValue('wzc_duration', 300);
    // 防御加成跟随主设置（getTarget() 读循环模拟页 target_defense_bonus）
    const tgtMain = (typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 };
    const targetCfg = {
      level: getEnvValue('wzc_target_level', tgtMain.level),
      defense_bonus: tgtMain.defense_bonus || 0,
    };
    // Boss 攻击间隔跟随主设置（设置面板的 slider，存 localStorage）
    const bossInterval = (typeof getBossAttackInterval === 'function') ? getBossAttackInterval() : 0;
    const embedLv = getEnvEmbed();

    document.getElementById('wzc_pbox').style.display = 'block';
    wzcResetPhaseTimings();   // 新搜索：重置阶段时间戳
    wzcUpdateProgress(null);
    // 显示控制按钮
    const pauseBtn = document.getElementById('wzc_pause');
    const cancelBtn = document.getElementById('wzc_cancel');
    if (pauseBtn) { pauseBtn.style.display = ''; pauseBtn.textContent = '⏸ 暂停'; }
    if (cancelBtn) cancelBtn.style.display = '';
    wzcStartPolling();

    // Phase A 加速 enhance + Phase B 偏导 enhance 候选（按 enum 部位 auto-derive）
    let phaseInputs = { haste_enhance_ids: {}, enhance_candidates: {} };
    try {
      phaseInputs = await wzcDerivePhaseInputs(Object.keys(cands));
      console.log('[wzc] phase inputs derived:', phaseInputs);
    } catch (e) {
      console.warn('[wzc] phase inputs derive failed:', e);
    }

    // 锁定槽：只有"小附魔不锁"(unlockEnhanceLocked) 的进 enhance_candidates；锁住的剔除
    const finalEnhanceCandidates = {};
    for (const pos of Object.keys(phaseInputs.enhance_candidates || {})) {
      const ids = phaseInputs.enhance_candidates[pos] || [];
      if (!ids.length) continue;
      const ps = state.perSlot[pos];
      if (!ps) continue;
      if (ps.mode === 'enum') {
        finalEnhanceCandidates[pos] = ids;
      } else if (ps.mode === 'lock' && unlockEnhanceLocked.has(pos)) {
        finalEnhanceCandidates[pos] = ids;
      }
      // mode='lock' 且 lockEnhance=true → 不进 Phase B（保持配装器值）
    }

    const body = {
      fixed_slots: fixed,
      candidates: cands,
      target_haste: hasteSegments,
      duration: dur,
      mount: getMountId(),
      talents: envTalents,
      recipes: envRecipes,
      macro_text: macroText,
      target: targetCfg,
      network_delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      initial_rage: (typeof adminInitialRage !== 'undefined') ? (adminInitialRage || 0) : 0,
      boss_attack_interval: bossInterval > 0 ? bossInterval : 0,
      // 与模拟器主页面同步：铁骨气劲 / 实验性武学 / 寒甲期望 / 团队增益
      tiegu_mode: (typeof getTieguMode === 'function') ? getTieguMode() : 2,
      experimental: (typeof isExperimental === 'function') ? isExperimental() : false,
      hanjia_expectation: (typeof isHanjiaExpectationEnabled === 'function') ? isHanjiaExpectationEnabled() : false,
      team_buffs: (typeof getTeamBuffs === 'function') ? getTeamBuffs() : [],
      formation: (typeof getCurrentFormation === 'function') ? getCurrentFormation() : null,
      top_n: 8,
      use_pareto: !!document.getElementById('wzc_use_pareto')?.checked,
      bucket_size: Math.max(0, parseInt(document.getElementById('wzc_bucket_size')?.value, 10) || 500),
      stone_id: stoneIdToSend,              // 主武器锁定且五彩石不锁则置 0；其余沿用 cfg.stoneId
      default_strength: embedLv,
      default_embedding: [embedLv, embedLv, embedLv],
      default_enchants,
      default_enhances,
      // ─── 新搜索维度（外攻 build 自动配置）─────────────────────────
      haste_enhance_ids: phaseInputs.haste_enhance_ids,
      enhance_candidates: finalEnhanceCandidates,
      top_k_phase_b: 200,
      // 锁定槽是否搜索附魔现在由 enhance_candidates 是否含该 pos 决定（per-slot），
      // 这里恒传 true 让后端按 enhance_candidates 内容跑 Phase B。
      search_locked_enhance: true,
    };
    // 缓存搜索上下文（"发送到广场"按钮要用这些字段重建完整方案）
    const lockedSlotsSnapshot = {};
    POS_LIST.forEach(pos => {
      if (state.perSlot[pos]?.mode === 'lock' && cfg.slots?.[pos]) {
        lockedSlotsSnapshot[pos] = { ...cfg.slots[pos] };
      }
    });
    state.lastSearchCtx = {
      embedLv,
      default_enchants: { ...default_enchants },
      lockedSlots: lockedSlotsSnapshot,
      target: targetCfg,
      duration: dur,
      macro_text: macroText,
      talents: envTalents,
      recipes: envRecipes,
      network_delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
      initial_rage: (typeof adminInitialRage !== 'undefined') ? (adminInitialRage || 0) : 0,
      boss_attack_interval: bossInterval > 0 ? bossInterval : 0,
      stone_id: stoneIdToSend,
      stone_name: cfg.stoneName || '',
      mount: getMountId(),
      mount_key: (typeof currentMountKey === 'function') ? currentMountKey() : (currentMount?.mount || null),
      mount_label: currentMount?.mount_label || '',
      // 全局 simulate 参数快照（fit_curve / 发送广场 时复用，避免用户搜完改了全局导致 DPS 对不上）
      hanjia_expectation: (typeof isHanjiaExpectationEnabled === 'function') ? isHanjiaExpectationEnabled() : false,
      tiegu_mode: (typeof getTieguMode === 'function') ? getTieguMode() : 2,
      experimental: (typeof isExperimental === 'function') ? isExperimental() : false,
      team_buffs: (typeof getTeamBuffs === 'function') ? getTeamBuffs() : [],
      formation: (typeof getCurrentFormation === 'function') ? getCurrentFormation() : null,
    };
    console.log('[wzc] POST auto_optimize 启动 (candidates:', Object.keys(cands).length, 'positions)');
    // POST 立即返回 {ok:true} —— 后端把搜索 spawn 到后台任务，结果通过 progress.result 拉
    try {
      const r = await fetch('/api/equip/auto_optimize', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!r.ok) throw new Error(await r.text());
      const ack = await r.json();
      console.log('[wzc] POST ack:', ack);
      // 不在此 enable button —— polling 看到 done 后才 enable
    } catch (e) {
      alert('启动搜索失败：' + e.message);
      console.error('[wzc] POST error', e);
      btn.disabled = false;
      // POST 都没起来，直接停 polling
      if (_wzcPollHandle) { clearInterval(_wzcPollHandle); _wzcPollHandle = null; }
    }
  }
  document.getElementById('wzc_run').addEventListener('click', runSearch);

  // ─── 模型评价指标卡片 ─────────────────────────────────────────────
  // 渲染顶部"S6 二次拟合"质量卡：R² / top10 重合 / RMSE / 样本数
  // metrics 为 null 时返回空串（小池子或失败路径不显示）
  function wzcRenderFitMetricsCard(metrics, model) {
    if (!metrics || !model) return '';
    const r2 = (metrics.r_squared * 100).toFixed(2);
    const r2Color = metrics.r_squared >= 0.95 ? '#3fb950'
                  : metrics.r_squared >= 0.9 ? '#d4a017'
                  : '#f85149';
    const overlapColor = metrics.top10_overlap >= 8 ? '#3fb950'
                       : metrics.top10_overlap >= 6 ? '#d4a017'
                       : '#f85149';
    return `
      <div class="wzc-fit-card" data-wzc-tip="S6 二次拟合（55 sims 一次性算 9 维 grad + Hessian），用于属性收益曲线和搜索质量评估。R² 越接近 100% 越准；top10 重合表示拟合预测 top10 与真实 top10 的交集（满分 10）。">
        <span class="wzc-fit-title">📊 模型评价：</span>
        <span class="wzc-fit-stat">R²：<b style="color:${r2Color}">${r2}%</b></span>
        <span class="wzc-fit-stat">top10 重合：<b style="color:${overlapColor}">${metrics.top10_overlap}/10</b></span>
        <span class="wzc-fit-stat">RMSE：<b>${Math.round(metrics.rmse).toLocaleString()}</b></span>
        <span class="wzc-fit-stat">MAE：<b>${Math.round(metrics.mae).toLocaleString()}</b></span>
        <span class="wzc-fit-stat">样本：<b>${metrics.fit_samples}</b> 拟合 + <b>${metrics.validation_samples.toLocaleString()}</b> 验证</span>
        <span class="wzc-fit-stat">池子：<b>${model.pool_size.toLocaleString()}</b></span>
      </div>
    `;
  }

  function renderResult(resp, elapsedStr) {
    document.getElementById('wzc_result_wrap').style.display = '';
    // 缓存 S6 拟合数据，供"属性收益曲线"展开按钮使用
    state.lastFitModel = resp.fit_model || null;
    state.lastFitMetrics = resp.fit_metrics || null;
    state.expandedCurveIdx = new Set();   // 新搜索：清空展开状态
    if (!resp.feasible) {
      document.getElementById('wzc_summary').innerHTML = `<div style="color:#f85149">不可行：${(resp.warnings || []).join('; ') || '未知'}</div>`;
      document.getElementById('wzc_top_body').innerHTML = '';
      document.getElementById('wzc_stats').textContent = JSON.stringify(resp.stats || {}, null, 2);
      return;
    }
    const s = resp.stats || {};
    const phaseBLine = (s.phase_b_bases > 0)
      ? `<div data-wzc-tip="对前 N 套候选配装，每套用梯度评估方法挑出最佳的小附魔组合，再补一次模拟得到最终 DPS">附魔挑选：从前 ${s.phase_b_bases} 套候选配装中各选最优小附魔（${s.phase_b_simulated.toLocaleString()} 次模拟，${(s.time_phase_b_ms / 1000).toFixed(1)}s）</div>`
      : '';
    // 智能模式 vs 完整模拟（池子 > 1百万 时启用预筛，否则全 sim）
    const smartMode = !!s.smart_mode;
    const weaponLocked = !!s.weapon_locked;
    let modeBadge;
    if (smartMode) {
      if (weaponLocked) {
        modeBadge = `<span class="wzc-mode-badge wzc-mode-smart" data-wzc-tip="池子 > 1百万，已启用 S6 Hessian 预筛（55 sims 一次性算完整 Hessian 排序取 top）。主武器已锁定，精度可信。">⚡ 智能模式</span>`;
      } else {
        modeBadge = `<span class="wzc-mode-badge wzc-mode-warn" data-wzc-tip="智能模式启用但主武器未锁定。候选池如混紫武/橙武，特殊效果非线性可能导致排名偏差，建议锁定主武器后重跑。">⚠️ 智能模式 · 武器未锁</span>`;
      }
    } else {
      modeBadge = `<span class="wzc-mode-badge wzc-mode-full" data-wzc-tip="池子规模适中，直接全部模拟。结果精度最高。">🎯 完整模拟</span>`;
    }
    const rankSeg = smartMode
      ? ` → <span data-wzc-tip="智能模式：S6 Hessian 梯度预筛后保留的 top 数（55 次模拟一次性算完整 Hessian，按预测 DPS 排序取前 N）">梯度预筛 ${s.after_rank.toLocaleString()}</span>`
      : '';
    const rankTimeSeg = (s.time_rank_ms > 0) ? ` · 梯度预筛 ${(s.time_rank_ms / 1000).toFixed(1)}s` : '';
    const warnings = (resp.warnings || []).filter(w => w);
    const warnBanner = warnings.length > 0
      ? `<div class="wzc-warn-banner">⚠ ${warnings.map(escapeHtml).join('<br>⚠ ')}</div>`
      : '';
    document.getElementById('wzc_summary').innerHTML = `
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
        <span data-wzc-tip="只算锁定部位 + 大附魔的基础 DPS（不含搜索枚举位的装备）。这是搜索的对照基准 — 每张候选卡上的「+X.XX%」就是相对此值的提升。和「循环模拟」页跑出来的 DPS 不一样，那里用的是你当前完整配装。">基线 DPS：<b>${Math.round(resp.baseline_dps).toLocaleString()}</b>（加速 ${resp.baseline_haste}）</span>
        ${modeBadge}
      </div>
      ${warnBanner}
      <div data-wzc-tip="搜索的数据漏斗：从所有可能组合层层筛减到最终模拟的配置数。鼠标悬停每段查看含义。">
        <span data-wzc-tip="按你设定的筛选条件，所有部位候选装备的笛卡尔积总数">全部组合 ${s.total_combinations.toLocaleString()}</span>
         → <span data-wzc-tip="去掉加速达不到目标段位的组合（haste 硬约束剪枝）">加速达标 ${s.after_haste_pruning.toLocaleString()}</span>
         → <span data-wzc-tip="把属性完全等价的不同组合折叠成一个（按累加属性 hash 去重）">去重 ${s.unique_keys.toLocaleString()}</span>
         → <span data-wzc-tip="按 8 维属性 Pareto 比较，剔除被其它组合全面碾压的劣势配置">精选 ${s.after_pareto.toLocaleString()}</span>${rankSeg}
         → <span data-wzc-tip="对剩余配置逐一跑战斗模拟得到真实 DPS">实际模拟 ${s.simulated.toLocaleString()}</span>
      </div>
      ${phaseBLine}
      <div data-wzc-tip="各阶段耗时累加。枚举 = 计算所有候选属性；筛选 = Pareto 剔劣；预筛 = 梯度排序；模拟 = 实际跑 DPS；附魔 = 小附魔挑选">耗时：枚举 ${(s.time_calc_ms / 1000).toFixed(1)}s · 筛选 ${(s.time_pareto_ms / 1000).toFixed(1)}s${rankTimeSeg} · 模拟 ${(s.time_simulate_ms / 1000).toFixed(1)}s${s.time_phase_b_ms > 0 ? ` · 附魔 ${(s.time_phase_b_ms / 1000).toFixed(1)}s` : ''} · 合计 ${(s.time_total_ms / 1000).toFixed(1)}s${(Math.abs((parseFloat(elapsedStr) || 0) - s.time_total_ms / 1000) > 1.0) ? `（实际 ${elapsedStr}s）` : ''}</div>
    `;
    // 把所有 [data-wzc-tip] 元素绑到模拟器全局 tooltip（智能定位 + 多行支持），不用浏览器原生 title
    document.getElementById('wzc_summary').querySelectorAll('[data-wzc-tip]').forEach(el => {
      const tip = el.dataset.wzcTip;
      if (!tip) return;
      el.style.cursor = 'help';
      el.addEventListener('mouseenter', () => wzcShowHover(el, escapeHtml(tip), true));
      el.addEventListener('mouseleave', wzcHideHover);
    });
    // 异步预加载所有部位的附魔表（用来把 enhance ID 转成名字）
    const subs = new Set(Object.values(POS_TO_SUB));
    Promise.all([...subs].map(s => wzcGetEnhances(s).catch(() => [])))
      .then(() => renderResultCards(resp.top || []));
    // 先渲染一遍（附魔名可能还是 ID，预加载完后会再刷一次）
    renderResultCards(resp.top || []);
    document.getElementById('wzc_stats').textContent = JSON.stringify(resp.stats, null, 2);
  }

  function renderResultCards(top) {
    const enhNameOf = (pos, eid) => {
      if (!eid) return null;
      const list = _wzcEnhCache.get(POS_TO_SUB[pos]) || [];
      const e = list.find(x => x.id === eid);
      return e?.name || `#${eid}`;
    };
    const enhEntryOf = (pos, eid) => {
      if (!eid) return null;
      const list = _wzcEnhCache.get(POS_TO_SUB[pos]) || [];
      return list.find(x => x.id === eid) || null;
    };
    const fmt = (v, d = 0) => v != null ? v.toLocaleString(undefined, { maximumFractionDigits: d }) : '—';
    const pct = (v) => v != null ? (v * 100).toFixed(2) + '%' : '—';
    // 锁定槽的现有附魔从配装器读取
    const lockedCfg = window.Jx3Equip?.getCurrentConfig?.()?.slots || {};

    const tbody = document.getElementById('wzc_top_body');
    tbody.innerHTML = top.map((t, i) => {
      const deltaCls = t.delta_pct > 0 ? 'wzc-delta-up' : (t.delta_pct < 0 ? 'wzc-delta-down' : 'wzc-delta-zero');
      const deltaSign = t.delta_pct >= 0 ? '+' : '';
      const p = t.panel || {};

      // 装备分组（武器单独一组）
      const armorPos = ['HAT','JACKET','BELT','WRIST','BOTTOMS','SHOES','NECKLACE','PENDANT','RING_1','RING_2'];
      const weaponPos = ['PRIMARY_WEAPON','SECONDARY_WEAPON'];
      const renderEqLine = (pos) => {
        const id = t.slots?.[pos];
        if (!id) return '';
        const name = t.names?.[pos] || `#${id}`;
        const isLocked = !state.perSlot[pos] || state.perSlot[pos].mode === 'lock';
        // 附魔 ID 来源：result.enhances 优先（搜索结果选定的）；否则锁定槽用 user 配装里的
        let enhId = t.enhances?.[pos];
        if (!enhId && isLocked) enhId = lockedCfg[pos]?.enhance_id;
        const enhName = enhNameOf(pos, enhId);
        const enhEntry = enhEntryOf(pos, enhId);
        const lockTag = isLocked ? '<span class="card-eq-lock" title="已锁定">🔒</span>' : '';
        const enhCls = `card-enh ${enchantQualityClass(enhEntry)}`.trim();
        const enhSeg = enhName
          ? ` <span class="${enhCls}">+ ${escapeHtml(enhName)}</span>`
          : ` <span class="card-enh-empty">（无附魔）</span>`;
        return `<div class="card-eq-line" data-pos="${pos}" data-equip-id="${id}" data-enh-id="${enhId || 0}">
          <span class="card-eq-slot">${POS_LABEL[pos]}</span>
          <span class="card-eq-name">${lockTag}${escapeHtml(name)}</span>${enhSeg}
        </div>`;
      };
      const armorLines = armorPos.map(renderEqLine).filter(Boolean).join('');
      const weaponLines = weaponPos.map(renderEqLine).filter(Boolean).join('');

      // 五彩石
      const stoneLine = t.stone_id
        ? `<div class="card-stone">💎 五彩石：${escapeHtml(t.stone_name || `#${t.stone_id}`)}</div>`
        : '';

      // 面板属性按心法布局：分山劲 8 项 / 铁骨衣 14 项（左右两栏对齐）
      const isTiegu = currentMount?.mount === 'TieGuYi' || currentMount?.mount_label === '铁骨衣';
      // data-attr-key 给 hover 处理用，对应 _wzcAttrTooltip 里的 case
      const cell = (label, val, key) => `<div data-attr-key="${key}"><span>${label}</span><b>${val}</b></div>`;
      const leftCells = isTiegu
        ? [
            cell('气血', fmt(p.max_life), 'hp'),
            cell('身法', fmt(p.agility), 'agi'),
            cell('攻击', fmt(p.physics_attack_power), 'atk'),
            cell('会心', pct(p.crit_rate), 'crit'),
            cell('会效', pct(p.crit_effect), 'crit_eff'),
            cell('招架', pct(p.parry_rate), 'parry'),
            cell('拆招', fmt(p.parry_value), 'parry_val'),
          ]
        : [
            cell('身法', fmt(p.agility), 'agi'),
            cell('攻击', fmt(p.physics_attack_power), 'atk'),
            cell('会心', pct(p.crit_rate), 'crit'),
            cell('会效', pct(p.crit_effect), 'crit_eff'),
          ];
      const rightCells = isTiegu
        ? [
            cell('体质', fmt(p.vitality), 'vit'),
            cell('破防', pct(p.overcome_rate), 'oc'),
            cell('无双', pct(p.strain_rate), 'strain'),
            cell('破招', fmt(p.surplus_value), 'surplus'),
            cell('加速', pct(p.haste_rate), 'haste'),
            cell('外防', pct(p.physics_shield_rate), 'pshield'),
            cell('内防', pct(p.magic_shield_rate), 'mshield'),
          ]
        : [
            cell('破防', pct(p.overcome_rate), 'oc'),
            cell('无双', pct(p.strain_rate), 'strain'),
            cell('破招', fmt(p.surplus_value), 'surplus'),
            cell('加速', pct(p.haste_rate), 'haste'),
          ];
      // 行交错填入 grid（左1 右1 左2 右2 ...）
      const gridCells = [];
      const rows = Math.max(leftCells.length, rightCells.length);
      for (let r = 0; r < rows; r++) {
        gridCells.push(leftCells[r] || '<div></div>');
        gridCells.push(rightCells[r] || '<div></div>');
      }
      const panelGrid = `<div class="card-panel-grid">${gridCells.join('')}</div>`;

      // 收益曲线按钮：该候选有 raw 时显示；点击后调 /api/equip/fit_curve 现场拟合，
      // 参考点 = 当前候选 raw + 装备特效，曲线在当前点附近最准
      const curveAvailable = !!(t.raw && state.lastSearchCtx);
      const curveBtn = curveAvailable
        ? `<button class="wzc-card-curve" data-curve-idx="${i}" data-wzc-tip="点击在右侧抽屉展开 9 维属性收益曲线 + 9×9 H 矩阵热力表（约 0.5 秒拟合）">📈 收益曲线</button>`
        : '';

      return `
        <div class="wzc-result-card" data-row-idx="${i}">
          <div class="card-header">
            <span class="card-rank">#${i + 1}</span>
            <span class="card-dps">${Math.round(t.dps).toLocaleString()}</span>
            <span class="card-delta ${deltaCls}">${deltaSign}${t.delta_pct.toFixed(2)}%</span>
          </div>
          <div class="card-actions">
            <button class="wzc-card-apply" data-apply-idx="${i}" title="把这套装备应用到上方候选池作为新基线（含本套搜出来的大/小附魔），方便继续迭代搜索">↑ 应用为基线</button>
            ${curveBtn}
            <button class="wzc-card-send" data-send-idx="${i}" title="发送到战斗广场">📤 广场</button>
          </div>
          ${panelGrid}
          <div class="card-eq-list">
            ${armorLines}
            ${weaponLines}
          </div>
          ${stoneLine}
        </div>
      `;
    }).join('');
    bindResultHover(top);
    bindResultSendButtons(top);
    bindResultApplyButtons(top);
    bindResultPanelHover(top);
    bindResultCurveButtons(top);
  }

  // 「↑ 应用为基线」: 把 top[i] 的整套装备（含搜出的大/小附魔）写到 state.slotOverrides，
  // 候选池表第二列 + runSearch baseline + picker baseline 都会立即反映新基线。
  // 用户可在新基线上继续调 lock/enum/筛选 → 再搜出下一轮 top。
  function bindResultApplyButtons(topRows) {
    document.querySelectorAll('button[data-apply-idx]').forEach(btn => {
      btn.addEventListener('click', () => {
        const i = parseInt(btn.dataset.applyIdx, 10);
        const t = topRows[i];
        if (!t || !t.slots) return;
        let n = 0;
        for (const [pos, equipId] of Object.entries(t.slots)) {
          if (!equipId) continue;
          const name = t.names?.[pos] || '';
          const enhanceId = t.enhances?.[pos];   // 小附魔（搜出来的最优）
          const enchantId = t.enchants?.[pos];   // 大附魔（如果后端有传；通常跟主源一致）
          state.slotOverrides[pos] = {
            equip_id: equipId,
            name,
            ...(Number.isFinite(enhanceId) && enhanceId > 0 ? { enhance_id: enhanceId } : {}),
            ...(Number.isFinite(enchantId) && enchantId > 0 ? { enchant_id: enchantId } : {}),
          };
          n++;
        }
        saveWzcState();
        syncCurrentEquip();
        renderCandsTable();
        updateOverridesToolbar();
        // 给用户视觉反馈：按钮短暂变色
        btn.textContent = `✓ 已应用 ${n} 件`;
        btn.classList.add('applied');
        setTimeout(() => {
          btn.textContent = '↑ 应用为基线';
          btn.classList.remove('applied');
        }, 1500);
      });
    });
  }

  // 结果卡 panel 单元格 hover：直接复用全局 jx3BuildAttrTooltip
  //   t.raw 是 RawAttrs，t.panel 是 PanelAttrs（physics_attack_power / overcome_rate / strain_rate）
  //   全局 helper 内部对 panel 字段名做兼容（CombatStats panel_attack vs PanelAttrs physics_attack_power 等）
  function _wzcAttrTooltipHtml(key, t) {
    return jx3BuildAttrTooltip(key, t.raw || {}, t.panel || {});
  }

  // ─── 属性收益（行内展开） ─────────────────────────────────────
  // 后端 fit_curve 返回 9 维 raw quadratic 模型（grad + Hessian）+ 各属性最大单附魔等级
  // 前端展示 8 个"显示维度"：去掉力道（外功心法 grad ≈ 0）+ 去掉全能（合成维度对决策意义不大）
  //   显示 idx [0..7] → raw idx [1..8]（身法 / 基础攻击 / 武器伤害 / 破招 / 会心 / 会效 / 破防 / 无双）

  const WZC_DISPLAY_LABELS = ['身法', '基础攻击', '武器伤害', '破招', '会心', '会心效果', '破防', '无双'];

  // 显示维度 → raw 9 维的"系数向量"：c[k] 表示该显示维度对原 raw 第 k 维的单位贡献
  function _wzcDisplayCoef(displayIdx) {
    const c = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    c[displayIdx + 1] = 1;   // 身法..无双 直接对应 raw idx 1..8
    return c;
  }

  // 该显示维度的最大单附魔等级（按 jx3dps-online 思路：每属性各自的 Δ）
  function _wzcDisplayMaxLevel(fitModel, displayIdx) {
    return (fitModel.max_enhance_levels || [])[displayIdx + 1] || 0;
  }

  // 单点收益：每 +1 等级 DPS = grad · c
  function _wzcDisplayGradPerLevel(fitModel, displayIdx) {
    const c = _wzcDisplayCoef(displayIdx);
    let s = 0;
    for (let k = 0; k < 9; k++) s += fitModel.grad[k] * c[k];
    return s;
  }

  // 满附魔收益：+N·c 的 ΔDPS = N·(grad·c) + ½·N²·(c^T H c)
  function _wzcDisplayMaxEnhanceGain(fitModel, displayIdx) {
    const N = _wzcDisplayMaxLevel(fitModel, displayIdx);
    if (N <= 0) return 0;
    const c = _wzcDisplayCoef(displayIdx);
    let g = 0, h = 0;
    for (let k = 0; k < 9; k++) g += fitModel.grad[k] * c[k];
    for (let i = 0; i < 9; i++)
      for (let j = 0; j < 9; j++)
        h += fitModel.hess[i][j] * c[i] * c[j];
    return N * g + 0.5 * N * N * h;
  }

  // 属性置换：减 fromIdx N_i 等级 + 加 toIdx N_j 等级 的 ΔDPS
  //   ΔDPS = N_j (grad·c_j) - N_i (grad·c_i)
  //          + ½ ( N_i² c_i^T H c_i + N_j² c_j^T H c_j - 2 N_i N_j c_i^T H c_j )
  function _wzcSwapDelta(fitModel, fromIdx, toIdx) {
    if (fromIdx === toIdx) return null;
    const Ni = _wzcDisplayMaxLevel(fitModel, fromIdx);
    const Nj = _wzcDisplayMaxLevel(fitModel, toIdx);
    if (Ni <= 0 || Nj <= 0) return null;
    const ci = _wzcDisplayCoef(fromIdx);
    const cj = _wzcDisplayCoef(toIdx);
    let gi = 0, gj = 0, hii = 0, hjj = 0, hij = 0;
    for (let k = 0; k < 9; k++) {
      gi += fitModel.grad[k] * ci[k];
      gj += fitModel.grad[k] * cj[k];
    }
    for (let p = 0; p < 9; p++) {
      for (let q = 0; q < 9; q++) {
        hii += fitModel.hess[p][q] * ci[p] * ci[q];
        hjj += fitModel.hess[p][q] * cj[p] * cj[q];
        hij += fitModel.hess[p][q] * ci[p] * cj[q];
      }
    }
    return Nj * gj - Ni * gi + 0.5 * (Ni*Ni*hii + Nj*Nj*hjj - 2*Ni*Nj*hij);
  }

  // ───（已废弃）以下两个函数保留以防其它地方还引用，但 wzcRenderCurveExpand 不再用
  // 单个属性曲线：固定其他维度在 baseRaw9，沿 axis 在 [axis_min, axis_max] 内采 30 点画 quadratic
  function wzcRenderAxisCurve(fitModel, baseRaw9, axis, label) {
    const W = 220, H = 150;            // 高度增加给底部边际收益行让位
    const PADL = 38, PADR = 8, PADT = 16, PADB = 36;
    const plotW = W - PADL - PADR;
    const plotH = H - PADT - PADB;
    const xMin = fitModel.axis_min[axis];
    const xMax = fitModel.axis_max[axis];
    const xRange = Math.max(1e-6, xMax - xMin);
    const xCur = baseRaw9[axis];

    const N = 30;
    const ys = [];
    let yMin = +Infinity, yMax = -Infinity;
    const r = baseRaw9.slice();
    for (let k = 0; k <= N; k++) {
      r[axis] = xMin + (xRange * k) / N;
      const y = wzcPredictRaw(fitModel, r);
      ys.push(y);
      if (y < yMin) yMin = y;
      if (y > yMax) yMax = y;
    }
    const yCur = wzcPredictRaw(fitModel, baseRaw9);
    if (yCur < yMin) yMin = yCur;
    if (yCur > yMax) yMax = yCur;
    const yPad = (yMax - yMin) * 0.05 + 1;
    yMin -= yPad; yMax += yPad;
    const yRange = Math.max(1e-6, yMax - yMin);

    const xToScreen = (x) => PADL + ((x - xMin) / xRange) * plotW;
    const yToScreen = (y) => PADT + plotH - ((y - yMin) / yRange) * plotH;
    const points = ys.map((y, k) => `${xToScreen(xMin + (xRange * k) / N).toFixed(1)},${yToScreen(y).toFixed(1)}`).join(' ');
    const cxCur = xToScreen(xCur);
    const cyCur = yToScreen(yCur);

    // 边际：在当前点 ±100 单位的 dy/dx（中心差分，比单边差分更对称）
    const r2 = baseRaw9.slice(); r2[axis] = xCur + 100;
    const r3 = baseRaw9.slice(); r3[axis] = Math.max(0, xCur - 100);
    const yPlus  = wzcPredictRaw(fitModel, r2);
    const yMinus = wzcPredictRaw(fitModel, r3);
    const slope = (yPlus - yMinus) / Math.max(1e-6, (r2[axis] - r3[axis]));
    const slopeColor = slope > 1 ? 'var(--green)' : (slope < -1 ? 'var(--red)' : 'var(--text-dim)');
    const slopeText = `每 +100 等级 ${slope >= 0 ? '+' : ''}${Math.abs(slope) < 0.5 ? '0' : Math.round(slope).toLocaleString()} DPS`;

    // 凸性：½·h_ii。负 = 上凸（递减），正 = 下凸（递增），0 = 直线
    const curvature = 0.5 * fitModel.hess[axis][axis];
    const curvDelta100 = curvature * 100 * 100;   // ±100 内由二阶项贡献
    let shapeTag = '直线';
    if (Math.abs(curvDelta100) >= 1) {
      shapeTag = curvature < 0 ? '↗ 递减' : '↗ 递增';
    }

    return `
      <div class="wzc-curve-cell" data-axis="${axis}"
        data-wzc-tip="${escapeHtml(label)}：当前 ${Math.round(xCur).toLocaleString()} → DPS ${Math.round(yCur).toLocaleString()}<br>边际：每 +100 等级约 ${slope >= 0 ? '+' : ''}${slope.toFixed(1)} DPS<br>凸性：${shapeTag}（½·h_ii=${curvature.toExponential(2)}）<br>显示范围 [${Math.round(xMin).toLocaleString()}, ${Math.round(xMax).toLocaleString()}]">
        <svg width="${W}" height="${H}" class="wzc-curve-svg" viewBox="0 0 ${W} ${H}">
          <text x="${PADL + plotW / 2}" y="11" text-anchor="middle" class="wzc-curve-title">${escapeHtml(label)}</text>
          <line x1="${PADL}" y1="${PADT + plotH}" x2="${PADL + plotW}" y2="${PADT + plotH}" class="wzc-curve-axis"/>
          <line x1="${PADL}" y1="${PADT}" x2="${PADL}" y2="${PADT + plotH}" class="wzc-curve-axis"/>
          <text x="${PADL - 4}" y="${PADT + 4}" text-anchor="end" class="wzc-curve-tick">${Math.round(yMax).toLocaleString()}</text>
          <text x="${PADL - 4}" y="${PADT + plotH}" text-anchor="end" class="wzc-curve-tick">${Math.round(yMin).toLocaleString()}</text>
          <polyline points="${points}" class="wzc-curve-line"/>
          <circle cx="${cxCur.toFixed(1)}" cy="${cyCur.toFixed(1)}" r="4" class="wzc-curve-pt-cur"/>
          <text x="${PADL}" y="${PADT + plotH + 11}" text-anchor="start" class="wzc-curve-tick">${Math.round(xMin).toLocaleString()}</text>
          <text x="${PADL + plotW}" y="${PADT + plotH + 11}" text-anchor="end" class="wzc-curve-tick">${Math.round(xMax).toLocaleString()}</text>
          <text x="${PADL + plotW / 2}" y="${H - 6}" text-anchor="middle" class="wzc-curve-margin" fill="${slopeColor}">${escapeHtml(slopeText)}</text>
        </svg>
      </div>
    `;
  }

  // 边际收益排名条：把 9 维 grad·100 排序，做一行小条形图（横向）
  // 通用收益排名表：按 sortKey 字段绝对值降序，只画一列（满附魔 或 +100 等级）
  function _wzcRenderRankTable(items, sortKey, valueLabel, titleText, hintText, formatVal) {
    const sorted = items.slice().sort((a, b) => Math.abs(b[sortKey]) - Math.abs(a[sortKey]));
    const maxAbs = Math.max(1, ...sorted.map(it => Math.abs(it[sortKey])));
    const rows = sorted.map(it => {
      const v = it[sortKey];
      const wPct = (Math.abs(v) / maxAbs) * 100;
      const cls = v >= 0 ? 'wzc-mrk-pos' : 'wzc-mrk-neg';
      const display = formatVal ? formatVal(it) : `${v >= 0 ? '+' : ''}${Math.round(v).toLocaleString()}`;
      return `
        <div class="wzc-mrk-row">
          <span class="wzc-mrk-label">${escapeHtml(it.label)}</span>
          <span class="wzc-mrk-bar"><span class="wzc-mrk-fill ${cls}" style="width:${wPct.toFixed(1)}%"></span></span>
          <span class="wzc-mrk-val ${cls}"><b>${display}</b></span>
        </div>
      `;
    }).join('');
    return `
      <div class="wzc-mrk-section">
        <div class="wzc-mrk-title">${escapeHtml(titleText)}
          <span class="wzc-curve-hint">${escapeHtml(hintText)}</span>
        </div>
        ${rows}
      </div>
    `;
  }

  // 收益排名：拆成两张表
  //   表 1：单分附魔收益（按"满附魔 ΔDPS"绝对值降序）—— 决策优先级
  //   表 2：单点（+100 等级）收益（按"+100 等级 ΔDPS"绝对值降序）—— 粒度参考
  function wzcRenderMarginalRank(fitModel) {
    const items = WZC_DISPLAY_LABELS.map((label, displayIdx) => {
      const perLevel = _wzcDisplayGradPerLevel(fitModel, displayIdx);
      const maxN = _wzcDisplayMaxLevel(fitModel, displayIdx);
      const fullEnh = _wzcDisplayMaxEnhanceGain(fitModel, displayIdx);
      return { label, displayIdx, per100: perLevel * 100, maxN, fullEnh };
    });
    const fullEnhTable = _wzcRenderRankTable(
      items.filter(it => it.maxN > 0),   // 没附魔的属性不进满附魔排名
      'fullEnh',
      '满附魔 ΔDPS',
      '单分属性收益排名',
      '把该属性堆满 1 个最大单附魔（各属性最大附魔等级不同）的 ΔDPS，按此降序——决策优先级。负值 = 加反掉 DPS',
      (it) => `${it.fullEnh >= 0 ? '+' : ''}${Math.round(it.fullEnh).toLocaleString()} <span class="wzc-mrk-tag">(${Math.round(it.maxN)}级)</span>`,
    );
    const per100Table = _wzcRenderRankTable(
      items,
      'per100',
      '+100 等级 ΔDPS',
      '单点属性收益排名',
      '每 +100 等级带来的 DPS 增量（粒度参考，不含"各属性最大附魔等级不同"信息）',
      (it) => `${it.per100 >= 0 ? '+' : ''}${Math.round(it.per100).toLocaleString()}`,
    );
    return fullEnhTable + per100Table;
  }

  // 9×9 属性置换矩阵：每格 = "减 i 行 + 加 j 列 各 1 个最大附魔" 的 ΔDPS
  // 行内最大值打 👑（必须减此属性时最优补偿）+ 金边
  function _wzcAbbrevDps(v) {
    const a = Math.abs(v);
    if (a < 1) return '·';
    const sign = v >= 0 ? '+' : '−';
    if (a >= 1e6) return `${sign}${(a / 1e6).toFixed(2)}M`;
    if (a >= 1e4) return `${sign}${(a / 1e3).toFixed(1)}K`;
    return `${v >= 0 ? '+' : '−'}${Math.round(a).toLocaleString()}`;
  }
  function wzcRenderSwapMatrix(fitModel) {
    const N_DIM = WZC_DISPLAY_LABELS.length;
    const vals = [];
    let absMax = 0;
    for (let i = 0; i < N_DIM; i++) {
      vals.push(new Array(N_DIM).fill(null));
      for (let j = 0; j < N_DIM; j++) {
        if (i === j) continue;
        const v = _wzcSwapDelta(fitModel, i, j);
        if (v == null) continue;
        vals[i][j] = v;
        if (Math.abs(v) > absMax) absMax = Math.abs(v);
      }
    }
    if (absMax < 1e-6) absMax = 1;

    // 每行最大值（含 0/null 跳过）→ 行内皇冠标记
    const rowBest = vals.map(row => {
      let bestJ = -1, bestV = -Infinity;
      row.forEach((v, j) => { if (v != null && v > bestV) { bestV = v; bestJ = j; } });
      return bestJ;
    });

    let html = '<table class="wzc-swap-table"><thead><tr><th><span class="wzc-swap-corner">减↓ / 加→</span></th>';
    for (let j = 0; j < N_DIM; j++) {
      html += `<th>${escapeHtml(WZC_DISPLAY_LABELS[j])}</th>`;
    }
    html += '</tr></thead><tbody>';
    for (let i = 0; i < N_DIM; i++) {
      const Ni = _wzcDisplayMaxLevel(fitModel, i);
      const rowLabelTip = Ni > 0 ? `减 ${WZC_DISPLAY_LABELS[i]} ${Math.round(Ni)} 等级（1 个最大附魔）` : `${WZC_DISPLAY_LABELS[i]}（无对应附魔）`;
      html += `<tr><th data-wzc-tip="${escapeHtml(rowLabelTip)}">${escapeHtml(WZC_DISPLAY_LABELS[i])}</th>`;
      for (let j = 0; j < N_DIM; j++) {
        if (i === j) {
          html += '<td class="wzc-swap-diag">·</td>';
          continue;
        }
        const v = vals[i][j];
        if (v == null) {
          html += '<td class="wzc-swap-na" data-wzc-tip="缺该属性附魔数据">–</td>';
          continue;
        }
        const Nj = _wzcDisplayMaxLevel(fitModel, j);
        const ratio = v / absMax;
        const alpha = Math.min(0.92, Math.abs(ratio));
        const bg = v >= 0
          ? `rgba(var(--green-rgb), ${alpha.toFixed(3)})`
          : `rgba(var(--red-rgb), ${alpha.toFixed(3)})`;
        const display = _wzcAbbrevDps(v);
        const sign = v >= 0 ? '+' : '';
        const fullVal = `${sign}${Math.round(v).toLocaleString()}`;
        const isBest = rowBest[i] === j && v > 0;
        const cls = isBest ? 'wzc-swap-best' : '';
        const tip = `减 ${WZC_DISPLAY_LABELS[i]} ${Math.round(Ni)} 等级 + 加 ${WZC_DISPLAY_LABELS[j]} ${Math.round(Nj)} 等级 → DPS <b>${fullVal}</b>${isBest ? '<br>👑 该行最优补偿' : ''}`;
        html += `<td class="${cls}" style="background:${bg}" data-wzc-tip="${escapeHtml(tip)}">${isBest ? '👑 ' : ''}${display}</td>`;
      }
      html += '</tr>';
    }
    html += '</tbody></table>';
    return html;
  }

  // 9×9 Hessian 二阶贡献矩阵：每格显示"如果 i 维 +D_REF + j 维 +D_REF 时的二阶贡献"
  //   单元值 = ½·h_ij·D_REF² —— 用固定参考增量（默认 1000）让所有格在同一量纲对比
  //   对角线（i==j）= 自身的二次项贡献；非对角线 = 属性间真实交叉
  // 单元格用 K/M 缩写避免数字撑爆；hover tip 显示完整值 + h_ij 本身
  function _wzcAbbrevDps(v) {
    const a = Math.abs(v);
    if (a < 1) return '·';
    const sign = v >= 0 ? '+' : '−';
    if (a >= 1e6) return `${sign}${(a / 1e6).toFixed(2)}M`;
    if (a >= 1e4) return `${sign}${(a / 1e3).toFixed(1)}K`;
    return `${v >= 0 ? '+' : '−'}${Math.round(a).toLocaleString()}`;
  }
  function wzcRenderHessianMatrix(fitModel) {
    const D_REF = 1000;
    const vals = [];
    let absMax = 0;
    for (let i = 0; i < 9; i++) {
      vals.push(new Array(9));
      for (let j = 0; j < 9; j++) {
        const v = 0.5 * fitModel.hess[i][j] * D_REF * D_REF;
        vals[i][j] = v;
        if (Math.abs(v) > absMax) absMax = Math.abs(v);
      }
    }
    if (absMax < 1e-6) absMax = 1;
    const labels = fitModel.axis_labels;

    let html = '<table class="wzc-hess-table"><thead><tr><th></th>';
    for (let j = 0; j < 9; j++) {
      html += `<th>${escapeHtml(labels[j])}</th>`;
    }
    html += '</tr></thead><tbody>';
    for (let i = 0; i < 9; i++) {
      html += `<tr><th>${escapeHtml(labels[i])}</th>`;
      for (let j = 0; j < 9; j++) {
        const v = vals[i][j];
        const ratio = v / absMax;
        const alpha = Math.min(0.92, Math.abs(ratio));
        const bg = v >= 0
          ? `rgba(63, 185, 80, ${alpha.toFixed(3)})`
          : `rgba(248, 81, 73, ${alpha.toFixed(3)})`;
        const display = _wzcAbbrevDps(v);
        const sign = v >= 0 ? '+' : '';
        const fullVal = `${sign}${Math.round(v).toLocaleString()}`;
        const tip = `${labels[i]} × ${labels[j]}：每轴 +${D_REF} 等级 → 二阶贡献 <b>${fullVal}</b> DPS<br>h[${i},${j}] = ${fitModel.hess[i][j].toExponential(3)}`;
        html += `<td style="background:${bg}" data-wzc-tip="${escapeHtml(tip)}">${display}</td>`;
      }
      html += '</tr>';
    }
    html += '</tbody></table>';
    return html;
  }

  // 拼装一行结果的"展开区"内容：当前 DPS + 边际收益排名 + 属性置换矩阵
  // fitModel 是 /api/equip/fit_curve 返回的（参考点 = 当前 raw_a + 该候选 equipment）
  function wzcRenderCurveExpand(fitModel, simCount, elapsedMs) {
    if (!fitModel) {
      return '<div style="color:#888;padding:8px">没有拟合数据</div>';
    }
    const refDps = fitModel.ref_dps;
    return `
      <div class="wzc-curve-content">
        <div class="wzc-curve-summary">
          <span>当前 DPS：<b>${Math.round(refDps).toLocaleString()}</b></span>
          <span>拟合 sim：<b>${simCount || 55}</b></span>
          <span>耗时：<b>${(elapsedMs || 0).toFixed(0)} ms</b></span>
        </div>
        ${wzcRenderMarginalRank(fitModel)}
        <div class="wzc-swap-section">
          <div class="wzc-swap-title">属性置换矩阵
            <span class="wzc-curve-hint">每格 = 「减 X 行 1 个最大附魔 + 加 Y 列 1 个最大附魔」的 ΔDPS（按各属性最大附魔等级算，不同属性 N 不同）。绿正红负，每行 👑 = 该行最优补偿（必须减此属性时换什么）。鼠标悬停看具体等级</span>
          </div>
          ${wzcRenderSwapMatrix(fitModel)}
        </div>
      </div>
    `;
  }

  // 单例 drawer：所有"📈 收益曲线"按钮共享一个右侧抽屉
  //   首次需要时 lazy 创建；切换不同行时复用同一个 DOM；ESC / 遮罩 / × 都关闭
  function _wzcEnsureCurveDrawer() {
    let dr = document.getElementById('wzc_curve_drawer');
    if (dr) return dr;
    const wrap = document.createElement('div');
    wrap.id = 'wzc_curve_drawer_wrap';
    wrap.innerHTML = `
      <div class="wzc-curve-mask" id="wzc_curve_mask"></div>
      <aside class="wzc-curve-drawer" id="wzc_curve_drawer">
        <div class="wzc-curve-drawer-head">
          <span id="wzc_curve_drawer_title">属性收益曲线</span>
          <button class="wzc-curve-drawer-close" id="wzc_curve_close" type="button">×</button>
        </div>
        <div class="wzc-curve-drawer-body" id="wzc_curve_drawer_body"></div>
      </aside>
    `;
    document.body.appendChild(wrap);
    document.getElementById('wzc_curve_close').addEventListener('click', _wzcCloseCurveDrawer);
    document.getElementById('wzc_curve_mask').addEventListener('click', _wzcCloseCurveDrawer);
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && document.getElementById('wzc_curve_drawer_wrap')?.classList.contains('open')) {
        _wzcCloseCurveDrawer();
      }
    });
    return document.getElementById('wzc_curve_drawer');
  }
  function _wzcCloseCurveDrawer() {
    const wrap = document.getElementById('wzc_curve_drawer_wrap');
    if (wrap) wrap.classList.remove('open');
    state.expandedCurveIdx?.clear();
    document.querySelectorAll('button.wzc-card-curve.on').forEach(b => {
      b.classList.remove('on');
      b.textContent = '📈 收益曲线';
    });
  }
  // 显示 drawer 并填内容；fitModel 来自 /api/equip/fit_curve
  //   titleText：drawer 顶部标题（wzc 调用方传 "#1 属性收益曲线 · DPS X"，配装器传别的）
  function _wzcOpenCurveDrawer(titleText, fitModel, simCount, elapsedMs) {
    _wzcEnsureCurveDrawer();
    const wrap = document.getElementById('wzc_curve_drawer_wrap');
    const title = document.getElementById('wzc_curve_drawer_title');
    const body = document.getElementById('wzc_curve_drawer_body');
    title.textContent = titleText;
    body.innerHTML = wzcRenderCurveExpand(fitModel, simCount, elapsedMs);
    wrap.classList.add('open');
    body.querySelectorAll('[data-wzc-tip]').forEach(el => {
      const tip = el.dataset.wzcTip;
      if (!tip) return;
      el.style.cursor = 'help';
      el.addEventListener('mouseenter', () => wzcShowHover(el, tip, true));
      el.addEventListener('mouseleave', wzcHideHover);
    });
  }

  // 把 wzc top entry + ctx 转成 /api/equip/fit_curve 请求体
  //   参考点 = 该候选自己的 raw（attributes）+ 该候选自己的 equipment（含 ENCHANT_*）
  //   宏 / 奇穴 / 秘籍 / 目标 / 杂项参数 跟随搜索时的 ctx
  function _wzcBuildFitCurveBody(t, ctx) {
    const eq = {};
    const lockedCfgSnap = ctx?.lockedSlots || {};
    Object.entries(t.slots || {}).forEach(([pos, equipId]) => {
      if (!equipId) return;
      eq[pos] = equipId;
      let enchantId = 0;
      const lockedSlot = lockedCfgSnap[pos];
      if (lockedSlot) enchantId = lockedSlot.enchant_id || 0;
      else enchantId = (ctx?.default_enchants || {})[pos] || 0;
      if (enchantId) eq[`ENCHANT_${pos}`] = enchantId;
    });
    const r = t.raw || {};
    const attrs = {
      li_dao: r.strength || 0,
      shen_fa: r.agility || 0,
      vitality: r.vitality || 0,
      gen_gu: 44, yuan_qi: 44,
      base_attack: r.base_attack || 0,
      base_magical_attack: r.base_magical_attack || 0,
      weapon_damage: r.weapon_damage || 0,
      surplus_value: r.surplus_value || 0,
      crit_level: r.crit_level || 0,
      crit_effect_level: r.crit_effect_level || 0,
      overcome_level: r.overcome_level || 0,
      strain_level: r.strain_level || 0,
      haste_level: r.haste_level || 0,
      parry_value: r.parry_value || 0,
      parry_level: r.parry_level || 0,
    };
    return {
      haste_level: r.haste_level || 0,
      sequence: ['__macro__'],
      attributes: attrs,
      equipment: eq,
      talents: ctx?.talents || [],
      recipes: ctx?.recipes || [],
      macro_text: ctx?.macro_text || '',
      macro_duration: ctx?.duration || 300,
      target: ctx?.target || (typeof getTarget === 'function' ? getTarget() : { level: 134, defense_bonus: 0 }),
      network_delay: ctx?.network_delay || 0,
      initial_rage: ctx?.initial_rage || 0,
      boss_attack_interval: ctx?.boss_attack_interval || 0,
      // 全局参数：优先用搜索时 ctx 快照（保证 DPS 与 t.dps 一致）；ctx 没存时 fallback 到当前全局
      hanjia_expectation: ('hanjia_expectation' in (ctx || {})) ? !!ctx.hanjia_expectation
        : ((typeof isHanjiaExpectationEnabled === 'function') ? isHanjiaExpectationEnabled() : false),
      tiegu_mode: (ctx?.tiegu_mode != null) ? ctx.tiegu_mode
        : ((typeof getTieguMode === 'function') ? getTieguMode() : 2),
      experimental: ('experimental' in (ctx || {})) ? !!ctx.experimental
        : ((typeof isExperimental === 'function') ? isExperimental() : false),
      team_buffs: Array.isArray(ctx?.team_buffs) ? ctx.team_buffs
        : ((typeof getTeamBuffs === 'function') ? getTeamBuffs() : []),
      formation: ('formation' in (ctx || {})) ? ctx.formation
        : (window._formationSelection ? { ...window._formationSelection } : null),
      lite: true,
      lite_keep_timeline: false,
      // 拟合参数
      order: 2,
      pert_delta: 1000,
      axis_scale: 5,
    };
  }

  // 给"📈 收益曲线"按钮绑点击：async 调 /api/equip/fit_curve → 渲染 drawer
  function bindResultCurveButtons(topRows) {
    const tbody = document.getElementById('wzc_top_body');
    if (!tbody) return;
    tbody.querySelectorAll('button.wzc-card-curve').forEach(btn => {
      btn.addEventListener('click', async e => {
        e.stopPropagation();
        if (btn.disabled) return;
        const idx = parseInt(btn.dataset.curveIdx, 10);
        if (!Number.isFinite(idx)) return;
        const t = topRows[idx];
        if (!t || !t.raw) {
          alert('该结果缺少 raw 数据，无法拟合');
          return;
        }
        const wasOpen = btn.classList.contains('on');
        // 切到新行/关闭当前行：先重置其它按钮高亮
        tbody.querySelectorAll('button.wzc-card-curve.on').forEach(b => {
          b.classList.remove('on');
          b.textContent = '📈 收益曲线';
        });
        if (wasOpen) {
          _wzcCloseCurveDrawer();
          return;
        }
        // loading
        btn.disabled = true;
        btn.classList.add('on');
        const origText = '📉 收起';
        btn.textContent = '⏳ 计算中…';
        try {
          const body = _wzcBuildFitCurveBody(t, state.lastSearchCtx || {});
          const resp = await fetch('/api/equip/fit_curve', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body),
          });
          if (!resp.ok) throw new Error(await resp.text());
          const data = await resp.json();
          if (!data.feasible || !data.fit_model) {
            throw new Error(data.error || '拟合失败');
          }
          btn.textContent = origText;
          const titleText = `#${idx + 1} 属性收益曲线 · DPS ${Math.round(t.dps).toLocaleString()}`;
          _wzcOpenCurveDrawer(titleText, data.fit_model, data.sim_count, data.elapsed_ms);
        } catch (err) {
          console.error('[wzc] fit_curve 失败', err);
          alert('拟合失败：' + (err?.message || err));
          btn.classList.remove('on');
          btn.textContent = '📈 收益曲线';
        } finally {
          btn.disabled = false;
        }
      });
    });
  }

  function bindResultPanelHover(topRows) {
    const tbody = document.getElementById('wzc_top_body');
    if (!tbody) return;
    tbody.querySelectorAll('.wzc-result-card').forEach(card => {
      const idx = parseInt(card.dataset.rowIdx, 10);
      const t = topRows[idx];
      if (!t) return;
      card.querySelectorAll('.card-panel-grid > div[data-attr-key]').forEach(cell => {
        const key = cell.dataset.attrKey;
        cell.style.cursor = 'help';
        cell.addEventListener('mouseenter', () => {
          const html = _wzcAttrTooltipHtml(key, t);
          if (html) wzcShowHover(cell, html, true);
        });
        cell.addEventListener('mouseleave', wzcHideHover);
      });
    });
  }

  // 把第 i 个搜索结果按当前搜索 ctx 拼成 plaza Build 并 add
  function _wzcBuildPlazaFromResult(t, i) {
    const ctx = state.lastSearchCtx || {};
    const lockedCfgSnap = ctx.lockedSlots || {};
    const embedLv = ctx.embedLv || 6;
    const slots = {};
    Object.keys(t.slots || {}).forEach(pos => {
      const equipId = t.slots[pos];
      if (!equipId) return;
      let enchant_id = 0;
      const lockedSlot = lockedCfgSnap[pos];
      if (lockedSlot) {
        enchant_id = lockedSlot.enchant_id || 0;
      } else {
        enchant_id = (ctx.default_enchants || {})[pos] || 0;
      }
      const enhance_id = (t.enhances || {})[pos] || 0;
      slots[pos] = {
        equip_id: equipId,
        // plaza 概览 / 装备 chip 显示用；后端 t.names[pos] 已带回
        name: (t.names || {})[pos] || '',
        strength: embedLv,
        embedding: [embedLv, embedLv, embedLv],
        enhance_id,
        enchant_id,
      };
    });
    const equipment = {
      slots,
      stoneId:   t.stone_id || ctx.stone_id || 0,
      stoneName: t.stone_name || ctx.stone_name || '',
      mount: ctx.mount_key || (currentMount?.mount || null),
    };
    // rotation：复用搜索 ctx 里的 macro_text；plaza 期望 macro 是 {mode, general/shield/blade} 对象
    // 之前用 lookahead `(?=^#page\s+\w|$)/m` 会被 `$` (行末) 截断，shield/blade 只取一行 — 用 split 法替代
    const macroObj = parseStanceMacroText(ctx.macro_text || '');
    const baseName = `配装搜索 #${i + 1} · DPS ${Math.round(t.dps).toLocaleString()}`;
    return {
      name: window.Jx3Plaza?.nextDefaultName?.() ? `${window.Jx3Plaza.nextDefaultName()}（${baseName}）` : baseName,
      mount: ctx.mount_key || (currentMount?.mount || null),
      mount_label: ctx.mount_label || currentMount?.mount_label || '',
      equipment,
      talents: ctx.talents || [],
      recipes: ctx.recipes || [],
      rotation: {
        sequence: [],   // wzc 不构造序列，宏直接跑
        macro: macroObj,
        delay: ctx.network_delay || 0,
        initial_rage: ctx.initial_rage || 0,
        macro_duration: ctx.duration || 300,
        boss_attack_interval: ctx.boss_attack_interval || 0,
      },
      target: ctx.target || ((typeof getTarget === 'function') ? getTarget() : null),
      // 用本候选的 raw 作为 attributes；getAttrs() 读基础设置页 input，与 wzc 候选属性不一致
      attributes: t.raw ? {
        li_dao:            t.raw.strength,
        shen_fa:           t.raw.agility,
        vitality:          t.raw.vitality,
        base_attack:       t.raw.base_attack,
        weapon_damage:     t.raw.weapon_damage,
        surplus_value:     t.raw.surplus_value,
        crit_level:        t.raw.crit_level,
        crit_effect_level: t.raw.crit_effect_level,
        overcome_level:    t.raw.overcome_level,
        strain_level:      t.raw.strain_level,
        haste_level:       t.raw.haste_level,
        parry_level:       t.raw.parry_level,
        parry_value:       t.raw.parry_value,
      } : ((typeof getAttrs === 'function') ? getAttrs() : null),
      // wzc 是 lite simulate，没完整 timeline / skill_stats；只填 dps + 转换后的 panel 让 plaza 概览能显示
      // t.panel 是 PanelAttrs（physics_attack_power / overcome_rate / strain_rate / ...），
      // plaza 概览读 CombatStats-style 字段（panel_attack / overcome / strain），需要转换
      snapshot: {
        dps: t.dps || 0,
        total_damage: (t.dps || 0) * (ctx.duration || 300),
        fight_time: ctx.duration || 300,
        skill_count: 0,
        skill_stats: [],
        panel: t.panel ? {
          panel_attack: t.panel.physics_attack_power,
          crit_rate:    t.panel.crit_rate,
          crit_effect:  t.panel.crit_effect,
          overcome:     t.panel.overcome_rate,
          strain:       t.panel.strain_rate,
          haste_rate:   t.panel.haste_rate,
          surplus_value: t.panel.surplus_value,
          parry_rate:   t.panel.parry_rate,
          parry_value:  t.panel.parry_value,
          vitality:     t.panel.vitality,
          agility:      t.panel.agility,
          strength:     t.panel.strength,
          max_life:     t.panel.max_life,
        } : null,
        computed_at: Date.now(),
        from_wzc: true,
      },
      confirmedSave: false,
    };
  }

  function bindResultSendButtons(topRows) {
    const tbody = document.getElementById('wzc_top_body');
    if (!tbody) return;
    tbody.querySelectorAll('button.wzc-card-send').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const idx = parseInt(btn.dataset.sendIdx, 10);
        const t = topRows[idx];
        if (!t) return;
        if (!window.Jx3Plaza?.add) { alert('广场未加载'); return; }
        try {
          const draft = _wzcBuildPlazaFromResult(t, idx);
          const created = window.Jx3Plaza.add(draft);
          // 临时按钮反馈
          const orig = btn.textContent;
          btn.textContent = '✓ 已发送';
          btn.classList.add('sent');
          setTimeout(() => { btn.textContent = orig; btn.classList.remove('sent'); }, 1800);
          console.log('[wzc] sent to plaza:', created);
        } catch (e) {
          alert('发送失败：' + e.message);
        }
      });
    });
  }

  function bindResultHover(topRows) {
    const tbody = document.getElementById('wzc_top_body');
    if (!tbody) return;
    // 用搜索时的镶嵌等级 / 大附魔 / 锁定槽快照填回 SlotConfig，让 hover tooltip 能算出镶嵌数值
    const ctx = state.lastSearchCtx || {};
    const embedLv = ctx.embedLv || 6;
    const lockedCfgSnap = ctx.lockedSlots || {};
    const defaultEnchants = ctx.default_enchants || {};
    const stoneName = ctx.stone_name || '';
    tbody.querySelectorAll('.card-eq-line').forEach(line => {
      const pos = line.dataset.pos;
      const equipId = parseInt(line.dataset.equipId, 10);
      const enhId = parseInt(line.dataset.enhId, 10) || 0;
      if (!equipId) return;
      // 锁定槽优先用 cfg 快照；否则用 default_enchants[pos]
      const lockedSlot = lockedCfgSnap[pos];
      const enchant_id = lockedSlot?.enchant_id || defaultEnchants[pos] || 0;
      const slotCfg = {
        equip_id: equipId,
        strength: embedLv,
        embedding: [embedLv, embedLv, embedLv],
        enhance_id: enhId,
        enchant_id,
      };
      // 同卡片整套装备（{ POS: equip_id }）作为算"已穿件数"的上下文，避免误用主页面装备
      const cardEl = line.closest('.wzc-result-card');
      const rowIdx = cardEl ? parseInt(cardEl.dataset.rowIdx, 10) : -1;
      const contextSlots = topRows[rowIdx]?.slots || null;
      line.addEventListener('mouseenter', () => {
        wzcShowHover(line,
          window.Jx3Equip?.buildItemTooltip?.(pos, slotCfg, { stoneName, contextSlots }) || '',
          true);
      });
      line.addEventListener('mouseleave', wzcHideHover);
    });
  }

  // 页面激活时初始化
  let _initialized = false;
  new MutationObserver(() => {
    if (!page.classList.contains('active')) return;
    renderEnv();
    if (!_initialized) {
      _initialized = true;
      loadHasteTiers();
      loadWzcMeta();             // 提前拉装备 meta（schools/kinds chips 数据源）
      loadWzcState();            // 恢复 perSlot filter / excluded / mode + 上次结果 + bucket / pareto
      // 监听 bucket_size / use_pareto / inherit_enchants 改动 → 持久化
      document.getElementById('wzc_bucket_size')?.addEventListener('input', saveWzcState);
      document.getElementById('wzc_use_pareto')?.addEventListener('change', saveWzcState);
      document.getElementById('wzc_inherit_enchants')?.addEventListener('change', saveWzcState);
      // 环境 input / select / radio：持久化
      ['wzc_target_level','wzc_duration'].forEach(id => {
        const el = document.getElementById(id);
        el?.addEventListener('input',  saveWzcState);
        el?.addEventListener('change', saveWzcState);
      });
      document.querySelectorAll('input[name="wzc_embed"]').forEach(r => {
        r.addEventListener('change', saveWzcState);
      });
      // 时长快捷加减：±15 / ±30 / ±60，clamp 到 input 的 min/max
      document.querySelectorAll('.wzc-dur-btn[data-dur-add]').forEach(btn => {
        btn.addEventListener('click', () => {
          const el = document.getElementById('wzc_duration');
          if (!el) return;
          const inc = parseInt(btn.dataset.durAdd, 10) || 0;
          const cur = parseInt(el.value, 10) || 0;
          const min = parseInt(el.min, 10) || 1;
          const max = parseInt(el.max, 10) || 3600;
          el.value = Math.max(min, Math.min(max, cur + inc));
          saveWzcState();
        });
      });
      // 循环来源：点 [导入存档…] 直接弹 picker（与「加载配装」/「导入循环」UX 一致），
      // 选完后 openImportPicker 内部把 source 设为 'import'；[取消导入] 切回 'loop'
      document.getElementById('wzc_import_pick')?.addEventListener('click', openImportPicker);
      document.getElementById('wzc_import_clear')?.addEventListener('click', () => {
        state.env.source = 'loop';
        state.env.importedFile = null;
        state.env.importedMacro = null;
        state.env.importedTalents = null;
        state.env.importedRecipes = null;
        state.env.importedEquipment = null;
        // 装备来源切回配装器：清空 wzc 内单件覆盖（用户决策：换源 = 重置参考装备），
        // 刷新候选池表的"当前装备"列
        state.slotOverrides = {};
        syncCurrentEquip();
        renderCandsTable();
        renderEnv();
        saveWzcState();
      });
      // 奇穴 / 秘籍 / 团辅按钮：复用模拟器全局 modal；modal 关闭后刷新 env 计数
      // talent/recipe overlay 用 DOM remove；team_buffs_modal 用 style.display 切换，需分别检测
      const refreshAfterModal = () => {
        const stop = Date.now() + 60000;
        const tick = () => {
          const t = document.getElementById('talent_overlay');
          const r = document.getElementById('recipe_overlay');
          const tb = document.getElementById('team_buffs_modal');
          const tbVisible = tb && tb.style.display && tb.style.display !== 'none';
          if (!t && !r && !tbVisible) { renderEnv(); return; }
          if (Date.now() > stop) return;
          setTimeout(tick, 300);
        };
        setTimeout(tick, 300);
      };
      document.getElementById('wzc_open_talents')?.addEventListener('click', () => {
        document.getElementById('btn_talents')?.click();
        refreshAfterModal();
      });
      document.getElementById('wzc_open_recipes')?.addEventListener('click', () => {
        document.getElementById('btn_recipes')?.click();
        refreshAfterModal();
      });
      document.getElementById('wzc_open_team_buffs')?.addEventListener('click', () => {
        document.getElementById('btn_team_buffs')?.click();
        refreshAfterModal();
      });
      syncCurrentEquip();
      renderCandsTable();
      // 上次搜索结果：直接恢复（不要重跑）
      if (state.lastResult) {
        try {
          const ageS = state.lastResultAt ? Math.round((Date.now() - state.lastResultAt) / 1000) : 0;
          const elapsedStr = state.lastResultElapsed || '—';
          renderResult(state.lastResult, elapsedStr);
          // 加一行小提示告诉用户这是缓存
          const sumEl = document.getElementById('wzc_summary');
          if (sumEl && ageS > 0) {
            const tag = ageS < 60 ? `${ageS}s 前`
              : ageS < 3600 ? `${Math.floor(ageS/60)}m 前`
              : ageS < 86400 ? `${Math.floor(ageS/3600)}h 前`
              : `${Math.floor(ageS/86400)}d 前`;
            sumEl.insertAdjacentHTML('afterbegin',
              `<div class="wzc-hint" style="color:#79c0ff;margin-bottom:6px;">📦 已加载上次搜索结果（${tag}）</div>`);
          }
        } catch (e) { console.warn('[wzc] 恢复 lastResult 失败', e); }
      }
      // 默认拉一次候选（当前 filter 应用）
      (async () => {
        await refreshAllCands();
        renderCandsTable();
      })();
    } else {
      // 重进时刷新当前装备 / 环境信息
      syncCurrentEquip();
      renderCandsTable();
    }
  }).observe(page, { attributes: true, attributeFilter: ['class'] });
})();

// ═══════════════════════════════════════════════════════════════════════════
// PR 19：历史库（userdata/loops/）
// ═══════════════════════════════════════════════════════════════════════════
(function initHistoryPage() {
  const page = document.getElementById('page-history');
  if (!page) return;
  const listEl = page.querySelector('#hist_list');
  const titleEl = page.querySelector('#hist_preview_title');
  const infoEl = page.querySelector('#hist_preview_info');
  const ta = page.querySelector('#hist_preview_macro');
  const hl = page.querySelector('#hist_preview_hl');
  const statusEl = page.querySelector('#hist_status');
  const btnApply = page.querySelector('#hist_apply');
  const btnToB = page.querySelector('#hist_to_b');
  const btnDelete = page.querySelector('#hist_delete');
  let currentFile = null;
  let currentCfg = null;

  async function refreshList() {
    listEl.innerHTML = '<div class="wz-hint">加载中…</div>';
    try {
      const r = await fetch('/api/loop/list');
      const data = await r.json();
      const files = data.files || [];
      if (files.length === 0) { listEl.innerHTML = '<div class="wz-hint">userdata/loops/ 为空</div>'; return; }
      listEl.innerHTML = files.map(f => `
        <div class="wz-iter-hist-row" data-file="${escapeHtml(f)}" style="cursor:pointer;">
          <span class="wz-iter-hist-kind" style="flex:1;">${escapeHtml(f)}</span>
        </div>`).join('');
      listEl.querySelectorAll('[data-file]').forEach(el => {
        el.addEventListener('click', () => selectFile(el.dataset.file, el));
      });
    } catch (e) {
      listEl.innerHTML = `<div class="wz-hint" style="color:#f85149">加载失败：${e.message}</div>`;
    }
  }

  async function selectFile(name, el) {
    listEl.querySelectorAll('.wz-iter-hist-row').forEach(x => x.classList.remove('current'));
    if (el) el.classList.add('current');
    currentFile = name;
    titleEl.textContent = '预览：' + name;
    infoEl.innerHTML = '<div class="wz-hint">加载中…</div>';
    ta.value = ''; if (hl) hl.innerHTML = '';
    btnApply.disabled = true; btnToB.disabled = true; btnDelete.disabled = true;
    try {
      const r = await fetch('/api/loop/load?name=' + encodeURIComponent(name));
      const cfg = await r.json();
      if (cfg.error) { infoEl.innerHTML = `<div class="wz-hint" style="color:#f85149">${cfg.error}</div>`; return; }
      currentCfg = cfg;
      const mc = cfg.macro || {};
      let macro = '';
      if (mc.mode === 'stance') {
        if (mc.shield) macro += '#page shield\n' + mc.shield + '\n';
        if (mc.blade) macro += '#page blade\n' + mc.blade + '\n';
      } else {
        macro = mc.general || '';
      }
      ta.value = macro.trim();
      if (hl && typeof highlightMacroText === 'function') hl.innerHTML = highlightMacroText(macro) + '\n';
      const seqN = (cfg.sequence || []).length;
      const exported = cfg.exported_at ? new Date(cfg.exported_at).toLocaleString() : '?';
      const delay = cfg.network_delay != null ? cfg.network_delay + 'ms' : '?';
      const rage = cfg.initial_rage != null ? cfg.initial_rage : '—';
      infoEl.innerHTML = `
        <div>导出时间：${exported}</div>
        <div>序列项：<b>${seqN}</b> · 延迟：${delay} · 起始怒气：${rage}</div>
        <div>宏模式：${mc.mode || 'general'} · 字数：<b>${macro.trim().length}</b></div>
      `;
      btnApply.disabled = false; btnToB.disabled = !macro.trim(); btnDelete.disabled = false;
    } catch (e) {
      infoEl.innerHTML = `<div class="wz-hint" style="color:#f85149">加载失败：${e.message}</div>`;
    }
  }

  page.querySelector('#hist_refresh')?.addEventListener('click', refreshList);
  page.querySelector('#hist_open_dir')?.addEventListener('click', async () => {
    try {
      const r = await fetch('/api/loop/open_folder', { method: 'POST' });
      const d = await r.json();
      if (!d.ok) statusEl.textContent = '打开失败：' + (d.error || '');
    } catch (e) { statusEl.textContent = '请求失败：' + e.message; }
  });
  btnApply?.addEventListener('click', () => {
    if (!currentCfg) return;
    if (!confirm('将覆盖当前循环模拟的目标/奇穴/秘籍/序列/宏/延迟/起始怒气，继续？')) return;
    try {
      applyLoopConfig(currentCfg);
      window.Jx3Nav?.switchPage('page-sim');
    } catch (e) { statusEl.textContent = '应用失败：' + e.message; }
  });
  btnToB?.addEventListener('click', () => {
    if (!currentCfg) return;
    window.Jx3WizardB?.enter();
    // 进入后等一点时间再把文本写进去
    setTimeout(() => {
      const mc = currentCfg.macro || {};
      let macro = '';
      if (mc.mode === 'stance') {
        if (mc.shield) macro += '#page shield\n' + mc.shield + '\n';
        if (mc.blade) macro += '#page blade\n' + mc.blade + '\n';
      } else macro = mc.general || '';
      const wTa = document.getElementById('wzb_macro');
      if (wTa) {
        wTa.value = macro.trim();
        wTa.dispatchEvent(new Event('input'));
      }
    }, 150);
  });
  btnDelete?.addEventListener('click', async () => {
    if (!currentFile) return;
    if (!confirm(`确认删除 ${currentFile}？此操作不可撤销。`)) return;
    try {
      const r = await fetch('/api/loop/delete', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: currentFile }),
      });
      const d = await r.json();
      if (!d.ok) { statusEl.textContent = '删除失败：' + (d.error || ''); return; }
      statusEl.textContent = '已删除 ' + currentFile;
      currentFile = null; currentCfg = null;
      ta.value = ''; if (hl) hl.innerHTML = '';
      infoEl.innerHTML = ''; titleEl.textContent = '预览';
      btnApply.disabled = true; btnToB.disabled = true; btnDelete.disabled = true;
      refreshList();
    } catch (e) { statusEl.textContent = '请求失败：' + e.message; }
  });

  // 页切到 page-history 时刷新
  new MutationObserver(() => {
    if (page.classList.contains('active')) refreshList();
  }).observe(page, { attributes: true, attributeFilter: ['class'] });
})();

// ═══════════════════════════════════════════════════════════════
// 配装器 (Equipment Configurator)
// ═══════════════════════════════════════════════════════════════
(function setupEquip() {
  const page = document.getElementById('page-equip');
  if (!page) return;

  // POS_TO_SUB 已抽到顶层全局，直接用

  // 状态
  const state = {
    currentPos: null,
    currentItemId: null,
    // 每部位配置
    slots: {},  // { HAT: { equip_id, strength, embedding: [6,6], enhance_id, enchant_id }, ... }
    stoneId: 0,
    stoneName: '',
    meta: null,
    schools: [],
    kinds: [],
    filter: {
      min_level: 22000,
      max_level: 0,
      schools: new Set(),
      kinds: new Set(),
      attrs: new Set(),
      battle_types: new Set(['PVE']),
      keyword: '',
      onlySet: false,
      onlyOrange: false,
      categories: new Set(),
    },
    // 排序：列表表头点击切换；默认按 DPS Δ 降序，DPS 算完后 scheduleDpsResort 节流重排
    sort: { key: 'dps_delta', dir: 'desc' },
    // DPS 预览结果缓存：item_id → dps（schedulePreviewDps 每跑完一个填）
    // 切换部位 / 重新拉列表时清空；按 DPS Δ 排序时从这里读
    dpsCache: new Map(),
    baselineDps: null,
    lastListRaw: [],   // 上次 renderList 的过滤后原始数据，DPS 重排时按 id 查
    lastCalcResp: null,
  };

  // 镶嵌"连锁"开关（默认开启）：开启时改一个孔位会同步所有其他孔位
  state.embedLink = true;

  // 从 localStorage 恢复
  try {
    const saved = localStorage.getItem('eq_config_v1');
    if (saved) {
      const d = JSON.parse(saved);
      if (d.slots) state.slots = d.slots;
      if (d.stoneId) state.stoneId = d.stoneId;
      if (d.stoneName) state.stoneName = d.stoneName;
      if (typeof d.embedLink === 'boolean') state.embedLink = d.embedLink;
    }
  } catch (e) {}

  function saveToLocal() {
    try {
      localStorage.setItem('eq_config_v1', JSON.stringify({
        slots: state.slots,
        stoneId: state.stoneId,
        stoneName: state.stoneName,
        embedLink: state.embedLink,
      }));
    } catch (e) {}
  }

  async function apiPost(url, body) {
    const r = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body || {}),
    });
    return r.json();
  }
  async function apiGet(url) {
    const r = await fetch(url);
    return r.json();
  }

  // 缓存：装备详情 / 附魔列表（用于 hover tooltip + 节流 API）
  const detailCache = new Map();      // equip_id → detail
  const enhanceCache = new Map();     // sub_type → entries
  const enchantCache = new Map();     // sub_type → entries

  // 注意：id 跨表不唯一，必须配 sub_type 才能定位
  async function getDetailCached(subType, id) {
    const key = `${subType}:${id}`;
    if (detailCache.has(key)) return detailCache.get(key);
    const resp = await apiPost('/api/equip/detail', { id, sub_type: subType });
    const d = resp?.ok ? resp.detail : null;
    if (d) detailCache.set(key, d);
    return d;
  }
  async function getEnhancesCached(subType) {
    if (enhanceCache.has(subType)) return enhanceCache.get(subType);
    const list = await apiPost('/api/equip/enhances', { sub_type: subType });
    const arr = Array.isArray(list) ? list : [];
    enhanceCache.set(subType, arr);
    return arr;
  }
  async function getEnchantsCached(subType) {
    if (enchantCache.has(subType)) return enchantCache.get(subType);
    const list = await apiPost('/api/equip/enchants', { sub_type: subType });
    const arr = Array.isArray(list) ? list : [];
    enchantCache.set(subType, arr);
    return arr;
  }

  // 加载元数据
  async function loadMeta() {
    if (state.meta) return state.meta;
    try {
      const meta = await apiGet('/api/equip/meta');
      state.meta = meta;
      state.schools = meta.schools || [];
      state.kinds = meta.kinds || [];
      state.filter.min_level = 22000;
      renderChips();
      return meta;
    } catch (e) {
      console.error('加载装备元数据失败', e);
    }
  }

  function renderChips() {
    const schoolBox = document.getElementById('eq_school_chips');
    const kindBox = document.getElementById('eq_kind_chips');
    if (!schoolBox || !kindBox) return;
    // 门派芯片（优先排序常用的）
    const schoolOrder = ['通用', '精简', '无修', '苍云', '天策', '少林', '明教'];
    const schools = [...state.schools].filter(s => s && s !== '——').sort((a, b) => {
      const ia = schoolOrder.indexOf(a), ib = schoolOrder.indexOf(b);
      if (ia === -1 && ib === -1) return a.localeCompare(b);
      if (ia === -1) return 1;
      if (ib === -1) return -1;
      return ia - ib;
    });
    schoolBox.innerHTML = schools.map(s => `<button class="eq-chip" data-school="${s}">${s}</button>`).join('');
    schoolBox.querySelectorAll('.eq-chip').forEach(btn => {
      // 同步当前 state.filter 到 active 态
      if (state.filter.schools.has(btn.dataset.school)) btn.classList.add('active');
      btn.addEventListener('click', () => {
        const s = btn.dataset.school;
        if (state.filter.schools.has(s)) state.filter.schools.delete(s);
        else state.filter.schools.add(s);
        btn.classList.toggle('active');
        refreshList();
      });
    });

    const kinds = [...state.kinds].filter(k => k && k !== '——' && k !== '通用');
    kindBox.innerHTML = kinds.map(k => `<button class="eq-chip" data-kind="${k}">${k}</button>`).join('');
    kindBox.querySelectorAll('.eq-chip').forEach(btn => {
      if (state.filter.kinds.has(btn.dataset.kind)) btn.classList.add('active');
      btn.addEventListener('click', () => {
        const k = btn.dataset.kind;
        if (state.filter.kinds.has(k)) state.filter.kinds.delete(k);
        else state.filter.kinds.add(k);
        btn.classList.toggle('active');
        refreshList();
      });
    });
  }

  /** 当前心法的默认 kind（按主输出/主防御属性区分）。
   *  装备数据里的 magic_kind 不是"外功"这种聚合标签，而是更细的"力道/身法/防御/体质"等。 */
  function getDefaultKindsForMount() {
    const m = (typeof currentMount !== 'undefined' && currentMount?.mount) || 'FenShanJin';
    if (m === 'TieGuYi')   return ['防御'];           // 主 T，堆防御
    if (m === 'FenShanJin') return ['身法'];           // 苍云外攻，主属性 = 身法
    return [];
  }

  /** 若 schools/kinds 都为空，自动选上"通用 + (心法默认 kind)"作为默认筛选，
   *  让首次进入某部位时的列表/DPS 预览候选缩到一个合理小集。
   *  (renderChips 已经读 state.filter 同步 active，但若芯片已绘出，这里也直接打 active 让当前面板立刻反映)
   */
  function applyDefaultFilterIfFresh() {
    if (state.filter.schools.size > 0 || state.filter.kinds.size > 0) return;
    const wantSchool = '通用';
    if ((state.schools || []).includes(wantSchool)) {
      state.filter.schools.add(wantSchool);
      document.querySelector(`#eq_school_chips .eq-chip[data-school="${wantSchool}"]`)?.classList.add('active');
    }
    const wantKinds = getDefaultKindsForMount();
    for (const k of wantKinds) {
      if ((state.kinds || []).includes(k)) {
        state.filter.kinds.add(k);
        document.querySelector(`#eq_kind_chips .eq-chip[data-kind="${k}"]`)?.classList.add('active');
      }
    }
  }

  // 部位按钮
  page.querySelectorAll('.eq-slot').forEach(btn => {
    if (!btn.dataset.label) btn.dataset.label = (btn.textContent || '').trim();
    btn.addEventListener('click', () => {
      hideSlotTooltip();
      selectPosition(btn.dataset.pos);
    });
    btn.addEventListener('mouseenter', () => {
      clearTimeout(hoverTimer);
      hoverTimer = setTimeout(() => showSlotTooltip(btn), 180);
    });
    btn.addEventListener('mouseleave', hideSlotTooltip);
  });

  function selectPosition(pos) {
    state.currentPos = pos;
    state.currentItemId = state.slots[pos]?.equip_id || null;
    clearDpsCache();
    page.querySelectorAll('.eq-slot').forEach(b => {
      b.classList.toggle('active', b.dataset.pos === pos);
    });
    const head = document.getElementById('eq_center_head');
    const slotLabel = page.querySelector(`.eq-slot[data-pos="${pos}"]`).dataset.label || '';
    head.textContent = `▸ ${slotLabel}`;
    head.classList.add('active');
    document.getElementById('eq_filters').style.display = '';
    document.getElementById('eq_list_table').style.display = '';
    document.getElementById('eq_clear_slot').disabled = !state.slots[pos];
    // 默认筛选：第一次进入或 reset 后选一个位置时，自动勾上"通用 + 外功"
    applyDefaultFilterIfFresh();
    // 首次填 DPS 来源下拉（plaza 列表 + userdata/loops 文件）
    if (!state._dpsSourcePopulated) {
      state._dpsSourcePopulated = true;
      populateDpsSourceOptions();
    }
    bindSortHeaders();
    refreshList();
    if (state.currentItemId) {
      showDetailForItem(state.currentItemId);
    } else {
      document.getElementById('eq_detail').style.display = 'none';
      document.getElementById('eq_detail_empty').style.display = '';
    }
  }

  // 装备列表
  async function refreshList() {
    if (!state.currentPos) return;
    const sub = POS_TO_SUB[state.currentPos];
    const body = {
      sub_type: sub,
      min_level: state.filter.min_level || 0,
      max_level: state.filter.max_level || 0,
      schools: [...state.filter.schools],
      kinds: [...state.filter.kinds],
      attrs: [...state.filter.attrs],
      battle_types: [...state.filter.battle_types],
      keyword: state.filter.keyword || '',
      categories: [...state.filter.categories],
    };
    try {
      const items = await apiPost('/api/equip/search', body);
      renderList(items || []);
    } catch (e) {
      console.error('搜索失败', e);
    }
  }

  function compareItems(a, b) {
    const { key, dir } = state.sort;
    if (!key) return 0; // 默认：保持后端返回顺序
    const sign = dir === 'asc' ? 1 : -1;
    if (key === 'dps_delta') {
      const da = state.dpsCache.get(a.id);
      const db = state.dpsCache.get(b.id);
      const aValid = (da != null && !Number.isNaN(da));
      const bValid = (db != null && !Number.isNaN(db));
      // 未算完的统一沉底（无论 asc/desc）
      if (!aValid && !bValid) return 0;
      if (!aValid) return 1;
      if (!bValid) return -1;
      return sign * (da - db);
    }
    let va, vb;
    if (key === 'name')              { va = a.name || ''; vb = b.name || ''; }
    else if (key === 'magic_type')   { va = a.magic_type || ''; vb = b.magic_type || ''; }
    else if (key === 'belong_school'){ va = a.belong_school || ''; vb = b.belong_school || ''; }
    else if (key === 'set_name')     { va = a.set_name || ''; vb = b.set_name || ''; }
    else if (key === 'level')        { va = a.level || 0; vb = b.level || 0; }
    if (typeof va === 'string') return sign * va.localeCompare(vb, 'zh');
    return sign * (va - vb);
  }

  function updateSortIndicators() {
    const head = document.querySelector('#eq_list_table thead');
    if (!head) return;
    head.querySelectorAll('th[data-sort-key]').forEach(th => {
      const k = th.dataset.sortKey;
      th.classList.toggle('sort-asc',  state.sort.key === k && state.sort.dir === 'asc');
      th.classList.toggle('sort-desc', state.sort.key === k && state.sort.dir === 'desc');
    });
  }

  function renderList(items) {
    let list = items;
    if (state.filter.onlySet) list = list.filter(i => i.set_name);
    if (state.filter.onlyOrange) list = list.filter(i => i.quality >= 5);
    state.lastListRaw = list;
    const tbody = document.getElementById('eq_list_body');
    const count = document.getElementById('eq_list_count');
    count.textContent = `共 ${list.length} 件`;
    let visible = list.slice(0, 500);
    if (state.sort.key) visible = [...visible].sort(compareItems);
    tbody.innerHTML = visible.map(it => {
      const cls = it.quality >= 5 ? 'eq-name-orange' : 'eq-name-purple';
      const isCur = it.id === state.currentItemId;
      const selected = isCur ? 'selected' : '';
      const curTag = isCur ? ' <span class="eq-cur-tag" title="本部位当前装备">[当前]</span>' : '';
      return `<tr data-id="${it.id}" data-name="${escapeHtml(it.name)}" data-quality="${it.quality || 0}" class="${selected}">
        <td class="${cls}">${escapeHtml(it.name)}${curTag}</td>
        <td>${escapeHtml(it.magic_type || '')}</td>
        <td>${escapeHtml(it.belong_school || '')}</td>
        <td>${escapeHtml(it.set_name || '')}</td>
        <td class="eq-lv">${it.level}</td>
        <td class="eq-dps-cell" data-dps-id="${it.id}"><span class="eq-dps-pending">·</span></td>
      </tr>`;
    }).join('');
    tbody.querySelectorAll('tr').forEach(tr => {
      tr.addEventListener('click', () => {
        const id = parseInt(tr.dataset.id, 10);
        const name = tr.dataset.name || '';
        const quality = parseInt(tr.dataset.quality, 10) || 0;
        selectItem(id, { name, quality });
      });
    });
    updateSortIndicators();
    // dpsCache 命中的行直接回填，剩下的让 schedulePreviewDps 跑
    if (state.baselineDps != null) {
      for (const it of visible) {
        const dps = state.dpsCache.get(it.id);
        if (dps != null) renderDpsCell(it.id, dps, state.baselineDps);
      }
    }
    // 触发 DPS 预览批量计算（不阻塞列表渲染；schedulePreviewDps 已用 cache 短路命中行）
    schedulePreviewDps(visible);
  }

  // 表头点击：第一次 desc → 第二次 asc → 第三次清空（回到后端原顺序）
  function bindSortHeaders() {
    const head = document.querySelector('#eq_list_table thead');
    if (!head || head.dataset.sortBound) return;
    head.dataset.sortBound = '1';
    head.addEventListener('click', (e) => {
      const th = e.target.closest('th[data-sort-key]');
      if (!th) return;
      const k = th.dataset.sortKey;
      if (state.sort.key !== k) state.sort = { key: k, dir: 'desc' };
      else if (state.sort.dir === 'desc') state.sort = { key: k, dir: 'asc' };
      else state.sort = { key: null, dir: 'desc' };
      // 不重发搜索请求，重新渲染当前列表（dpsCache 会自动复用）
      if (state.lastListRaw.length) renderList(state.lastListRaw);
    });
  }

  // ── DPS 预览：每行替换当前部位为该装备，跑一次 lite 模拟看 DPS 增减 ──
  // 不做缓存，跑出来一个填一个；设 token 让筛选切换时丢弃在途结果
  let _previewBatchToken = 0;

  // 预览来源（对应"DPS 来源"下拉）
  // 默认 'current'：取循环模拟页当前的宏 + 配置；
  // 'plaza:<id>'：从战斗广场加载某保存方案；
  // 'loop:<filename>'：从 userdata/loops 加载循环 JSON。
  state.previewSource = { kind: 'current' };

  /** 把 buildLoopConfig 风格的结构化 sequence 展平成 simulate API 需要的字符串数组 */
  function flattenSeqEntries(seq) {
    const out = [];
    for (const e of (seq || [])) {
      const cnt = Math.max(1, e.count || 1);
      let token = null;
      if (e.type === 'macro')         token = '__macro__';
      else if (e.type === 'wait_stance')   token = '__切体态延迟中__';
      else if (e.type === 'wait_zhan_jue') token = '__战绝回怒__';
      else if (e.type === 'break')         token = '__break__';
      else if (e.type === 'skill')         token = e.skill;
      if (!token) continue;
      for (let i = 0; i < cnt; i++) out.push(token);
    }
    return out;
  }

  /** { mode, general, shield, blade } → 后端宏文本 */
  function macroPagesToText(m) {
    if (!m) return '';
    if (m.mode === 'general') return (m.general || '').trim();
    let t = '';
    if (m.shield) t += '#page shield\n' + m.shield + '\n';
    if (m.blade)  t += '#page blade\n' + m.blade + '\n';
    return t.trim();
  }

  /** 解析预览来源 → 跑模拟需要的 bundle（不含 attributes，由调用方覆盖）。
   *  时长口径：跟随来源自带 macro_duration（"当前循环"取 macroLastDuration，
   *  方案/loop 取保存值），缺省 fallback 60s（从未跑过 sim 的初始态）。
   *  返回 null 表示来源不可用，调用方应将 DPS 单元置 "—"。 */
  async function resolvePreviewSource() {
    const src = state.previewSource || { kind: 'current' };
    const FALLBACK_DURATION = 60; // 用户从未跑过 sim 的兜底
    if (src.kind === 'current') {
      const macroText = (typeof buildMacroText === 'function') ? buildMacroText() : '';
      if (!macroText.trim()) {
        // 当前循环没填宏 —— 用纯序列模式，看主页 DOM 里有什么
        const cfg = (typeof buildLoopConfig === 'function') ? buildLoopConfig() : null;
        const seq = cfg ? flattenSeqEntries(cfg.sequence) : [];
        if (seq.length === 0) return null;
        return {
          sequence: seq,
          macro_text: '',
          talents: getCurrentTalents(),
          recipes: (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [],
          target: (typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 },
          network_delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
          initial_rage: (typeof adminInitialRage !== 'undefined') ? (adminInitialRage || 0) : 0,
          boss_attack_interval: (typeof getBossAttackInterval === 'function') ? getBossAttackInterval() : 0,
          macro_duration: 0,
          team_buffs: (typeof getTeamBuffs === 'function') ? getTeamBuffs() : [],
          formation: (typeof getCurrentFormation === 'function') ? getCurrentFormation() : null,
        };
      }
      // 跟随循环模拟页上次跑的时长；若用户从未跑过 fallback 60s
      const duration = (typeof macroLastDuration !== 'undefined' && macroLastDuration > 0)
        ? macroLastDuration : FALLBACK_DURATION;
      const maxSlots = Math.ceil(duration / 0.25) + 20;
      return {
        sequence: Array(maxSlots).fill('__macro__'),
        macro_text: macroText,
        talents: getCurrentTalents(),
        recipes: (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [],
        target: (typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 },
        network_delay: parseInt(document.getElementById('sim_delay')?.value) || 0,
        initial_rage: (typeof adminInitialRage !== 'undefined') ? (adminInitialRage || 0) : 0,
        boss_attack_interval: (typeof getBossAttackInterval === 'function') ? getBossAttackInterval() : 0,
        macro_duration: duration,
        team_buffs: (typeof getTeamBuffs === 'function') ? getTeamBuffs() : [],
        formation: (typeof getCurrentFormation === 'function') ? getCurrentFormation() : null,
      };
    }
    if (src.kind === 'plaza') {
      const b = window.Jx3Plaza?.get?.(src.id);
      if (!b) return null;
      const r = b.rotation || {};
      const macroText = macroPagesToText(r.macro);
      const seq = flattenSeqEntries(r.sequence);
      // 优先用宏：方案有宏就按宏跑，时长跟随方案 macro_duration（fallback 60s）
      const useMacro = !!macroText.trim();
      const duration = useMacro
        ? (Number(r.macro_duration) > 0 ? Number(r.macro_duration) : FALLBACK_DURATION)
        : 0;
      const seqOrFill = useMacro
        ? Array(Math.ceil(duration / 0.25) + 20).fill('__macro__')
        : (seq.length ? seq : ['盾击']);
      return {
        sequence: seqOrFill,
        macro_text: useMacro ? macroText : '',
        talents: b.talents || [],
        recipes: b.recipes || [],
        target: b.target || ((typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 }),
        network_delay: r.delay || 0,
        initial_rage: r.initial_rage || 0,
        boss_attack_interval: r.boss_attack_interval || 0,
        macro_duration: duration,
        // 方案级 team_buffs / formation 优先；fallback 到全局（兼容旧方案没存增益的）
        team_buffs: Array.isArray(b.team_buffs) ? b.team_buffs
                  : ((typeof getTeamBuffs === 'function') ? getTeamBuffs() : []),
        formation: b.formation
                || ((typeof getCurrentFormation === 'function') ? getCurrentFormation() : null),
      };
    }
    if (src.kind === 'loop') {
      try {
        const resp = await fetch(`/api/loop/load?name=${encodeURIComponent(src.name)}`);
        if (!resp.ok) return null;
        const cfg = await resp.json();
        if (cfg.error) return null;
        const macroText = macroPagesToText(cfg.macro);
        const seq = flattenSeqEntries(cfg.sequence);
        const useMacro = !!macroText.trim();
        const duration = useMacro
          ? (Number(cfg.macro_duration) > 0 ? Number(cfg.macro_duration) : FALLBACK_DURATION)
          : 0;
        const seqOrFill = useMacro
          ? Array(Math.ceil(duration / 0.25) + 20).fill('__macro__')
          : (seq.length ? seq : ['盾击']);
        // 奇穴/秘籍：loop 文件结构里 talents / recipes 是按层 / 按技能分组的对象，
        // 简单展平为扁平 ID 数组
        const flatTalents = [];
        for (const v of Object.values(cfg.talents || {})) {
          if (Array.isArray(v)) flatTalents.push(...v);
          else if (typeof v === 'number') flatTalents.push(v);
        }
        const flatRecipes = [];
        for (const v of Object.values(cfg.recipes || {})) {
          if (Array.isArray(v)) flatRecipes.push(...v);
        }
        return {
          sequence: seqOrFill,
          macro_text: useMacro ? macroText : '',
          talents: flatTalents.length ? flatTalents : getCurrentTalents(),
          recipes: flatRecipes.length ? flatRecipes : ((typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : []),
          target: cfg.target || ((typeof getTarget === 'function') ? getTarget() : { level: 134, defense_bonus: 0 }),
          network_delay: cfg.network_delay || 0,
          initial_rage: cfg.initial_rage || 0,
          boss_attack_interval: cfg.boss_attack_interval || 0,
          macro_duration: duration,
          // loop 方案存的 team_buffs/formation 优先；fallback 全局
          team_buffs: Array.isArray(cfg.team_buffs) ? cfg.team_buffs
                    : ((typeof getTeamBuffs === 'function') ? getTeamBuffs() : []),
          formation: cfg.formation
                  || ((typeof getCurrentFormation === 'function') ? getCurrentFormation() : null),
        };
      } catch (e) {
        console.warn('[eq-preview] 加载 loop 失败', e);
        return null;
      }
    }
    return null;
  }

  /** 把 plaza 列表 + userdata/loops 列表填到 #eq_dps_source 下拉里 */
  async function populateDpsSourceOptions() {
    const sel = document.getElementById('eq_dps_source');
    if (!sel) return;
    const cur = sel.value || 'current';
    const opts = ['<option value="current">当前循环</option>'];
    // 战斗广场方案
    try {
      const builds = window.Jx3Plaza?.list?.() || [];
      if (builds.length) {
        opts.push('<optgroup label="战斗广场方案">');
        for (const b of builds) {
          opts.push(`<option value="plaza:${b.id}">${escapeHtml(b.name || '(未命名方案)')}</option>`);
        }
        opts.push('</optgroup>');
      }
    } catch {}
    // userdata/loops
    try {
      const r = await fetch('/api/loop/list');
      if (r.ok) {
        const j = await r.json();
        const files = j.files || [];
        if (files.length) {
          opts.push('<optgroup label="保存的循环">');
          for (const f of files) {
            const stem = f.replace(/\.json$/i, '');
            opts.push(`<option value="loop:${escapeHtml(f)}">${escapeHtml(stem)}</option>`);
          }
          opts.push('</optgroup>');
        }
      }
    } catch {}
    sel.innerHTML = opts.join('');
    // 尽量保留原选中
    if ([...sel.options].some(o => o.value === cur)) sel.value = cur;
  }
  // 下拉变化 → 更新 state + 重跑预览
  document.getElementById('eq_dps_source')?.addEventListener('change', (e) => {
    const v = e.target.value || 'current';
    if (v === 'current') state.previewSource = { kind: 'current' };
    else if (v.startsWith('plaza:')) state.previewSource = { kind: 'plaza', id: v.slice(6) };
    else if (v.startsWith('loop:')) state.previewSource = { kind: 'loop', name: v.slice(5) };
    else state.previewSource = { kind: 'current' };
    clearDpsCache(); // 来源变了所有 DPS 失效
    refreshList(); // 触发新一轮 schedulePreviewDps
  });

  /** 拷贝当前 slots 并把 currentPos 替换为新 equip_id（保留精炼/镶嵌/附魔等已有配置） */
  function buildSwapSlots(equipId) {
    const out = JSON.parse(JSON.stringify(state.slots || {}));
    const cur = out[state.currentPos] || { strength: 6, embedding: [6, 6, 6], enhance_id: 0, enchant_id: 0 };
    out[state.currentPos] = { ...cur, equip_id: equipId };
    return out;
  }

  async function calcRawAttrsForSlots(slots, mountId, talents, stoneIdOverride) {
    const stoneId = (stoneIdOverride !== undefined) ? stoneIdOverride : (state.stoneId || 0);
    const r = await apiPost('/api/equip/calculate', {
      slots, stone_id: stoneId, mount: mountId, talents,
    });
    return r?.raw || null;
  }

  /** 用 raw 属性 + 来源 bundle (sequence/macro/talents/recipes/...) 跑一次 lite 模拟，返回 DPS。
   *  slots：参与 simulate 的装备清单（baseline 传 state.slots，candidate 传 swap 后的 slots）；
   *  折成 { POS: equip_id, ENCHANT_POS: enchant_id } 传给后端，让脚本侧的装备特效（神兵 /
   *  大附魔触发型 / 套装脚本）正常触发，否则候选与基线只看属性差，丢失实战 buff/特效维度。 */
  async function simulateDpsForRaw(raw, srcBundle, slots) {
    if (!raw || !srcBundle) return null;
    const equipMap = {};
    for (const [pos, s] of Object.entries(slots || {})) {
      if (s?.equip_id)   equipMap[pos] = s.equip_id;
      if (s?.enchant_id) equipMap['ENCHANT_' + pos] = s.enchant_id;
    }
    const r = await fetch('/api/simulate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        haste_level: Math.round(raw.haste_level || 0),
        sequence: srcBundle.sequence,
        macro_text: srcBundle.macro_text || undefined,
        macro_duration: srcBundle.macro_duration || undefined,
        talents: srcBundle.talents,
        recipes: srcBundle.recipes,
        channel_ticks: {}, timing_offsets: {}, qijin_buffs: {},
        network_delay: srcBundle.network_delay || 0,
        attributes: {
          li_dao:            raw.strength            || 44,
          shen_fa:           raw.agility             || 44,
          vitality:          raw.vitality            || 45,
          base_attack:       raw.base_attack         || 0,
          weapon_damage:     raw.weapon_damage       || 0,
          surplus_value:     raw.surplus_value       || 0,
          crit_level:        raw.crit_level          || 0,
          crit_effect_level: raw.crit_effect_level   || 0,
          overcome_level:    raw.overcome_level      || 0,
          strain_level:      raw.strain_level        || 0,
          haste_level:       raw.haste_level         || 0,
          parry_value:       raw.parry_value         || 0,
          parry_level:       raw.parry_level         || 0,
        },
        target: srcBundle.target,
        initial_rage: srcBundle.initial_rage || 0,
        boss_attack_interval: srcBundle.boss_attack_interval || undefined,
        equipment: equipMap,
        team_buffs: srcBundle.team_buffs || ((typeof getTeamBuffs === 'function') ? getTeamBuffs() : []),
        formation: srcBundle.formation || ((typeof getCurrentFormation === 'function') ? getCurrentFormation() : null),
        // lite + 不要 timeline：只关心 DPS，最小路径
        lite: true,
        lite_keep_timeline: false,
      }),
    });
    if (!r.ok) throw new Error(await r.text());
    const j = await r.json();
    return j.dps || 0;
  }

  /** 渲染单行 DPS 单元（不重排行，避免抖动） */
  function renderDpsCell(itemId, dps, baseline) {
    const cell = document.querySelector(`.eq-dps-cell[data-dps-id="${itemId}"]`);
    if (!cell) return;
    if (dps == null) {
      cell.innerHTML = '<span class="eq-dps-fail" title="计算失败">—</span>';
      return;
    }
    const delta = dps - baseline;
    const tol = Math.max(Math.abs(baseline) * 0.005, 50); // ±0.5% 内视为持平
    let cls = 'eq-dps-zero';
    let prefix = '';
    if (delta > tol) { cls = 'eq-dps-up';   prefix = '+'; }
    else if (delta < -tol) { cls = 'eq-dps-down'; prefix = ''; } // 负数自带 -
    const txt = prefix + Math.round(delta).toLocaleString();
    cell.innerHTML = `<span class="${cls}" title="DPS=${Math.round(dps).toLocaleString()}">${txt}</span>`;
  }

  /** 入口：列表渲染完后调用，启动 N 个 worker 并发计算 DPS 预览 */
  async function schedulePreviewDps(items) {
    if (!state.currentPos) return;
    const hintEl = document.getElementById('eq_dps_source_hint');

    // 解析来源（可能要等 fetch /api/loop/load）
    const srcBundle = await resolvePreviewSource();
    if (!srcBundle) {
      // 来源不可用 → 全部置为 "—"
      document.querySelectorAll('.eq-dps-cell').forEach(c => {
        c.innerHTML = '<span class="eq-dps-pending" title="DPS 来源不可用：请在循环模拟页填好宏，或选一个有效的保存方案/循环">—</span>';
      });
      if (hintEl) hintEl.textContent = '来源不可用';
      return;
    }
    if (hintEl) {
      const dur = srcBundle.macro_duration;
      const rec = (srcBundle.recipes || []).length;
      hintEl.textContent = dur > 0
        ? `按 ${dur}s · ${rec} 秘籍`
        : `序列 ${srcBundle.sequence.length} 步 · ${rec} 秘籍`;
    }
    const myToken = ++_previewBatchToken;
    const mountId = getCurrentMountId();
    const talentsForCalc = srcBundle.talents || getCurrentTalents();

    // 1. 基线（当前 slots 的 DPS）— cache 命中时跳过请求
    let baselineDps = state.baselineDps;
    if (baselineDps == null) {
      try {
        const baseRaw = await calcRawAttrsForSlots(state.slots, mountId, talentsForCalc);
        if (myToken !== _previewBatchToken) return;
        baselineDps = await simulateDpsForRaw(baseRaw, srcBundle, state.slots);
        if (myToken !== _previewBatchToken) return;
        state.baselineDps = baselineDps;
      } catch (e) {
        console.warn('[eq-preview] baseline 计算失败', e);
        return;
      }
    }

    // 2. 候选并发计算（worker pool 模型，每跑完一个就立即更新对应行）
    // visible 在 renderList 已切到 500 件作 DOM 上限；token 机制会在筛选切换时丢弃在途请求
    // dpsCache 命中的 id 直接渲染，不发请求
    const queue = items.filter(it => {
      if (state.dpsCache.has(it.id)) {
        renderDpsCell(it.id, state.dpsCache.get(it.id), baselineDps);
        return false;
      }
      return true;
    });
    const concurrency = 6; // 浏览器对同源最大约 6 并发，对齐
    async function worker() {
      while (queue.length) {
        if (myToken !== _previewBatchToken) return; // 筛选切了 → 丢
        const it = queue.shift();
        try {
          const swap = buildSwapSlots(it.id);
          const raw = await calcRawAttrsForSlots(swap, mountId, talentsForCalc);
          if (myToken !== _previewBatchToken) return;
          const dps = await simulateDpsForRaw(raw, srcBundle, swap);
          if (myToken !== _previewBatchToken) return;
          state.dpsCache.set(it.id, dps);
          renderDpsCell(it.id, dps, baselineDps);
          scheduleDpsResort();
        } catch (e) {
          if (myToken !== _previewBatchToken) return;
          renderDpsCell(it.id, null, baselineDps);
        }
      }
    }
    await Promise.all(Array.from({ length: concurrency }, () => worker()));
  }

  // DPS Δ 排序时：每跑完一个 cache 触发节流重排（不重发请求，只 reorder DOM 行）
  let _dpsResortTimer = null;
  function scheduleDpsResort() {
    if (state.sort.key !== 'dps_delta') return;
    clearTimeout(_dpsResortTimer);
    _dpsResortTimer = setTimeout(() => {
      const tbody = document.getElementById('eq_list_body');
      if (!tbody) return;
      const rows = [...tbody.children];
      rows.sort((a, b) => {
        const ida = parseInt(a.dataset.id, 10);
        const idb = parseInt(b.dataset.id, 10);
        const da = state.dpsCache.get(ida);
        const db = state.dpsCache.get(idb);
        const aValid = (da != null && !Number.isNaN(da));
        const bValid = (db != null && !Number.isNaN(db));
        if (!aValid && !bValid) return 0;
        if (!aValid) return 1;
        if (!bValid) return -1;
        return state.sort.dir === 'asc' ? da - db : db - da;
      });
      tbody.replaceChildren(...rows);
    }, 200);
  }

  function clearDpsCache() {
    state.dpsCache.clear();
    state.baselineDps = null;
  }

  function selectItem(id, meta) {
    if (!state.currentPos) return;
    if (!state.slots[state.currentPos]) {
      state.slots[state.currentPos] = {
        equip_id: id, strength: 6, embedding: [6, 6, 6], enhance_id: 0, enchant_id: 0,
      };
    } else {
      // 保留精炼/镶嵌/附魔设置，只换装备 ID
      state.slots[state.currentPos].equip_id = id;
    }
    if (meta) {
      if (meta.name) state.slots[state.currentPos].name = meta.name;
      if (meta.quality != null) state.slots[state.currentPos].quality = meta.quality;
    }
    state.currentItemId = id;
    document.getElementById('eq_clear_slot').disabled = false;
    updateSlotBadges();
    saveToLocal();
    clearDpsCache(); // 替换装备改变 baseline + 所有候选 swap → 全部失效
    refreshList(); // 刷新选中状态
    showDetailForItem(id);
    recalculate();
  }

  function updateSlotBadges() {
    page.querySelectorAll('.eq-slot').forEach(btn => {
      const slot = state.slots[btn.dataset.pos];
      btn.classList.toggle('filled', !!slot);
      const label = btn.dataset.label || '';
      const name = slot?.name || '';
      const orangeCls = slot && slot.quality >= 5 ? ' orange' : '';
      btn.innerHTML = `<span class="eq-slot-label">${escapeHtml(label)}</span>` +
        (name ? `<span class="eq-slot-item${orangeCls}">${escapeHtml(name)}</span>` : '');
      btn.removeAttribute('title');
    });
  }

  // ── 部位按钮 hover tooltip ──────────────────────────
  let slotTooltipEl = null;
  let hoverTimer = null;
  let hoverPos = null;

  function ensureTooltipEl() {
    if (slotTooltipEl) return slotTooltipEl;
    slotTooltipEl = document.createElement('div');
    slotTooltipEl.className = 'eq-slot-tooltip';
    slotTooltipEl.style.display = 'none';
    document.body.appendChild(slotTooltipEl);
    return slotTooltipEl;
  }

  // 接受外部 cfg；如果 cfg 缺省则用 state.slots[pos]（向后兼容）。stoneName 也可外传。
  // contextSlots：算"全身已穿同套件数"用的整套装备字典（{ POS: equip_id } 或 { POS: { equip_id, ... } }
  // 都接受）；缺省回退到 state.slots（配装器主页面装备）。wzc 结果卡 / plaza 方案
  // hover 必须传该方案自己的 slots，否则会拿主页面装备的件数显示，给出错误数。
  async function buildSlotTooltipHtml(pos, cfg, stoneNameOverride, contextSlots) {
    if (!cfg) cfg = state.slots[pos];
    if (!cfg?.equip_id) return '';
    const d = await getDetailCached(POS_TO_SUB[pos], cfg.equip_id);
    if (!d) return '';
    const stoneName = (stoneNameOverride !== undefined) ? stoneNameOverride : state.stoneName;
    const [enhances, enchants] = await Promise.all([
      getEnhancesCached(d.sub_type),
      [2, 3, 6, 8, 9, 10].includes(d.sub_type) ? getEnchantsCached(d.sub_type) : Promise.resolve([]),
    ]);

    const STRENGTH_P = [0, 0.005, 0.013, 0.024, 0.038, 0.055, 0.075, 0.098, 0.124];
    const NON_STR = new Set(['atSkillEventHandler', 'atExecuteScript', 'atSetEquipmentRecipe']);
    const str = cfg.strength || 0;
    const fmt1024Pct = v => (v / 1024 * 100).toFixed(1) + '%';

    const parts = [];
    const nameCls = d.quality >= 5 ? 'orange' : 'purple';
    parts.push(`<div class="eq-tip-name ${nameCls}">${escapeHtml(d.name)}</div>`);

    const subs = [];
    if (d.level) subs.push(`品级 ${d.level}`);
    if (d.max_strength) subs.push(`精炼 ${str}/${d.max_strength}`);
    if (d.belong_school) subs.push(d.belong_school);
    if (d.magic_kind) subs.push(d.magic_kind);
    parts.push(`<div class="eq-tip-sub">${escapeHtml(subs.join(' · '))}</div>`);

    const lines = [];
    if (d.sub_type === 0 || d.sub_type === 1) {
      const b1 = d.bases.find(b => b.slot === 'atMeleeWeaponDamageBase');
      const b2 = d.bases.find(b => b.slot === 'atMeleeWeaponDamageRand');
      const b3 = d.bases.find(b => b.slot === 'atMeleeWeaponAttackSpeedBase');
      if (b1) {
        const rand = b2 ? b2.value : 0;
        lines.push(`<div class="eq-d-base">${d.sub_type === 1 ? '远程' : '近身'}伤害提高 ${b1.value}-${b1.value + rand}</div>`);
      }
      if (b3) lines.push(`<div class="eq-d-base">速度 ${(b3.value / 16).toFixed(1)}</div>`);
    } else {
      for (const b of d.bases) {
        lines.push(`<div class="eq-d-base">${escapeHtml(b.label)}提高 ${b.value}</div>`);
      }
    }
    for (const m of d.magics) {
      if (m.slot === 'atSkillEventHandler' || m.slot === 'atExecuteScript' || m.slot === 'atSetEquipmentRecipe') {
        const txt = m.desc ? escapeHtml(m.desc) : escapeHtml(m.label);
        lines.push(`<div style="color:var(--warning)">${txt}</div>`);
      } else {
        const isThreat = m.slot === 'atActiveThreatCoefficient';
        let tail = '';
        if (str > 0 && !NON_STR.has(m.slot)) {
          const bonus = Math.round(m.value * STRENGTH_P[Math.min(str, 8)]);
          if (bonus > 0) {
            const bonusText = isThreat ? fmt1024Pct(bonus) : bonus;
            tail = ` <span class="eq-d-str">(+${bonusText})</span>`;
          }
        }
        const valueText = isThreat ? fmt1024Pct(m.value) : m.value;
        lines.push(`<div class="eq-d-attr">${escapeHtml(m.label)}提高 ${valueText}${tail}</div>`);
      }
    }
    for (let i = 0; i < d.diamonds.length; i++) {
      const ds = d.diamonds[i];
      const lv = (cfg.embedding || [])[i] || 0;
      const val = Math.floor(Math.floor(ds.base_value) * embedCoeff(lv));
      lines.push(`<div class="eq-d-diamond">◇ ${escapeHtml(ds.label)}提高 ${val || '?'} <span class="eq-tip-meta">(${lv}级)</span></div>`);
    }
    parts.push(`<div class="eq-tip-attrs">${lines.join('')}</div>`);

    const enhId = cfg.enhance_id || 0;
    const enhEntry = enhId ? enhances.find(e => e.id === enhId) : null;
    const enhName = enhEntry ? enhEntry.name : (enhId ? `#${enhId}` : '（无）');
    let enhAttrText = '';
    if (enhEntry && Array.isArray(enhEntry.attributes) && enhEntry.attributes.length > 0) {
      const parts2 = enhEntry.attributes.map(a => `${a[1]}+${a[2]}`);
      enhAttrText = ` <span class="eq-tip-meta">(${escapeHtml(parts2.join(' '))})</span>`;
    }
    const enhCls = `eq-tip-enh-name ${enchantQualityClass(enhEntry)}`.trim();
    parts.push(`<div class="eq-tip-row"><span class="eq-tip-k">小附魔</span><span class="${enhCls}">${escapeHtml(enhName)}${enhAttrText}</span></div>`);

    if ([2, 3, 6, 8, 9, 10].includes(d.sub_type)) {
      const encId = cfg.enchant_id || 0;
      const encEntry = encId ? enchants.find(e => e.id === encId) : null;
      const encName = encEntry ? encEntry.name : (encId ? `#${encId}` : '（无）');
      const encCls = enchantQualityClass(encEntry);
      parts.push(`<div class="eq-tip-row"><span class="eq-tip-k">大附魔</span><span class="${encCls}">${escapeHtml(encName)}</span></div>`);
    }

    if (d.sub_type === 0) {
      parts.push(`<div class="eq-tip-row"><span class="eq-tip-k">五彩石</span><span>${escapeHtml(stoneName || '（未选择）')}</span></div>`);
    }

    if (d.set_bonuses && d.set_bonuses.tiers.length > 0) {
      // 全身已穿同 set_id 件数（实拉 detail 比较；detailCache 命中后近瞬时，绕开 state.slots.set_id 缓存的 stale 风险）
      // contextSlots 优先（wzc 结果 / plaza 方案的整套装备）；缺省回退到主页面 state.slots
      const slotsForCount = contextSlots || state.slots;
      let wornCount = 0;
      await Promise.all(Object.entries(slotsForCount).map(async ([p, s]) => {
        // s 可能是裸 equip_id（wzc t.slots 形式）或 { equip_id } 对象
        const eid = (typeof s === 'number') ? s : s?.equip_id;
        if (!eid) return;
        try {
          const dd = await getDetailCached(POS_TO_SUB[p], eid);
          if (dd?.set_id === d.set_id) wornCount++;
        } catch (e) {}
      }));
      const tierHtml = d.set_bonuses.tiers.map(([n, attrs]) => {
        const aLines = attrs.map(a => a.desc
          ? `<div style="color:var(--warning)">${escapeHtml(a.desc)}</div>`
          : `<div>${escapeHtml(a.label)}+${a.value}</div>`).join('');
        const active = wornCount >= n;
        const color = active ? 'var(--gold)' : 'var(--text-dim)';
        const tag = `<span style="color:${color};margin-left:4px">${active ? '✓' : ''}已穿 ${wornCount}/${n}</span>`;
        return `<div class="eq-tip-set-tier" style="${active ? '' : 'opacity:0.6'}"><span class="eq-tip-set-n">${n}件：</span>${tag}${aLines}</div>`;
      }).join('');
      parts.push(`<div class="eq-tip-set"><div class="eq-tip-set-name">${escapeHtml(d.set_bonuses.name)}</div>${tierHtml}</div>`);
    }

    return parts.join('');
  }

  function positionTooltip(tip, btn) {
    const pad = 8;
    const vpW = window.innerWidth;
    const vpH = window.innerHeight;
    tip.style.maxHeight = (vpH - 16) + 'px';
    tip.style.left = '0px';
    tip.style.top = '0px';
    const br = btn.getBoundingClientRect();
    const tr = tip.getBoundingClientRect();
    let left = br.right + pad;
    if (left + tr.width > vpW - 4) {
      left = br.left - pad - tr.width;
      if (left < 4) left = Math.max(4, vpW - tr.width - 4);
    }
    let top = br.top;
    if (top + tr.height > vpH - 4) top = vpH - tr.height - 4;
    if (top < 4) top = 4;
    tip.style.left = left + 'px';
    tip.style.top = top + 'px';
  }

  async function showSlotTooltip(btn) {
    const pos = btn.dataset.pos;
    if (!state.slots[pos]?.equip_id) return;
    hoverPos = pos;
    const html = await buildSlotTooltipHtml(pos);
    if (hoverPos !== pos) return;
    if (!html) return;
    const tip = ensureTooltipEl();
    tip.innerHTML = html;
    tip.style.display = '';
    positionTooltip(tip, btn);
  }
  function hideSlotTooltip() {
    hoverPos = null;
    clearTimeout(hoverTimer);
    if (slotTooltipEl) slotTooltipEl.style.display = 'none';
  }

  // 装备详情。sub_type 可选，未传时按当前部位 (POS_TO_SUB) 推断
  async function showDetailForItem(id, subType) {
    const st = (subType != null) ? subType : (state.currentPos != null ? POS_TO_SUB[state.currentPos] : null);
    if (st == null) return;
    // 渲染套装块前确保所有 slot 的 set_id 最新（detailCache 命中后瞬时返回）
    await hydrateSlotNames();
    const d = await getDetailCached(st, id);
    if (!d) return;
    // 缓存名称 / 品质 / 套装信息到对应部位（套装件数计数依赖 set_id）
    for (const pos of Object.keys(state.slots)) {
      const s = state.slots[pos];
      if (s && s.equip_id === id) {
        s.name = d.name;
        s.quality = d.quality;
        s.set_id = d.set_id || 0;
        s.set_name = d.set_bonuses?.name || '';
      }
    }
    updateSlotBadges();
    saveToLocal();
    document.getElementById('eq_detail').style.display = '';
    document.getElementById('eq_detail_empty').style.display = 'none';

    const nameEl = document.getElementById('eq_dn_name');
    nameEl.textContent = d.name;
    nameEl.className = 'eq-detail-name' + (d.quality >= 5 ? ' orange' : '');

    const subParts = [];
    if (d.level) subParts.push(`品级 ${d.level}`);
    if (d.max_strength) subParts.push(`精炼 ${state.slots[state.currentPos].strength}/${d.max_strength}`);
    if (d.belong_school) subParts.push(d.belong_school);
    if (d.magic_kind) subParts.push(d.magic_kind);
    document.getElementById('eq_dn_sub').textContent = subParts.join(' · ');

    // 属性列表
    const attrsEl = document.getElementById('eq_dn_attrs');
    const lines = [];
    // 武器特殊：Base1=武器伤害, Base2=浮动, Base3=攻速
    if (d.sub_type === 0 || d.sub_type === 1) {
      const b1 = d.bases.find(b => b.slot === 'atMeleeWeaponDamageBase');
      const b2 = d.bases.find(b => b.slot === 'atMeleeWeaponDamageRand');
      const b3 = d.bases.find(b => b.slot === 'atMeleeWeaponAttackSpeedBase');
      if (b1) {
        const rand = b2 ? b2.value : 0;
        lines.push(`<div class="eq-d-base">${d.sub_type === 1 ? '远程' : '近身'}伤害提高 ${b1.value}-${b1.value + rand}</div>`);
      }
      if (b3) lines.push(`<div class="eq-d-base">速度 ${(b3.value / 16).toFixed(1)}</div>`);
    } else {
      for (const b of d.bases) {
        lines.push(`<div class="eq-d-base">${b.label}提高 ${b.value}</div>`);
      }
    }
    // 魔法属性 —— 有精炼时追加 (+xx) 显示加成
    const STRENGTH_P = [0, 0.005, 0.013, 0.024, 0.038, 0.055, 0.075, 0.098, 0.124];
    const curStrength = state.slots[state.currentPos].strength || 0;
    const NON_STRENGTH_SLOTS = new Set([
      'atSkillEventHandler', 'atExecuteScript', 'atSetEquipmentRecipe',
    ]);
    const fmt1024Pct = v => (v / 1024 * 100).toFixed(1) + '%';
    for (const m of d.magics) {
      if (m.slot === 'atSkillEventHandler' || m.slot === 'atExecuteScript' || m.slot === 'atSetEquipmentRecipe') {
        const txt = m.desc ? escapeHtml(m.desc) : m.label;
        lines.push(`<div style="color:var(--warning)">${txt}</div>`);
      } else {
        const isThreat = m.slot === 'atActiveThreatCoefficient';
        let tail = '';
        if (curStrength > 0 && !NON_STRENGTH_SLOTS.has(m.slot)) {
          const bonus = Math.round(m.value * STRENGTH_P[Math.min(curStrength, 8)]);
          if (bonus > 0) {
            const bonusText = isThreat ? fmt1024Pct(bonus) : bonus;
            tail = ` <span class="eq-d-str">(+${bonusText})</span>`;
          }
        }
        const valueText = isThreat ? fmt1024Pct(m.value) : m.value;
        lines.push(`<div class="eq-d-attr">${m.label}提高 ${valueText}${tail}</div>`);
      }
    }
    // 镶嵌孔
    for (let i = 0; i < d.diamonds.length; i++) {
      const ds = d.diamonds[i];
      const embedLv = state.slots[state.currentPos].embedding[i] || 0;
      const coeff = embedCoeff(embedLv);
      const actualVal = Math.floor(Math.floor(ds.base_value) * coeff);
      lines.push(`<div class="eq-d-diamond">◇ ${ds.label}提高 ${actualVal || '?'}</div>`);
    }
    attrsEl.innerHTML = lines.join('');

    // 精炼星星
    renderStars(d.max_strength);
    // 镶嵌按钮（多行布局：每孔一行 + 顶部"连锁" toggle + 6/7/8 一键）
    renderEmbedding(d.diamonds);
    // 大小附魔
    loadEnchantOptions(d.sub_type);
    // 五彩石（仅近武）
    document.getElementById('eq_stone_row').style.display = (d.sub_type === 0) ? '' : 'none';
    if (d.sub_type === 0) {
      document.getElementById('eq_stone_name').textContent = state.stoneName || '（未选择）';
    }
    // 套装：当场实拉所有 slot 的 detail 实时计数（detailCache 命中瞬时；绕开 state.slots.set_id 缓存可能 stale 的问题）
    const setEl = document.getElementById('eq_set_info');
    if (d.set_bonuses && d.set_bonuses.tiers.length > 0) {
      setEl.classList.remove('none');
      let wornCount = 0;
      await Promise.all(Object.entries(state.slots).map(async ([pos, s]) => {
        if (!s?.equip_id) return;
        try {
          const dd = await getDetailCached(POS_TO_SUB[pos], s.equip_id);
          if (dd?.set_id === d.set_id) wornCount++;
        } catch (e) {}
      }));
      const tierHtml = d.set_bonuses.tiers.map(([n, attrs]) => {
        const partsHtml = attrs.map(a => {
          if (a.desc) return `<span style="color:var(--warning)">${escapeHtml(a.desc)}</span>`;
          return `${escapeHtml(a.label)}+${a.value}`;
        }).join('<br>&nbsp;&nbsp;');
        const active = wornCount >= n;
        const color = active ? 'var(--gold)' : 'var(--text-dim)';
        const tag = `<span style="color:${color};margin-left:6px;font-size:11px">${active ? '✓' : ''}已穿 ${wornCount}/${n}</span>`;
        const opacity = active ? '' : 'opacity:0.55;';
        return `<div style="margin-top:2px;${opacity}"><span style="color:${active ? 'var(--gold)' : 'var(--text-dim)'}">${n}件：</span>${tag}<br>&nbsp;&nbsp;${partsHtml}</div>`;
      }).join('');
      setEl.innerHTML = `<div style="color:var(--gold);font-weight:500">${escapeHtml(d.set_bonuses.name)}</div>${tierHtml}`;
    } else {
      setEl.classList.add('none');
      setEl.textContent = '—';
    }
  }

  function embedCoeff(lv) {
    if (lv === 0) return 0;
    const ratio = 37400 / 27800;
    if (lv <= 6) return 0.195 * lv * ratio;
    return 1.3 * (0.65 * lv - 3.2) * ratio;
  }

  // 精炼星星
  function renderStars(maxStrength) {
    const cfg = state.slots[state.currentPos];
    if (!cfg) return;
    const max = Math.min(maxStrength || 8, 8);
    const cur = cfg.strength || 0;
    const el = document.getElementById('eq_stars');
    el.innerHTML = '';
    for (let i = 1; i <= max; i++) {
      const s = document.createElement('span');
      s.className = 'eq-star' + (i <= cur ? ' filled' : '');
      s.textContent = '★';
      s.dataset.lv = i;
      s.addEventListener('mouseenter', () => {
        el.querySelectorAll('.eq-star').forEach((ss, idx) => {
          ss.classList.toggle('hover-highlight', idx < i && !ss.classList.contains('filled'));
        });
      });
      s.addEventListener('mouseleave', () => {
        el.querySelectorAll('.eq-star').forEach(ss => ss.classList.remove('hover-highlight'));
      });
      s.addEventListener('click', () => {
        cfg.strength = i;
        saveToLocal();
        showDetailForItem(cfg.equip_id);
        recalculate();
      });
      el.appendChild(s);
    }
  }

  document.getElementById('eq_stars_clear').addEventListener('click', () => {
    const cfg = state.slots[state.currentPos];
    if (!cfg) return;
    cfg.strength = 0;
    saveToLocal();
    showDetailForItem(cfg.equip_id);
    recalculate();
  });

  // 镶嵌：CSS grid 两列布局——左侧 chain icon（跨所有孔行），右侧 header + 每孔一行。
  // chain icon 仿 Adobe 的"链接长宽比"控件：连锁开 = 实线 + 闭合链节，断 = 虚线 + 链节断开。
  // 连锁开时点单孔同步全部；快捷按钮 6/7/8 始终全设（不受连锁影响）。
  function renderEmbedding(diamonds) {
    const count = diamonds?.length || 0;
    const pos = state.currentPos;
    const cfg = state.slots[pos];
    const row = document.getElementById('eq_embed_row');
    const group = document.getElementById('eq_embed_group');
    if (count === 0) { row.style.display = 'none'; return; }
    row.style.display = '';
    if (!cfg.embedding) cfg.embedding = [];
    while (cfg.embedding.length < count) cfg.embedding.push(6);

    group.innerHTML = '';

    // helper：按 idx 设置等级；连锁开则同步所有孔，关则只改 idx
    const setLevel = (idx, lv) => {
      if (state.embedLink) {
        for (let k = 0; k < count; k++) cfg.embedding[k] = lv;
      } else {
        cfg.embedding[idx] = lv;
      }
      saveToLocal();
      showDetailForItem(cfg.equip_id);
      recalculate();
    };

    // 左侧 chain icon（孔数 >= 2 才显示，跨所有孔行）。
    // 标准 Lucide link / unlink-2 icon（与 Adobe / Figma / VS Code 同语义）。
    if (count >= 2) {
      const linkBtn = document.createElement('button');
      linkBtn.type = 'button';
      linkBtn.className = 'eq-embed-link-icon' + (state.embedLink ? ' linked' : '');
      linkBtn.title = state.embedLink ? '连锁开启：改任意孔位同步所有（点击关闭）' : '连锁关闭：每孔独立修改（点击开启）';
      linkBtn.style.gridRow = `1 / span ${count}`;
      linkBtn.innerHTML = `
        <svg class="eq-embed-link-svg ec-on" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/>
          <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>
        </svg>
        <svg class="eq-embed-link-svg ec-off" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="m18.84 12.25 1.72-1.71h-.02a5.004 5.004 0 0 0-.12-7.07 5.006 5.006 0 0 0-6.95 0l-1.72 1.71"/>
          <path d="m5.17 11.75-1.71 1.71a5.004 5.004 0 0 0 .12 7.07 5.006 5.006 0 0 0 6.95 0l1.71-1.71"/>
          <line x1="8" x2="8" y1="2" y2="5"/>
          <line x1="2" x2="5" y1="8" y2="8"/>
          <line x1="16" x2="16" y1="19" y2="22"/>
          <line x1="19" x2="22" y1="16" y2="16"/>
        </svg>
      `;
      linkBtn.addEventListener('click', () => {
        state.embedLink = !state.embedLink;
        saveToLocal();
        showDetailForItem(cfg.equip_id);  // 重渲染让 icon 状态切换
      });
      group.appendChild(linkBtn);
    }

    // 每孔一行：孔标签 + 等级按钮 + 数值 + 行内 6/7/8 快捷（扁平化 ΔDPS 在按钮内）
    const lineRefs = [];
    for (let i = 0; i < count; i++) {
      const ds = diamonds[i] || {};
      const lv = cfg.embedding[i] || 0;
      const actualVal = Math.floor(Math.floor(ds.base_value || 0) * embedCoeff(lv));

      const line = document.createElement('div');
      line.className = 'eq-embed-line';
      line.innerHTML = `
        <button type="button" class="eq-embed-btn" data-idx="${i}">${lv}</button>
        <span class="eq-embed-slot-label">${escapeHtml(ds.label || '')}</span>
        <span class="eq-embed-val">+${actualVal || '?'}</span>
        <span class="eq-embed-quick-group">
          ${[6, 7, 8].map(qlv => `
            <button type="button" class="eq-mini-btn eq-embed-quick" data-lv="${qlv}" title="${['六','七','八'][qlv-6]}级">
              <span class="lv">${qlv}</span>
              <span class="ec-delta zero" data-lv="${qlv}">…</span>
            </button>
          `).join('')}
        </span>
      `;
      line.querySelector('.eq-embed-btn').addEventListener('click', (e) => showEmbedMenu(e.currentTarget, i));
      line.querySelectorAll('.eq-embed-quick').forEach(qb => {
        qb.addEventListener('click', () => setLevel(i, +qb.dataset.lv));
      });
      group.appendChild(line);
      lineRefs.push(line);
    }

    // ΔDPS 按"该孔单独改成 lv"算。cache key 跟当前 state.slots[pos].embedding 其他孔状态绑定，
    // 否则用户改一个孔的等级后，旧 cache（其他孔状态不同）会让 ΔDPS 失真。
    // 简化：每次重渲染前清掉 embed scope 的旧 cache。
    for (const k of state.subDpsCache.keys()) {
      if (k.startsWith(`${pos}:emb:`)) state.subDpsCache.delete(k);
    }
    const items = [];
    for (let i = 0; i < count; i++) {
      for (const qlv of [6, 7, 8]) {
        items.push({ key: `${pos}:emb:s${i}:${qlv}`, lv: qlv, idx: i });
      }
    }
    previewSubsetDps(
      items,
      (swap, it) => {
        const slot = swap[pos];
        slot.embedding = [...(slot.embedding || [])];
        slot.embedding[it.idx] = it.lv;
      },
      (it, dps, baseline) => {
        const line = lineRefs[it.idx];
        if (!line) return;
        const span = line.querySelector(`.ec-delta[data-lv="${it.lv}"]`);
        if (!span) return;
        const d = Math.round(dps - baseline);
        let cls = 'zero';
        if (d > 0) cls = 'up';
        else if (d < 0) cls = 'down';
        span.className = `ec-delta ${cls}`;
        span.textContent = fmtCompact(d);
      },
      { scope: 'embed' },
    );
  }

  function showEmbedMenu(anchor, slotIdx) {
    // 移除旧菜单
    document.querySelectorAll('.eq-embed-menu').forEach(m => m.remove());
    const menu = document.createElement('div');
    menu.className = 'eq-embed-menu';
    const linked = state.embedLink;
    for (let i = 0; i <= 8; i++) {
      const b = document.createElement('button');
      b.textContent = i;
      b.addEventListener('click', () => {
        const cfg = state.slots[state.currentPos];
        if (linked) {
          for (let k = 0; k < cfg.embedding.length; k++) cfg.embedding[k] = i;
        } else {
          cfg.embedding[slotIdx] = i;
        }
        anchor.textContent = i;
        menu.remove();
        saveToLocal();
        showDetailForItem(cfg.equip_id);
        recalculate();
      });
      menu.appendChild(b);
    }
    // 菜单仅显示 0-8 数字（ΔDPS 已扁平化到主行 6/7/8 按钮）
    const rect = anchor.getBoundingClientRect();
    menu.style.left = rect.left + 'px';
    menu.style.top = (rect.bottom + 2) + 'px';
    document.body.appendChild(menu);
    setTimeout(() => {
      const onClick = (e) => {
        if (!menu.contains(e.target)) {
          menu.remove();
          document.removeEventListener('click', onClick);
        }
      };
      document.addEventListener('click', onClick);
    }, 0);
  }

  // 大小附魔
  // 外功/防御心法不需要的附魔 —— slot 命中任一即隐藏
  const ENCHANT_HIDE_SLOTS = new Set([
    'atSpiritBase', 'atSpiritBasePercentAdd',                     // 根骨
    'atSpunkBase', 'atSpunkBasePercentAdd',                       // 元气
    'atMagicAttackPowerBase', 'atMagicCriticalStrike',
    'atMagicCriticalDamagePowerBase', 'atMagicOvercome',          // 内功 攻/会心/会效/破防（内防 atMagicShield 保留）
    'atSolarAttackPowerBase', 'atLunarAttackPowerBase', 'atNeutralAttackPowerBase',
    'atPoisonAttackPowerBase', 'atSolarAndLunarAttackPowerBase',
    'atSolarOvercomeBase', 'atLunarOvercomeBase', 'atNeutralOvercomeBase',
    'atPoisonOvercomeBase', 'atSolarAndLunarOvercomeBase',
    'atSolarCriticalStrike', 'atLunarCriticalStrike', 'atNeutralCriticalStrike',
    'atPoisonCriticalStrike', 'atSolarAndLunarCriticalStrike',
    'atSolarCriticalDamagePowerBase', 'atLunarCriticalDamagePowerBase',
    'atNeutralCriticalDamagePowerBase', 'atPoisonCriticalDamagePowerBase',
    'atSolarAndLunarCriticalDamagePowerBase',
    'atTherapyPowerBase',                                         // 治疗量
  ]);
  const ENCHANT_HIDE_NAME_RE = /(根骨|元气|内功攻击|内功会心|内功破防|阳性|阴性|混元|毒性|阴阳|治疗量)/;

  function shouldHideEnchant(e) {
    if (e.attributes && e.attributes.some(a => ENCHANT_HIDE_SLOTS.has(a[0]))) return true;
    if (e.name && ENCHANT_HIDE_NAME_RE.test(e.name)) return true;
    if (e.desc && ENCHANT_HIDE_NAME_RE.test(e.desc)) return true;
    return false;
  }

  // 过滤 + 按最新排序（id 越大越新）；已选中的条目永不过滤
  function prepEnchantList(list, currentId) {
    return list
      .filter(e => e.id === currentId || !shouldHideEnchant(e))
      .slice()
      .sort((a, b) => b.id - a.id);
  }

  /** select 折叠态文字颜色：浏览器原生不继承 option 的 color，必须在 select 上手动设。
   *  在 innerHTML 重写后 / onchange 后调用，让选中行也看到 quality 色。 */
  function syncSelectColor(sel) {
    if (!sel) return;
    const opt = sel.options[sel.selectedIndex];
    sel.style.color = opt?.style?.color || '';
  }

  // ── 子项 ΔDPS 预览（小附魔 / 大附魔 / 镶嵌等级）：参考装备列表 ΔDPS 同语义 ──
  // baseline = 当前 state.slots 的 DPS（与装备列表共享 state.baselineDps）；
  // candidate = 改一个字段（enhance_id / enchant_id / embedding[idx]）后的 DPS；
  // 并发 6 跑 lite simulate；token 防 stale；缓存复用 state.subDpsCache。
  state.subDpsCache = state.subDpsCache || new Map();
  // per-scope token：镶嵌 / 小附魔 / 五彩石 同时跑不互相打断（旧版单 token bug）
  const _previewTokens = { embed: 0, enh: 0, stone: 0, default: 0 };

  async function previewSubsetDps(items, applyMut, updateRow, opts = {}) {
    const scope = opts.scope || 'default';
    const stoneIdOf = opts.stoneIdOf;
    _previewTokens[scope] = (_previewTokens[scope] || 0) + 1;
    const myToken = _previewTokens[scope];
    const srcBundle = await resolvePreviewSource();
    if (!srcBundle) {
      console.warn('[ΔDPS] previewSource 不可用 — 请到循环模拟页填序列或宏后再来');
      return;
    }
    const mountId = getCurrentMountId();
    const talents = srcBundle.talents || getCurrentTalents();

    // baseline 每次现算（不缓存）：cfg 任何字段变化都会让缓存失效，单独 invalidate 太繁琐
    let baseline;
    try {
      const baseRaw = await calcRawAttrsForSlots(state.slots, mountId, talents);
      if (myToken !== _previewTokens[scope]) return;
      baseline = await simulateDpsForRaw(baseRaw, srcBundle, state.slots);
      if (myToken !== _previewTokens[scope]) return;
    } catch (e) { return; }

    const queue = items.filter(it => {
      if (state.subDpsCache.has(it.key)) {
        updateRow(it, state.subDpsCache.get(it.key), baseline);
        return false;
      }
      return true;
    });

    const concurrency = 6;
    async function worker() {
      while (queue.length) {
        if (myToken !== _previewTokens[scope]) return;
        const it = queue.shift();
        try {
          const swap = JSON.parse(JSON.stringify(state.slots));
          applyMut(swap, it);
          const stoneId = stoneIdOf ? stoneIdOf(it) : undefined;
          const raw = await calcRawAttrsForSlots(swap, mountId, talents, stoneId);
          if (myToken !== _previewTokens[scope]) return;
          const dps = await simulateDpsForRaw(raw, srcBundle, swap);
          if (myToken !== _previewTokens[scope]) return;
          state.subDpsCache.set(it.key, dps);
          updateRow(it, dps, baseline);
        } catch (e) {}
      }
    }
    await Promise.all(Array.from({ length: concurrency }, () => worker()));
  }

  function fmtDeltaText(dps, baseline) {
    if (dps == null || baseline == null) return '';
    const d = Math.round(dps - baseline);
    if (d === 0) return ' Δ0';
    const sign = d > 0 ? '+' : '';
    return ` Δ${sign}${d.toLocaleString()}`;
  }

  // 紧凑数字格式：用于按钮内 ΔDPS（避免被几万级数字撑爆容器）
  // 1234 → "+1234"；12345 → "+12.3k"；1234567 → "+1.23M"
  function fmtCompact(d) {
    if (d === 0) return '0';
    const sign = d > 0 ? '+' : '-';
    const a = Math.abs(d);
    if (a < 10000) return sign + a;
    if (a < 1000000) return sign + (a / 1000).toFixed(1) + 'k';
    return sign + (a / 1000000).toFixed(2) + 'M';
  }

  // 小附魔 picker：保存当前 entries / pos / cfg，给 dropdown 渲染和 ΔDPS 更新用
  let _enhPickerCtx = null;

  // 小附魔名字简化：去掉重复的部位段（·头·/·帽·/·腰·...）。
  // 例："风语·头·铸（外攻）" → "风语·铸（外攻）"；玩家在装备的部位上下文里不需要重复"·头·"。
  const _ENH_POS_RE = /·(头|帽|腰|腕|鞋|衣|上装|下装|暗器|项链|戒指|腰坠|护手)·?/g;
  function shortEnhName(name) {
    return String(name || '').replace(_ENH_POS_RE, '·').replace(/·+/g, '·').replace(/^·|·$/g, '');
  }
  // 属性数值串："外功攻击+356" → "+356"（label 跟 name 里的"（外攻）"重复了，省掉）
  function shortEnhAttrs(attrs) {
    if (!attrs || attrs.length === 0) return '';
    return attrs.map(a => (a[2] >= 0 ? `+${a[2]}` : `${a[2]}`)).join(' ');
  }

  function renderEnhancePicker(pos, enhances, cfg) {
    ensureEnhancePickerSetup();
    const picker = document.getElementById('eq_enhance_picker');
    const trigger = document.getElementById('eq_enhance_trigger');
    const dropdown = document.getElementById('eq_enhance_dropdown');
    if (!picker || !trigger || !dropdown) return;

    // 当前选中的 entry（含 id=0 的"无"占位）
    const noneEntry = { id: 0, name: '（无）', attributes: [], quality: 0, is_challenge: false };
    const currentEntry = enhances.find(e => e.id === cfg.enhance_id) || noneEntry;
    _enhPickerCtx = { pos, enhances, cfg, dropdown, trigger };

    // 触发器：简化格式 "<短名> +<值>"（不显示 ΔDPS，基线就是自身永远 0）
    const cls = enchantQualityClass(currentEntry);
    trigger.querySelector('.enh-name').className = `enh-name ${cls}`;
    trigger.querySelector('.enh-name').textContent = shortEnhName(currentEntry.name);
    trigger.querySelector('.enh-attrs').textContent = shortEnhAttrs(currentEntry.attributes);
    trigger.querySelector('.enh-delta').textContent = '';

    // dropdown 列表：每行 "<短名> +<值> Δ-xxk"
    const allOptions = [noneEntry, ...enhances];
    dropdown.innerHTML = allOptions.map(e => {
      const optCls = enchantQualityClass(e);
      const sel = e.id === cfg.enhance_id ? 'active' : '';
      return `<div class="eq-enh-option ${sel}" data-enh-id="${e.id}">
        <span class="enh-name ${optCls}">${escapeHtml(shortEnhName(e.name))}</span>
        <span class="enh-attrs">${escapeHtml(shortEnhAttrs(e.attributes))}</span>
        <span class="enh-delta" data-enh-id="${e.id}"></span>
      </div>`;
    }).join('');

    dropdown.querySelectorAll('.eq-enh-option').forEach(row => {
      row.addEventListener('click', () => {
        const id = parseInt(row.dataset.enhId, 10) || 0;
        cfg.enhance_id = id;
        dropdown.hidden = true;
        picker.classList.remove('open');
        saveToLocal();
        // 切换附魔后 baseline 变化，需要清 enh scope cache 并重启 preview
        for (const k of state.subDpsCache.keys()) {
          if (k.startsWith(`${pos}:enh:`)) state.subDpsCache.delete(k);
        }
        renderEnhancePicker(pos, enhances, cfg);
        recalculate();
        // 重启 ΔDPS preview（baseline 现算 + 重跑所有候选）
        const items = [{ id: 0 }, ...enhances].map(e => ({ key: `${pos}:enh:${e.id}`, id: e.id }));
        previewSubsetDps(
          items,
          (swap, it) => { swap[pos] = { ...swap[pos], enhance_id: it.id }; },
          (it, dps, baseline) => updateEnhancePickerDelta(it.id, dps, baseline),
          { scope: 'enh' },
        );
      });
    });
  }

  function updateEnhancePickerDelta(enhId, dps, baseline) {
    if (!_enhPickerCtx) return;
    const span = _enhPickerCtx.dropdown.querySelector(`.enh-delta[data-enh-id="${enhId}"]`);
    if (!span) return;
    const d = Math.round(dps - baseline);
    let cls = 'zero';
    if (d > 0) cls = 'up';
    else if (d < 0) cls = 'down';
    span.className = `enh-delta ${cls}`;
    span.textContent = d === 0 ? '' : fmtCompact(d);
  }

  // picker 触发 / 关闭事件（在 renderEnhancePicker 第一次跑时延迟绑定，避免 DOM 未渲染）
  let _enhPickerSetup = false;
  function ensureEnhancePickerSetup() {
    if (_enhPickerSetup) return;
    const picker = document.getElementById('eq_enhance_picker');
    const trigger = document.getElementById('eq_enhance_trigger');
    const dropdown = document.getElementById('eq_enhance_dropdown');
    if (!picker || !trigger || !dropdown) return;
    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      const open = !dropdown.hidden;
      if (open) {
        dropdown.hidden = true;
        picker.classList.remove('open');
      } else {
        dropdown.hidden = false;
        picker.classList.add('open');
      }
    });
    document.addEventListener('click', (e) => {
      if (!picker.contains(e.target)) {
        dropdown.hidden = true;
        picker.classList.remove('open');
      }
    });
    _enhPickerSetup = true;
  }

  async function loadEnchantOptions(subType) {
    const cfg = state.slots[state.currentPos];
    const pos = state.currentPos;
    const encSel = document.getElementById('eq_enchant_select');
    const encRow = document.getElementById('eq_enchant_row');

    // 小附魔（自定义 picker，原生 select 无法着色 / 右对齐 / tabular-nums）
    let enhances = [];
    try {
      enhances = prepEnchantList(await getEnhancesCached(subType), cfg.enhance_id || 0);
    } catch (e) {}
    renderEnhancePicker(pos, enhances, cfg);
    if (enhances.length > 0) {
      const items = [{ id: 0, name: '（无）', attributes: [] }, ...enhances].map(e => ({
        key: `${pos}:enh:${e.id}`, id: e.id,
      }));
      previewSubsetDps(
        items,
        (swap, it) => { swap[pos] = { ...swap[pos], enhance_id: it.id }; },
        (it, dps, baseline) => updateEnhancePickerDelta(it.id, dps, baseline),
        { scope: 'enh' },
      );
    }

    // 大附魔：仅特定部位
    const needEnchant = [2, 3, 6, 8, 9, 10].includes(subType);
    encRow.style.display = needEnchant ? '' : 'none';
    if (needEnchant) {
      let enchants = [];
      try {
        enchants = prepEnchantList(await getEnchantsCached(subType), cfg.enchant_id || 0);
        encSel.innerHTML = '<option value="0">（无）</option>' +
          enchants.map(e => {
            const sel = e.id === cfg.enchant_id ? 'selected' : '';
            return `<option value="${e.id}"${enchantQualityStyle(e)} ${sel}>${escapeHtml(e.name)}</option>`;
          }).join('');
        syncSelectColor(encSel);
      } catch (e) {}
      encSel.onchange = () => {
        cfg.enchant_id = parseInt(encSel.value, 10) || 0;
        syncSelectColor(encSel);
        saveToLocal();
        recalculate();
      };
      // 大附魔不展示 ΔDPS（用户要求）
    }
  }

  // ── 五彩石弹窗 ────────────────────────────────────
  state.stoneCache = [];                                  // 所有五彩石（一次性加载）
  state.stoneFilter = { level: null, attrs: [null, null, null], kw: '' };
  state.stoneSort = { key: 'level', dir: 'desc' };        // 排序状态：等级降序 / 名称 / delta

  state.stoneTokenLabel = new Map();  // token (锐刃/霸体/...) → 属性 label (外功攻击/体质/...)

  function buildStoneTokenLabelMap(stones) {
    const map = new Map();
    for (const s of stones) {
      const toks = s._tokens || [];
      const attrs = s.attributes || [];
      for (let i = 0; i < Math.min(toks.length, attrs.length); i++) {
        if (!map.has(toks[i])) map.set(toks[i], attrs[i].label);
      }
    }
    return map;
  }

  // 五彩石表头点击切换排序
  document.querySelectorAll('.eq-stone-sort-th').forEach(th => {
    th.addEventListener('click', () => {
      const key = th.dataset.sortKey;
      if (state.stoneSort.key === key) {
        state.stoneSort.dir = state.stoneSort.dir === 'asc' ? 'desc' : 'asc';
      } else {
        state.stoneSort.key = key;
        // 数字列默认降序，名称默认升序
        state.stoneSort.dir = (key === 'name') ? 'asc' : 'desc';
      }
      renderStoneUI();
    });
  });

  document.getElementById('eq_stone_pick').addEventListener('click', async () => {
    document.getElementById('eq_stone_modal').style.display = '';
    if (state.stoneCache.length === 0) {
      try {
        state.stoneCache = await apiPost('/api/equip/stones', { selectors: [] });
        // 解析名字为属性数组
        state.stoneCache.forEach(s => { s._tokens = parseStoneTokens(s.name); });
        state.stoneTokenLabel = buildStoneTokenLabelMap(state.stoneCache);
      } catch (e) {}
    }
    renderStoneUI();
  });
  document.getElementById('eq_stone_modal_close').addEventListener('click', () => {
    document.getElementById('eq_stone_modal').style.display = 'none';
  });
  document.getElementById('eq_stone_clear').addEventListener('click', () => {
    state.stoneId = 0;
    state.stoneName = '';
    document.getElementById('eq_stone_name').textContent = '（未选择）';
    saveToLocal();
    recalculate();
  });
  document.getElementById('eq_stone_search').addEventListener('input', (e) => {
    state.stoneFilter.kw = e.target.value.trim();
    renderStoneUI();
  });
  document.getElementById('eq_stone_reset').addEventListener('click', () => {
    state.stoneFilter = { level: null, attrs: [null, null, null], kw: '' };
    document.getElementById('eq_stone_search').value = '';
    renderStoneUI();
  });

  // 解析石头名字为属性 tokens，如：彩·锐刃·急速·无双(陆) → ['锐刃','急速','无双']
  function parseStoneTokens(name) {
    const noLevel = String(name).replace(/[(（][壹贰叁肆伍陆][)）]\s*$/, '');
    return noLevel.split('·').filter(p => p && p !== '彩');
  }

  // 外功/防御心法不需要的五彩石标签
  function isHiddenStoneLabel(label) {
    if (!label) return false;
    if (label === '根骨' || label === '元气' || label === '治疗量') return true;
    if (label === '根骨百分比' || label === '元气百分比') return true;
    if (label.includes('内功') && label !== '内功防御') return true;
    if (/^(阳性|阴性|混元|毒性|阴阳)/.test(label)) return true;
    return false;
  }

  function stoneHasHiddenToken(stone) {
    const toks = stone._tokens || [];
    const tokenLabel = state.stoneTokenLabel;
    if (!tokenLabel) return false;
    return toks.some(t => isHiddenStoneLabel(tokenLabel.get(t)));
  }

  function matchFilter(stone, filter) {
    if (stoneHasHiddenToken(stone)) return false;
    if (filter.level && stone.level !== filter.level) return false;
    const toks = stone._tokens || [];
    for (let i = 0; i < 3; i++) {
      const need = filter.attrs[i];
      if (need && toks[i] !== need) return false;
    }
    if (filter.kw && !stone.name.includes(filter.kw) &&
        !stone.attributes.some(a => a.label.includes(filter.kw))) return false;
    return true;
  }

  // 获取某列（等级/属性0/属性1/属性2）的"可用取值"
  // 给定已选择的前置条件（attrs[0..idx-1] 和 level），返回匹配的 stones 中该位置的 unique tokens
  function getColOptions(stones, filter, col) {
    const ft = { level: filter.level, attrs: [...filter.attrs], kw: '' };
    if (col === 'level') ft.level = null;
    else { for (let i = col; i < 3; i++) ft.attrs[i] = null; }
    const out = new Set();
    for (const s of stones) {
      if (!matchFilter(s, ft)) continue;
      if (col === 'level') {
        if (s.level > 0) out.add(s.level);
      } else {
        const v = (s._tokens || [])[col];
        if (v) out.add(v);
      }
    }
    return [...out];
  }

  function renderStoneChips(containerId, options, currentValue, onPick, labelFor) {
    const el = document.getElementById(containerId);
    el.innerHTML = '';
    options.forEach(v => {
      const btn = document.createElement('button');
      btn.className = 'eq-stone-chip';
      btn.textContent = labelFor ? labelFor(v) : v;
      if (labelFor) btn.title = v;  // 悬停显示原 token 名
      if (v === currentValue) btn.classList.add('active');
      btn.addEventListener('click', () => onPick(v));
      el.appendChild(btn);
    });
    if (options.length === 0) {
      el.innerHTML = '<span style="color:var(--text-dim);font-size:10px">（无可用选项）</span>';
    }
  }

  function renderStoneUI() {
    const stones = state.stoneCache;
    const f = state.stoneFilter;

    // 等级栏（总是显示所有等级）
    const lvOpts = getColOptions(stones, f, 'level').sort((a, b) => b - a);
    renderStoneChips('eq_stone_lv_chips', lvOpts, f.level, v => {
      f.level = (f.level === v) ? null : v;
      renderStoneUI();
    });

    // 属性 1/2/3 栏（按钮显示对应属性名，如 锐刃→外功攻击；原 token 作为 title）
    const tokenLabel = state.stoneTokenLabel;
    const labelFor = tok => tokenLabel?.get(tok) || tok;
    for (let i = 0; i < 3; i++) {
      const opts = getColOptions(stones, f, i);
      renderStoneChips(`eq_stone_a${i}_chips`, opts, f.attrs[i], v => {
        if (f.attrs[i] === v) {
          f.attrs[i] = null;
          // 清除后续选中
          for (let j = i + 1; j < 3; j++) f.attrs[j] = null;
        } else {
          f.attrs[i] = v;
          // 若后续选中在新可用集合里不存在，清空
          for (let j = i + 1; j < 3; j++) {
            const nextOpts = getColOptions(stones, f, j);
            if (f.attrs[j] && !nextOpts.includes(f.attrs[j])) f.attrs[j] = null;
          }
        }
        renderStoneUI();
      }, labelFor);
    }

    // 下方大表格
    const matched = stones.filter(s => matchFilter(s, f));
    const sort = state.stoneSort;
    const sortStone = (a, b) => {
      let va, vb;
      if (sort.key === 'level') { va = a.level || 0; vb = b.level || 0; }
      else if (sort.key === 'name') { return sort.dir === 'asc' ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name); }
      else if (sort.key === 'delta') {
        const da = state.subDpsCache.get(`stone:${a.id}`);
        const db = state.subDpsCache.get(`stone:${b.id}`);
        // 未跑出来的排到末尾
        if (da == null && db == null) return 0;
        if (da == null) return 1;
        if (db == null) return -1;
        va = da; vb = db;
      } else { va = 0; vb = 0; }
      return sort.dir === 'asc' ? va - vb : vb - va;
    };
    matched.sort(sortStone);
    const tbody = document.getElementById('eq_stone_list_body');
    const visible = matched.slice(0, 400);
    // 表头排序指示
    document.querySelectorAll('.eq-stone-sort-th').forEach(th => {
      const ind = th.querySelector('.sort-ind');
      if (!ind) return;
      ind.textContent = (sort.key === th.dataset.sortKey) ? (sort.dir === 'asc' ? ' ▲' : ' ▼') : '';
    });
    tbody.innerHTML = visible.map(s => {
      const attrStr = s.attributes.map(a => `${a.label}+${a.value}`).join(' · ');
      const needStr = s.attributes.map(a => `${a.need_count}/${a.need_intensity}`).join(',');
      return `<tr data-id="${s.id}" data-name="${escapeHtml(s.name)}">
        <td>${s.level || '—'}</td>
        <td>${escapeHtml(s.name)}</td>
        <td>${escapeHtml(attrStr)}</td>
        <td style="font-size:10px;color:var(--text-muted)">${escapeHtml(needStr)}</td>
        <td class="eq-stone-dps-cell" data-stone-id="${s.id}"><span class="eq-dps-pending">…</span></td>
      </tr>`;
    }).join('');
    tbody.querySelectorAll('tr').forEach(tr => {
      tr.addEventListener('click', () => {
        state.stoneId = parseInt(tr.dataset.id, 10);
        state.stoneName = tr.dataset.name;
        document.getElementById('eq_stone_name').textContent = state.stoneName;
        document.getElementById('eq_stone_modal').style.display = 'none';
        saveToLocal();
        recalculate();
      });
    });

    // 启动五彩石 ΔDPS preview（仅可见 400 条）
    const items = visible.map(s => ({ key: `stone:${s.id}`, id: s.id }));
    previewSubsetDps(
      items,
      (_swap, _it) => {},                  // 不改 slots
      (it, dps, baseline) => {
        const cell = tbody.querySelector(`.eq-stone-dps-cell[data-stone-id="${it.id}"]`);
        if (!cell) return;
        const d = dps - baseline;
        const tol = Math.max(Math.abs(baseline) * 0.005, 50);
        let cls = 'eq-dps-zero', sign = '';
        if (d > tol) { cls = 'eq-dps-up'; sign = '+'; }
        else if (d < -tol) { cls = 'eq-dps-down'; }
        cell.innerHTML = `<span class="${cls}">${sign}${Math.round(d).toLocaleString()}</span>`;
        maybeResortStones();
      },
      { scope: 'stone', stoneIdOf: (it) => it.id },
    );
  }

  // 当前排序按 ΔDPS 时，preview 跑完一条节流重排一次
  let _stoneResortTimer = null;
  function maybeResortStones() {
    if (state.stoneSort.key !== 'delta') return;
    clearTimeout(_stoneResortTimer);
    _stoneResortTimer = setTimeout(renderStoneUI, 250);
  }

  // 筛选控件：品级双滑条
  const rangeMin = document.getElementById('eq_min_level');
  const rangeMax = document.getElementById('eq_max_level');
  const rangeMinVal = document.getElementById('eq_min_level_val');
  const rangeMaxVal = document.getElementById('eq_max_level_val');
  const rangeFill = document.getElementById('eq_range_fill');

  function syncRange() {
    const min = parseInt(rangeMin.min, 10) || 0;
    const max = parseInt(rangeMin.max, 10) || 44000;
    let lo = parseInt(rangeMin.value, 10);
    let hi = parseInt(rangeMax.value, 10);
    if (!Number.isFinite(lo)) lo = min;
    if (!Number.isFinite(hi)) hi = max;
    if (lo > hi) { [lo, hi] = [hi, lo]; rangeMin.value = lo; rangeMax.value = hi; }
    rangeMinVal.textContent = lo;
    rangeMaxVal.textContent = hi;
    const span = max - min;
    const leftPct = span > 0 ? ((lo - min) / span) * 100 : 0;
    const rightPct = span > 0 ? ((max - hi) / span) * 100 : 0;
    rangeFill.style.left = leftPct + '%';
    rangeFill.style.right = rightPct + '%';
    state.filter.min_level = lo;
    state.filter.max_level = hi >= max ? 0 : hi;
    refreshList();
  }
  rangeMin.addEventListener('input', syncRange);
  rangeMax.addEventListener('input', syncRange);
  syncRange();

  document.getElementById('eq_keyword').addEventListener('input', (e) => {
    state.filter.keyword = e.target.value;
    refreshList();
  });
  document.getElementById('eq_only_set').addEventListener('change', (e) => {
    state.filter.onlySet = e.target.checked;
    refreshList();
  });
  document.getElementById('eq_only_orange').addEventListener('change', (e) => {
    state.filter.onlyOrange = e.target.checked;
    refreshList();
  });
  document.getElementById('eq_filter_reset').addEventListener('click', () => {
    state.filter.schools.clear();
    state.filter.kinds.clear();
    state.filter.attrs.clear();
    state.filter.battle_types = new Set(['PVE']);
    state.filter.keyword = '';
    state.filter.onlySet = false;
    state.filter.onlyOrange = false;
    state.filter.categories.clear();
    rangeMin.value = 22000;
    rangeMax.value = 44000;
    syncRange();
    document.getElementById('eq_keyword').value = '';
    document.getElementById('eq_only_set').checked = false;
    document.getElementById('eq_only_orange').checked = false;
    page.querySelectorAll('#eq_school_chips .eq-chip.active, #eq_kind_chips .eq-chip.active, #eq_attr_chips .eq-chip.active, #eq_battle_chips .eq-chip.active, #eq_category_chips .eq-chip.active').forEach(c => c.classList.remove('active'));
    // 重置后 PVE 仍默认激活
    page.querySelector('#eq_battle_chips .eq-chip[data-battle="PVE"]')?.classList.add('active');
    refreshList();
  });
  // 属性芯片
  page.querySelectorAll('#eq_attr_chips .eq-chip').forEach(btn => {
    btn.addEventListener('click', () => {
      const a = btn.dataset.attr;
      if (state.filter.attrs.has(a)) state.filter.attrs.delete(a);
      else state.filter.attrs.add(a);
      btn.classList.toggle('active');
      refreshList();
    });
  });
  // 战斗类型芯片
  page.querySelectorAll('#eq_battle_chips .eq-chip').forEach(btn => {
    // 默认激活态同步 state.filter.battle_types
    if (state.filter.battle_types.has(btn.dataset.battle)) btn.classList.add('active');
    btn.addEventListener('click', () => {
      const b = btn.dataset.battle;
      if (state.filter.battle_types.has(b)) state.filter.battle_types.delete(b);
      else state.filter.battle_types.add(b);
      btn.classList.toggle('active');
      refreshList();
    });
  });
  // 类型芯片（OR 关系：任一匹配即过；空 = 不过滤）
  page.querySelectorAll('#eq_category_chips .eq-chip').forEach(btn => {
    if (state.filter.categories.has(btn.dataset.cat)) btn.classList.add('active');
    btn.addEventListener('click', () => {
      const c = btn.dataset.cat;
      if (state.filter.categories.has(c)) state.filter.categories.delete(c);
      else state.filter.categories.add(c);
      btn.classList.toggle('active');
      refreshList();
    });
  });
  // 全选/全不选：作用于所有筛选 chip（门派/心法/属性/战斗/类型）
  document.getElementById('eq_filter_all').addEventListener('click', () => {
    page.querySelectorAll('#eq_school_chips .eq-chip').forEach(btn => {
      state.filter.schools.add(btn.dataset.school); btn.classList.add('active');
    });
    page.querySelectorAll('#eq_kind_chips .eq-chip').forEach(btn => {
      state.filter.kinds.add(btn.dataset.kind); btn.classList.add('active');
    });
    page.querySelectorAll('#eq_attr_chips .eq-chip').forEach(btn => {
      state.filter.attrs.add(btn.dataset.attr); btn.classList.add('active');
    });
    page.querySelectorAll('#eq_battle_chips .eq-chip').forEach(btn => {
      state.filter.battle_types.add(btn.dataset.battle); btn.classList.add('active');
    });
    page.querySelectorAll('#eq_category_chips .eq-chip').forEach(btn => {
      state.filter.categories.add(btn.dataset.cat); btn.classList.add('active');
    });
    refreshList();
  });
  document.getElementById('eq_filter_none').addEventListener('click', () => {
    state.filter.schools.clear();
    state.filter.kinds.clear();
    state.filter.attrs.clear();
    state.filter.battle_types.clear();
    state.filter.categories.clear();
    page.querySelectorAll('#eq_school_chips .eq-chip, #eq_kind_chips .eq-chip, #eq_attr_chips .eq-chip, #eq_battle_chips .eq-chip, #eq_category_chips .eq-chip').forEach(btn => btn.classList.remove('active'));
    refreshList();
  });

  // 清空当前部位/全部重置
  document.getElementById('eq_clear_slot').addEventListener('click', () => {
    if (!state.currentPos) return;
    delete state.slots[state.currentPos];
    state.currentItemId = null;
    updateSlotBadges();
    document.getElementById('eq_detail').style.display = 'none';
    document.getElementById('eq_detail_empty').style.display = '';
    document.getElementById('eq_clear_slot').disabled = true;
    saveToLocal();
    refreshList();
    recalculate();
  });
  // 「📈 属性收益」按钮：跟"DPS 来源"下拉同上下文，确保 ref_dps 跟 ΔDPS 预览一致
  document.getElementById('eq_fit_curve_btn')?.addEventListener('click', (e) => {
    const button = e.currentTarget;
    window.Jx3FitCurve?.runAndShow?.({
      title: '属性收益曲线（配装器）',
      button,
      buildBody: async () => {
        const cfg = window.Jx3Equip?.getCurrentConfig?.() || { slots: {}, stoneId: 0 };
        // 1. 用"DPS 来源"绑定的预览上下文（sequence/macro_text/talents/recipes/target/...）
        //    确保 ref_dps 等于配装器 ΔDPS 预览的 baseline DPS（都是同一 bundle 跑 sim）
        const bundle = await resolvePreviewSource();
        if (!bundle) {
          throw new Error('DPS 来源不可用：请在「DPS 来源」下拉里选一个有效的方案/循环，或在循环模拟页填好宏');
        }
        // 2. mount ID（从全局 currentMount 推导；后端 mount: u32，10389=铁骨衣 / 10390=分山劲）
        const mountId = (typeof currentMount !== 'undefined' && currentMount?.mount === 'TieGuYi') ? 10389 : 10390;
        const calc = await window.Jx3Equip?.calculatePanel?.(cfg.slots, cfg.stoneId || 0, mountId, bundle.talents);
        if (!calc?.raw) throw new Error('未能计算属性面板');
        // 3. raw → attrs，cfg.slots → equipment dict
        const attrs = window.Jx3FitCurve.rawToAttrs(calc.raw);
        const eq = window.Jx3FitCurve.slotsToEquipDict(cfg.slots);
        // 4. 拼 fit_curve body：sequence / macro / target / 时长等全部跟随 bundle；
        //    全局开关（hanjia / tiegu / experimental / team_buffs / formation）用当前页面状态
        return {
          haste_level: calc.raw.haste_level || 0,
          sequence: bundle.sequence,
          macro_text: bundle.macro_text || '',
          macro_duration: bundle.macro_duration || 300,
          attributes: attrs,
          equipment: eq,
          talents: bundle.talents || [],
          recipes: bundle.recipes || [],
          target: bundle.target || { level: 134, defense_bonus: 0 },
          network_delay: bundle.network_delay || 0,
          initial_rage: bundle.initial_rage || 0,
          boss_attack_interval: bundle.boss_attack_interval || 0,
          hanjia_expectation: (typeof isHanjiaExpectationEnabled === 'function') ? isHanjiaExpectationEnabled() : false,
          tiegu_mode: (typeof getTieguMode === 'function') ? getTieguMode() : 2,
          experimental: (typeof isExperimental === 'function') ? isExperimental() : false,
          team_buffs: (typeof getTeamBuffs === 'function') ? getTeamBuffs() : [],
          formation: window._formationSelection ? { ...window._formationSelection } : null,
          lite: true,
          lite_keep_timeline: false,
          order: 2,
          pert_delta: 1000,
          axis_scale: 5,
        };
      },
    });
  });
  document.getElementById('eq_reset_all').addEventListener('click', () => {
    if (!confirm('确认清空所有装备配置？')) return;
    state.slots = {};
    state.stoneId = 0;
    state.stoneName = '';
    state.currentItemId = null;
    state.currentPos = null;
    updateSlotBadges();
    page.querySelectorAll('.eq-slot').forEach(b => b.classList.remove('active'));
    document.getElementById('eq_center_head').textContent = '请从左侧选择一个部位';
    document.getElementById('eq_center_head').classList.remove('active');
    document.getElementById('eq_filters').style.display = 'none';
    document.getElementById('eq_list_table').style.display = 'none';
    document.getElementById('eq_detail').style.display = 'none';
    document.getElementById('eq_detail_empty').style.display = '';
    saveToLocal();
    recalculate();
  });

  // 属性计算
  let calcTimer = null;
  function recalculate() {
    if (calcTimer) clearTimeout(calcTimer);
    calcTimer = setTimeout(async () => {
      // 即使没装备也调用：后端会返回全角色基础 + 心法固定增益 + 转化结果
      const mountId = getCurrentMountId();
      const talents = getCurrentTalents();
      try {
        const resp = await apiPost('/api/equip/calculate', {
          slots: state.slots,
          stone_id: state.stoneId || 0,
          mount: mountId,
          talents,
        });
        state.lastCalcResp = resp;
        renderAttrs(resp);
      } catch (e) {
        console.error('属性计算失败', e);
      }
    }, 150);
  }

  // 心法标识 → 计算用 ID（backend equip.calculate 用此 ID 路由心法固定增益 / 主属性转化）
  const MOUNT_NAME_TO_ID = {
    'FenShanJin': 10390,
    'TieGuYi':    10389,
  };

  function getCurrentMountId() {
    const name = (typeof currentMount !== 'undefined' && currentMount?.mount) || 'FenShanJin';
    return MOUNT_NAME_TO_ID[name] || 10390;
  }

  function updateMountLabel() {
    const el = document.getElementById('eq_mount_label');
    if (!el) return;
    const label = (typeof currentMount !== 'undefined' && currentMount?.mount_label) || '';
    el.textContent = label ? `· ${label}` : '';
  }

  function getCurrentTalents() {
    try {
      if (typeof getSelectedTalents === 'function') {
        return getSelectedTalents();
      }
    } catch (e) {}
    return [];
  }

  function clearAttrsDisplay() {
    ['score','quality','hp','vit','str','agi','atk','atk_base','crit','crit_eff','oc','strain','haste','surplus','pvx',
     'pshield','mshield','parry','parry_val','dodge','tough','decrit'].forEach(k => {
      const el = document.getElementById('eq_av_' + k);
      if (el) el.textContent = '—';
    });
  }

  function renderAttrs(resp) {
    if (!resp) return;
    const r = resp.raw || {};
    const p = resp.panel || {};
    const set = (id, v) => {
      const el = document.getElementById(id);
      if (el) el.textContent = v;
    };
    // 后端已每步 floor，前端直接显示；百分比保留 2 位
    const num = v => (v || 0).toLocaleString();
    const pct = v => ((v || 0) * 100).toFixed(2) + '%';

    set('eq_av_score', num(resp.score));
    set('eq_av_quality', num(resp.quality_level));
    set('eq_av_hp', num(p.max_life));
    set('eq_av_vit', num(r.vitality));
    set('eq_av_str', num(r.strength));
    set('eq_av_agi', num(r.agility));
    set('eq_av_atk_base', num(r.base_attack));
    set('eq_av_atk', num(p.physics_attack_power));
    set('eq_av_crit', pct(p.crit_rate));
    set('eq_av_crit_eff', pct(p.crit_effect));
    set('eq_av_oc', pct(p.overcome_rate));
    set('eq_av_strain', pct(p.strain_rate));
    set('eq_av_haste', pct(p.haste_rate));
    set('eq_av_surplus', num(p.surplus_value));
    set('eq_av_pvx', num(r.pvx_all_round));
    set('eq_av_pshield', pct(p.physics_shield_rate));
    set('eq_av_mshield', pct(p.magic_shield_rate));
    set('eq_av_parry', pct(p.parry_rate));
    set('eq_av_parry_val', num(p.parry_value));
    set('eq_av_dodge', pct(p.dodge_rate));
    set('eq_av_tough', pct(p.toughness_rate));
    set('eq_av_decrit', pct(p.decritical_damage_rate));
    // 同步 raw 到模拟器属性面板输入框（走配装器替代手填）
    if (typeof syncRawToAttrsInputs === 'function') syncRawToAttrsInputs(r);
    // tooltip 延迟绑定（只需一次）
    bindAttrsTooltips();
    // 套装件数 + 装备特效指示器
    renderSetEffectIndicators();
  }

  // 套装件数 + 装备特效指示器（属性面板下方）
  // 与 backend/src/equip_effects.rs 保持同步；ID 列表写死避免每次 hover 拉接口
  const TIANXIA_HONGYUAN_IDS_FE = [40213, 40245, 40277, 40309, 42128, 42160, 43553, 43586, 45287, 45320];
  const YU_YAN_IDS_FE = [40214, 40246, 40278, 40310, 42129, 42161, 43554, 43587, 45288, 45321];
  const YOU_FENG_SHI_WEI_IDS_FE = [44121, 44154, 44187, 44220, 44253, 44286];
  const YOU_FENG_BU_GUI_IDS_FE = [44122, 44155, 44188, 44221, 44254, 44287];
  async function renderSetEffectIndicators() {
    const setEl = document.getElementById('eq_set_indicator');
    const effEl = document.getElementById('eq_effect_indicator');
    if (!setEl || !effEl) return;
    // ── 1. 套装件数（实拉 detail，绕开 state.slots.set_id 缓存可能 stale 的问题） ──
    const setMap = new Map(); // set_id -> {name, count}
    await Promise.all(Object.entries(state.slots).map(async ([pos, s]) => {
      if (!s?.equip_id) return;
      try {
        const dd = await getDetailCached(POS_TO_SUB[pos], s.equip_id);
        if (!dd?.set_id) return;
        const cur = setMap.get(dd.set_id) || { name: dd.set_bonuses?.name || dd.set_name || `套装#${dd.set_id}`, count: 0 };
        cur.count++;
        setMap.set(dd.set_id, cur);
      } catch (e) {}
    }));
    const sets = Array.from(setMap.entries()).map(([sid, d]) => ({ sid, ...d }))
      .sort((a, b) => b.count - a.count);
    if (sets.length === 0) {
      setEl.style.display = 'none';
    } else {
      setEl.style.display = '';
      let html = '<div class="eq-attrs-row eq-attrs-section-title">套装效果</div>';
      for (const s of sets) {
        // 4 件套触发：主色；2 件套触发：暗主色；其他暗灰
        const active4 = s.count >= 4;
        const active2 = s.count >= 2;
        const color = active4 ? 'var(--gold)' : active2 ? 'var(--gold-dim)' : 'var(--text-dim)';
        const tag = active4 ? '✓ 4件套' : active2 ? '✓ 2件套' : '未激活';
        html += `<div class="eq-attrs-row" style="color:${color}">`
          + `<span class="eq-al">${escapeHtml(s.name)}</span>`
          + `<span class="eq-av">${s.count} 件 · ${tag}</span>`
          + `</div>`;
      }
      setEl.innerHTML = html;
    }
    // ── 2. 装备特效（主武器） ──
    const wid = state.slots?.PRIMARY_WEAPON?.equip_id || 0;
    const effects = [];
    if (TIANXIA_HONGYUAN_IDS_FE.includes(wid)) {
      effects.push({ name: '天下宏愿', desc: '盾飞 +5% / 斩刀 +5% / 盾击神兵 / 神兵·无双 buff' });
    }
    if (YU_YAN_IDS_FE.includes(wid)) {
      effects.push({ name: '驭焰', desc: '盾压神兵' });
    }
    if (YOU_FENG_SHI_WEI_IDS_FE.includes(wid)) {
      effects.push({ name: '幽烽蝶语·式微', desc: '盾刀会心 +5% / 斩刀会心 +5% / 神兵·无双 buff' });
    }
    if (YOU_FENG_BU_GUI_IDS_FE.includes(wid)) {
      effects.push({ name: '幽烽蝶语·不归', desc: '（仅威胁向，PVE 无输出影响）' });
    }
    if (effects.length === 0) {
      effEl.style.display = 'none';
    } else {
      effEl.style.display = '';
      let html = '<div class="eq-attrs-row eq-attrs-section-title">装备特效</div>';
      for (const e of effects) {
        html += `<div class="eq-attrs-row" style="color:var(--gold)">`
          + `<span class="eq-al">${escapeHtml(e.name)}</span>`
          + `<span class="eq-av" style="font-size:11px;color:var(--text-muted)">${escapeHtml(e.desc)}</span>`
          + `</div>`;
      }
      effEl.innerHTML = html;
    }
  }

  // ── 属性行 hover 结构化 tooltip（模拟器 log-tooltip 风格） ──────────
  let attrsTooltipsBound = false;
  function bindAttrsTooltips() {
    if (attrsTooltipsBound) return;
    attrsTooltipsBound = true;
    const num = v => Math.round(v || 0).toLocaleString();
    const pct = v => ((v || 0) * 100).toFixed(2) + '%';
    const row = (k, v, cls) => `<div class="lt-row"><span class="lt-key">${k}</span><span class="lt-val${cls ? ' ' + cls : ''}">${v}</span></div>`;
    const dim = t => `<div class="lt-dim" style="margin-top:3px">${t}</div>`;
    const sec = (title, body) => `<div class="lt-section"><div class="lt-title">${title}</div>${body}</div>`;
    const frame = body => `<div class="log-tooltip">${body}</div>`;

    const defs = [
      { id: 'score',    title: '装分',       build: (r, p, d) => sec('装分', row('总分', num(d.score)) + dim('所有装备的分数累加（含精炼/镶嵌/附魔）')) },
      { id: 'quality',  title: '品质等级',   build: (r, p, d) => sec('品质等级', row('平均', num(d.quality_level)) + dim('装备品级的平均值（含精炼加成）')) },
      { id: 'hp',       title: '最大气血',   build: (r, p) => sec('最大气血', row('气血', num(p.max_life)) + row('体质', num(r.vitality)) + dim('基础 199476（全心法）+ 体质 × (系统 10 + 心法附加)；铁骨衣 = 12.2 / 体质')) },
      { id: 'vit',      title: '体质',       build: (r) => sec('体质', row('数值', num(r.vitality)) + dim('→ 气血 ×10（系统）；铁骨衣专属 → 外攻 郭氏 41 / 招架 郭氏 184 / 拆招 郭氏 2304 / 气血 +2.2')) },
      { id: 'str',      title: '力道',       build: (r) => sec('力道', row('数值', num(r.strength)) + dim('→ 外攻 ×0.163 / 破防 ×0.3（系统）')) },
      { id: 'agi',      title: '身法',       build: (r) => sec('身法', row('数值', num(r.agility)) + dim('→ 会心 ×0.9（系统）；分山劲专属 → 外攻 郭氏 1925 / 招架 郭氏 113 / 拆招 郭氏 1024')) },
      { id: 'atk',      title: '外功攻击',   build: (r, p) => {
        const base = Math.round(r.base_attack || 0);
        const final_ = Math.round(p.physics_attack_power || 0);
        const delta = final_ - base;
        return sec('外功攻击',
          row('基础', num(r.base_attack)) +
          row('最终', num(p.physics_attack_power)) +
          (delta !== 0 ? row('差额', (delta > 0 ? '+' : '') + num(delta)) : '') +
          dim('基础 = 心法固定 + 装备 + 力道×0.163；最终 = 基础 + 百分比加成 + 心法转化（身法/体质 → 攻击）'));
      }},
      { id: 'crit',     title: '会心',       build: (r, p) => sec('会心', row('等级', num(r.crit_level)) + row('面板', pct(p.crit_rate)) + dim('等级 / 197703 → 百分比')) },
      { id: 'crit_eff', title: '会心效果',   build: (r, p) => sec('会心效果', row('等级', num(r.crit_effect_level)) + row('面板', pct(p.crit_effect)) + dim('基础 1.75 + 等级 / 72844.2')) },
      { id: 'oc',       title: '破防',       build: (r, p) => sec('破防', row('等级', num(r.overcome_level)) + row('面板', pct(p.overcome_rate)) + dim('等级 / 225957.6 → 百分比')) },
      { id: 'strain',   title: '无双',       build: (r, p) => sec('无双', row('等级', num(r.strain_level)) + row('面板', pct(p.strain_rate)) + dim('等级 / 133333.2 → 百分比')) },
      { id: 'haste',    title: '加速',       build: (r, p) => sec('加速', row('等级', num(r.haste_level)) + row('面板', pct(p.haste_rate)) + dim('等级 / 210078，封顶 25%')) },
      { id: 'surplus',  title: '破招',       build: (r, p) => sec('破招', row('数值', num(p.surplus_value)) + dim('破招伤害公式的直乘因子（已含游戏内 7.421 常数）')) },
      { id: 'pvx',      title: '全能',       build: (r) => {
        const v = Math.round(r.pvx_all_round || 0);
        return sec('全能',
          row('点数', num(r.pvx_all_round)) +
          (v > 0 ? row('破招', '+' + num(Math.floor(v * 0.5))) +
                    row('无双', '+' + num(Math.floor(v * 1.5))) +
                    row('化劲', '+' + num(Math.floor(v * 1.0)))
                  : '') +
          dim('每点 = 0.5 破招等级 + 1.5 无双等级 + 1 化劲等级'));
      }},
      { id: 'pshield',  title: '外功防御',   build: (r, p) => sec('外功防御', row('等级', num(r.physics_shield)) + row('面板', pct(p.physics_shield_rate)) + dim('130 级：等级 / (等级 + 126007.2)，封顶 75%')) },
      { id: 'mshield',  title: '内功防御',   build: (r, p) => sec('内功防御', row('等级', num(r.magic_shield)) + row('面板', pct(p.magic_shield_rate)) + dim('130 级：等级 / (等级 + 126007.2)，封顶 75%')) },
      { id: 'parry',    title: '招架',       build: (r, p) => sec('招架', row('等级', num(r.parry_level)) + row('面板', pct(p.parry_rate)) + dim('等级 / (等级 + 107553.6) + 3%（心法自带基础）')) },
      { id: 'parry_val',title: '拆招',       build: (r, p) => sec('拆招', row('数值', num(p.parry_value)) + dim('用于减免被招架后的伤害；铁骨衣靠体质 ×2.25 堆叠')) },
      { id: 'dodge',    title: '闪避',       build: (r, p) => sec('闪避', row('等级', num(r.dodge_level)) + row('面板', pct(p.dodge_rate)) + dim('等级 / (等级 + 91634.4)')) },
      { id: 'tough',    title: '御劲',       build: (r, p) => sec('御劲', row('等级', num(r.toughness_level)) + row('面板', pct(p.toughness_rate)) + dim('等级 / 197703 → 百分比（PvP 减会心率）')) },
      { id: 'decrit',   title: '化劲',       build: (r, p) => sec('化劲', row('等级', num(r.decritical_damage_level)) + row('面板', pct(p.decritical_damage_rate)) + dim('等级 / (等级 + 33046.2) + 9.96%（PvP 减会心伤害）')) },
    ];

    for (const def of defs) {
      const el = document.getElementById('eq_av_' + def.id);
      if (!el) continue;
      const rowEl = el.parentElement;
      rowEl.style.cursor = 'help';
      rowEl.addEventListener('mouseenter', () => {
        const data = state.lastCalcResp;
        if (!data) return;
        const html = frame(def.build(data.raw || {}, data.panel || {}, data));
        showTooltip(rowEl, html);
      });
      rowEl.addEventListener('mouseleave', hideTooltip);
    }
  }


  // 强制从 detail 同步 name/quality/set_id/set_name 到所有 slot（detailCache 命中后近瞬时）
  // 必须强制刷新而不是按缺失 filter——旧版本可能写入过错误的 set_id，否则套装识别会持续报 0/N
  async function hydrateSlotNames() {
    const slots = Object.entries(state.slots).filter(([, s]) => s?.equip_id);
    if (slots.length === 0) return;
    let dirty = false;
    await Promise.all(slots.map(async ([pos, s]) => {
      try {
        const d = await getDetailCached(POS_TO_SUB[pos], s.equip_id);
        if (!d) return;
        if (s.name !== d.name) { s.name = d.name; dirty = true; }
        if (s.quality !== d.quality) { s.quality = d.quality; dirty = true; }
        const newSid = d.set_id || 0;
        const newSn = d.set_bonuses?.name || '';
        if (s.set_id !== newSid) { s.set_id = newSid; dirty = true; }
        if (s.set_name !== newSn) { s.set_name = newSn; dirty = true; }
      } catch (e) {}
    }));
    updateSlotBadges();
    if (dirty) saveToLocal();
  }

  // 全身装备里属于指定 set_id 的件数（不含未 hydrate 的）
  function countWornSetMembers(targetSetId) {
    if (!targetSetId) return 0;
    let n = 0;
    for (const s of Object.values(state.slots)) {
      if (s?.set_id === targetSetId) n++;
    }
    return n;
  }
  // 暴露给 tooltip 渲染（buildSlotTooltipHtml 在另一个 IIFE 里）
  window.Jx3Equip = window.Jx3Equip || {};
  window.Jx3Equip._countWornSetMembers = countWornSetMembers;

  // 页切换时加载
  new MutationObserver(() => {
    if (page.classList.contains('active')) {
      loadMeta().then(() => {
        updateMountLabel();
        updateSlotBadges();
        hydrateSlotNames();
        recalculate();
      });
    }
  }).observe(page, { attributes: true, attributeFilter: ['class'] });

  // ── 把配装 raw 属性同步到模拟器属性面板输入框（走配装器替代手填） ──
  function syncRawToAttrsInputs(raw) {
    if (!raw) return;
    const setInput = (id, v) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.value = Math.round(v || 0);
      el.dispatchEvent(new Event('input',  { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
    };
    setInput('li_dao',            raw.strength);
    setInput('shen_fa',           raw.agility);
    setInput('vitality',          raw.vitality);
    setInput('base_attack',       raw.base_attack);
    setInput('weapon_damage',     raw.weapon_damage);
    setInput('surplus_value',     raw.surplus_value);
    setInput('crit_level',        raw.crit_level);
    setInput('crit_effect_level', raw.crit_effect_level);
    setInput('overcome_level',    raw.overcome_level);
    setInput('strain_level',      raw.strain_level);
    setInput('haste_level',       raw.haste_level);
    setInput('parry_value',       raw.parry_value);
    setInput('parry_level',       raw.parry_level);
  }

  // ── 对外 API ──
  window.Jx3Equip = {
    /** 读取当前独立配装（从 state，与 localStorage 保持同步）*/
    getCurrentConfig() {
      return {
        slots: JSON.parse(JSON.stringify(state.slots || {})),
        stoneId: state.stoneId || 0,
        stoneName: state.stoneName || '',
      };
    },
    /** 构造装备 hover tooltip HTML（异步：要拉装备详情）。
     *  pos:  POS_LIST 中的位置标识，决定 sub_type。
     *  cfg:  { equip_id, strength?, embedding?, enhance_id?, enchant_id? }；缺省字段不渲染。
     *  opts: { stoneName? }，仅主武器位有效。
     *  返回 HTML 字符串；equip_id 不存在时返回空串。
     */
    async buildItemTooltip(pos, cfg, opts = {}) {
      try {
        return await buildSlotTooltipHtml(pos, cfg, opts.stoneName, opts.contextSlots);
      } catch (e) { return ''; }
    },
    /** 通过 /api/equip/calculate 拿到一套 slots 的完整面板 + raw（调用方负责传 mount/talents）*/
    async calculatePanel(slots, stoneId, mount, talents) {
      try {
        return await apiPost('/api/equip/calculate', {
          slots, stone_id: stoneId || 0, mount, talents: talents || [],
        });
      } catch (e) { return null; }
    },
    /** 应用一套配装：写入 state + localStorage + 刷新 UI（若 page-equip 打开）+ 重算属性 */
    async applyConfig(cfg) {
      if (!cfg) return;
      state.slots     = JSON.parse(JSON.stringify(cfg.slots || {}));
      state.stoneId   = cfg.stoneId   || 0;
      state.stoneName = cfg.stoneName || '';
      saveToLocal();
      try {
        updateSlotBadges();
        hydrateSlotNames();
      } catch (e) {}
      try {
        const mountId = getCurrentMountId();
        const talents = getCurrentTalents();
        const resp = await apiPost('/api/equip/calculate', {
          slots: state.slots,
          stone_id: state.stoneId || 0,
          mount: mountId,
          talents,
        });
        state.lastCalcResp = resp;
        try { renderAttrs(resp); } catch (e) {}
        syncRawToAttrsInputs(resp?.raw);
        return resp;
      } catch (e) {
        console.error('applyConfig 计算失败', e);
      }
    },
    /** 跳到配装器页 */
    openPage() {
      window.Jx3Nav?.switchPage('page-equip');
    },
    /** 主动同步 raw attrs 到属性面板 DOM */
    syncToAttrsInputs: syncRawToAttrsInputs,

    // ── 多配装文件 CRUD ──
    async listConfigs() {
      try {
        const r = await apiGet('/api/equip/configs/list');
        return Array.isArray(r?.files) ? r.files : [];
      } catch { return []; }
    },
    async saveConfig(name) {
      if (!name || !name.trim()) throw new Error('name required');
      const cfg = {
        name: name.trim(),
        mount: (typeof currentMount !== 'undefined' && currentMount?.mount) || null,
        slots: JSON.parse(JSON.stringify(state.slots || {})),
        stone_id: state.stoneId || 0,
        stone_name: state.stoneName || '',
      };
      const r = await apiPost('/api/equip/configs/save', { name: name.trim(), config: cfg });
      return r;
    },
    async loadConfig(file) {
      const r = await apiGet('/api/equip/configs/load?file=' + encodeURIComponent(file));
      if (!r || r.error) throw new Error(r?.error || 'load failed');
      return r;  // { name, mount, slots, stone_id, stone_name, created_at }
    },
    async deleteConfig(file) {
      return await apiPost('/api/equip/configs/delete', { file });
    },
  };

  // ── 配装器页按钮：[加载…]
  //    [导出…] / [另存为] / [本地 JSON 导出] / [本地 JSON 导入] / [在线库 JSON 导出 / 导入]
  //    都合并进顶层 _openEquipExportTabModal (导出 3 Tab) + plaza picker 弹窗的"智能导入"子窗
  document.getElementById('eq_load')?.addEventListener('click', () => {
    window.Jx3Plaza?.openPickerModal?.({ fromEquipPage: true });
  });

})();

// ═══════════════════════════════════════════════════════════════
// 战斗广场 (工作流 C · 方案对比)
// ═══════════════════════════════════════════════════════════════
(function setupPlaza() {
  const page = document.getElementById('page-plaza');
  if (!page) return;

  const STORAGE_KEY = 'plaza_builds_v1';
  const SCHEMA_VERSION = 1;

  // ── 数据层 ──
  /** @returns {{version:number, builds:Array}} */
  function loadStore() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return { version: SCHEMA_VERSION, builds: [] };
      const d = JSON.parse(raw);
      if (!d || typeof d !== 'object') return { version: SCHEMA_VERSION, builds: [] };
      if (!Array.isArray(d.builds)) d.builds = [];
      d.version = SCHEMA_VERSION;
      return d;
    } catch {
      return { version: SCHEMA_VERSION, builds: [] };
    }
  }
  function saveStore(s) {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(s)); } catch {}
  }
  function uid() {
    return 'b_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
  }
  function nextDefaultName(store) {
    let n = store.builds.length + 1;
    const used = new Set(store.builds.map(b => b.name));
    while (used.has(`方案${n}`)) n++;
    return `方案${n}`;
  }

  const PlazaStore = {
    list() { return loadStore().builds; },
    get(id) { return loadStore().builds.find(b => b.id === id) || null; },
    add(build) {
      const s = loadStore();
      const now = Date.now();
      const b = {
        id: uid(),
        name: build.name || nextDefaultName(s),
        mount: build.mount || null,
        equipment: build.equipment || null,
        talents: build.talents || [],
        recipes: build.recipes || [],
        rotation: build.rotation || null,
        snapshot: build.snapshot || null,
        created_at: now,
        updated_at: now,
      };
      s.builds.push(b);
      saveStore(s);
      return b;
    },
    update(id, patch) {
      const s = loadStore();
      const i = s.builds.findIndex(b => b.id === id);
      if (i < 0) return null;
      s.builds[i] = { ...s.builds[i], ...patch, updated_at: Date.now() };
      saveStore(s);
      return s.builds[i];
    },
    remove(id) {
      const s = loadStore();
      const i = s.builds.findIndex(b => b.id === id);
      if (i < 0) return false;
      s.builds.splice(i, 1);
      saveStore(s);
      return true;
    },
    duplicate(id) {
      const src = this.get(id);
      if (!src) return null;
      const copy = JSON.parse(JSON.stringify(src));
      copy.name = (src.name || '方案') + ' · 副本';
      delete copy.id; delete copy.created_at; delete copy.updated_at;
      return this.add(copy);
    },
    nextDefaultName() { return nextDefaultName(loadStore()); },
  };
  // 对外暴露供工作流 A / 配装器等后续阶段调用
  window.Jx3Plaza = PlazaStore;

  // ── 向导状态机 ──
  const WIZARD_STEPS = [
    { id: 1, key: 'config',      label: '奇穴秘籍', page: 'page-plaza-step2' },
    { id: 2, key: 'equip',       label: '配装',     page: 'page-equip' },
    { id: 3, key: 'rotation',    label: '循环',     page: 'page-sim' },
    { id: 4, key: 'overview',    label: '概览',     page: 'page-plaza-step4' },
  ];

  /** @type {{draft: object, currentStep: number, editingId: string|null, returnTo: string}|null} */
  let wizardState = null;

  const wzShell = document.getElementById('wizard-shell');
  const wzPrev   = document.getElementById('ws_prev');
  const wzNext   = document.getElementById('ws_next');
  const wzCancel = document.getElementById('ws_cancel');
  const wzExit   = document.getElementById('ws_exit');
  const wzName   = document.getElementById('ws_name_label');
  const wzMount  = document.getElementById('ws_mount_label');
  const wzStatus = document.getElementById('ws_status');
  const wzProgress = document.getElementById('ws_progress');

  function newDraft() {
    // 用当前全局状态预填，而不是全空（进入向导感觉像从零开始会很烦）
    const talents = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const recipes = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
    const target  = (typeof getTarget === 'function') ? getTarget() : null;
    const delayRaw = document.getElementById('sim_delay')?.value;
    const delay = parseInt(delayRaw || '0') || 0;
    return {
      id: null,
      name: PlazaStore.nextDefaultName(),
      mount: currentMountKey(),
      mount_label: currentMountLabel(),
      version: currentVersionKey(),
      version_label: currentVersionLabel(),
      equipment: (window.Jx3Equip?.getCurrentConfig?.()) || null,
      talents,
      recipes,
      rotation: { delay },
      snapshot: null,
      confirmedSave: false,  // Step 4 必须至少点一次"保存方案"
    };
  }

  function enterWizard(editingId = null) {
    const existing = editingId ? PlazaStore.get(editingId) : null;
    const draft = existing
      ? JSON.parse(JSON.stringify(existing))
      : newDraft();
    if (existing) draft.confirmedSave = false;  // 编辑也要主动点确定
    wizardState = {
      draft,
      currentStep: 1,
      editingId,
      returnTo: 'page-plaza',
    };
    document.body.classList.add('wizard-mode');
    wzShell?.setAttribute('aria-hidden', 'false');
    renderWizardShell();
    goToStep(1);
  }

  function exitWizard() {
    wizardState = null;
    document.body.classList.remove('wizard-mode');
    wzShell?.setAttribute('aria-hidden', 'true');
    window.Jx3Nav?.switchPage('page-plaza');
  }

  // 占位：真正的 goToStep 在 commit/apply 逻辑之后定义（需要闭包捕获它们）
  let goToStep = async (n) => { void n; };

  function renderWizardShell() {
    if (!wizardState) return;
    const { draft, currentStep } = wizardState;
    if (wzName)  wzName.textContent  = draft.name || '方案';
    if (wzMount) wzMount.textContent = draft.mount_label || currentMountLabel();
    if (wzStatus) wzStatus.textContent = `第 ${currentStep} 步 / 共 ${WIZARD_STEPS.length} 步`;

    // 进度条样式
    wzProgress?.querySelectorAll('.ws-step').forEach(el => {
      const s = Number(el.dataset.step);
      el.classList.toggle('active', s === currentStep);
      el.classList.toggle('done', s < currentStep);
    });
    wzProgress?.querySelectorAll('.ws-bar').forEach((el, i) => {
      // i 个 bar 位于 step i+1 之前；step (i+1) 已 active/done 时 bar 也 done
      el.classList.toggle('done', currentStep > i + 1);
    });

    // 按钮状态
    if (wzPrev) wzPrev.disabled = currentStep === 1;
    if (wzNext) {
      if (currentStep === WIZARD_STEPS.length) {
        wzNext.textContent = '保存方案';
        wzNext.classList.add('primary');
      } else {
        wzNext.textContent = '下一步 →';
        wzNext.classList.add('primary');
      }
    }
  }

  // ── 步骤数据 commit / apply ──
  function commitStep(n, draft) {
    if (n === 1) {  // 奇穴秘籍 + 目标 + 延迟
      draft.talents = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
      draft.recipes = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
      draft.target  = (typeof getTarget === 'function') ? getTarget() : null;
      draft.rotation = draft.rotation || {};
      draft.rotation.delay = parseInt(document.getElementById('sim_delay')?.value || '0') || 0;
    } else if (n === 2) {  // 配装
      draft.equipment = window.Jx3Equip?.getCurrentConfig?.() || null;
      draft.attributes = (typeof getAttrs === 'function') ? getAttrs() : null;
    } else if (n === 3) {  // 循环
      try {
        const cfg = (typeof buildLoopConfig === 'function') ? buildLoopConfig() : null;
        if (cfg) {
          draft.rotation = {
            ...(draft.rotation || {}),
            sequence: cfg.sequence || [],
            macro: cfg.macro || {},
            delay: cfg.network_delay || 0,  // sim-toolbar 可再改；以最新为准
            initial_rage: cfg.initial_rage,
            macro_duration: cfg.macro_duration,
            boss_attack_interval: cfg.boss_attack_interval,
          };
          if (cfg.target) draft.target = cfg.target;
        }
        draft.attributes = (typeof getAttrs === 'function') ? getAttrs() : null;
        // sim-toolbar 也能改奇穴/秘籍/目标，跳步时一并捕获，避免顶栏点 Step 1 被 revert
        draft.talents = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : (draft.talents || []);
        draft.recipes = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : (draft.recipes || []);
        if (typeof getTarget === 'function') draft.target = getTarget();
      } catch (e) { console.warn('commitStep 3', e); }
    }
  }

  async function applyStep(n, draft) {
    if (n === 1) {  // 奇穴秘籍 + 目标 + 延迟
      // 先加载元数据（避免 chip 显示 #id）
      try { await ensureTalentRecipeLists(); } catch {}
      applyTalentsFromArray(draft.talents || []);
      applyRecipesFromArray(draft.recipes || []);
      if (draft.target) {
        const lvl = document.getElementById('target_level');
        const def = document.getElementById('target_defense_bonus');
        if (lvl && draft.target.level != null) {
          lvl.value = draft.target.level;
          lvl.dispatchEvent(new Event('change', { bubbles: true }));
        }
        if (def && draft.target.defense_bonus != null) def.value = draft.target.defense_bonus;
      }
      if (draft.rotation?.delay != null) {
        const v = String(draft.rotation.delay);
        const el = document.getElementById('sim_delay');
        if (el) el.value = v;
        const item = document.querySelector(`#page-sim .sim-dropdown-item[data-value="${v}"]`);
        const lab = document.getElementById('sim_delay_label');
        if (lab && item) lab.textContent = item.textContent;
      }
      try { syncStep1AuxFromGlobal(); } catch {}
      // 全局已对齐 draft，刷新页面 chip / 计数（page-active MO 早于本次 apply 触发过）
      try { renderStep2Summary(); } catch {}
    } else if (n === 2) {  // 配装
      if (draft.equipment && window.Jx3Equip?.applyConfig) {
        try { await window.Jx3Equip.applyConfig(draft.equipment); } catch (e) {}
      }
    } else if (n === 3) {  // 循环
      if (draft.rotation) {
        const cfg = {
          version: (typeof LOOP_CONFIG_VERSION !== 'undefined') ? LOOP_CONFIG_VERSION : 1,
          sequence: draft.rotation.sequence || [],
          macro: draft.rotation.macro || {},
          network_delay: draft.rotation.delay,
          initial_rage: draft.rotation.initial_rage,
          macro_duration: draft.rotation.macro_duration,
          boss_attack_interval: draft.rotation.boss_attack_interval,
          target: draft.target || undefined,
        };
        try {
          if (typeof applyLoopConfig === 'function') applyLoopConfig(cfg);
        } catch (e) { console.warn('applyStep 3', e); }
      }
    }
  }

  /** 按 talentList 的 tier 信息把 id 数组写回 talentSelection */
  // 暴露给顶层 openImportLoopModal 等共用
  window.applyTalentsFromArray = (ids) => applyTalentsFromArray(ids);
  window.applyRecipesFromArray = (ids) => applyRecipesFromArray(ids);
  // 注：ensureTalentRecipeLists 在下方定义后再 expose
  function applyTalentsFromArray(ids) {
    if (typeof talentSelection === 'undefined' || typeof talentList === 'undefined') return;
    for (let t = 1; t <= 10; t++) talentSelection[t] = null;
    talentSelection.mixed.length = 0;
    for (const id of ids || []) {
      const info = talentList.find(x => x.id === id);
      if (!info) continue;
      if (info.tier === 'mixed' || info.tier === 8 || info.tier === 9 || info.tier === 10) {
        talentSelection.mixed.push(id);
      } else if (typeof info.tier === 'number' && info.tier >= 1 && info.tier <= 7) {
        talentSelection[info.tier] = id;
      }
    }
    try { typeof refreshTalentUI === 'function' && refreshTalentUI(); } catch {}
    try { typeof enforceTalentGating === 'function' && enforceTalentGating(); } catch {}
  }

  function applyRecipesFromArray(ids) {
    if (typeof selectedRecipes === 'undefined' || typeof recipeList === 'undefined') return;
    for (const k of Object.keys(selectedRecipes)) selectedRecipes[k].clear();
    for (const id of ids || []) {
      const info = recipeList.find(x => x.id === id);
      if (!info) continue;
      if (selectedRecipes[info.skill]) selectedRecipes[info.skill].add(id);
    }
    try { typeof refreshRecipeUI === 'function' && refreshRecipeUI(); } catch {}
  }

  wzPrev?.addEventListener('click', async () => {
    if (!wizardState) return;
    commitStep(wizardState.currentStep, wizardState.draft);
    const next = Math.max(1, wizardState.currentStep - 1);
    await doGoToStep(next);
  });
  wzNext?.addEventListener('click', async () => {
    if (!wizardState) return;
    commitStep(wizardState.currentStep, wizardState.draft);
    if (wizardState.currentStep < WIZARD_STEPS.length) {
      await doGoToStep(wizardState.currentStep + 1);
    } else {
      saveWizardDraft();
    }
  });
  async function doGoToStep(n) {
    wizardState.currentStep = n;
    const target = WIZARD_STEPS[n - 1];
    window.Jx3Nav?.switchPage(target.page);
    renderWizardShell();
    // 等一个 microtask 保证页面切换后再 apply
    await Promise.resolve();
    await applyStep(n, wizardState.draft);
    // 进 Step 4 时刷新概览；无快照且有序列/宏时自动跑一次
    if (n === 4) {
      renderOverview();
      const d = wizardState.draft;
      const rot = d?.rotation || {};
      const hasSeq = Array.isArray(rot.sequence) && rot.sequence.length > 0;
      const hasMacro = rot.macro && (rot.macro.general || rot.macro.shield || rot.macro.blade);
      if (!d.snapshot && (hasSeq || hasMacro)) {
        runSnapshot();
      }
    }
  }
  // 替换原 goToStep 为 doGoToStep（保留同名兼容）
  goToStep = doGoToStep;  // 这里原 goToStep 是 function 声明；重新赋值 let 变量

  // 点击顶栏进度条的 step 直接跳转（先 commit 当前步再跳）
  wzProgress?.querySelectorAll('.ws-step').forEach(el => {
    el.style.cursor = 'pointer';
    el.addEventListener('click', async () => {
      if (!wizardState) return;
      const s = Number(el.dataset.step);
      if (!s || s === wizardState.currentStep) return;
      commitStep(wizardState.currentStep, wizardState.draft);
      await doGoToStep(s);
    });
  });

  function askCancel() {
    if (!wizardState) return;
    if (!confirm('取消向导将丢弃未保存的修改，确定吗？')) return;
    exitWizard();
  }
  wzCancel?.addEventListener('click', askCancel);
  wzExit?.addEventListener('click', askCancel);

  // 对外暴露 API
  window.Jx3PlazaWizard = {
    enter: enterWizard,
    exit: exitWizard,
    isActive: () => wizardState != null,
    currentStep: () => wizardState?.currentStep ?? 0,
    draft: () => wizardState?.draft || null,
    goToStep,
  };

  // ═══════════════════════════════════════════════════════════════
  // Step 1 · 奇穴 / 秘籍 / 目标 / 延迟
  // ═══════════════════════════════════════════════════════════════

  // 按需加载 talent/recipe 元数据（供 chip 解析 id → name；不打开 modal）
  // 用 Promise 缓存防止并发重复填充
  let talentLoadP = null;
  let recipeLoadP = null;
  // expose ensureTalentRecipeLists 给顶层
  window.ensureTalentRecipeLists = () => ensureTalentRecipeLists();
  async function ensureTalentRecipeLists() {
    if (typeof talentList !== 'undefined' && talentList.length === 0 && !talentLoadP) {
      talentLoadP = (async () => {
        try {
          const res = await fetch(API.talents, { signal: AbortSignal.timeout(3000) });
          if (res.ok) {
            const data = await res.json();
            if (Array.isArray(data)) {
              // 整体替换（原位清空再填充），与 initTalentModal 的 `talentList = await ...` 行为对齐
              talentList.length = 0;
              talentList.push(...data);
            }
          }
        } catch {}
      })();
    }
    if (typeof recipeList !== 'undefined' && recipeList.length === 0 && !recipeLoadP) {
      recipeLoadP = (async () => {
        try {
          const res = await fetch(API.recipes, { signal: AbortSignal.timeout(3000) });
          if (res.ok) {
            const data = await res.json();
            if (Array.isArray(data)) {
              recipeList.length = 0;
              recipeList.push(...data);
            }
          }
        } catch {}
      })();
    }
    if (talentLoadP) await talentLoadP;
    if (recipeLoadP) await recipeLoadP;
  }
  // 暴露供其他工作流（如 A）复用
  window.Jx3Plaza = window.Jx3Plaza || {};
  window.Jx3Plaza.ensureTalentRecipeLists = ensureTalentRecipeLists;

  function renderStep2Summary() {
    // 奇穴
    const tIds = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const talentsSumEl = document.getElementById('pc2_talents_summary');
    if (talentsSumEl) talentsSumEl.textContent = `已选 ${tIds.length} 个`;
    const tChipsEl = document.getElementById('pc2_talents_chips');
    if (tChipsEl) {
      if (!tIds.length) {
        tChipsEl.innerHTML = '<span class="pc2-chips-empty">尚未选择</span>';
      } else {
        const list = (typeof talentList !== 'undefined') ? talentList : [];
        const unresolvedIds = [];
        const html = tIds.map(id => {
          const info = list.find(x => x.id === id);
          if (!info) unresolvedIds.push(id);
          return `<span class="pc2-chip">${escapeHtml(info?.name || ('#' + id))}</span>`;
        }).join('');
        tChipsEl.innerHTML = html;
        // 如果有 id 无法解析，尝试加载元数据后再刷
        if (unresolvedIds.length && list.length === 0) {
          ensureTalentRecipeLists().then(renderStep2Summary);
        }
      }
    }
    // 秘籍
    const rIds = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
    const recipesSumEl = document.getElementById('pc2_recipes_summary');
    if (recipesSumEl) recipesSumEl.textContent = `已选 ${rIds.length} 条`;
    const rChipsEl = document.getElementById('pc2_recipes_chips');
    if (rChipsEl) {
      if (!rIds.length) {
        rChipsEl.innerHTML = '<span class="pc2-chips-empty">尚未选择</span>';
      } else {
        const list = (typeof recipeList !== 'undefined') ? recipeList : [];
        // 按技能分组简要显示（skill 是可读名，不是 id）
        const bySkill = {};
        const unresolved = [];
        for (const id of rIds) {
          const info = list.find(x => x.id === id);
          if (!info) { unresolved.push(id); continue; }
          if (!bySkill[info.skill]) bySkill[info.skill] = 0;
          bySkill[info.skill] += 1;
        }
        const parts = Object.entries(bySkill)
          .map(([sk, n]) => `<span class="pc2-chip">${escapeHtml(sk)} × ${n}</span>`);
        if (unresolved.length) {
          parts.push(`<span class="pc2-chip pc2-chip-dim">未识别 × ${unresolved.length}</span>`);
        }
        rChipsEl.innerHTML = parts.join('');
        if (unresolved.length && list.length === 0) {
          ensureTalentRecipeLists().then(renderStep2Summary);
        }
      }
    }

    // 团辅
    const tbSumEl = document.getElementById('pc2_team_buffs_summary');
    if (tbSumEl) {
      const tbCount = (typeof getTeamBuffs === 'function') ? getTeamBuffs().length : 0;
      const tbOn = !!window._teamBuffsGlobalEnabled;
      tbSumEl.textContent = tbOn ? `已启用 ${tbCount} 条` : '已启用 0 条（全局关闭）';
    }

    // 只渲染摘要。写回 draft 留给 commitStep(1) / 模态关闭 / 目标延迟 pick 处理
    // —— renderStep2Summary 会被 page 激活 MutationObserver 触发，
    //    若此时写回会用 applyStep 未跑完前的全局默认值覆盖 draft 里记录的奇穴秘籍。
  }

  /** 用户确认变更后（modal 关闭、目标/延迟 pick）才把全局状态回写到 draft */
  function writeStep1BackToDraft() {
    if (!wizardState?.draft) return;
    const tIds = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const rIds = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
    wizardState.draft.talents = tIds;
    wizardState.draft.recipes = rIds;
    try {
      const t = (typeof getTarget === 'function') ? getTarget() : null;
      if (t) wizardState.draft.target = t;
      const delay = parseInt(document.getElementById('sim_delay')?.value || '0') || 0;
      wizardState.draft.rotation = wizardState.draft.rotation || {};
      wizardState.draft.rotation.delay = delay;
      // 团辅（enabled 子集，与 buildLoopConfig.team_buffs 一致）
      if (typeof getTeamBuffs === 'function') {
        wizardState.draft.team_buffs = getTeamBuffs();
      }
    } catch {}
  }

  document.getElementById('pc2_talents_btn')?.addEventListener('click', () => {
    document.getElementById('btn_talents')?.click();
  });
  document.getElementById('pc2_recipes_btn')?.addEventListener('click', () => {
    document.getElementById('btn_recipes')?.click();
  });
  document.getElementById('pc2_team_buffs_btn')?.addEventListener('click', () => {
    document.getElementById('btn_team_buffs')?.click();
  });

  // ── 关键：监听 modal 关闭（关闭时刷新 Step 1）──
  // talent/recipe overlay 用 .open class 切换；team_buffs_modal 用 style.display:none/flex 切换
  function watchModalClose(overlayId, displayBased = false) {
    const hook = (el) => {
      if (!el || el.__stepObs) return;
      el.__stepObs = new MutationObserver(() => {
        const pc2Page = document.getElementById('page-plaza-step2');
        if (!pc2Page?.classList.contains('active')) return;
        const closed = displayBased
          ? (el.style.display === 'none')
          : !el.classList.contains('open');
        if (closed) {
          writeStep1BackToDraft();
          renderStep2Summary();
          try { syncStep1AuxFromGlobal(); } catch {}
        }
      });
      el.__stepObs.observe(el, { attributes: true, attributeFilter: ['class', 'style'] });
    };
    const existing = document.getElementById(overlayId);
    if (existing) { hook(existing); return; }
    const bodyObs = new MutationObserver(() => {
      const el = document.getElementById(overlayId);
      if (el) { hook(el); bodyObs.disconnect(); }
    });
    bodyObs.observe(document.body, { childList: true });
  }
  watchModalClose('talent_overlay');
  watchModalClose('recipe_overlay');
  watchModalClose('team_buffs_modal', true);

  // ── Step 1 · 目标 / 延迟 hover 下拉 ──
  function pc2PickTarget(v, text) {
    // 同步全局 select
    const orig = document.getElementById('target_level');
    if (orig && orig.value !== v) {
      orig.value = v;
      orig.dispatchEvent(new Event('change', { bubbles: true }));
    }
    // 同步 sim-toolbar inline label
    const simLab = document.getElementById('target_level_label');
    if (simLab) simLab.textContent = text;
    document.querySelectorAll('#sim_slot_target .sim-dropdown-item, #tb_slot_target .sim-dropdown-item').forEach(item => {
      item.classList.toggle('active', item.dataset.targetValue === v);
    });
    // 自身 label + active
    const lab = document.getElementById('pc2_target_label');
    if (lab) lab.textContent = text;
    document.querySelectorAll('#pc2_target_menu .sim-dropdown-item').forEach(i => {
      i.classList.toggle('active', i.dataset.value === v);
    });
    // 写回 draft
    if (wizardState?.draft) {
      try {
        const t = (typeof getTarget === 'function') ? getTarget() : null;
        if (t) wizardState.draft.target = t;
      } catch {}
    }
  }

  function pc2PickDelay(v, text) {
    const el = document.getElementById('sim_delay');
    if (el) el.value = v;
    const simLab = document.getElementById('sim_delay_label');
    const itemInSim = document.querySelector(`#page-sim .sim-dropdown-item[data-value="${v}"]`);
    if (simLab && itemInSim) simLab.textContent = itemInSim.textContent;
    document.querySelectorAll('#page-sim .sim-dropdown-item').forEach(i => {
      i.classList.toggle('active', i.dataset.value === v);
    });
    // 自身
    const lab = document.getElementById('pc2_delay_label');
    if (lab) lab.textContent = text;
    document.querySelectorAll('#pc2_delay_menu .sim-dropdown-item').forEach(i => {
      i.classList.toggle('active', i.dataset.value === v);
    });
    if (wizardState?.draft) {
      wizardState.draft.rotation = wizardState.draft.rotation || {};
      wizardState.draft.rotation.delay = parseInt(v, 10) || 0;
    }
  }

  function buildPc2TargetMenu() {
    const menu = document.getElementById('pc2_target_menu');
    const origTarget = document.getElementById('target_level');
    if (!menu || !origTarget) return;
    menu.innerHTML = '';
    for (const opt of Array.from(origTarget.options)) {
      const item = document.createElement('div');
      item.className = 'sim-dropdown-item';
      item.dataset.value = opt.value;
      item.textContent = opt.textContent;
      item.addEventListener('click', () => pc2PickTarget(opt.value, opt.textContent));
      menu.appendChild(item);
    }
  }

  // 延迟菜单是静态的，绑定一次 click 处理
  document.querySelectorAll('#pc2_delay_menu .sim-dropdown-item').forEach(item => {
    item.addEventListener('click', () => pc2PickDelay(item.dataset.value, item.textContent));
  });

  function syncStep1AuxFromGlobal() {
    // 目标菜单若未构建或 options 变了，重建
    const origTarget = document.getElementById('target_level');
    const menu = document.getElementById('pc2_target_menu');
    if (origTarget && menu && menu.children.length !== origTarget.options.length) {
      buildPc2TargetMenu();
    }
    // 同步当前值到 label + active
    if (origTarget) {
      const v = origTarget.value;
      const opt = Array.from(origTarget.options).find(o => o.value === v);
      const lab = document.getElementById('pc2_target_label');
      if (lab) lab.textContent = opt ? opt.textContent : '—';
      document.querySelectorAll('#pc2_target_menu .sim-dropdown-item').forEach(i => {
        i.classList.toggle('active', i.dataset.value === v);
      });
    }
    // 同步延迟
    const origDelay = document.getElementById('sim_delay');
    if (origDelay) {
      const v = origDelay.value || '0';
      const item = document.querySelector(`#pc2_delay_menu .sim-dropdown-item[data-value="${v}"]`);
      const lab = document.getElementById('pc2_delay_label');
      if (lab && item) lab.textContent = item.textContent;
      document.querySelectorAll('#pc2_delay_menu .sim-dropdown-item').forEach(i => {
        i.classList.toggle('active', i.dataset.value === v);
      });
    }
  }

  // 页面进入时刷新摘要（模拟器 talent/recipe modal 的选择事件都在模态里处理，
  // 关闭后用户会看到新的选中数量 — 用 MutationObserver 监控模态 overlay 的关闭来触发刷新）
  new MutationObserver(() => {
    const p = document.getElementById('page-plaza-step2');
    if (p && p.classList.contains('active')) renderStep2Summary();
  }).observe(document.body, { childList: true, subtree: false });

  const pc2Page = document.getElementById('page-plaza-step2');
  if (pc2Page) {
    new MutationObserver(() => {
      if (pc2Page.classList.contains('active')) renderStep2Summary();
    }).observe(pc2Page, { attributes: true, attributeFilter: ['class'] });
  }

  // ═══════════════════════════════════════════════════════════════
  // Step 4 · 概览 + 保存
  // ═══════════════════════════════════════════════════════════════

  /** 构造概览四卡 HTML 片段，Step 4 和广场只读快照弹窗共用 */
  function buildOverviewBlocks(src) {
    const esc = (s) => escapeHtml(s ?? '');
    const fmtNum = (v) => (v == null || !isFinite(v)) ? '0' : Math.round(v).toLocaleString();
    const fmtPct = (v) => (v == null || !isFinite(v)) ? '—' : (v * 100).toFixed(2) + '%';
    const p = src.attributes || {};
    const panel = src.snapshot?.panel || null;  // 跑过模拟才有；包含最终面板 / 百分比
    const eq = src.equipment || {};
    const slots = eq.slots || {};
    const isTieGu = (src.mount === 'TieGuYi');
    const slotCount = Object.values(slots).filter(v => v && (typeof v === 'object') && v.equip_id).length;
    // 全部属性网格：有 panel 优先显示最终数值/百分比；否则退化为 等级
    const cell = (k, v) => `<div class="pc4-attr-cell"><span class="pc4-attr-k">${k}</span><span class="pc4-attr-v">${v}</span></div>`;
    const cells = [];
    cells.push(cell('力道', fmtNum(p.li_dao)));
    cells.push(cell('身法', fmtNum(p.shen_fa)));
    cells.push(cell('体质', fmtNum(panel?.vitality ?? p.vitality)));
    if (panel) {
      cells.push(cell('最终攻击', fmtNum(panel.panel_attack)));
    } else {
      cells.push(cell('基础攻击', fmtNum(p.base_attack)));
    }
    cells.push(cell('武器伤害', fmtNum(p.weapon_damage)));
    cells.push(cell('破招值', fmtNum(panel?.surplus_value ?? p.surplus_value)));
    if (panel) {
      cells.push(cell('会心率', fmtPct(panel.crit_rate)));
      cells.push(cell('会心效果', fmtPct(panel.crit_effect)));
      cells.push(cell('破防', fmtPct(panel.overcome)));
      cells.push(cell('无双', fmtPct(panel.strain)));
      cells.push(cell('加速', fmtPct(panel.haste_rate)));
      if (isTieGu) {
        cells.push(cell('招架率', fmtPct(panel.parry_rate)));
        cells.push(cell('拆招值', fmtNum(panel.parry_value)));
      }
    } else {
      cells.push(cell('会心等级', fmtNum(p.crit_level)));
      cells.push(cell('会效等级', fmtNum(p.crit_effect_level)));
      cells.push(cell('破防等级', fmtNum(p.overcome_level)));
      cells.push(cell('无双等级', fmtNum(p.strain_level)));
      cells.push(cell('加速等级', fmtNum(p.haste_level)));
      if (isTieGu) {
        cells.push(cell('招架等级', fmtNum(p.parry_level)));
        cells.push(cell('拆招值', fmtNum(p.parry_value)));
      }
    }
    const attrGrid = `<div class="pc4-attr-grid">${cells.join('')}</div>`;
    // 装备栏 chip（key 大写：HAT/JACKET/...，与配装器 / wzc / sim 一致）
    const slotNames = {
      HAT: '帽', JACKET: '衣', BELT: '腰', WRIST: '腕', BOTTOMS: '裤', SHOES: '鞋',
      NECKLACE: '项链', PENDANT: '腰坠',
      RING_1: '戒 ①', RING_2: '戒 ②',
      PRIMARY_WEAPON: '主武器', SECONDARY_WEAPON: '副武器',
      // 兼容老格式（小写 key）
      hat: '帽', clothes: '衣', belt: '腰', wrist: '腕', bottoms: '裤', shoes: '鞋',
      weapon: '主武器', pendant: '项链', ring_1: '戒 ①', ring_2: '戒 ②', waist_pendant: '腰坠', ornament: '副武器',
    };
    const slotChips = Object.entries(slots)
      .filter(([, v]) => v && (typeof v === 'object') && v.equip_id)
      .map(([k, v]) => `<span class="pc2-chip pc4-eq-chip" data-pos="${esc(k)}" data-eq-id="${v.equip_id}" data-enh-id="${v.enhance_id || 0}" data-enc-id="${v.enchant_id || 0}" data-strength="${v.strength || 0}" data-emb="${esc(JSON.stringify(v.embedding || []))}">${esc(slotNames[k] || k)}：${esc(v.name || ('#' + v.equip_id))}</span>`);
    const specials = [];
    if (eq.stoneName) specials.push(`<span class="pc2-chip">五彩石：${esc(eq.stoneName)}</span>`);
    const enchantCount = Object.values(slots).filter(v => v && v.enchant_id).length;
    if (enchantCount > 0) specials.push(`<span class="pc2-chip">大附魔 × ${enchantCount}</span>`);

    const equipHTML = `
      <div class="pc4-line"><span class="pc4-k">心法</span><span class="pc4-v">${esc(src.mount_label || '—')}</span></div>
      <div class="pc4-line"><span class="pc4-k">装备</span><span class="pc4-v">${slotCount} 件</span></div>
      ${attrGrid}
      ${slotChips.length ? `<div class="pc4-sub-title">装备栏</div><div class="pc2-chips">${slotChips.join('')}</div>` : ''}
      ${specials.length ? `<div class="pc4-sub-title">特殊装备</div><div class="pc2-chips">${specials.join('')}</div>` : ''}
    `;

    // 奇穴秘籍 / 目标 / 延迟
    const talents = src.talents || [];
    const recipes = src.recipes || [];
    const tList = (typeof talentList !== 'undefined') ? talentList : [];
    const rList = (typeof recipeList !== 'undefined') ? recipeList : [];
    const talentNames = talents.map(id => tList.find(x => x.id === id)?.name).filter(Boolean);
    const bySkill = {};
    for (const id of recipes) {
      const info = rList.find(x => x.id === id);
      if (!info) continue;
      bySkill[info.skill] = (bySkill[info.skill] || 0) + 1;
    }
    const recipeParts = Object.entries(bySkill)
      .map(([sk, nn]) => `<span class="pc2-chip">${esc(sk)} × ${nn}</span>`);
    const targetLabel = src.target?.level ? `${src.target.level}级` : '—';
    const delayMs = src.rotation?.delay || 0;
    // 团辅条数（src.team_buffs 来自 buildLoopConfig，含 enabled 项；旧方案没有则 fallback 全局）
    const teamBuffs = Array.isArray(src.team_buffs)
      ? src.team_buffs.filter(s => s?.enabled).length
      : (typeof getTeamBuffs === 'function' ? getTeamBuffs().length : 0);

    const trHTML = `
      <div class="pc4-line"><span class="pc4-k">奇穴</span><span class="pc4-v">${talents.length} 个</span></div>
      ${talentNames.length ? `<div class="pc4-sub">${talentNames.map(esc).join('、')}</div>` : ''}
      <div class="pc4-line"><span class="pc4-k">秘籍</span><span class="pc4-v">${recipes.length} 条</span></div>
      ${recipeParts.length ? `<div class="pc2-chips">${recipeParts.join('')}</div>` : ''}
      <div class="pc4-line"><span class="pc4-k">团辅</span><span class="pc4-v">${teamBuffs} 条</span></div>
      <div class="pc4-line"><span class="pc4-k">目标</span><span class="pc4-v">${targetLabel}</span></div>
      <div class="pc4-line"><span class="pc4-k">网络延迟</span><span class="pc4-v">${delayMs} ms</span></div>
    `;

    // 循环
    const rot = src.rotation || {};
    const seqN = Array.isArray(rot.sequence) ? rot.sequence.length : 0;
    const macroObj = rot.macro || {};
    const mode = macroObj.mode || 'general';
    const macroSegs = [];
    if (macroObj.general) macroSegs.push(`general ${macroObj.general.trim().split('\n').length}行`);
    if (macroObj.shield)  macroSegs.push(`shield ${macroObj.shield.trim().split('\n').length}行`);
    if (macroObj.blade)   macroSegs.push(`blade ${macroObj.blade.trim().split('\n').length}行`);
    const macroText = macroSegs.length ? `${mode}（${macroSegs.join(' / ')}）` : '—';
    const rotHTML = `
      <div class="pc4-line"><span class="pc4-k">序列</span><span class="pc4-v">${seqN} 项</span></div>
      <div class="pc4-line"><span class="pc4-k">宏</span><span class="pc4-v">${esc(macroText)}</span></div>
      ${rot.initial_rage != null ? `<div class="pc4-line"><span class="pc4-k">起手怒气</span><span class="pc4-v">${rot.initial_rage} 怒</span></div>` : ''}
      ${rot.macro_duration != null ? `<div class="pc4-line"><span class="pc4-k">宏时长</span><span class="pc4-v">${rot.macro_duration} 秒</span></div>` : ''}
      ${rot.boss_attack_interval != null ? `<div class="pc4-line"><span class="pc4-k">Boss 间隔</span><span class="pc4-v">${rot.boss_attack_interval} 秒</span></div>` : ''}
    `;

    // 快照（DPS + 元信息）与战斗统计表拆开两卡，便于右侧独占 stats 列
    const snap = src.snapshot;
    let snapHTML, statsHTML;
    if (snap && snap.dps > 0) {
      snapHTML = `
        <div class="pc4-dps-big">${Math.round(snap.dps).toLocaleString('en-US').replace(/,/g, '')}<span class="pc4-dps-unit">DPS</span></div>
        <div class="pc4-line"><span class="pc4-k">总伤害</span><span class="pc4-v">${Math.round(snap.total_damage || 0).toLocaleString()}</span></div>
        ${snap.fight_time ? `<div class="pc4-line"><span class="pc4-k">战斗时长</span><span class="pc4-v">${snap.fight_time.toFixed(2)} 秒</span></div>` : ''}
        ${snap.skill_count ? `<div class="pc4-line"><span class="pc4-k">技能数</span><span class="pc4-v">${snap.skill_count}</span></div>` : ''}
        <div class="pc4-line pc4-dim">快照时间：${fmtTs(snap.computed_at)}</div>
      `;
      const stats = Array.isArray(snap.skill_stats) ? snap.skill_stats : [];
      statsHTML = stats.length ? `
        <table class="pc4-stats-table">
          <thead><tr><th>技能</th><th class="pc4-num">次数</th><th class="pc4-num">伤害</th><th class="pc4-num">占比</th></tr></thead>
          <tbody>
            ${stats.map(s => `<tr>
              <td>${esc(s.name)}</td>
              <td class="pc4-num">${s.count}</td>
              <td class="pc4-num">${formatDamageWan(s.damage)}</td>
              <td class="pc4-num">${s.pct.toFixed(1)}%</td>
            </tr>`).join('')}
          </tbody>
        </table>` : `<div class="pc4-dim">无伤害事件。</div>`;
    } else if (snap) {
      snapHTML = `<div class="pc4-dim" style="color:var(--warning)">模拟返回 DPS = 0。请检查序列/宏/配装是否完整。</div>`;
      statsHTML = `<div class="pc4-dim">—</div>`;
    } else {
      snapHTML = `<div class="pc4-dim">尚未模拟。</div>`;
      statsHTML = `<div class="pc4-dim">—</div>`;
    }

    return { equipHTML, trHTML, rotHTML, snapHTML, statsHTML };
  }

  function renderOverview() {
    if (!wizardState) return;
    const d = wizardState.draft;
    // 属性可能在旧方案里缺失、或用户刚在 sim page 改过还没 commit；兜底从全局读一次
    if (!d.attributes && typeof getAttrs === 'function') {
      try { d.attributes = getAttrs(); } catch {}
    }
    // 名字
    const nameInp = document.getElementById('pc4_name_input');
    if (nameInp) {
      nameInp.value = d.name || PlazaStore.nextDefaultName();
      nameInp.oninput = (e) => { d.name = e.target.value; if (wzName) wzName.textContent = d.name || '方案'; };
    }

    const blocks = buildOverviewBlocks(d);
    const eqEl    = document.getElementById('pc4_equipment');
    const trEl    = document.getElementById('pc4_talents_recipes');
    const rotEl   = document.getElementById('pc4_rotation');
    const snapEl  = document.getElementById('pc4_snapshot');
    const statsEl = document.getElementById('pc4_stats');
    if (eqEl)    eqEl.innerHTML    = blocks.equipHTML;
    if (trEl)    trEl.innerHTML    = blocks.trHTML;
    if (rotEl)   rotEl.innerHTML   = blocks.rotHTML;
    // 装备 chip hover：复用 Jx3Equip.buildItemTooltip
    if (eqEl) {
      const eqStoneName = d.equipment?.stoneName || '';
      const contextSlots = d.equipment?.slots || null;
      eqEl.querySelectorAll('.pc4-eq-chip[data-eq-id]').forEach(chip => {
        const pos = chip.dataset.pos;
        const equipId = parseInt(chip.dataset.eqId, 10);
        if (!equipId) return;
        let embedding = [];
        try { embedding = JSON.parse(chip.dataset.emb || '[]') || []; } catch {}
        const slotCfg = {
          equip_id: equipId,
          strength: parseInt(chip.dataset.strength, 10) || 0,
          embedding,
          enhance_id: parseInt(chip.dataset.enhId, 10) || 0,
          enchant_id: parseInt(chip.dataset.encId, 10) || 0,
        };
        chip.style.cursor = 'help';
        chip.addEventListener('mouseenter', async () => {
          try {
            const html = await window.Jx3Equip?.buildItemTooltip?.(pos, slotCfg, { stoneName: eqStoneName, contextSlots });
            if (html) showTooltip(chip, html);
          } catch {}
        });
        chip.addEventListener('mouseleave', hideTooltip);
      });
    }
    if (snapEl) {
      // Step 4 里未跑过快照时提示去重算；其他情况沿用 blocks.snapHTML
      if (!d.snapshot) {
        snapEl.innerHTML = `<div class="pc4-dim">尚未模拟。点右上「重算」跑一次得到 DPS 估计。</div>`;
      } else {
        snapEl.innerHTML = blocks.snapHTML;
      }
    }
    if (statsEl) statsEl.innerHTML = blocks.statsHTML;
  }

  let _snapshotPromise = null;
  async function runSnapshot() {
    if (_snapshotPromise) return _snapshotPromise;
    if (!wizardState) return;
    _snapshotPromise = (async () => {
    const d = wizardState.draft;
    const snapEl = document.getElementById('pc4_snapshot');
    if (snapEl) snapEl.innerHTML = '<div class="pc4-dim">正在模拟…</div>';
    try {
      const rot = d.rotation || {};
      // 由 rotation.macro 构造 macro_text（若序列含 __macro__ 占位，后端需要它才能展开）
      const macroObj = rot.macro || {};
      let macroText = '';
      if (macroObj.mode === 'stance') {
        if (macroObj.shield) macroText += '#page shield\n' + macroObj.shield + '\n';
        if (macroObj.blade)  macroText += '#page blade\n'  + macroObj.blade  + '\n';
      } else {
        macroText = (macroObj.general || '').trim();
      }
      macroText = macroText.trim();
      // 展开 LoopConfig sequence：count 重复 + 同时构造 per-item channel_ticks/timing_offsets/qijin_buffs map
      // 与模拟器主页 runSimulate 对齐，否则引导跳数/timing 偏移/移除气劲全部丢失
      let sequence = [];
      const channelTicks = {};
      const timingOffsetsMap = {};
      const qijinBuffsMap = {};
      let outIdx = 0;
      for (const e of (rot.sequence || [])) {
        const n = Math.max(1, Number(e.count) || 1);
        const name = e.type === 'skill' ? e.skill :
                     e.type === 'macro' ? '__macro__' :
                     e.type === 'break' ? null :
                     e.type === 'wait_stance' ? '__切体态延迟中__' :
                     e.type === 'wait_zhan_jue' ? '__战绝回怒__' : null;
        if (!name) continue;
        for (let k = 0; k < n; k++) {
          if (e.channel_ticks) channelTicks[String(outIdx)] = e.channel_ticks;
          if (e.offset)        timingOffsetsMap[String(outIdx)] = e.offset;
          if (e.qijin_buff)    qijinBuffsMap[String(outIdx)] = e.qijin_buff;
          sequence.push(name);
          outIdx++;
        }
      }
      // 纯宏模式：当 sequence 只有 __macro__、且设置了 macro_duration，
      //   需要给足 slot 让后端按时长截断（对齐 runMacroSimulate 的口径，
      //   否则只有 1 个 __macro__ 会提前结束，fight_time 比宏设置短一截）
      if (rot.macro_duration && sequence.length > 0 && sequence.every(s => s === '__macro__')) {
        const maxSlots = Math.ceil(rot.macro_duration / 0.25) + 20;
        if (sequence.length < maxSlots) sequence = Array(maxSlots).fill('__macro__');
      }
      // 装备清单：脚本判定装备特效（盾击神兵 / 大附魔等）。draft.equipment 是 getCurrentConfig
      // 整体（含 strength/embedding/...），需要折成 getEquipmentMap 格式 { POS: equip_id, ENCHANT_POS: enchant_id }
      const equipMap = {};
      try {
        for (const [pos, s] of Object.entries(d.equipment?.slots || {})) {
          if (s?.equip_id)   equipMap[pos] = s.equip_id;
          if (s?.enchant_id) equipMap['ENCHANT_' + pos] = s.enchant_id;
        }
      } catch (e) {}
      const body = {
        haste_level: parseInt(d.attributes?.haste_level) || 0,
        sequence,
        channel_ticks: channelTicks,
        timing_offsets: timingOffsetsMap,
        qijin_buffs: qijinBuffsMap,
        talents: d.talents || [],
        recipes: d.recipes || [],
        network_delay: rot.delay || 0,
        attributes: d.attributes || null,
        target: d.target || null,
        initial_rage: rot.initial_rage,
        boss_attack_interval: rot.boss_attack_interval,
        macro_duration: rot.macro_duration,
        macro_text: sequence.includes('__macro__') ? macroText : undefined,
        equipment: equipMap,
        // 与 runMacroSimulate / runSimulate 对齐，否则 DPS / fight_time 与 sim 页不一致
        hanjia_expectation: (typeof isHanjiaExpectationEnabled === 'function') ? isHanjiaExpectationEnabled() : undefined,
        tiegu_mode:         (typeof getTieguMode === 'function')              ? getTieguMode()              : undefined,
        experimental:       (typeof isExperimental === 'function')            ? isExperimental()            : undefined,
        // 团辅 / 阵法：方案级 d 优先，fallback 全局当前
        team_buffs: Array.isArray(d.team_buffs) && d.team_buffs.length
                  ? d.team_buffs.filter(s => s?.enabled)
                  : ((typeof getTeamBuffs === 'function') ? getTeamBuffs() : []),
        formation: d.formation
                || ((typeof getCurrentFormation === 'function') ? getCurrentFormation() : null),
      };
      const r = await fetch('/api/simulate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(10000),
      });
      const data = await r.json();
      d.snapshot = {
        dps: data.dps || 0,
        total_damage: data.total_damage || 0,
        fight_time: data.fight_time || 0,
        skill_count: data.skill_count || 0,
        skill_stats: buildSkillStats(data.timeline || [], data.total_damage || 0),
        panel: firstPanelStats(data.timeline || []),
        computed_at: Date.now(),
      };
      renderOverview();
    } catch (e) {
      if (snapEl) snapEl.innerHTML = `<div class="pc4-dim" style="color:var(--warning)">模拟失败：${escapeHtml(e.message)}</div>`;
    } finally {
      _snapshotPromise = null;
    }
    })();
    return _snapshotPromise;
  }
  document.getElementById('pc4_rerun')?.addEventListener('click', runSnapshot);

  // 向导 Step 3（page-sim）跑出 DPS 后自动写入 draft.snapshot，
  // 避免跳到 Step 4 还要手动点「重算」
  window.addEventListener('jx3-sim-complete', (e) => {
    if (!wizardState || wizardState.currentStep !== 3) return;
    const data = e.detail;
    if (!data || typeof data.dps !== 'number') return;
    wizardState.draft.snapshot = {
      dps: data.dps || 0,
      total_damage: data.total_damage || 0,
      fight_time: data.fight_time || 0,
      skill_count: data.skill_count || 0,
      skill_stats: buildSkillStats(data.timeline || [], data.total_damage || 0),
      panel: firstPanelStats(data.timeline || []),
      computed_at: Date.now(),
    };
  });

  /** 取 timeline 里第一个带 runtime_stats 的事件，作为面板快照（最终攻击 / 副属性百分比） */
  function firstPanelStats(timeline) {
    for (const ev of timeline) {
      if (ev && ev.runtime_stats) return ev.runtime_stats;
    }
    return null;
  }

  /** 从 timeline 计算按技能聚合的战斗统计（全量；与模拟器主页弹窗对齐）。合并同名按 mergedName 走。 */
  function buildSkillStats(timeline, totalDamage) {
    const counts = {};
    for (const ev of timeline) {
      if (!ev.damage_total) continue;
      const key = (typeof mergedName === 'function') ? mergedName(ev.name) : ev.name;
      if (!counts[key]) counts[key] = { name: key, count: 0, damage: 0 };
      counts[key].count++;
      counts[key].damage += ev.damage_total;
    }
    return Object.values(counts)
      .filter(c => c.damage > 0)
      .map(c => ({
        name: c.name,
        count: c.count,
        damage: c.damage,
        pct: totalDamage > 0 ? (c.damage / totalDamage * 100) : 0,
      }))
      .sort((a, b) => b.damage - a.damage);
  }

  // Step 4：发送到循环蒸馏
  document.getElementById('pc4_send_a')?.addEventListener('click', () => {
    if (!wizardState) return;
    if (!window.Jx3WorkflowA?.enterWithDraft) { alert('循环蒸馏工作流未加载'); return; }
    // 深拷贝当前 draft；编辑态带上原 build id，让 A-7 的 [更新原方案] 可用
    const draft = JSON.parse(JSON.stringify(wizardState.draft));
    if (wizardState.editingId) draft.id = wizardState.editingId;
    exitWizard();  // 先退出向导；enterWithDraft 会切到 page-wizard-a
    window.Jx3WorkflowA.enterWithDraft(draft);
  });

  async function saveWizardDraft() {
    if (!wizardState) return;
    const d = wizardState.draft;
    const nameInp = document.getElementById('pc4_name_input');
    if (nameInp) d.name = nameInp.value.trim() || PlazaStore.nextDefaultName();
    if (!d.name) { alert('请给方案命名'); return; }
    // 没跑过快照时自动跑一次
    if (!d.snapshot) {
      await runSnapshot();
    }
    // 清理 draft 里的内部字段
    const payload = { ...d };
    delete payload.confirmedSave;
    delete payload.id;
    if (wizardState.editingId) {
      PlazaStore.update(wizardState.editingId, payload);
    } else {
      PlazaStore.add(payload);
    }
    exitWizard();
  }

  // ── UI ──
  const elCards  = page.querySelector('#plaza_cards');
  const elCount  = page.querySelector('#plaza_count');
  const elFooter = page.querySelector('#plaza_footer');
  const elMount  = page.querySelector('#plaza_mount_label');
  const elBack   = page.querySelector('#plaza_back_hub');

  elBack?.addEventListener('click', () => window.Jx3Nav?.switchPage('page-hub'));

  function fmtDps(n) {
    if (n == null || !isFinite(n)) return '—';
    return Math.round(n).toLocaleString('en-US').replace(/,/g, '');
  }
  function currentMountLabel() {
    return (typeof currentMount !== 'undefined' && currentMount?.mount_label) || '—';
  }
  function currentMountKey() {
    return (typeof currentMount !== 'undefined' && currentMount?.mount) || null;
  }
  function currentVersionLabel() {
    return (typeof currentMount !== 'undefined' && currentMount?.version_label) || '—';
  }
  function currentVersionKey() {
    return (typeof currentMount !== 'undefined' && currentMount?.version) || null;
  }

  function renderEmpty() {
    elCards.innerHTML = '';
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'plaza-card plaza-card-add plaza-card-empty';
    card.innerHTML = `
      <div class="plaza-add-icon">+</div>
      <div class="plaza-add-title">新建方案</div>
      <div class="plaza-add-desc">配装 → 奇穴秘籍 → 循环 → 保存</div>
    `;
    card.addEventListener('click', onAddClick);
    elCards.appendChild(card);
    elFooter.style.display = 'none';
  }

  // 卡片排序与"隐藏跨心法"状态（持久化到 localStorage）
  const PLAZA_UI_KEY = 'plaza_ui_v1';
  let plazaUI = { sort: 'updated', hideDiffMount: false };
  try { Object.assign(plazaUI, JSON.parse(localStorage.getItem(PLAZA_UI_KEY) || '{}')); } catch {}
  function savePlazaUI() {
    try { localStorage.setItem(PLAZA_UI_KEY, JSON.stringify(plazaUI)); } catch {}
  }
  const elToolbar    = document.getElementById('plaza_toolbar');
  const elSort       = document.getElementById('plaza_sort');
  const elHideDiff   = document.getElementById('plaza_hide_diff_mount');
  if (elSort) {
    elSort.value = plazaUI.sort;
    elSort.addEventListener('change', () => {
      plazaUI.sort = elSort.value; savePlazaUI(); renderCards();
    });
  }
  if (elHideDiff) {
    elHideDiff.checked = !!plazaUI.hideDiffMount;
    elHideDiff.addEventListener('change', () => {
      plazaUI.hideDiffMount = elHideDiff.checked; savePlazaUI(); renderCards();
    });
  }

  function mountLabelOf(m) {
    return m === 'FenShanJin' ? '分山劲' : m === 'TieGuYi' ? '铁骨衣' : (m || '—');
  }

  function sortBuilds(builds, key) {
    const arr = builds.slice();
    switch (key) {
      case 'dps':
        arr.sort((a, b) => (b.snapshot?.dps || -1) - (a.snapshot?.dps || -1));
        break;
      case 'name':
        arr.sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), 'zh'));
        break;
      case 'mount':
        arr.sort((a, b) => mountLabelOf(a.mount).localeCompare(mountLabelOf(b.mount), 'zh')
                         || (b.updated_at || 0) - (a.updated_at || 0));
        break;
      case 'updated':
      default:
        arr.sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0));
    }
    return arr;
  }

  function renderCards() {
    const store = loadStore();
    if (store.builds.length === 0) { renderEmpty(); if (elToolbar) elToolbar.style.display = 'none'; return; }
    if (elToolbar) elToolbar.style.display = '';
    elCards.innerHTML = '';
    const curMount = currentMountKey();
    const curVersion = currentVersionKey();
    // 心法+版本都相同才视为"当前环境"可编辑
    const sameEnv = (b) => (!curMount || b.mount === curMount) && (!b.version || !curVersion || b.version === curVersion);

    // 差异 badge：同环境可见卡里最高 DPS 作为 baseline
    const sameEnvBuilds = store.builds.filter(b => curMount && b.mount === curMount && (!b.version || !curVersion || b.version === curVersion));
    const maxDps = sameEnvBuilds.reduce((m, b) => {
      const d = b.snapshot?.dps;
      return (typeof d === 'number' && d > m) ? d : m;
    }, 0);

    // 应用筛选 + 排序
    let visible = store.builds.slice();
    if (plazaUI.hideDiffMount && curMount) {
      visible = visible.filter(b => sameEnv(b));
    }
    visible = sortBuilds(visible, plazaUI.sort);

    for (const b of visible) {
      const diffMount   = curMount && b.mount && b.mount !== curMount;
      const diffVersion = !diffMount && curVersion && b.version && b.version !== curVersion;
      const diffEnv = diffMount || diffVersion;
      const readOnlyLabel = diffMount ? '心法不符，只读' : (diffVersion ? '版本不符，只读' : '');
      const card = document.createElement('div');
      card.className = 'plaza-card' + (diffEnv ? ' plaza-card-disabled' : '');
      card.dataset.buildId = b.id;

      const dps = b.snapshot?.dps;
      const mountLabel = mountLabelOf(b.mount);
      const versionLabel = b.version_label || '—';

      // 差异 badge（同环境 + 有 DPS + 多卡时计算）
      let diffBadge = '';
      if (!diffEnv && typeof dps === 'number' && maxDps > 0 && sameEnvBuilds.length > 1) {
        if (Math.abs(dps - maxDps) < 0.5) {
          diffBadge = '<span class="plaza-card-diff plaza-card-diff-best" title="当前环境最佳">BEST</span>';
        } else {
          const pct = ((dps - maxDps) / maxDps) * 100;
          diffBadge = `<span class="plaza-card-diff plaza-card-diff-down" title="相对最佳 DPS">${pct.toFixed(1)}%</span>`;
        }
      }

      card.innerHTML = `
        <div class="plaza-card-hd">
          <span class="plaza-card-name" title="${escapeHtml(b.name)}">${escapeHtml(b.name)}</span>
          <span class="plaza-card-mount">${escapeHtml(mountLabel)}</span>
        </div>
        <div class="plaza-card-ver">${escapeHtml(versionLabel)}</div>
        <div class="plaza-card-dps">
          <span class="plaza-card-dps-val">${fmtDps(dps)}</span>
          <span class="plaza-card-dps-unit">DPS</span>
          ${diffBadge}
        </div>
        <div class="plaza-card-meta">
          <span>奇穴 ${Array.isArray(b.talents) ? b.talents.length : 0}</span>
          <span>秘籍 ${Array.isArray(b.recipes) ? b.recipes.length : 0}</span>
          <span class="plaza-card-meta-time">${fmtTs(b.updated_at)}</span>
        </div>
        <div class="plaza-card-actions">
          <button class="sim-btn plaza-btn-edit"  data-action="edit"      ${diffEnv ? 'disabled' : ''}>编辑</button>
          <button class="sim-btn plaza-btn-view"  data-action="view">${diffEnv ? '查看快照' : '概览'}</button>
          <button class="sim-btn plaza-btn-dup"   data-action="duplicate">复制</button>
          <button class="sim-btn plaza-btn-del"   data-action="delete">删除</button>
        </div>
        ${diffEnv ? `<div class="plaza-card-disabled-mask">${readOnlyLabel}</div>` : ''}
      `;

      card.querySelectorAll('button[data-action]').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          onCardAction(btn.dataset.action, b.id);
        });
      });
      elCards.appendChild(card);
    }

    // 末尾添加卡
    const addCard = document.createElement('button');
    addCard.type = 'button';
    addCard.className = 'plaza-card plaza-card-add';
    addCard.innerHTML = `
      <div class="plaza-add-icon">+</div>
      <div class="plaza-add-title">新建方案</div>
    `;
    addCard.addEventListener('click', onAddClick);
    elCards.appendChild(addCard);

    elFooter.style.display = '';
    const hiddenCount = store.builds.length - visible.length;
    elCount.textContent = hiddenCount > 0
      ? `共 ${store.builds.length} 个方案（隐藏 ${hiddenCount} 个跨心法）`
      : `共 ${store.builds.length} 个方案`;
  }

  function onAddClick() {
    enterWizard(null);
  }

  function onCardAction(action, id) {
    if (action === 'delete') {
      const b = PlazaStore.get(id);
      if (!b) return;
      if (!confirm(`删除方案「${b.name}」？此操作不可撤销。`)) return;
      PlazaStore.remove(id);
      renderCards();
      return;
    }
    if (action === 'duplicate') {
      PlazaStore.duplicate(id);
      renderCards();
      return;
    }
    if (action === 'edit') {
      enterWizard(id);
      return;
    }
    if (action === 'view') {
      openSnapshotModal(id);
      return;
    }
  }

  // ═══════════════════════════════════════════════════════════════
  // 只读快照弹窗（Phase 5）
  // ═══════════════════════════════════════════════════════════════
  function openSnapshotModal(id) {
    const b = PlazaStore.get(id);
    if (!b) return;
    document.getElementById('plaza_snapshot_overlay')?.remove();

    const curMount   = currentMountKey();
    const curVersion = currentVersionKey();
    const diffMount   = curMount && b.mount && b.mount !== curMount;
    const diffVersion = !diffMount && curVersion && b.version && b.version !== curVersion;
    const diffEnv = diffMount || diffVersion;
    const mountLabel = mountLabelOf(b.mount);
    const versionLabel = b.version_label || '—';
    const diffLabel = diffMount ? '心法不符' : (diffVersion ? '版本不符' : '');

    const esc = s => escapeHtml(s ?? '');
    const blocks = buildOverviewBlocks(b);
    const snapHTML = b.snapshot
      ? blocks.snapHTML
      : `<div class="pc4-dim">尚未模拟。${diffEnv ? '切换到此心法/版本后可编辑并重算。' : '编辑后在 Step 4 点"重算"。'}</div>`;

    const overlay = document.createElement('div');
    overlay.id = 'plaza_snapshot_overlay';
    overlay.className = 'talent-overlay open';
    overlay.innerHTML = `
      <div class="talent-modal plaza-snapshot-modal">
        <div class="talent-header">
          <span>
            ${esc(b.name)}
            <span class="plaza-snapshot-mount">${esc(mountLabel)} · ${esc(versionLabel)}</span>
            ${diffEnv ? `<span class="plaza-snapshot-cross">${esc(diffLabel)}</span>` : ''}
          </span>
          <button class="talent-close" type="button">&times;</button>
        </div>
        <div class="talent-body">
          <div class="plaza-snapshot-grid">
            <section class="pc4-card">
              <div class="pc4-card-title">⚔️ 配装</div>
              <div class="pc4-card-body">${blocks.equipHTML}</div>
            </section>
            <section class="pc4-card">
              <div class="pc4-card-title">🧠 奇穴秘籍 / 目标 / 延迟</div>
              <div class="pc4-card-body">${blocks.trHTML}</div>
            </section>
            <section class="pc4-card">
              <div class="pc4-card-title">🔁 循环</div>
              <div class="pc4-card-body">${blocks.rotHTML}</div>
            </section>
            <section class="pc4-card pc4-card-dps">
              <div class="pc4-card-title">📊 模拟结果</div>
              <div class="pc4-card-body">${snapHTML}</div>
            </section>
            <section class="pc4-card pc4-card-stats">
              <div class="pc4-card-title">🔥 战斗统计（按技能伤害）</div>
              <div class="pc4-card-body">${b.snapshot ? blocks.statsHTML : '<div class="pc4-dim">—</div>'}</div>
            </section>
          </div>
        </div>
        <div class="equip-picker-actions">
          <button class="sim-btn" id="ps_close">关闭</button>
          <span class="equip-picker-spacer"></span>
          ${diffEnv ? '' : `<button class="sim-btn" id="ps_send_a" title="用此方案的环境进入循环蒸馏工作流">发送到循环蒸馏</button>`}
          <button class="sim-btn" id="ps_dup">复制为新方案</button>
          ${diffEnv
            ? `<button class="sim-btn primary" id="ps_switch_mount">切换到 ${esc(mountLabel)} · ${esc(versionLabel)} 并编辑</button>`
            : `<button class="sim-btn primary" id="ps_edit">编辑</button>`}
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const close = () => overlay.remove();
    overlay.querySelector('.talent-close').addEventListener('click', close);
    overlay.querySelector('#ps_close').addEventListener('click', close);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
    overlay.querySelector('#ps_dup')?.addEventListener('click', () => {
      PlazaStore.duplicate(id);
      close();
      renderCards();
    });
    overlay.querySelector('#ps_edit')?.addEventListener('click', () => {
      close();
      enterWizard(id);
    });
    overlay.querySelector('#ps_send_a')?.addEventListener('click', () => {
      if (!window.Jx3WorkflowA?.enterWithDraft) { alert('循环蒸馏工作流未加载'); return; }
      // 方案本身就可当 draft（结构兼容 snapshotSimStateAsDraft）
      window.Jx3WorkflowA.enterWithDraft(b);
      close();
    });
    overlay.querySelector('#ps_switch_mount')?.addEventListener('click', async () => {
      await switchMountAndEdit(b);
      close();
    });
  }

  // 跨心法 / 跨版本：切换到方案对应的 (version, mount) 后进入向导编辑
  async function switchMountAndEdit(b) {
    if (!b || !b.mount) return;
    if (typeof currentMount === 'undefined' || !currentMount) {
      alert('心法状态未就绪');
      return;
    }
    // 优先用 build 的 version，没有则保留当前
    const target = {
      version: b.version || currentMount.version,
      mount: b.mount,
    };
    if (target.mount === currentMount.mount && target.version === currentMount.version) {
      enterWizard(b.id); return;
    }
    const targetLabel = `${mountLabelOf(b.mount)} · ${b.version_label || '—'}`;
    const confirmMsg = `方案 ${b.name} 属于 ${targetLabel}。\n切换环境会清空当前奇穴/秘籍选择，是否继续？`;
    if (!confirm(confirmMsg)) return;
    try {
      const r = await fetch('/api/mounts/switch', {
        method: 'POST', headers: {'Content-Type':'application/json'},
        body: JSON.stringify(target),
      });
      const data = await r.json();
      if (!data.ok) { alert('切换失败：' + (data.error || 'unknown')); return; }
      try { localStorage.setItem('mount_choice', JSON.stringify(target)); } catch {}
      // 直接刷新整页（最稳的做法，和顶栏心法切换一致）
      location.reload();
    } catch (e) {
      alert('切换失败：' + e.message);
    }
  }

  function refreshMountLabel() {
    if (elMount) elMount.textContent = currentMountLabel();
  }

  function onPageEnter() {
    refreshMountLabel();
    renderCards();
  }

  // 监听 page-plaza 获得 active class 时刷新
  new MutationObserver(() => {
    if (page.classList.contains('active')) onPageEnter();
  }).observe(page, { attributes: true, attributeFilter: ['class'] });

  // 初次若已是 active
  if (page.classList.contains('active')) onPageEnter();

  // ═══════════════════════════════════════════════════════════════
  // sim-toolbar 新入口：[配装] 按钮 + [发送到 ▾] 下拉
  // ═══════════════════════════════════════════════════════════════

  function countSlots(cfg) {
    if (!cfg || !cfg.slots) return 0;
    return Object.values(cfg.slots).filter(s => s && s.equip_id).length;
  }
  function mountLabel(m) {
    return m === 'FenShanJin' ? '分山劲' : m === 'TieGuYi' ? '铁骨衣' : (m || '—');
  }

  async function openEquipPickerModal(opts = {}) {
    const fromEquipPage = !!opts.fromEquipPage;
    document.getElementById('plaza_equip_picker_overlay')?.remove();

    const overlay = document.createElement('div');
    overlay.id = 'plaza_equip_picker_overlay';
    overlay.className = 'talent-overlay open';

    // 左侧列表 + 右侧预览面板
    overlay.innerHTML = `
      <div class="talent-modal equip-picker-modal" style="min-width:840px;max-width:1080px">
        <div class="talent-header">
          <span>加载配装</span>
          <button class="talent-close" type="button">&times;</button>
        </div>
        <div class="talent-body" style="display:flex;gap:12px">
          <div id="ep_body" style="flex:1.2;min-width:0;max-height:560px;overflow:auto">
            <div class="equip-picker-empty">正在加载…</div>
          </div>
          <div id="ep_preview" style="flex:1;min-width:0;border-left:1px solid var(--border-soft);padding-left:12px;font-size:12px;max-height:560px;overflow:auto">
            <div style="color:var(--text-muted);text-align:center;padding:30px 6px">点击左侧某行查看预览</div>
          </div>
        </div>
        <div class="equip-picker-actions">
          <button class="sim-btn" id="ep_cancel">取消</button>
          <button class="sim-btn" id="ep_import_json" title="粘贴 / 选文件导入；自动识别本项目 / jx3box / 在线库 3 种格式">从 JSON 导入…</button>
          <span class="equip-picker-spacer"></span>
          <button class="sim-btn" id="ep_apply_full" disabled title="方案文件可用：同时载入配装 + 奇穴 + 秘籍 + 目标 + 延迟 + 循环">载入整个方案</button>
          <button class="sim-btn" id="ep_apply" disabled>应用配装</button>
          <button class="sim-btn primary" id="ep_goto" disabled>${fromEquipPage ? '应用（留在本页）' : '应用并跳转配装器'}</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const close = () => overlay.remove();
    overlay.querySelector('.talent-close')?.addEventListener('click', close);
    overlay.querySelector('#ep_cancel')?.addEventListener('click', close);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
    // 智能 JSON 导入：关掉本弹窗 → 子窗输入 JSON → _smartImportEquipmentText 自动嗅探格式
    overlay.querySelector('#ep_import_json')?.addEventListener('click', () => {
      close();
      _openEquipSmartImportModal();
    });

    // 异步并行取两个来源
    const [files, builds] = await Promise.all([
      window.Jx3Equip?.listConfigs?.() || [],
      Promise.resolve(PlazaStore.list()),
    ]);

    const body       = overlay.querySelector('#ep_body');
    const previewEl  = overlay.querySelector('#ep_preview');
    body.innerHTML = renderPickerBody(files, builds);

    // 行选中
    const applyBtn = overlay.querySelector('#ep_apply');
    const gotoBtn  = overlay.querySelector('#ep_goto');
    const applyFullBtn = overlay.querySelector('#ep_apply_full');
    // PRIMARY 按钮在不同行类型下切换：build 行优先 ep_apply_full（载入整个方案），其它优先 ep_goto
    const setPrimary = (which) => {
      [applyBtn, applyFullBtn, gotoBtn].forEach(b => b?.classList.remove('primary'));
      which?.classList.add('primary');
    };
    const updateButtonsForRow = (row) => {
      // 默认全禁用
      [applyBtn, applyFullBtn, gotoBtn].forEach(b => { if (b) b.disabled = true; });
      if (!row) { setPrimary(gotoBtn); return; }
      const src = row.dataset.source;
      if (src === 'build') {
        const build = PlazaStore.get(row.dataset.id);
        const mountMismatch = build?.mount && currentMountKey() && build.mount !== currentMountKey();
        applyFullBtn.disabled = !!mountMismatch;
        applyFullBtn.title = mountMismatch
          ? `方案心法（${mountLabel(build.mount)}）与当前不符，切心法后再载入`
          : '载入配装 + 奇穴 + 秘籍 + 目标 + 延迟 + 循环 全套';
        applyBtn.disabled = false;
        applyBtn.title = '仅应用配装（不动奇穴/秘籍/循环）— 一般用「载入整个方案」更全';
        gotoBtn.disabled = false;
        // build 行：应用整个方案是首选
        setPrimary(mountMismatch ? gotoBtn : applyFullBtn);
      } else if (src === 'file') {
        applyFullBtn.disabled = true;
        applyFullBtn.title = '独立配装文件只含装备信息，无法载入整个方案';
        applyBtn.disabled = false;
        applyBtn.title = '应用此配装文件（仅装备）';
        gotoBtn.disabled = false;
        setPrimary(gotoBtn);
      } else if (src === 'current') {
        // current 行：apply 是无操作 (config 已经是当前)。隐藏 apply 与 apply_full，仅留 goto（跳页）
        applyFullBtn.disabled = true;
        applyFullBtn.title = '当前配装已生效，无方案数据可载入';
        applyBtn.disabled = true;
        applyBtn.title = '当前配装已生效，无需重新应用';
        gotoBtn.disabled = false;
        gotoBtn.title = fromEquipPage ? '已在配装器页' : '跳转到配装器页';
        setPrimary(gotoBtn);
      }
    };
    // ── 预览：装备列表 + 属性面板 ───────────────────────────────────────
    // POS_LABEL / POS_TO_SUB 用顶层全局
    async function fetchEquipName(subType, id) {
      try {
        const r = await fetch('/api/equip/detail', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id, sub_type: subType }),
        });
        const j = r.ok ? await r.json() : null;
        return j?.detail?.name || `#${id}`;
      } catch { return `#${id}`; }
    }
    let _previewToken = 0;
    async function renderPreview(source, payload) {
      const myToken = ++_previewToken;
      previewEl.innerHTML = `<div style="color:var(--text-muted);padding:10px">加载中…</div>`;

      // 1. 解析 equipment + 额外字段
      let equipment = null, mountKey = null, label = '', extra = null;
      if (source === 'file') {
        try {
          const cfg = await window.Jx3Equip.loadConfig(payload.file);
          if (myToken !== _previewToken) return;
          equipment = { slots: cfg.slots || {}, stoneId: cfg.stone_id || 0, stoneName: cfg.stone_name || '' };
          mountKey  = cfg.mount || null;
          label     = payload.label || payload.file;
        } catch (e) {
          previewEl.innerHTML = `<div style="color:var(--red);padding:10px">加载失败：${escapeHtml(e.message)}</div>`;
          return;
        }
      } else if (source === 'build') {
        const b = PlazaStore.get(payload.id);
        if (!b) { previewEl.innerHTML = `<div style="color:var(--red);padding:10px">方案已丢失</div>`; return; }
        equipment = b.equipment || null;
        mountKey  = b.mount || null;
        label     = b.name || '(未命名方案)';
        const _talentIds = b.talents || [];
        const _recipeIds = Array.isArray(b.recipes) ? b.recipes : [];
        extra = {
          talents: _talentIds.length,
          recipes: _recipeIds.length,
          talentIds: _talentIds,
          recipeIds: _recipeIds,
          target: b.target,
          duration: b.rotation?.macro_duration,
          delay: b.rotation?.delay,
          initial_rage: b.rotation?.initial_rage,
          boss_attack_interval: b.rotation?.boss_attack_interval,
          sequence_n: Array.isArray(b.rotation?.sequence) ? b.rotation.sequence.length : 0,
          sequence: b.rotation?.sequence || [],
          macro_chars: (() => {
            const m = b.rotation?.macro;
            if (!m) return 0;
            if (typeof m === 'string') return m.length;
            return (m.general || '').length + (m.shield || '').length + (m.blade || '').length;
          })(),
          macro: b.rotation?.macro,
        };
      } else if (source === 'current') {
        equipment = window.Jx3Equip?.getCurrentConfig?.() || null;
        mountKey  = (typeof currentMountKey === 'function') ? currentMountKey() : null;
        label     = '当前配装';
      }
      if (!equipment) { previewEl.innerHTML = `<div style="color:var(--text-muted);padding:10px">无装备数据</div>`; return; }

      // 2. 装备清单（异步拉名字，先占位 #id）
      const slots = equipment.slots || {};
      const POS_ORDER = ['HAT','JACKET','BELT','WRIST','BOTTOMS','SHOES','NECKLACE','PENDANT','RING_1','RING_2','PRIMARY_WEAPON','SECONDARY_WEAPON'];
      const eqLines = POS_ORDER.map(pos => {
        const s = slots[pos];
        if (!s?.equip_id) return '';
        const cached = s.name || `#${s.equip_id}`;
        return `<div class="ep-prv-row" data-pos="${pos}" data-eq-id="${s.equip_id}">
          <span class="ep-prv-pos">${POS_LABEL[pos] || pos}</span>
          <span class="ep-prv-name">${escapeHtml(cached)}</span>
        </div>`;
      }).filter(Boolean).join('');
      const stoneLine = equipment.stoneId
        ? `<div class="ep-prv-row"><span class="ep-prv-pos">五彩石</span><span class="ep-prv-name">${escapeHtml(equipment.stoneName || `#${equipment.stoneId}`)}</span></div>`
        : '';

      // extra 信息（仅方案）— 每个 value 单元有 data-prv-info 属性，render 后绑 hover
      const cell = (key, html) => `<span class="ep-prv-extra" data-prv-info="${key}">${html}</span>`;
      const extraBlock = extra ? `
        <div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--border-soft);display:grid;grid-template-columns:auto 1fr;gap:3px 10px;color:var(--text)">
          <span style="color:var(--text-muted)">奇穴/秘籍</span>${cell('talents_recipes', `${extra.talents} / ${extra.recipes}`)}
          ${extra.target ? `<span style="color:var(--text-muted)">目标</span>${cell('target', `Lv${extra.target.level} 防御加成 ${extra.target.defense_bonus ?? 0}`)}` : ''}
          ${extra.duration != null ? `<span style="color:var(--text-muted)">时长</span>${cell('duration', extra.duration + 's')}` : ''}
          ${extra.delay != null ? `<span style="color:var(--text-muted)">网络延迟</span>${cell('delay', extra.delay + ' ms')}` : ''}
          ${extra.boss_attack_interval ? `<span style="color:var(--text-muted)">Boss 间隔</span>${cell('boss', extra.boss_attack_interval + 's')}` : ''}
          <span style="color:var(--text-muted)">序列</span>${cell('sequence', extra.sequence_n + ' 项')}
          <span style="color:var(--text-muted)">宏文本</span>${cell('macro', extra.macro_chars + ' 字符')}
        </div>
      ` : '';

      previewEl.innerHTML = `
        <div style="color:var(--gold);font-weight:600;font-size:13px;margin-bottom:6px">${escapeHtml(label)}${mountKey ? ` <span style="color:var(--text-muted);font-weight:400;font-size:11px">· ${escapeHtml(mountLabel(mountKey))}</span>` : ''}</div>
        <div id="ep_prv_panel" style="margin-bottom:10px;padding:6px 8px;background:rgba(0,0,0,0.18);border-radius:4px;color:var(--text-muted)">面板加载中…</div>
        <div class="ep-prv-eq">${eqLines || '<div style="color:var(--text-muted);padding:8px">无装备</div>'}${stoneLine}</div>
        ${extraBlock}
      `;

      // 3. 异步补装备名（如配装文件没 hydrated）+ 绑装备 hover
      // anchor 锁修 race：mouseenter 内 await 期间用户已 mouseleave 时不要 show（否则永不消失）
      let _epHoverAnchor = null;
      const rows = previewEl.querySelectorAll('.ep-prv-row[data-eq-id]');
      rows.forEach(async row => {
        const pos = row.dataset.pos;
        const id = parseInt(row.dataset.eqId, 10);
        const subType = POS_TO_SUB[pos];
        const slot = slots[pos];
        if (!slot?.name) {
          const nm = await fetchEquipName(subType, id);
          if (myToken !== _previewToken) return;
          const nameEl = row.querySelector('.ep-prv-name');
          if (nameEl) nameEl.textContent = nm;
        }
        // 装备 hover：复用 Jx3Equip.buildItemTooltip + 全局 showTooltip
        // 同方案整套 slots 作为算"已穿件数"的上下文
        row.style.cursor = 'help';
        row.addEventListener('mouseenter', async () => {
          _epHoverAnchor = row;
          try {
            const html = await window.Jx3Equip?.buildItemTooltip?.(pos, slot, { stoneName: equipment.stoneName, contextSlots: slots });
            if (_epHoverAnchor !== row) return;   // 已离开此 row（含切到别的 row 也算离开）
            if (html) showTooltip(row, html);
          } catch {}
        });
        row.addEventListener('mouseleave', () => {
          _epHoverAnchor = null;
          hideTooltip();
        });
      });

      // 3.5 Extra 信息 hover：奇穴/秘籍/目标/时长/延迟/Boss/序列/宏文本
      if (extra) {
        const buildExtraTooltip = (key) => {
          const esc = escapeHtml;
          const sec = (title, body) => `<div class="lt-section"><div class="lt-title">${esc(title)}</div>${body}</div>`;
          const dim = txt => `<div class="lt-dim">${esc(txt)}</div>`;
          const wrap = body => `<div class="log-tooltip" style="max-width:480px">${body}</div>`;
          if (key === 'talents_recipes') {
            // 奇穴
            const tNames = (extra.talentIds || []).map(id => {
              const t = (typeof talentList !== 'undefined') ? talentList.find(x => x.id === id) : null;
              return t ? `${esc(t.name)} <span style="color:var(--text-muted)">#${id}</span>`
                       : `<span style="color:var(--text-muted)">#${id}</span>`;
            });
            // 秘籍按 skill 分组
            const groups = new Map();
            for (const id of (extra.recipeIds || [])) {
              const r = (typeof recipeList !== 'undefined') ? recipeList.find(x => x.id === id) : null;
              const k = r?.skill || '其它';
              if (!groups.has(k)) groups.set(k, []);
              groups.get(k).push(r ? `${esc(r.name)}` : `<span style="color:var(--text-muted)">#${id}</span>`);
            }
            const tBody = tNames.length
              ? `<div style="display:flex;flex-direction:column;gap:2px">${tNames.map(n => '<div>' + n + '</div>').join('')}</div>`
              : dim('（无）');
            const rBody = groups.size
              ? `<div style="display:flex;flex-direction:column;gap:4px">${
                  [...groups.entries()].map(([sk, list]) =>
                    `<div><span style="color:var(--text-muted)">${esc(sk)}：</span>${list.join('、')}</div>`
                  ).join('')
                }</div>`
              : dim('（无）');
            return wrap(sec(`奇穴 (${extra.talents})`, tBody) + sec(`秘籍 (${extra.recipes})`, rBody));
          }
          if (key === 'target') {
            const t = extra.target || {};
            return wrap(sec('目标', `<div>等级 Lv${t.level ?? '-'}</div><div>防御加成 ${t.defense_bonus ?? 0}%</div>${dim('防御参数随等级自动查表（target_base_defense / defense_level_param）')}`));
          }
          if (key === 'duration') {
            return wrap(sec('模拟时长', `<div>${extra.duration}s</div>${dim('宏循环模拟运行时长（macro_duration）')}`));
          }
          if (key === 'delay') {
            return wrap(sec('网络延迟', `<div>${extra.delay} ms</div>${dim('每次主 GCD 之后的延迟补偿（首个 GCD 不计）')}`));
          }
          if (key === 'boss') {
            return wrap(sec('Boss 攻击间隔', `<div>${extra.boss_attack_interval}s</div>${dim('用于坚铁/寒甲期望传播子系统计算 Boss 受击频率')}`));
          }
          if (key === 'sequence') {
            const seq = extra.sequence || [];
            if (seq.length === 0) return wrap(sec('手动序列', dim('（空 — 走宏循环）')));
            const lines = seq.slice(0, 30).map((e, i) => {
              if (e.type === 'macro') return `${i+1}. <span style="color:var(--gold)">[宏]</span>` + (e.count > 1 ? ` ×${e.count}` : '');
              if (e.type === 'wait_stance') return `${i+1}. <span style="color:var(--text-muted)">[等待切体态]</span>`;
              if (e.type === 'wait_zhan_jue') return `${i+1}. <span style="color:var(--text-muted)">[战绝回怒]</span>`;
              if (e.type === 'break') return `${i+1}. <span style="color:var(--text-muted)">— 中断 —</span>`;
              if (e.type === 'skill') return `${i+1}. ${esc(e.skill || '?')}` + (e.count > 1 ? ` ×${e.count}` : '');
              return `${i+1}. ${esc(JSON.stringify(e))}`;
            });
            const more = seq.length > 30 ? `<div style="color:var(--text-muted);margin-top:4px">… 共 ${seq.length} 项，仅显示前 30</div>` : '';
            return wrap(sec(`手动序列 (${seq.length})`, `<div style="display:flex;flex-direction:column;gap:1px;font-size:11px">${lines.join('')}</div>${more}`));
          }
          if (key === 'macro') {
            const m = extra.macro;
            if (!m) return wrap(sec('宏文本', dim('（无）')));
            if (typeof m === 'string') {
              const truncated = m.length > 1500 ? m.slice(0, 1500) + '\n…' : m;
              return wrap(sec('宏文本', `<pre style="white-space:pre-wrap;font-size:11px;margin:0;color:var(--text)">${esc(truncated)}</pre>`));
            }
            const blocks = [];
            if (m.general) blocks.push(`<div style="color:var(--text-muted);font-size:11px;margin-bottom:2px">通用</div><pre style="white-space:pre-wrap;font-size:11px;margin:0 0 6px 0;color:var(--text)">${esc(m.general.length > 800 ? m.general.slice(0, 800) + '\n…' : m.general)}</pre>`);
            if (m.shield) blocks.push(`<div style="color:var(--text-muted);font-size:11px;margin-bottom:2px">擎盾</div><pre style="white-space:pre-wrap;font-size:11px;margin:0 0 6px 0;color:var(--text)">${esc(m.shield.length > 800 ? m.shield.slice(0, 800) + '\n…' : m.shield)}</pre>`);
            if (m.blade)  blocks.push(`<div style="color:var(--text-muted);font-size:11px;margin-bottom:2px">擎刀</div><pre style="white-space:pre-wrap;font-size:11px;margin:0 0 6px 0;color:var(--text)">${esc(m.blade.length > 800 ? m.blade.slice(0, 800) + '\n…' : m.blade)}</pre>`);
            return wrap(sec('宏文本（多页）', blocks.length ? blocks.join('') : dim('（空）')));
          }
          return '';
        };
        // 确保 talentList / recipeList 已加载（异步）
        if ((typeof talentList === 'undefined' || talentList.length === 0) && typeof initTalentModal === 'function') {
          initTalentModal().catch(() => {});
        }
        if ((typeof recipeList === 'undefined' || recipeList.length === 0) && typeof initRecipeModal === 'function') {
          initRecipeModal().catch(() => {});
        }
        previewEl.querySelectorAll('.ep-prv-extra[data-prv-info]').forEach(el => {
          el.style.cursor = 'help';
          el.addEventListener('mouseenter', () => {
            const html = buildExtraTooltip(el.dataset.prvInfo);
            if (html) showTooltip(el, html);
          });
          el.addEventListener('mouseleave', hideTooltip);
        });
      }

      // 4. 异步算面板属性（用 calculatePanel）
      try {
        const slotsForCalc = JSON.parse(JSON.stringify(slots));
        // 默认 talents/recipes 用当前页面（避免 calculate 报错；最终 applyConfig 时会覆盖）
        const tlts = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
        // 心法 ID 派生
        let mountId = null;
        if (mountKey === 'FenShanJin') mountId = 10390;
        else if (mountKey === 'TieGuYi') mountId = 10389;
        else if (typeof getCurrentMountId === 'function') mountId = getCurrentMountId();
        const resp = await window.Jx3Equip?.calculatePanel?.(slotsForCalc, equipment.stoneId || 0, mountId, tlts);
        if (myToken !== _previewToken) return;
        if (!resp?.panel) return;
        const p = resp.panel;
        const r = resp.raw || {};
        const num = v => Math.round(v || 0).toLocaleString();
        const pct = v => ((v || 0) * 100).toFixed(2) + '%';
        const isTiegu = mountKey === 'TieGuYi';
        // 行带 data-attr-key，hover 通过全局 jx3BuildAttrTooltip 显示等级 / 公式
        const cells = [
          ['atk',      '攻击', num(p.physics_attack_power)],
          ['crit',     '会心', pct(p.crit_rate)],
          ['crit_eff', '会效', pct(p.crit_effect)],
          ['oc',       '破防', pct(p.overcome_rate)],
          ['strain',   '无双', pct(p.strain_rate)],
          ['haste',    '加速', pct(p.haste_rate)],
          ['surplus',  '破招', num(p.surplus_value)],
          ['hp',       '气血', num(p.max_life)],
        ];
        if (isTiegu) {
          cells.push(
            ['parry',     '招架', pct(p.parry_rate)],
            ['parry_val', '拆招', num(p.parry_value)],
            ['pshield',   '外防', pct(p.physics_shield_rate)],
            ['mshield',   '内防', pct(p.magic_shield_rate)],
          );
        }
        const panelHtml = cells.map(([key, k, v]) =>
          `<div class="ep-prv-attr" data-attr-key="${key}" style="display:flex;justify-content:space-between;font-size:11px;cursor:help"><span style="color:var(--text-muted)">${k}</span><b style="color:var(--text)">${v}</b></div>`
        ).join('');
        const panel = previewEl.querySelector('#ep_prv_panel');
        if (panel) {
          panel.innerHTML = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:2px 14px">${panelHtml}</div>`;
          // hover：复用全局 helper（与配装器/wzc 结果卡/wzc 候选预览一致）
          panel.querySelectorAll('.ep-prv-attr[data-attr-key]').forEach(cell => {
            const key = cell.dataset.attrKey;
            cell.addEventListener('mouseenter', () => {
              const html = jx3BuildAttrTooltip(key, r, p);
              if (html) showTooltip(cell, html);
            });
            cell.addEventListener('mouseleave', hideTooltip);
          });
        }
      } catch (e) {
        const panel = previewEl.querySelector('#ep_prv_panel');
        if (panel) panel.textContent = '面板计算失败：' + e.message;
      }
    }
    const bindRowSelect = () => {
      body.querySelectorAll('.ep-row[data-pickable="1"]').forEach(row => {
        row.addEventListener('click', (e) => {
          if (e.target.closest('button[data-row-action]')) return;  // 行内按钮走自己的事件
          body.querySelectorAll('.ep-row.selected').forEach(r => r.classList.remove('selected'));
          row.classList.add('selected');
          updateButtonsForRow(row);
          // 触发预览
          const src = row.dataset.source;
          if (src === 'file') {
            const file = row.dataset.file;
            const nameCell = row.querySelector('.ep-cell-name');
            renderPreview('file', { file, label: nameCell?.textContent || file });
          } else if (src === 'build') {
            renderPreview('build', { id: row.dataset.id });
          } else if (src === 'current') {
            renderPreview('current', {});
          }
        });
      });
    };
    bindRowSelect();
    // 删除（仅独立配装行有）
    body.querySelectorAll('button[data-row-action="delete"]').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        e.stopPropagation();
        const file = btn.dataset.file;
        if (!confirm(`删除独立配装「${btn.dataset.name || file}」？`)) return;
        const r = await window.Jx3Equip?.deleteConfig?.(file);
        if (r?.ok === false) { alert('删除失败：' + (r.error || '')); return; }
        // 重新加载
        const newFiles = await window.Jx3Equip?.listConfigs?.() || [];
        body.innerHTML = renderPickerBody(newFiles, PlazaStore.list());
        updateButtonsForRow(null);
        bindRowSelect();
      });
    });

    async function resolvePickedConfig() {
      const picked = body.querySelector('.ep-row.selected');
      if (!picked) { alert('请选择一行'); return null; }
      const src = picked.dataset.source;
      if (src === 'file') {
        try {
          const cfg = await window.Jx3Equip.loadConfig(picked.dataset.file);
          return { slots: cfg.slots || {}, stoneId: cfg.stone_id || 0, stoneName: cfg.stone_name || '' };
        } catch (e) { alert('加载失败：' + e.message); return null; }
      }
      if (src === 'build') {
        const b = PlazaStore.get(picked.dataset.id);
        return b?.equipment || null;
      }
      if (src === 'current') {
        return window.Jx3Equip?.getCurrentConfig?.() || null;
      }
      return null;
    }
    applyBtn?.addEventListener('click', async () => {
      const cfg = await resolvePickedConfig();
      if (!cfg) return;
      await window.Jx3Equip?.applyConfig?.(cfg);
      close();
    });
    gotoBtn?.addEventListener('click', async () => {
      const cfg = await resolvePickedConfig();
      if (!cfg) return;
      await window.Jx3Equip?.applyConfig?.(cfg);
      close();
      if (!fromEquipPage) window.Jx3Equip?.openPage?.();
    });

    // 载入整个方案：仅方案行可用 —— 配装 + 奇穴 + 秘籍 + 目标 + 延迟 + 循环 全套
    applyFullBtn?.addEventListener('click', async () => {
      const picked = body.querySelector('.ep-row.selected');
      if (!picked || picked.dataset.source !== 'build') return;
      const build = PlazaStore.get(picked.dataset.id);
      if (!build) { alert('方案已丢失'); return; }
      try {
        if (build.equipment) await window.Jx3Equip?.applyConfig?.(build.equipment);
        try { await ensureTalentRecipeLists(); } catch {}
        applyTalentsFromArray(build.talents || []);
        applyRecipesFromArray(build.recipes || []);
        if (build.target) {
          const lvl = document.getElementById('target_level');
          const def = document.getElementById('target_defense_bonus');
          if (lvl && build.target.level != null) {
            lvl.value = build.target.level;
            lvl.dispatchEvent(new Event('change', { bubbles: true }));
          }
          if (def && build.target.defense_bonus != null) def.value = build.target.defense_bonus;
        }
        if (build.rotation && typeof applyLoopConfig === 'function') {
          const cfg = {
            version: (typeof LOOP_CONFIG_VERSION !== 'undefined') ? LOOP_CONFIG_VERSION : 1,
            sequence: build.rotation.sequence || [],
            macro: build.rotation.macro || {},
            network_delay: build.rotation.delay,
            initial_rage: build.rotation.initial_rage,
            macro_duration: build.rotation.macro_duration,
            boss_attack_interval: build.rotation.boss_attack_interval,
            target: build.target || undefined,
          };
          // 异常前提下序列不会重建 → 弹窗给用户看，而不是 console.warn 静默
          try { applyLoopConfig(cfg); }
          catch (e) {
            console.warn('applyLoopConfig', e);
            alert('循环配置应用失败：' + e.message + '\n（装备/奇穴/秘籍已应用，仅循环序列未更新）');
          }
        }
        close();
        // 没在 page-sim 时切过去，方便用户立刻看到结果
        if (typeof Jx3Nav?.switchPage === 'function') {
          if (document.getElementById('page-sim')?.classList.contains('active') !== true) {
            Jx3Nav.switchPage('page-sim');
          }
        }
      } catch (e) {
        alert('载入失败：' + e.message);
      }
    });
  }

  function renderPickerBody(files, builds) {
    const esc = (s) => escapeHtml(s ?? '');
    let html = '';

    // ── 独立配装文件 ──
    html += '<div class="equip-picker-section-title">独立配装文件</div>';
    html += '<table class="equip-picker-table">';
    html += '<thead><tr><th>文件名</th><th>创建时间</th><th>概览</th><th></th></tr></thead>';
    html += '<tbody>';
    // 行 0：当前配装（未保存/实时状态）
    const current = window.Jx3Equip?.getCurrentConfig?.();
    const curCount = countSlots(current);
    html += `<tr class="ep-row ep-row-current" data-source="current" data-pickable="${curCount > 0 ? 1 : 0}">
      <td><span class="ep-cell-name">当前配装</span><span class="ep-cell-tag">未保存</span></td>
      <td class="ep-cell-dim">—</td>
      <td>${mountLabel((typeof currentMount !== 'undefined' && currentMount?.mount) || '')} · ${curCount} 件</td>
      <td></td>
    </tr>`;
    if (files.length === 0) {
      html += `<tr class="ep-row-empty"><td colspan="4">暂无已保存的独立配装文件。在配装器页面点「另存为…」保存后会出现在这里。</td></tr>`;
    } else {
      for (const f of files) {
        html += `<tr class="ep-row" data-source="file" data-pickable="1" data-file="${esc(f.file)}">
          <td><span class="ep-cell-name">${esc(f.name || f.file)}</span></td>
          <td class="ep-cell-dim">${fmtTs(f.created_at || f.updated_at)}</td>
          <td>${mountLabel(f.mount)} · ${f.slot_count || 0} 件</td>
          <td><button class="sim-btn sim-btn-xs" data-row-action="delete" data-file="${esc(f.file)}" data-name="${esc(f.name || f.file)}">删除</button></td>
        </tr>`;
      }
    }
    html += '</tbody></table>';

    // ── 方案文件 ──
    html += '<div class="equip-picker-section-title" style="margin-top:14px">方案文件</div>';
    html += '<table class="equip-picker-table">';
    html += '<thead><tr><th>文件名</th><th>创建时间</th><th>概览</th><th></th></tr></thead>';
    html += '<tbody>';
    if (builds.length === 0) {
      html += `<tr class="ep-row-empty"><td colspan="4">暂无方案。在战斗广场新建方案后会出现在这里。</td></tr>`;
    } else {
      for (const b of builds) {
        const slotN = countSlots(b.equipment);
        html += `<tr class="ep-row" data-source="build" data-pickable="${slotN > 0 ? 1 : 0}" data-id="${esc(b.id)}">
          <td><span class="ep-cell-name">${esc(b.name)}</span></td>
          <td class="ep-cell-dim">${fmtTs(b.created_at)}</td>
          <td>${mountLabel(b.mount)} · ${slotN} 件</td>
          <td></td>
        </tr>`;
      }
    }
    html += '</tbody></table>';
    return html;
  }

  // 对外暴露（配装器页 [加载…] 按钮调）
  PlazaStore.openPickerModal = openEquipPickerModal;
  window.Jx3Plaza.openPickerModal = openEquipPickerModal;

  document.getElementById('btn_equip_picker')?.addEventListener('click', () => openEquipPickerModal());

  // ── 发送到 A / C ──
  /** 收集 page-sim 当前完整状态 → 生成 plaza draft（未命名、未含 snapshot）
   *  口径与 C 向导 Step 3 commit 一致：rotation 走 buildLoopConfig，含 sequence/macro/delay/initial_rage/boss_attack_interval/macro_duration
   */
  function snapshotSimStateAsDraft() {
    const equipment = window.Jx3Equip?.getCurrentConfig?.() || null;
    const talents = (typeof getSelectedTalents === 'function') ? getSelectedTalents() : [];
    const recipes = (typeof getSelectedRecipes === 'function') ? getSelectedRecipes() : [];
    const attrs   = (typeof getAttrs === 'function') ? getAttrs() : null;
    let target    = (typeof getTarget === 'function') ? getTarget() : null;

    let rotation = {
      sequence: [],
      macro: {},
      delay: parseInt(document.getElementById('sim_delay')?.value || '0') || 0,
    };
    try {
      const cfg = (typeof buildLoopConfig === 'function') ? buildLoopConfig() : null;
      if (cfg) {
        rotation = {
          sequence: cfg.sequence || [],
          macro: cfg.macro || {},
          delay: cfg.network_delay || 0,
          initial_rage: cfg.initial_rage,
          macro_duration: cfg.macro_duration,
          boss_attack_interval: cfg.boss_attack_interval,
        };
        if (cfg.target) target = cfg.target;
      }
    } catch (e) { console.warn('snapshotSimStateAsDraft buildLoopConfig', e); }

    return {
      id: null,
      name: PlazaStore.nextDefaultName(),
      mount: currentMountKey(),
      mount_label: currentMountLabel(),
      version: currentVersionKey(),
      version_label: currentVersionLabel(),
      equipment,
      talents: Array.isArray(talents) ? talents : [],
      recipes,
      rotation,
      attributes: attrs,
      target,
      snapshot: null,
      confirmedSave: false,
    };
  }

  function sendToC() {
    const draft = snapshotSimStateAsDraft();
    if (!window.Jx3PlazaWizard) { alert('广场向导未加载'); return; }
    // 进向导，用预填 draft，走 doGoToStep(4) 以正确触发 renderOverview + 自动快照
    wizardState = {
      draft,
      currentStep: 1,  // 临时；doGoToStep 会覆盖
      editingId: null,
      returnTo: 'page-sim',
    };
    document.body.classList.add('wizard-mode');
    wzShell?.setAttribute('aria-hidden', 'false');
    renderWizardShell();
    doGoToStep(4);
  }

  function sendToA() {
    if (!window.Jx3WorkflowA?.enterWithDraft) {
      alert('循环蒸馏工作流未加载');
      return;
    }
    // 新鲜度检测：lastSimResult 的指纹应和当前输入一致，否则 A-4 载入的是旧 timeline
    const curHash = (typeof computeLoopInputsHash === 'function') ? computeLoopInputsHash() : '';
    const lastHash = (typeof lastSimResult !== 'undefined' && lastSimResult) ? lastSimResult._configHash : null;
    const hasLast = !!(lastSimResult && Array.isArray(lastSimResult.timeline) && lastSimResult.timeline.length);
    if (!hasLast) {
      if (!confirm('还没有模拟结果。继续发送到循环蒸馏？\n\n（进入后需要先在 Step 3 跑一次模拟再载入 timeline）')) return;
    } else if (lastHash && curHash && lastHash !== curHash) {
      const choice = confirm('当前序列/属性/奇穴/秘籍等与上次模拟结果不一致，先跑一次模拟再发送？\n\n[确定] 先跑模拟再发送    [取消] 直接发送（会用到旧的 timeline）');
      if (choice) {
        // 跑一次，监听 jx3-sim-complete 再继续
        const onComplete = () => {
          window.removeEventListener('jx3-sim-complete', onComplete);
          const draft = snapshotSimStateAsDraft();
          window.Jx3WorkflowA.enterWithDraft(draft);
        };
        window.addEventListener('jx3-sim-complete', onComplete);
        if (typeof runSimulate === 'function') runSimulate();
        else { window.removeEventListener('jx3-sim-complete', onComplete); alert('模拟函数未加载'); }
        return;
      }
    }
    const draft = snapshotSimStateAsDraft();
    window.Jx3WorkflowA.enterWithDraft(draft);
  }

  document.querySelectorAll('#page-sim .sim-send-to .sim-dropdown-item').forEach(item => {
    item.addEventListener('click', () => {
      const to = item.dataset.sendTo;
      if (to === 'c') sendToC();
      else if (to === 'a') sendToA();
    });
  });
})();

// ── "隐藏团辅" checkbox：自身 buff 列表过滤 ──
(function setupHideTeamBuffsToggle() {
  const cb = document.getElementById('sim_hide_team_buffs');
  if (!cb) return;
  // localStorage 无值时默认勾选（跟战斗记录弹窗的"隐藏团辅事件"口径一致）
  try {
    const v = localStorage.getItem('sim_hide_team_buffs');
    cb.checked = v === null ? true : (v === '1');
  } catch { cb.checked = true; }
  cb.addEventListener('change', () => {
    try { localStorage.setItem('sim_hide_team_buffs', cb.checked ? '1' : '0'); } catch {}
    if (typeof renderBuffList === 'function') {
      renderBuffList(typeof lastSimResult !== 'undefined' && lastSimResult?.buffs || []);
    }
  });
})();

// ── 循环模拟页：三面板可拖动 splitter ──
// 垂直 splitter 调状态面板宽度，水平 splitter 调时间轴面板高度（在 sim-main-row 和底部时间轴之间）。
// localStorage 持久化，双击重置。
(function setupSimPanelResizers() {
  const STORAGE_KEY = 'sim_panel_layout_v1';
  const MIN_STATUS_W = 220;     // 状态面板最小宽
  const MIN_RIGHT_W  = 320;     // 右栏最小宽
  const MIN_MAIN_H   = 200;     // 中间区（含序列+技能栏）最小高
  const MIN_TIMELINE_H = 140;   // 时间轴最小高

  let saved = {};
  try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); } catch {}

  const statusPanel   = document.getElementById('sim_status_panel');
  const rightCol      = document.getElementById('sim_right_col');
  const vSplit        = document.getElementById('sim_splitter_v');
  const hSplit        = document.getElementById('sim_splitter_h');
  const timelinePanel = document.querySelector('#page-sim .sim-timeline-panel');
  if (!statusPanel || !rightCol || !vSplit || !hSplit || !timelinePanel) return;
  const pageSim = document.getElementById('page-sim');

  // 恢复保存的尺寸
  if (typeof saved.statusWidth === 'number' && saved.statusWidth >= MIN_STATUS_W) {
    statusPanel.style.width = saved.statusWidth + 'px';
  }
  if (typeof saved.timelineHeight === 'number' && saved.timelineHeight >= MIN_TIMELINE_H) {
    timelinePanel.style.height = saved.timelineHeight + 'px';
    timelinePanel.dataset.resized = '1';
  }

  const save = () => {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(saved)); } catch {}
  };

  // 通用 pointer 拖动器
  const attachDrag = (handle, axis, getStart, setOn) => {
    handle.addEventListener('pointerdown', (ev) => {
      if (ev.button !== 0) return; // 仅左键
      ev.preventDefault();
      handle.classList.add('dragging');
      document.body.classList.add(axis === 'x' ? 'sim-resizing-v' : 'sim-resizing-h');
      const start = getStart(ev);
      try { handle.setPointerCapture(ev.pointerId); } catch {}

      const onMove = (e) => setOn(e, start);
      const onUp = (e) => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        handle.classList.remove('dragging');
        document.body.classList.remove('sim-resizing-v');
        document.body.classList.remove('sim-resizing-h');
        try { handle.releasePointerCapture(ev.pointerId); } catch {}
        save();
      };
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
    });
  };

  // 垂直 splitter：拖 X 改状态面板宽
  attachDrag(vSplit, 'x',
    (ev) => ({
      x: ev.clientX,
      w: statusPanel.getBoundingClientRect().width,
      // 主行总宽（含 gap），限制状态宽不挤死右栏
      rowW: statusPanel.parentElement.getBoundingClientRect().width,
    }),
    (e, s) => {
      const dx = e.clientX - s.x;
      const maxW = Math.max(MIN_STATUS_W, s.rowW - MIN_RIGHT_W);
      const newW = Math.max(MIN_STATUS_W, Math.min(maxW, s.w + dx));
      statusPanel.style.width = newW + 'px';
      saved.statusWidth = newW;
    },
  );

  // 水平 splitter：拖 Y 改时间轴高度（splitter 在中间区下方、时间轴上方；向下拖时间轴变小）
  attachDrag(hSplit, 'y',
    (ev) => ({
      y: ev.clientY,
      h: timelinePanel.getBoundingClientRect().height,
      pageH: pageSim ? pageSim.getBoundingClientRect().height : window.innerHeight,
    }),
    (e, s) => {
      const dy = e.clientY - s.y;
      const maxH = Math.max(MIN_TIMELINE_H, s.pageH - MIN_MAIN_H);
      const newH = Math.max(MIN_TIMELINE_H, Math.min(maxH, s.h - dy));
      timelinePanel.style.height = newH + 'px';
      timelinePanel.dataset.resized = '1';
      saved.timelineHeight = newH;
    },
  );

  // 双击重置：恢复默认布局
  vSplit.addEventListener('dblclick', () => {
    statusPanel.style.width = '';
    delete saved.statusWidth;
    save();
  });
  hSplit.addEventListener('dblclick', () => {
    timelinePanel.style.height = '';
    delete timelinePanel.dataset.resized;
    delete saved.timelineHeight;
    save();
  });
})();

// ── 循环模拟页：时间轴折叠（默认折叠）──
// 折叠时 timeline-panel 只剩 header 高度（26px）；splitter 隐藏；中间区自动占满。
// localStorage 持久化折叠状态。
(function setupSimTimelineCollapse() {
  const STORAGE_KEY = 'sim_timeline_collapsed_v1';
  const panel  = document.getElementById('sim_timeline_panel');
  const header = document.getElementById('sim_timeline_header');
  const hSplit = document.getElementById('sim_splitter_h');
  if (!panel || !header || !hSplit) return;

  // 默认折叠（HTML 上已有 sim-timeline-collapsed class）；localStorage 显式 "0" 才展开
  let collapsed = true;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw === '0') collapsed = false;
  } catch {}

  const COLLAPSED_H = 26;     // 折叠态高度（仅 header）
  const DEFAULT_OPEN_H = 360;  // splitter 未拖过时的展开默认高度（同 CLAUDE.md 文档）

  const getOpenHeight = () => {
    // 优先用 splitter saved 高度（与 setupSimPanelResizers 共享 STORAGE_KEY），否则 fallback 360
    try {
      const raw = localStorage.getItem('sim_panel_layout_v1');
      if (raw) {
        const obj = JSON.parse(raw);
        if (obj && typeof obj.timelineHeight === 'number' && obj.timelineHeight >= 140) return obj.timelineHeight;
      }
    } catch {}
    return DEFAULT_OPEN_H;
  };

  /** 设置 panel 的高度 + flex（inline）；JS 通过 inline 控高，无需 CSS !important */
  const setHeight = (h) => {
    panel.style.height = h + 'px';
    panel.style.flex = `0 0 ${h}px`;
  };

  const apply = (animate) => {
    const targetH = collapsed ? COLLAPSED_H : getOpenHeight();
    if (animate) {
      // 启动 transition：先把当前 height 固化到 inline，再设目标
      const fromH = panel.getBoundingClientRect().height;
      panel.classList.add('sim-timeline-animating');
      setHeight(fromH);
      // 强制 reflow 让浏览器把上面的赋值作为 transition 起点
      void panel.offsetHeight;
      setHeight(targetH);
      panel.classList.toggle('sim-timeline-collapsed', collapsed);
      hSplit.classList.toggle('sim-splitter-hidden', collapsed);

      const cleanup = () => {
        panel.classList.remove('sim-timeline-animating');
        if (!collapsed && panel.dataset.resized !== '1') {
          // 展开且 splitter 没拖过 → 清掉 inline，让 CSS flex:1 接管自适应
          panel.style.height = '';
          panel.style.flex = '';
        }
      };
      // transitionend + 超时兜底（防 transition 被打断）
      panel.addEventListener('transitionend', function onEnd(e) {
        if (e && e.target !== panel) return;
        panel.removeEventListener('transitionend', onEnd);
        cleanup();
      });
      setTimeout(cleanup, 360);
    } else {
      // 启动时无动画分支：直接套用最终态
      if (collapsed) {
        setHeight(COLLAPSED_H);
      } else if (panel.dataset.resized !== '1') {
        panel.style.height = '';
        panel.style.flex = '';
      } else {
        setHeight(panel.getBoundingClientRect().height);
      }
      panel.classList.toggle('sim-timeline-collapsed', collapsed);
      hSplit.classList.toggle('sim-splitter-hidden', collapsed);
    }
    try { localStorage.setItem(STORAGE_KEY, collapsed ? '1' : '0'); } catch {}
  };

  header.addEventListener('click', () => {
    collapsed = !collapsed;
    apply(true);
  });

  apply(false);
})();

// ── 循环模拟页：序列技能块缩放（右下角 +/- 按钮）──
// 通过 CSS variable --seq-scale 控制；所有子元素尺寸/字号/角标偏移都从 scale 派生。
// localStorage 持久化，点击百分比文字重置到 100%。
(function setupSimSequenceZoom() {
  const STORAGE_KEY = 'sim_seq_zoom_v1';
  const MIN = 0.5;
  const MAX = 1.5;
  const STEP = 0.1;
  const DEFAULT = 1.0;

  const seq    = document.getElementById('sim_sequence');
  const btnOut = document.getElementById('seq_zoom_out');
  const btnIn  = document.getElementById('seq_zoom_in');
  const valEl  = document.getElementById('seq_zoom_value');
  if (!seq || !btnOut || !btnIn || !valEl) return;

  const clamp = (v) => Math.max(MIN, Math.min(MAX, v));
  const round = (v) => Math.round(v * 10) / 10;

  let scale = DEFAULT;
  try {
    const raw = parseFloat(localStorage.getItem(STORAGE_KEY));
    if (Number.isFinite(raw)) scale = clamp(round(raw));
  } catch {}

  const apply = () => {
    seq.style.setProperty('--seq-scale', String(scale));
    valEl.textContent = Math.round(scale * 100) + '%';
    btnOut.disabled = scale <= MIN + 1e-6;
    btnIn.disabled  = scale >= MAX - 1e-6;
    try { localStorage.setItem(STORAGE_KEY, String(scale)); } catch {}
  };

  btnOut.addEventListener('click', () => { scale = clamp(round(scale - STEP)); apply(); });
  btnIn .addEventListener('click', () => { scale = clamp(round(scale + STEP)); apply(); });
  valEl .addEventListener('click', () => { scale = DEFAULT; apply(); });

  apply();
})();
